//! Minimal logger mimicking `env_logger` output with microsecond timestamps.

use std::io::Write;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

static MAX_LEVEL: AtomicUsize = AtomicUsize::new(1);

pub fn init(additional_verbosity: u8) {
    let base: usize = match std::env::var("RUST_LOG") {
        Ok(v) => match v.trim().to_ascii_lowercase().as_str() {
            "off" => 0,
            "error" => 1,
            "warn" => 2,
            "info" => 3,
            "debug" => 4,
            "trace" => 5,
            _ => 1,
        },
        Err(_) => 1,
    };
    let lvl = (base + additional_verbosity as usize).min(5);
    MAX_LEVEL.store(lvl, Ordering::Relaxed);
}

#[inline]
pub fn enabled(level: Level) -> bool {
    (level as usize) <= MAX_LEVEL.load(Ordering::Relaxed)
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn timestamp() -> String {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = now.as_secs() as i64;
    let micros = now.subsec_micros();
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",
        y,
        m,
        d,
        rem / 3600,
        (rem % 3600) / 60,
        rem % 60,
        micros
    )
}

pub fn log(level: Level, target: &str, msg: std::fmt::Arguments) {
    if !enabled(level) {
        return;
    }
    let lvl = match level {
        Level::Error => "ERROR",
        Level::Warn => "WARN ",
        Level::Info => "INFO ",
        Level::Debug => "DEBUG",
        Level::Trace => "TRACE",
    };
    let line = format!("[{} {} {}] {}\n", timestamp(), lvl, target, msg);
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(line.as_bytes());
}

#[macro_export]
macro_rules! error {
    (target: $t:expr, $($arg:tt)+) => { $crate::logging::log($crate::logging::Level::Error, $t, format_args!($($arg)+)) };
    ($($arg:tt)+) => { $crate::logging::log($crate::logging::Level::Error, "srgn", format_args!($($arg)+)) };
}
#[macro_export]
macro_rules! warn {
    (target: $t:expr, $($arg:tt)+) => { $crate::logging::log($crate::logging::Level::Warn, $t, format_args!($($arg)+)) };
    ($($arg:tt)+) => { $crate::logging::log($crate::logging::Level::Warn, "srgn", format_args!($($arg)+)) };
}
#[macro_export]
macro_rules! info {
    (target: $t:expr, $($arg:tt)+) => { $crate::logging::log($crate::logging::Level::Info, $t, format_args!($($arg)+)) };
    ($($arg:tt)+) => { $crate::logging::log($crate::logging::Level::Info, "srgn", format_args!($($arg)+)) };
}
#[macro_export]
macro_rules! debug {
    (target: $t:expr, $($arg:tt)+) => { if $crate::logging::enabled($crate::logging::Level::Debug) { $crate::logging::log($crate::logging::Level::Debug, $t, format_args!($($arg)+)) } };
    ($($arg:tt)+) => { if $crate::logging::enabled($crate::logging::Level::Debug) { $crate::logging::log($crate::logging::Level::Debug, "srgn", format_args!($($arg)+)) } };
}
#[macro_export]
macro_rules! trace {
    (target: $t:expr, $($arg:tt)+) => { if $crate::logging::enabled($crate::logging::Level::Trace) { $crate::logging::log($crate::logging::Level::Trace, $t, format_args!($($arg)+)) } };
    ($($arg:tt)+) => { if $crate::logging::enabled($crate::logging::Level::Trace) { $crate::logging::log($crate::logging::Level::Trace, "srgn", format_args!($($arg)+)) } };
}
EOF"}

