//! Command line interface definition, mirroring the structure of the original tool so
//! that error messages (which clap derives from the structure) line up.

use clap::builder::{PossibleValue, PossibleValuesParser, TypedValueParser};
use clap::error::{ContextKind, ContextValue, ErrorKind};
use clap::{Arg, ArgAction, ArgGroup, Command};
use std::num::NonZeroUsize;

pub const LONG_HELP: &str = include_str!("help/long.txt");
pub const SHORT_HELP: &str = include_str!("help/short.txt");

/// A prepared query name, possibly with an attached pattern (`struct~PATTERN`).
#[derive(Clone, Debug)]
pub struct PreparedArg {
    pub name: String,
    pub pattern: Option<regex::Regex>,
}

#[derive(Clone)]
pub struct PreparedParser {
    plain: Vec<&'static str>,
    dynamic: Vec<&'static str>,
}

impl PreparedParser {
    fn new(plain: &[&'static str], dynamic: &[&'static str]) -> Self {
        Self {
            plain: plain.to_vec(),
            dynamic: dynamic.to_vec(),
        }
    }
}

impl TypedValueParser for PreparedParser {
    type Value = PreparedArg;

    fn parse_ref(
        &self,
        cmd: &Command,
        arg: Option<&Arg>,
        value: &std::ffi::OsStr,
    ) -> Result<Self::Value, clap::Error> {
        let s = value.to_string_lossy().to_string();
        if let Some((name, pat)) = s.split_once('~') {
            let re = match regex::Regex::new(pat) {
                Ok(r) => r,
                Err(e) => {
                    let mut err = clap::Error::new(ErrorKind::InvalidValue).with_cmd(cmd);
                    err.insert(ContextKind::InvalidArg, ContextValue::String(name.to_string()));
                    err.insert(ContextKind::InvalidValue, ContextValue::String(pat.to_string()));
                    err.insert(
                        ContextKind::Suggested,
                        ContextValue::StyledStrs(vec![format!("error was: {e}").into()]),
                    );
                    return Err(err);
                }
            };
            if self.dynamic.contains(&name) {
                return Ok(PreparedArg {
                    name: name.to_string(),
                    pattern: Some(re),
                });
            }
            if self.plain.contains(&name) {
                let mut err = clap::Error::new(ErrorKind::ArgumentConflict).with_cmd(cmd);
                err.insert(ContextKind::InvalidArg, ContextValue::String(name.to_string()));
                err.insert(
                    ContextKind::PriorArg,
                    ContextValue::String(format!("a pattern ('{pat}')")),
                );
                return Err(err);
            }
            let p = PossibleValuesParser::new(self.plain.clone());
            p.parse_ref(cmd, arg, std::ffi::OsStr::new(name))?;
            unreachable!()
        } else {
            let p = PossibleValuesParser::new(self.plain.clone());
            let v = p.parse_ref(cmd, arg, value)?;
            Ok(PreparedArg {
                name: v,
                pattern: None,
            })
        }
    }

    fn possible_values(&self) -> Option<Box<dyn Iterator<Item = PossibleValue> + '_>> {
        let mut all: Vec<PossibleValue> = Vec::new();
        for p in &self.plain {
            all.push(PossibleValue::new(*p));
            if self.dynamic.contains(p) {
                all.push(PossibleValue::new(format!("{p}~<PATTERN>")));
            }
        }
        Some(Box::new(all.into_iter()))
    }
}

pub struct LangDef {
    pub id: &'static str,
    pub long: &'static str,
    pub alias: Option<&'static str>,
    pub env: &'static str,
    pub group: &'static str,
    pub value_name: &'static str,
    pub plain: &'static [&'static str],
    pub dynamic: &'static [&'static str],
}

pub const C_VALUES: &[&str] = &[
    "comments", "strings", "includes", "type-def", "enum", "struct", "variable", "function",
    "function-def", "function-decl", "switch", "if", "for", "while", "do", "union", "identifier",
    "declaration", "call-expression",
];
pub const CSHARP_VALUES: &[&str] = &[
    "comments", "strings", "usings", "struct", "enum", "interface", "class", "method",
    "variable-declaration", "property", "constructor", "destructor", "field", "attribute",
    "identifier",
];
pub const GO_VALUES: &[&str] = &[
    "comments", "strings", "imports", "expression", "type-def", "type-alias", "struct",
    "interface", "const", "var", "func", "method", "free-func", "init-func", "type-params",
    "defer", "select", "go", "switch", "labeled", "goto", "struct-tags",
];
pub const GO_DYNAMIC: &[&str] = &["struct", "interface", "func"];
pub const HCL_VALUES: &[&str] = &[
    "variable", "resource", "data", "output", "provider", "required-providers", "terraform",
    "locals", "module", "variables", "resource-names", "resource-types", "data-names",
    "data-sources", "comments", "strings",
];
pub const PYTHON_VALUES: &[&str] = &[
    "comments", "strings", "imports", "doc-strings", "function-names", "function-calls", "class",
    "def", "async-def", "methods", "class-methods", "static-methods", "with", "try", "lambda",
    "globals", "variable-identifiers", "types", "identifiers",
];
pub const RUST_VALUES: &[&str] = &[
    "comments", "doc-comments", "uses", "strings", "attribute", "struct", "priv-struct",
    "pub-struct", "pub-crate-struct", "pub-self-struct", "pub-super-struct", "enum", "priv-enum",
    "pub-enum", "pub-crate-enum", "pub-self-enum", "pub-super-enum", "enum-variant", "fn",
    "impl-fn", "priv-fn", "pub-fn", "pub-crate-fn", "pub-self-fn", "pub-super-fn", "const-fn",
    "async-fn", "unsafe-fn", "extern-fn", "test-fn", "trait", "impl", "impl-type", "impl-trait",
    "mod", "mod-tests", "type-def", "identifier", "type-identifier", "closure", "unsafe",
];
pub const RUST_DYNAMIC: &[&str] = &["struct", "enum", "fn", "trait", "mod"];
pub const TS_VALUES: &[&str] = &[
    "comments", "strings", "imports", "function", "async-function", "sync-function", "method",
    "constructor", "class", "enum", "interface", "try-catch", "var-decl", "let", "const", "var",
    "type-params", "type-alias", "namespace", "export",
];

pub const LANGS: &[LangDef] = &[
    LangDef { id: "c", long: "c", alias: None, env: "C", group: "CScope", value_name: "C", plain: C_VALUES, dynamic: &[] },
    LangDef { id: "csharp", long: "csharp", alias: Some("cs"), env: "CSHARP", group: "CSharpScope", value_name: "CSHARP", plain: CSHARP_VALUES, dynamic: &[] },
    LangDef { id: "go", long: "go", alias: None, env: "GO", group: "GoScope", value_name: "GO", plain: GO_VALUES, dynamic: GO_DYNAMIC },
    LangDef { id: "hcl", long: "hcl", alias: None, env: "HCL", group: "HclScope", value_name: "HCL", plain: HCL_VALUES, dynamic: &[] },
    LangDef { id: "python", long: "python", alias: Some("py"), env: "PYTHON", group: "PythonScope", value_name: "PYTHON", plain: PYTHON_VALUES, dynamic: &[] },
    LangDef { id: "rust", long: "rust", alias: Some("rs"), env: "RUST", group: "RustScope", value_name: "RUST", plain: RUST_VALUES, dynamic: RUST_DYNAMIC },
    LangDef { id: "typescript", long: "typescript", alias: Some("ts"), env: "TYPESCRIPT", group: "TypeScriptScope", value_name: "TYPESCRIPT", plain: TS_VALUES, dynamic: &[] },
];

fn flag(id: &'static str) -> Arg {
    Arg::new(id).action(ArgAction::SetTrue)
}

pub fn build_command() -> Command {
    let mut cmd = Command::new("srgn")
        .version("0.14.1")
        .about("A grep-like tool which understands source code syntax and allows for manipulation in\naddition to search")
        .disable_help_flag(false)
        .arg(
            Arg::new("scope")
                .value_name("SCOPE")
                .default_value(".*")
                .index(1),
        )
        .arg(
            Arg::new("shell")
                .long("completions")
                .value_name("SHELL")
                .value_parser(["bash", "elvish", "fish", "powershell", "zsh"]),
        );

    // Composable actions
    cmd = cmd
        .arg(
            Arg::new("replace")
                .value_name("REPLACEMENT")
                .env("REPLACE")
                .last(true)
                .index(2),
        )
        .arg(flag("upper").short('u').long("upper").env("UPPER"))
        .arg(flag("lower").short('l').long("lower").env("LOWER"))
        .arg(flag("titlecase").short('t').long("titlecase").env("TITLECASE"))
        .arg(flag("normalize").short('n').long("normalize").env("NORMALIZE"))
        .arg(flag("german").short('g').long("german"))
        .arg(flag("symbols").short('S').long("symbols"))
        .group(
            ArgGroup::new("ComposableActions")
                .multiple(true)
                .args(["replace", "upper", "lower", "titlecase", "normalize", "german", "symbols"]),
        );

    // Standalone actions
    cmd = cmd
        .arg(
            flag("delete")
                .short('d')
                .long("delete")
                .requires("scope")
                .conflicts_with_all(["ComposableActions", "squeeze"]),
        )
        .arg(
            flag("squeeze")
                .short('s')
                .long("squeeze")
                .visible_alias("squeeze-repeats")
                .env("SQUEEZE")
                .requires("scope"),
        )
        .group(
            ArgGroup::new("StandaloneActions")
                .multiple(true)
                .args(["delete", "squeeze"]),
        );

    // Global options
    cmd = cmd
        .arg(
            Arg::new("glob")
                .short('G')
                .long("glob")
                .alias("files")
                .value_name("GLOB")
                .value_parser(|s: &str| glob::Pattern::new(s)),
        )
        .arg(flag("fail_no_files").long("fail-no-files"))
        .arg(flag("dry_run").long("dry-run"))
        .arg(flag("invert").short('i').long("invert").env("INVERT"))
        .arg(
            flag("literal_string")
                .short('L')
                .long("literal-string")
                .env("LITERAL_STRING"),
        )
        .arg(flag("fail_any").long("fail-any"))
        .arg(flag("fail_none").long("fail-none"))
        .arg(flag("join_language_scopes").short('j').long("join-language-scopes"))
        .arg(flag("line_numbers").long("line-numbers").hide(true))
        .arg(flag("only_matching").long("only-matching").hide(true))
        .arg(flag("hidden").short('H').long("hidden"))
        .arg(flag("gitignored").long("gitignored"))
        .arg(flag("sorted").long("sorted"))
        .arg(
            Arg::new("stdin_detection")
                .long("stdin-detection")
                .value_name("STDIN_DETECTION")
                .default_value("auto")
                .value_parser(["auto", "force-readable", "force-unreadable"]),
        )
        .arg(
            Arg::new("stdout_detection")
                .long("stdout-detection")
                .value_name("STDOUT_DETECTION")
                .default_value("auto")
                .value_parser(["auto", "force-tty", "force-pipe"]),
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .value_name("THREADS")
                .value_parser(clap::value_parser!(NonZeroUsize)),
        )
        .arg(
            Arg::new("additional_verbosity")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count),
        )
        .group(ArgGroup::new("GlobalOptions").multiple(true).args([
            "glob",
            "fail_no_files",
            "dry_run",
            "invert",
            "literal_string",
            "fail_any",
            "fail_none",
            "join_language_scopes",
            "line_numbers",
            "only_matching",
            "hidden",
            "gitignored",
            "sorted",
            "stdin_detection",
            "stdout_detection",
            "threads",
            "additional_verbosity",
        ]));

    for l in LANGS {
        let mut a = Arg::new(l.id)
            .long(l.long)
            .value_name(l.value_name)
            .env(l.env)
            .action(ArgAction::Append)
            .value_parser(PreparedParser::new(l.plain, l.dynamic));
        if let Some(al) = l.alias {
            a = a.visible_alias(al);
        }
        let qid: &'static str = Box::leak(format!("{}_query", l.id).into_boxed_str());
