    let m = match cmd.try_get_matches_from(argv.clone()) {
        Ok(m) => m,
        Err(e) => {
            use std::io::Write;
            match e.kind() {
                ErrorKind::DisplayHelp => {
                    let text = if help_is_long(&argv) { LONG_HELP } else { SHORT_HELP };
                    let text = text.replacen("Usage: executable", &format!("Usage: {}", bin_name()), 1);
                    let _ = std::io::stdout().write_all(text.as_bytes());
                    std::process::exit(0);
                }
                ErrorKind::DisplayVersion => {
                    let _ = std::io::stdout().write_all(b"srgn 0.14.1\n");
                    std::process::exit(0);
                }
                _ => e.exit(),
            }
        }
    };

    let get_flag = |id: &str| m.get_flag(id);
    let scope_explicit = matches!(
        m.value_source("scope"),
        Some(clap::parser::ValueSource::CommandLine)
    );
    let det = |id: &str| -> Detection {
        match m.get_one::<String>(id).map(|s| s.as_str()) {
            Some("force-readable") | Some("force-tty") => Detection::ForceOn,
            Some("force-unreadable") | Some("force-pipe") => Detection::ForceOff,
            _ => Detection::Auto,
        }
    };

    let mut langs = Vec::new();
    for l in LANGS {
        let prepared: Vec<PreparedArg> = m
            .get_many::<PreparedArg>(l.id)
            .map(|v| v.cloned().collect())
            .unwrap_or_default();
        let queries: Vec<String> = m
            .get_many::<String>(&format!("{}_query", l.id))
            .map(|v| v.cloned().collect())
            .unwrap_or_default();
        let query_files: Vec<String> = m
            .get_many::<String>(&format!("{}_query_file", l.id))
            .map(|v| v.cloned().collect())
            .unwrap_or_default();
        if !prepared.is_empty() || !queries.is_empty() || !query_files.is_empty() {
            langs.push(LangSelection {
                lang: l.id,
                prepared,
                queries,
                query_files,
            });
        }
    }

    Args {
        scope: m.get_one::<String>("scope").cloned().unwrap_or_else(|| ".*".into()),
        scope_explicit,
        shell: m.get_one::<String>("shell").cloned(),
        replace: m.get_one::<String>("replace").cloned(),
        upper: get_flag("upper"),
        lower: get_flag("lower"),
        titlecase: get_flag("titlecase"),
        normalize: get_flag("normalize"),
        german: get_flag("german"),
        symbols: get_flag("symbols"),
        delete: get_flag("delete"),
        squeeze: get_flag("squeeze"),
        glob: m.get_one::<glob::Pattern>("glob").cloned(),
        fail_no_files: get_flag("fail_no_files"),
        dry_run: get_flag("dry_run"),
        invert: get_flag("invert"),
        literal_string: get_flag("literal_string"),
        fail_any: get_flag("fail_any"),
        fail_none: get_flag("fail_none"),
        join_language_scopes: get_flag("join_language_scopes"),
        line_numbers: get_flag("line_numbers"),
        only_matching: get_flag("only_matching"),
        hidden: get_flag("hidden"),
        gitignored: get_flag("gitignored"),
        sorted: get_flag("sorted"),
        stdin_detection: det("stdin_detection"),
        stdout_detection: det("stdout_detection"),
        threads: m.get_one::<NonZeroUsize>("threads").cloned(),
        verbosity: m.get_count("additional_verbosity"),
        langs,
        german_prefer_original: get_flag("german_prefer_original"),
        german_naive: get_flag("german_naive"),
    }
}

/// Emit an error in the style of `Cli::command().error(...)` (note: plain `srgn` name).
pub fn custom_error(kind: ErrorKind, msg: &str) -> ! {
    let mut cmd = build_command();
    let err = cmd.error(kind, msg);
    err.exit()
}
