//! Scopes and views: splitting input into in-scope and out-of-scope parts.

use std::ops::Range;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CaptureKey {
    Numbered(usize),
    Named(String),
}

pub type Captures = Vec<(CaptureKey, String)>;

#[derive(Clone, Debug)]
pub enum Scope {
    In(String, Option<Captures>),
    Out(String),
}

impl Scope {
    pub fn text(&self) -> &str {
        match self {
            Scope::In(s, _) => s,
            Scope::Out(s) => s,
        }
    }
    pub fn is_in(&self) -> bool {
        matches!(self, Scope::In(..))
    }
}

pub type RawRanges = Vec<(Range<usize>, Option<Captures>)>;

pub trait Scoper {
    fn scope_raw(&self, input: &str) -> Result<RawRanges, String>;
}

#[derive(Clone, Debug, Default)]
pub struct View {
    pub scopes: Vec<Scope>,
}

/// Turn raw ranges into scopes covering all of `input`.
pub fn scopes_from_ranges(input: &str, ranges: RawRanges) -> Vec<Scope> {
    let mut out = Vec::new();
    let mut last = 0usize;
    for (r, caps) in ranges {
        if r.start > last {
            out.push(Scope::Out(input[last..r.start].to_string()));
        }
        if r.start < last {
            // overlapping; skip defensively
            continue;
        }
        if !r.is_empty() {
            out.push(Scope::In(input[r.clone()].to_string(), caps));
        }
        last = r.end;
    }
    if last < input.len() {
        out.push(Scope::Out(input[last..].to_string()));
    }
    out
}

impl View {
    pub fn new(input: &str) -> Self {
        View {
            scopes: vec![Scope::In(input.to_string(), None)],
        }
    }

    pub fn explode(&mut self, scoper: &dyn Scoper) -> Result<(), String> {
        let mut new = Vec::with_capacity(self.scopes.len());
        for scope in std::mem::take(&mut self.scopes) {
            match scope {
                Scope::In(text, caps) => {
                    if text.is_empty() {
                        continue;
                    }
                    let _ = caps;
                    let ranges = scoper.scope_raw(&text)?;
                    new.extend(scopes_from_ranges(&text, ranges));
                }
                out => new.push(out),
            }
        }
        self.scopes = new;
        Ok(())
    }

    pub fn has_any_in_scope(&self) -> bool {
        self.scopes.iter().any(|s| s.is_in())
    }

    pub fn squeeze(&mut self) {
        let mut new: Vec<Scope> = Vec::with_capacity(self.scopes.len());
        let mut prev_in = false;
        for s in std::mem::take(&mut self.scopes) {
            let is_in = s.is_in();
            if is_in && prev_in {
                continue;
            }
            prev_in = is_in;
            new.push(s);
        }
        self.scopes = new;
    }

    pub fn delete(&mut self) {
        for s in self.scopes.iter_mut() {
            if let Scope::In(text, _) = s {
                text.clear();
            }
        }
    }

    pub fn render(&self) -> String {
        let mut out = String::new();
        for s in &self.scopes {
            out.push_str(s.text());
        }
        out
    }

    /// Split the view into lines. Each line is its text plus in-scope byte ranges
    /// (relative to line start).
    pub fn lines(&self) -> Vec<Line> {
        let mut lines = Vec::new();
        let mut cur = Line::default();
        for s in &self.scopes {
            let is_in = s.is_in();
            let mut text = s.text();
            while !text.is_empty() {
                let (piece, rest, ends) = match text.find('\n') {
                    Some(i) => (&text[..=i], &text[i + 1..], true),
                    None => (text, "", false),
                };
                let start = cur.text.len();
                cur.text.push_str(piece);
                if is_in {
                    cur.ranges.push(start..cur.text.len());
                }
                if ends {
                    lines.push(std::mem::take(&mut cur));
                }
                text = rest;
            }
        }
        if !cur.text.is_empty() {
            lines.push(cur);
        }
        lines
    }
}

#[derive(Clone, Debug, Default)]
pub struct Line {
    pub text: String,
    pub ranges: Vec<Range<usize>>,
}

// ---------------------------------------------------------------------------
// Regex and literal scopers

pub struct RegexScoper {
    pub re: fancy_regex::Regex,
}

impl Scoper for RegexScoper {
    fn scope_raw(&self, input: &str) -> Result<RawRanges, String> {
        let mut out = Vec::new();
        let names: Vec<Option<String>> = self
            .re
            .capture_names()
            .map(|n| n.map(|s| s.to_string()))
            .collect();
        for caps in self.re.captures_iter(input) {
            let caps = caps.map_err(|e| format!("{e}"))?;
            let m = match caps.get(0) {
                Some(m) => m,
                None => continue,
            };
            let mut groups: Captures = Vec::new();
            // Highest-numbered first, mimicking the original's map ordering is not
            // needed for behavior; keep numeric order.
            for i in 0..caps.len() {
                if let Some(g) = caps.get(i) {
                    let key = match names.get(i).cloned().flatten() {
                        Some(n) if i > 0 => CaptureKey::Named(n),
                        _ => CaptureKey::Numbered(i),
                    };
                    groups.push((key, g.as_str().to_string()));
                }
            }
            out.push((m.start()..m.end(), Some(groups)));
        }
        Ok(out)
    }
}

pub struct LiteralScoper {
    pub lit: String,
}

impl Scoper for LiteralScoper {
    fn scope_raw(&self, input: &str) -> Result<RawRanges, String> {
        let mut out = Vec::new();
        if self.lit.is_empty() {
            return Ok(out);
        }
        for (i, _) in input.match_indices(self.lit.as_str()) {
            out.push((i..i + self.lit.len(), None));
        }
        Ok(out)
    }
}

/// Merge overlapping or adjacent ranges (sorted output).
pub fn merge_ranges(mut v: Vec<Range<usize>>) -> Vec<Range<usize>> {
    v.sort_by(|a, b| a.start.cmp(&b.start).then(a.end.cmp(&b.end)));
    let mut out: Vec<Range<usize>> = Vec::new();
    for r in v {
        if let Some(last) = out.last_mut() {
            if r.start <= last.end {
                if r.end > last.end {
                    last.end = r.end;
                }
                continue;
            }
        }
        out.push(r);
    }
    out
}

/// Subtract `right` ranges from `left` ranges (both merged & sorted).
pub fn subtract_ranges(left: &[Range<usize>], right: &[Range<usize>]) -> Vec<Range<usize>> {
    let mut out = Vec::new();
    for l in left {
        let mut pieces = vec![l.clone()];
        for r in right {
            let mut next = Vec::new();
            for p in pieces {
                if r.end <= p.start || r.start >= p.end {
                    next.push(p);
                    continue;
                }
                if r.start > p.start {
                    next.push(p.start..r.start);
                }
                if r.end < p.end {
                    next.push(r.end..p.end);
                }
            }
            pieces = next;
        }
        out.extend(pieces.into_iter().filter(|p| !p.is_empty()));
    }
    out
}
