# Generates src/unicode_tables.rs from Python's unicodedata (canonical decompositions, marks).
import unicodedata, sys

def full_decomp(cp):
    d = unicodedata.decomposition(chr(cp))
    if not d or d.startswith('<'):
        return None
    parts = [int(x, 16) for x in d.split()]
    out = []
    for p in parts:
        sub = full_decomp(p)
        if sub is None:
            out.append(p)
        else:
            out.extend(sub)
    return out

lines = []
lines.append("// Generated by tools/gen_unicode.py. Do not edit.")
lines.append("pub static DECOMP: &[(u32, &[u32])] = &[")
for cp in range(0x110000):
    if 0xAC00 <= cp <= 0xD7A3:
        continue
    d = full_decomp(cp)
    if d is not None:
        lines.append("    (0x%X, &[%s])," % (cp, ", ".join("0x%X" % x for x in d)))
lines.append("];")

# mark ranges
ranges = []
start = None
for cp in range(0x110001):
    is_mark = cp < 0x110000 and unicodedata.category(chr(cp)).startswith('M')
    if is_mark and start is None:
        start = cp
    elif not is_mark and start is not None:
        ranges.append((start, cp - 1))
        start = None
lines.append("pub static MARKS: &[(u32, u32)] = &[")
for a, b in ranges:
    lines.append("    (0x%X, 0x%X)," % (a, b))
lines.append("];")
open(sys.argv[1], "w").write("\n".join(lines) + "\n")
EOF
