{"command":"cat > /workspace/src/actions.rs <<'EOF'
//! Actions transforming in-scope text.

use crate::scoping::{CaptureKey, Captures};
use crate::unicode_tables::{DECOMP, MARKS};

#[derive(Debug)]
pub enum Action {
    Replacement(String),
    Upper,
    Lower,
    Titlecase,
    Normalization,
    Symbols,
    SymbolsInversion,
    German(crate::german::GermanOptions),
    Deletion,
}

impl Action {
    pub fn name(&self) -> &'static str {
        match self {
            Action::Replacement(_) => "Replacement",
            Action::Upper => "Upper",
            Action::Lower => "Lower",
            Action::Titlecase => "Titlecase",
            Action::Normalization => "Normalization",
            Action::Symbols => "Symbols",
            Action::SymbolsInversion => "SymbolsInversion",
            Action::German(_) => "German",
            Action::Deletion => "Deletion",
        }
    }

    pub fn apply(&self, input: &str, ctx: Option<&Captures>) -> Result<String, String> {
        match self {
            Action::Replacement(r) => match ctx {
                Some(caps) => inject_variables(r, caps)
                    .map_err(|e| format!("Action failed in replacement: Error in variable expressions: {e}")),
                None => Ok(r.clone()),
            },
            Action::Upper => Ok(upper(input)),
            Action::Lower => Ok(input.to_lowercase()),
            Action::Titlecase => Ok(crate::titlecase::titlecase(input)),
            Action::Normalization => Ok(normalize(input)),
            Action::Symbols => Ok(symbols(input)),
            Action::SymbolsInversion => Ok(symbols_invert(input)),
            Action::German(opts) => Ok(crate::german::process(input, opts)),
            Action::Deletion => Ok(String::new()),
        }
    }
}

pub fn upper(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for c in input.chars() {
        if c == 'ß' {
            out.push('ẞ');
        } else {
            out.extend(c.to_uppercase());
        }
    }
    out
}

fn is_mark(c: char) -> bool {
    let cp = c as u32;
    MARKS
        .binary_search_by(|&(a, b)| {
            if cp < a {
                std::cmp::Ordering::Greater
            } else if cp > b {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

fn decompose_into(c: char, out: &mut Vec<char>) {
    let cp = c as u32;
    // Hangul syllables
    if (0xAC00..=0xD7A3).contains(&cp) {
        let s_index = cp - 0xAC00;
        let l = 0x1100 + s_index / (21 * 28);
        let v = 0x1161 + (s_index % (21 * 28)) / 28;
        let t = 0x11A7 + s_index % 28;
        out.push(char::from_u32(l).unwrap());
        out.push(char::from_u32(v).unwrap());
        if t != 0x11A7 {
            out.push(char::from_u32(t).unwrap());
        }
        return;
    }
    match DECOMP.binary_search_by_key(&cp, |&(k, _)| k) {
        Ok(i) => {
            for &d in DECOMP[i].1 {
                out.push(char::from_u32(d).unwrap());
            }
        }
        Err(_) => out.push(c),
    }
}

pub fn normalize(input: &str) -> String {
    let mut buf = Vec::new();
    for c in input.chars() {
        decompose_into(c, &mut buf);
    }
    buf.into_iter().filter(|c| !is_mark(*c)).collect()
}

const SYMBOLS: &[(&str, &str)] = &[
    ("-->", "⟶"),
    ("<--", "⟵"),
    ("<->", "↔"),
    ("---", "—"),
