//! Title casing in the style of John Gruber's title case rules.

const SMALL_WORDS: &[&str] = &[
    "a", "an", "and", "as", "at", "but", "by", "en", "for", "if", "in", "of", "on", "or", "the",
    "to", "v", "v.", "via", "vs", "vs.",
];

fn is_small(w: &str) -> bool {
    let lw = w.to_lowercase();
    SMALL_WORDS.contains(&lw.as_str())
}

fn capitalize_first(w: &str) -> String {
    let mut out = String::with_capacity(w.len());
    let mut done = false;
    for c in w.chars() {
        if !done && c.is_alphabetic() {
            out.extend(c.to_uppercase());
            done = true;
        } else if !done && c.is_alphanumeric() {
            // digits first: do not capitalize
            done = true;
            out.push(c);
        } else {
            out.push(c);
        }
    }
    out
}

fn has_internal_caps(w: &str) -> bool {
    w.chars().skip(1).any(|c| c.is_uppercase())
}

pub fn titlecase(input: &str) -> String {
    let trimmed = input.trim();
    let lowered;
    let text: &str = if !trimmed.chars().any(|c| c.is_lowercase()) {
        lowered = trimmed.to_lowercase();
        &lowered
    } else {
        trimmed
    };
    // split into words and whitespace
    let mut tokens: Vec<(bool, &str)> = Vec::new();
    let mut start = 0;
    let mut in_ws: Option<bool> = None;
    for (i, c) in text.char_indices() {
        let ws = c.is_whitespace();
        match in_ws {
            None => in_ws = Some(ws),
            Some(prev) if prev != ws => {
                tokens.push((prev, &text[start..i]));
                start = i;
                in_ws = Some(ws);
            }
            _ => {}
        }
    }
    if let Some(prev) = in_ws {
        tokens.push((prev, &text[start..]));
    }
    let word_count = tokens.iter().filter(|t| !t.0).count();
    let mut out = String::with_capacity(text.len());
    let mut wi = 0;
    let mut prev_word: Option<&str> = None;
    for (ws, tok) in tokens {
        if ws {
            out.push_str(tok);
            continue;
        }
        let first = wi == 0;
        let last = wi + 1 == word_count;
        let after_sentence = prev_word
            .map(|p| p.ends_with(':') || p.ends_with('.') || p.ends_with('?') || p.ends_with('!'))
            .unwrap_or(false);
        wi += 1;
        prev_word = Some(tok);
        out.push_str(&case_word(tok, first || last || after_sentence));
    }
    out
}

fn case_word(w: &str, force: bool) -> String {
    if has_internal_caps(w) {
        return w.to_string();
    }
    if w.contains('@') {
        return w.to_string();
    }
    if !force && is_small(w) {
        return w.to_lowercase();
    }
    if w.contains('-') || w.contains('/') {
        let mut out = String::new();
        let mut part = String::new();
        for c in w.chars() {
            if c == '-' || c == '/' {
                out.push_str(&capitalize_first(&part));
                out.push(c);
                part.clear();
            } else {
                part.push(c);
            }
        }
        out.push_str(&capitalize_first(&part));
        return out;
    }
    capitalize_first(w)
}
