enum FileError {
    /// Error during application (reported as `Error processing path: Error applying: ...`)
    Apply(ApplyError),
}

fn walk(
    args: &Args,
    pipeline: &Pipeline,
    valid: &dyn Fn(&Path, &Path) -> bool,
) -> Result<(), AppError> {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let n_threads = args
        .threads
        .map(|t| t.get())
        .unwrap_or_else(|| std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1));
    if args.sorted {
        info!(
            "Will walk file tree sequentially, in sorted order, starting from: {:?}",
            Ok::<_, ()>(&cwd)
        );
    } else {
        info!(
            "Will walk file tree using {} thread(s), processing in arbitrary order, starting from: {:?}",
            n_threads,
            Ok::<_, ()>(&cwd)
        );
    }
    let mut builder = ignore::WalkBuilder::new(&cwd);
    builder
        .hidden(!args.hidden)
        .git_ignore(!args.gitignored)
        .sort_by_file_name(|a, b| a.cmp(b));
    let walker = builder.build();

    let mut n_seen = 0usize;
    let mut n_processed = 0usize;
    let mut any_in_scope = false;
    let mut stdout = std::io::stdout().lock();

    for entry in walker {
        let entry = match entry {
            Ok(e) => e,
            Err(e) => {
                warn!("Error walking: {e}");
                continue;
            }
        };
        let abs = entry.path().to_path_buf();
        let is_file = entry.file_type().map(|t| t.is_file()).unwrap_or(false);
        if !is_file {
            trace!("Skipping path (not a file): {}", abs.display());
            continue;
        }
        n_seen += 1;
        let rel = abs.strip_prefix(&cwd).unwrap_or(&abs).to_path_buf();
        if !valid(&rel, &abs) {
            trace!("Skipping path (invalid): {}", rel.display());
            continue;
        }
        debug!("Processing path: {}", rel.display());
        let bytes = match std::fs::read(&abs) {
            Ok(b) => b,
            Err(e) => {
                warn!("Could not read file {}: {e}", abs.display());
                continue;
            }
        };
        let text = match String::from_utf8(bytes) {
            Ok(t) => t,
            Err(_) => {
                warn!(
                    "File contains unreadable data (binary? invalid utf-8?), skipped: {}",
                    abs.display()
                );
                continue;
            }
        };
        n_processed += 1;
        let display = rel.display().to_string();
        match pipeline.process(&text, &display, true) {
            Ok((out, changed, any)) => {
                any_in_scope |= any;
                let s = &pipeline.settings;
                if s.search_mode || s.dry_run {
                    let _ = stdout.write_all(out.as_bytes());
                } else {
                    if changed {
                        if let Err(e) = std::fs::write(&abs, out.as_bytes()) {
                            return Err(AppError(format!("Error processing path: I/O error: {e}")));
                        }
                        let _ = writeln!(stdout, "{}", display);
                    } else {
                        debug!("Skipping writing file anew (nothing changed): {}", display);
                    }
                }
                debug!("Done processing file: {}", display);
            }
            Err(FileError::Apply(e)) => {
                let _ = stdout.flush();
                match e {
                    ApplyError::NoneInScope => {
                        // per-file absence is handled globally
                    }
                    ApplyError::SomeInScope => {
                        if args.sorted {
                            return Err(AppError("Some input was in scope".to_string()));
                        }
                        return Err(AppError(
                            "Error processing path: Error applying: Some input was in scope"
                                .to_string(),
                        ));
                    }
                    ApplyError::Action(_) => {
                        let msg = format!("Error applying: {e}");
                        if args.sorted {
                            error!("Aborting walk at {} due to: {}", abs.display(), msg);
                        } else {
                            error!("Error walking at {} due to: {}", abs.display(), msg);
                            error!("Aborting walk for safety");
                        }
                        return Err(AppError(format!("Error processing path: {msg}")));
                    }
                }
            }
        }
    }
    let _ = stdout.flush();
    info!("Saw {} items", n_seen);
    info!("Processed {} files", n_processed);

    if args.fail_no_files && n_processed == 0 {
        return Err(AppError("No files found".to_string()));
    }
    if pipeline.settings.fail_none && !any_in_scope {
        return Err(AppError("No input was in scope".to_string()));
    }
    info!("Done, exiting");
    Ok(())
}

const RED_BOLD: &str = "\x1b[1;31m";
const GREEN_BOLD: &str = "\x1b[1;32m";
const RESET: &str = "\x1b[0m";

impl Pipeline {
    /// Process one input. Returns (output text, changed?, any in scope?).
    fn process(
        &self,
        text: &str,
        display: &str,
        is_file: bool,
    ) -> Result<(String, bool, bool), FileError> {
        let s = &self.settings;
        debug!("Building view.");
        let mut view = View::new(text);
        for sc in &self.lang_scopers {
            view.explode(sc.as_ref())
                .map_err(|e| FileError::Apply(ApplyError::Action(e)))?;
        }
        view.explode(self.general.as_ref())
            .map_err(|e| FileError::Apply(ApplyError::Action(e)))?;
        if s.squeeze {
            view.squeeze();
        }
        let any = view.has_any_in_scope();
        if s.fail_any && any {
            return Err(FileError::Apply(ApplyError::SomeInScope));
        }
        if s.fail_none && !any && !is_file {
            return Err(FileError::Apply(ApplyError::NoneInScope));
        }

        debug!("Applying actions to view.");
        let old = view.clone();
        for scope in view.scopes.iter_mut() {
            if let scoping::Scope::In(t, caps) = scope {
                let mut cur = t.clone();
                for a in &self.actions {
                    cur = a
                        .apply(&cur, caps.as_ref())
                        .map_err(|e| FileError::Apply(ApplyError::Action(e)))?;
                }
                *t = cur;
            }
        }
        let new_text = view.render();
        let changed = new_text != text;

        let out = if s.only_matching || s.line_numbers {
            let mut out = String::new();
            let prefix = if s.is_tty { None } else { Some(display) };
            let mut body = String::new();
            if s.dry_run {
                let old_lines = old.lines();
                let new_lines = view.lines();
                for (i, (ol, nl)) in old_lines.iter().zip(new_lines.iter()).enumerate() {
                    self.emit_line(&mut body, ol, i + 1, prefix, Some(RED_BOLD));
                    self.emit_line(&mut body, nl, i + 1, prefix, Some(GREEN_BOLD));
                }
            } else {
                let style = if s.search_mode { Some(RED_BOLD) } else { None };
                for (i, l) in view.lines().iter().enumerate() {
                    self.emit_line(&mut body, l, i + 1, prefix, style);
                }
            }
            if s.is_tty && is_file && (s.search_mode || s.dry_run) {
                if !body.is_empty() {
                    if s.colorize {
                        out.push_str(&format!("\x1b[35m{display}{RESET}\n"));
                    } else {
                        out.push_str(display);
                        out.push('\n');
                    }
                    out.push_str(&body);
                    out.push('\n');
                }
            } else {
                out = body;
            }
            out
        } else {
            new_text
        };
        Ok((out, changed, any))
    }

    fn emit_line(
        &self,
        out: &mut String,
        line: &scoping::Line,
        num: usize,
        prefix: Option<&str>,
        style: Option<&str>,
    ) {
        let s = &self.settings;
        let ranges: Vec<&std::ops::Range<usize>> =
            line.ranges.iter().filter(|r| !r.is_empty()).collect();
        if s.only_matching && ranges.is_empty() {
            return;
        }
        match prefix {
            Some(p) => {
                out.push_str(p);
                out.push(':');
                if s.line_numbers {
                    out.push_str(&num.to_string());
                    out.push(':');
                }
                let rs: Vec<String> = ranges
                    .iter()
                    .map(|r| format!("{}-{}", r.start, r.end))
                    .collect();
                out.push_str(&rs.join(";"));
                out.push(':');
                out.push_str(&line.text);
            }
            None => {
                if s.line_numbers {
                    if s.colorize {
                        out.push_str(&format!("\x1b[32m{num}{RESET}:"));
                    } else {
                        out.push_str(&num.to_string());
                        out.push(':');
                    }
                }
                match (style, s.colorize) {
                    (Some(st), true) => {
                        let mut last = 0;
                        for r in &ranges {
                            out.push_str(&line.text[last..r.start]);
                            out.push_str(st);
                            out.push_str(&line.text[r.start..r.end]);
                            out.push_str(RESET);
                            last = r.end;
                        }
                        out.push_str(&line.text[last..]);
                    }
                    _ => out.push_str(&line.text),
                }
            }
        }
    }
}
EOF"}

