"""Differential tester: compare original vs. reimplementation on cases.

Case format (python literal list of dicts):
  {"args": [...], "stdin": "..." or None, "files": {"a.py": "..."}, "env": {...}}
"""
import os, re, subprocess, sys, tempfile, shutil, ast, json

ORIG = "/tmp/cmp/orig/executable"
MINE = "/tmp/cmp/mine/executable"
TS = re.compile(r"\[\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{6}Z ")

def run(binary, case):
    d = tempfile.mkdtemp(prefix="srgncmp")
    try:
        for name, content in case.get("files", {}).items():
            p = os.path.join(d, name)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "wb") as f:
                f.write(content.encode() if isinstance(content, str) else content)
        env = dict(os.environ)
        env.update(case.get("env", {}))
        stdin = case.get("stdin")
        kw = {}
        if stdin is None:
            kw["stdin"] = subprocess.DEVNULL
        else:
            kw["input"] = stdin.encode() if isinstance(stdin, str) else stdin
        r = subprocess.run([binary] + case["args"], cwd=d, env=env, capture_output=True, timeout=30, **kw)
        files = {}
        for root, dirs, fs in os.walk(d):
            for fn in fs:
                p = os.path.join(root, fn)
                rel = os.path.relpath(p, d)
                if "/.git/" in "/" + rel or rel.startswith(".git/"):
                    continue
                with open(p, "rb") as f:
                    files[rel] = f.read()
        err = TS.sub("[TS ", r.stderr.decode(errors="replace"))
        out = r.stdout.decode(errors="replace")
        if case.get("sort_out"):
            out = "\n".join(sorted(out.split("\n")))
        return out, err, r.returncode, files
    finally:
        shutil.rmtree(d)

def main():
    cases = ast.literal_eval(open(sys.argv[1]).read())
    verbose = "-v" in sys.argv
    check_err = "--noerr" not in sys.argv
    fails = 0
    for i, case in enumerate(cases):
        a = run(ORIG, case)
        b = run(MINE, case)
        names = ["stdout", "stderr", "rc", "files"]
        bad = []
        for n, x, y in zip(names, a, b):
            if n == "stderr" and not check_err:
                continue
            if x != y:
                bad.append((n, x, y))
        if bad:
            fails += 1
            print(f"=== FAIL case {i}: {case['args']} stdin={case.get('stdin')!r:.80}")
            for n, x, y in bad:
                if n == "files":
                    for k in sorted(set(x) | set(y)):
                        if x.get(k) != y.get(k):
                            print(f"  file {k}:\n    orig: {x.get(k)!r:.300}\n    mine: {y.get(k)!r:.300}")
                else:
                    print(f"  {n}:\n    orig: {x!r:.1500}\n    mine: {y!r:.1500}")
        elif verbose:
            print(f"ok case {i}: {case['args']}")
    print(f"{len(cases) - fails}/{len(cases)} passed")

if __name__ == "__main__":
    main()
