//! Concrete syntax tree and query infrastructure (tree-sitter compatible subset).

pub mod builder;
pub mod query;

pub type NodeId = u32;

#[derive(Clone, Debug)]
pub struct Node {
    pub kind: &'static str,
    pub named: bool,
    pub start: usize,
    pub end: usize,
    pub children: Vec<NodeId>,
    pub field: Option<&'static str>,
    pub missing: bool,
    pub extra: bool,
}

#[derive(Clone, Debug, Default)]
pub struct Tree {
    pub nodes: Vec<Node>,
    pub root: NodeId,
}

