    pub fn node(&self, id: NodeId) -> &Node {
        &self.nodes[id as usize]
    }

    pub fn to_sexp(&self) -> String {
        let mut out = String::new();
        self.write_sexp(self.root, &mut out, None);
        out
    }

    fn write_sexp(&self, id: NodeId, out: &mut String, field: Option<&str>) {
        let n = self.node(id);
        let visible = n.named || n.missing;
        if visible {
            if !out.is_empty() {
                out.push(' ');
            }
            if let Some(f) = field {
                out.push_str(f);
                out.push_str(": ");
            }
            if n.missing {
                if n.named {
                    out.push_str(&format!("(MISSING {})", n.kind));
                } else {
                    out.push_str(&format!("(MISSING \"{}\")", n.kind));
                }
                return;
            }
            out.push('(');
            out.push_str(n.kind);
        }
        for &c in &n.children {
            let cn = self.node(c);
            self.write_sexp(c, out, cn.field);
        }
        if visible {
            out.push(')');
        }
    }
}
