//! Event-style tree builder with tree-sitter-like handling of extras (comments).

use super::{Node, NodeId, Tree};

#[derive(Clone, Copy, Debug)]
pub struct Marker(usize);

struct Frame {
    children: Vec<NodeId>,
    /// Position used for zero-width nodes when the frame has no children.
    pos: usize,
}

pub struct Builder {
    pub nodes: Vec<Node>,
    stack: Vec<Frame>,
    pending: Vec<NodeId>,
    /// End of the last consumed token.
    pub last_end: usize,
}

impl Default for Builder {
    fn default() -> Self {
        Self::new()
    }
}

impl Builder {
    pub fn new() -> Self {
        Builder {
            nodes: Vec::new(),
            stack: vec![Frame {
                children: Vec::new(),
                pos: 0,
            }],
            pending: Vec::new(),
            last_end: 0,
        }
    }

    fn push_child(&mut self, id: NodeId) {
        self.stack.last_mut().unwrap().children.push(id);
    }

    /// Move pending extras into the currently open node.
    pub fn flush_extras(&mut self) {
        let pending = std::mem::take(&mut self.pending);
        for p in pending {
            self.push_child(p);
        }
    }

    /// Move pending extras that start before `pos` into the current node.
    pub fn flush_extras_before(&mut self, pos: usize) {
        let pending = std::mem::take(&mut self.pending);
        for p in pending {
            if self.nodes[p as usize].start < pos {
                self.push_child(p);
            } else {
                self.pending.push(p);
            }
        }
    }

    pub fn has_pending(&self) -> bool {
        !self.pending.is_empty()
    }

    pub fn pending_starts(&self) -> Vec<usize> {
        self.pending.iter().map(|&p| self.nodes[p as usize].start).collect()
    }

    pub fn open(&mut self) -> Marker {
        self.flush_extras();
        let pos = self.last_end;
        self.stack.push(Frame {
            children: Vec::new(),
            pos,
        });
        Marker(self.stack.len() - 1)
    }

    /// Open a node that starts with an already-completed node.
    pub fn open_before(&mut self, child: NodeId) -> Marker {
        let top = self.stack.last_mut().unwrap();
        let idx = top.children.iter().rposition(|&c| c == child);
        let mut moved = Vec::new();
        if let Some(i) = idx {
            moved = top.children.split_off(i);
        }
        let pos = self.nodes[child as usize].start;
        self.stack.push(Frame {
            children: moved,
            pos,
        });
        Marker(self.stack.len() - 1)
    }

    pub fn depth(&self) -> usize {
        self.stack.len()
    }

    pub fn new_node(&mut self, kind: &'static str, named: bool, start: usize, end: usize) -> NodeId {
        let id = self.nodes.len() as NodeId;
        self.nodes.push(Node {
            kind,
            named,
            start,
            end,
            children: Vec::new(),
            field: None,
            missing: false,
            extra: false,
        });
        id
    }

    pub fn close(&mut self, m: Marker, kind: &'static str) -> NodeId {
        self.close_ex(m, kind, true)
    }

    pub fn close_ex(&mut self, m: Marker, kind: &'static str, named: bool) -> NodeId {
        // Close any frames above the marker first (defensive).
        while self.stack.len() - 1 > m.0 {
            let f = self.stack.pop().unwrap();
            let parent = self.stack.last_mut().unwrap();
            parent.children.extend(f.children);
        }
        let f = self.stack.pop().unwrap();
        let (start, end) = if f.children.is_empty() {
            (f.pos, f.pos)
        } else {
            let first = &self.nodes[f.children[0] as usize];
            let last = &self.nodes[*f.children.last().unwrap() as usize];
            (first.start, last.end)
        };
        let id = self.new_node(kind, named, start, end);
        self.nodes[id as usize].children = f.children;
        self.push_child(id);
        id
    }

    /// Drop a marker, splicing its children into the parent (no node created).
    pub fn abandon(&mut self, m: Marker) {
        while self.stack.len() - 1 >= m.0 {
            let f = self.stack.pop().unwrap();
            let parent = self.stack.last_mut().unwrap();
            parent.children.extend(f.children);
            if self.stack.len() - 1 < m.0 {
                break;
            }
        }
    }

    pub fn leaf(&mut self, kind: &'static str, named: bool, start: usize, end: usize) -> NodeId {
        self.flush_extras();
        let id = self.new_node(kind, named, start, end);
        self.push_child(id);
        if end > self.last_end || start >= self.last_end {
            self.last_end = end;
        }
        id
    }

    pub fn missing(&mut self, kind: &'static str, named: bool) -> NodeId {
        let pos = self.last_end;
        let id = self.new_node(kind, named, pos, pos);
        self.nodes[id as usize].missing = true;
        self.push_child(id);
        id
    }

    pub fn extra(&mut self, kind: &'static str, start: usize, end: usize) -> NodeId {
        let id = self.new_node(kind, true, start, end);
        self.nodes[id as usize].extra = true;
        self.pending.push(id);
        if end > self.last_end {
            self.last_end = end;
        }
        id
    }

    pub fn set_field(&mut self, id: NodeId, field: &'static str) {
        self.nodes[id as usize].field = Some(field);
    }

    /// Last child id of the currently open node.
    pub fn last_child(&self) -> Option<NodeId> {
        self.stack.last().unwrap().children.last().copied()
    }

    pub fn current_children(&self) -> &[NodeId] {
        &self.stack.last().unwrap().children
    }

    pub fn kind(&self, id: NodeId) -> &'static str {
        self.nodes[id as usize].kind
    }

    pub fn set_kind(&mut self, id: NodeId, kind: &'static str) {
        self.nodes[id as usize].kind = kind;
    }

    /// Finish: wrap everything into a root node spanning to `src_len`.
    pub fn finish(mut self, root_kind: &'static str, src_len: usize) -> Tree {
        self.flush_extras();
        while self.stack.len() > 1 {
            let f = self.stack.pop().unwrap();
            let parent = self.stack.last_mut().unwrap();
            parent.children.extend(f.children);
        }
        let f = self.stack.pop().unwrap();
        let start = f
            .children
            .first()
            .map(|&c| self.nodes[c as usize].start)
            .unwrap_or(src_len);
        let start = start.min(src_len);
        let id = self.new_node(root_kind, true, start, src_len);
        self.nodes[id as usize].children = f.children;
        Tree {
            nodes: self.nodes,
            root: id,
        }
    }
}
