//! A tree-sitter compatible query language subset: parsing, validation and matching.

use super::{NodeId, Tree};
use std::collections::HashMap;

pub struct LangInfo {
    pub named: &'static [&'static str],
    pub anon: &'static [&'static str],
    pub fields: &'static [&'static str],
    /// Supertype name -> member kinds.
    pub supertypes: &'static [(&'static str, &'static [&'static str])],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Quant {
    One,
    ZeroOrOne,
    ZeroOrMore,
    OneOrMore,
}

#[derive(Debug, Clone)]
enum KindMatch {
    Named(String),
    AnyNamed,
    Any,
    Anon(String),
    Error,
    Missing(Option<String>),
}

#[derive(Debug, Clone)]
enum PatKind {
    Node {
        kind: KindMatch,
        supertype: Option<String>,
        children: Vec<Child>,
        negated: Vec<String>,
    },
    Alt(Vec<Pat>),
    Seq(Vec<Child>),
}

#[derive(Debug, Clone)]
struct Pat {
    kind: PatKind,
    quant: Quant,
    captures: Vec<usize>,
}

#[derive(Debug, Clone)]
struct Child {
    pat: Pat,
    field: Option<String>,
    anchor_before: bool,
    anchor_after: bool,
}

#[derive(Debug, Clone)]
enum PredArg {
    Capture(usize),
    Str(String),
}

#[derive(Debug, Clone)]
enum Predicate {
    Eq { cap: usize, other: PredArg, positive: bool, all: bool },
    Match { cap: usize, re: regex::Regex, positive: bool, all: bool },
    AnyOf { cap: usize, values: Vec<String>, positive: bool },
}

#[derive(Debug, Clone)]
struct Pattern {
    root: Pat,
    predicates: Vec<Predicate>,
}

#[derive(Debug)]
pub struct Query {
    patterns: Vec<Pattern>,
    pub capture_names: Vec<String>,
    disabled: Vec<bool>,
}

#[derive(Debug, Clone)]
pub struct QueryError {
    pub row: usize,
    pub column: usize,
    pub kind: &'static str,
    pub message: String,
}

impl std::fmt::Display for QueryError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "Query error at {}:{}. {}{}",
            self.row + 1,
            self.column + 1,
            self.kind,
            self.message
        )
    }
}

struct Parser<'a> {
    src: &'a str,
    pos: usize,
    info: &'a LangInfo,
    capture_names: Vec<String>,
}

fn is_ident_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '-' || c == '.' || c == '?' || c == '!'
}

impl<'a> Parser<'a> {
    fn row_col(&self, offset: usize) -> (usize, usize) {
        let before = &self.src[..offset.min(self.src.len())];
        let row = before.matches('\n').count();
        let col = before.len() - before.rfind('\n').map(|i| i + 1).unwrap_or(0);
        (row, col)
    }

    fn err_syntax(&self, offset: usize) -> QueryError {
        self.err_with_line(offset, "Invalid syntax:\n")
    }

    fn err_with_line(&self, offset: usize, kind: &'static str) -> QueryError {
        let (row, col) = self.row_col(offset);
        let line_start = self.src[..offset.min(self.src.len())]
            .rfind('\n')
            .map(|i| i + 1)
            .unwrap_or(0);
        let line_end = self.src[line_start..]
            .find('\n')
            .map(|i| line_start + i)
            .unwrap_or(self.src.len());
        let line = &self.src[line_start..line_end];
        QueryError {
            row,
            column: col,
            kind,
            message: format!("{}\n{}^", line, " ".repeat(col)),
        }
    }

    fn err_name(&self, offset: usize, kind: &'static str) -> QueryError {
        let (row, col) = self.row_col(offset);
        let name: String = self.src[offset..].chars().take_while(|&c| is_ident_char(c)).collect();
        QueryError {
            row,
            column: col,
            kind,
            message: name,
        }
    }

    fn peek(&self) -> Option<char> {
        self.src[self.pos..].chars().next()
    }

    fn peek2(&self) -> Option<char> {
        let mut it = self.src[self.pos..].chars();
        it.next();
        it.next()
    }

    fn skip_ws(&mut self) {
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => self.pos += c.len_utf8(),
                Some(';') => {
                    while let Some(c) = self.peek() {
                        self.pos += c.len_utf8();
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    fn ident(&mut self) -> String {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if is_ident_char(c) {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
        self.src[start..self.pos].to_string()
    }

    fn string(&mut self) -> Result<String, QueryError> {
        // at opening quote
        self.pos += 1;
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(self.err_syntax(self.pos)),
                Some('"') => {
                    self.pos += 1;
                    break;
                }
                Some('\\') => {
                    self.pos += 1;
                    match self.peek() {
                        None => return Err(self.err_syntax(self.pos)),
                        Some(c) => {
                            self.pos += c.len_utf8();
                            match c {
                                'n' => out.push('\n'),
                                'r' => out.push('\r'),
                                't' => out.push('\t'),
                                '0' => out.push('\0'),
                                other => out.push(other),
                            }
                        }
                    }
                }
                Some('\n') => return Err(self.err_syntax(self.pos)),
                Some(c) => {
                    self.pos += c.len_utf8();
                    out.push(c);
                }
            }
        }
        Ok(out)
    }

    fn capture_id(&mut self, name: &str) -> usize {
        if let Some(i) = self.capture_names.iter().position(|n| n == name) {
            i
        } else {
            self.capture_names.push(name.to_string());
            self.capture_names.len() - 1
        }
    }

    fn is_field(&self, name: &str) -> bool {
        self.info.fields.contains(&name)
    }

    fn check_named(&self, name: &str, offset: usize) -> Result<(), QueryError> {
        if name == "_" || name == "ERROR" || name == "MISSING" {
            return Ok(());
        }
        if self.info.named.contains(&name) || self.info.supertypes.iter().any(|(s, _)| *s == name) {
            Ok(())
        } else {
            Err(self.err_name(offset, "Invalid node type "))
        }
    }

    /// Parse suffixes: quantifiers and captures.
    fn suffixes(&mut self, pat: &mut Pat) -> Result<(), QueryError> {
        loop {
            self.skip_ws();
            match self.peek() {
                Some('*') => {
                    self.pos += 1;
                    pat.quant = Quant::ZeroOrMore;
                }
                Some('+') => {
                    self.pos += 1;
                    pat.quant = Quant::OneOrMore;
                }
                Some('?') => {
                    self.pos += 1;
                    pat.quant = Quant::ZeroOrOne;
                }
                Some('@') => {
                    self.pos += 1;
                    let start = self.pos;
                    let name = self.ident();
                    if name.is_empty() {
                        return Err(self.err_syntax(start));
                    }
                    let id = self.capture_id(&name);
                    pat.captures.push(id);
                }
                _ => break,
            }
        }
        Ok(())
    }

    /// Parse one pattern. Returns None if a predicate was parsed instead (added to `preds`).
    fn pattern(
        &mut self,
        preds: &mut Vec<(usize, String, Vec<(PredArg, usize)>)>,
    ) -> Result<Option<Pat>, QueryError> {
        self.skip_ws();
        let start = self.pos;
        let c = match self.peek() {
            Some(c) => c,
            None => return Err(self.err_syntax(self.pos)),
        };
        let mut pat = match c {
            '[' => {
                self.pos += 1;
                let mut alts = Vec::new();
                loop {
                    self.skip_ws();
                    match self.peek() {
                        Some(']') => {
                            self.pos += 1;
                            break;
                        }
                        None => return Err(self.err_syntax(self.pos)),
                        _ => {}
                    }
                    match self.pattern(preds)? {
                        Some(p) => alts.push(p),
                        None => {}
                    }
                }
                if alts.is_empty() {
                    return Err(self.err_syntax(self.pos - 1));
                }
                Pat { kind: PatKind::Alt(alts), quant: Quant::One, captures: vec![] }
            }
            '"' => {
                let off = self.pos + 1;
                let s = self.string()?;
                if !self.info.anon.contains(&s.as_str()) {
                    let (row, col) = self.row_col(off);
                    return Err(QueryError { row, column: col, kind: "Invalid node type ", message: s });
                }
                Pat { kind: PatKind::Node { kind: KindMatch::Anon(s), supertype: None, children: vec![], negated: vec![] }, quant: Quant::One, captures: vec![] }
            }
            '_' if !self.peek2().map(is_ident_char).unwrap_or(false) => {
                self.pos += 1;
                Pat { kind: PatKind::Node { kind: KindMatch::Any, supertype: None, children: vec![], negated: vec![] }, quant: Quant::One, captures: vec![] }
            }
            '(' => {
                self.pos += 1;
                self.skip_ws();
                match self.peek() {
                    Some('#') => {
                        self.pos += 1;
                        let name = self.ident();
                        let mut args = Vec::new();
                        loop {
                            self.skip_ws();
                            match self.peek() {
                                Some(')') => {
                                    self.pos += 1;
                                    break;
                                }
                                Some('@') => {
                                    self.pos += 1;
                                    let off = self.pos;
                                    let n = self.ident();
                                    match self.capture_names.iter().position(|x| *x == n) {
                                        Some(i) => args.push((PredArg::Capture(i), off)),
                                        None => return Err(self.err_name(off, "Invalid capture name ")),
                                    }
                                }
                                Some('"') => {
                                    let off = self.pos;
                                    let s = self.string()?;
                                    args.push((PredArg::Str(s), off));
                                }
                                Some(c) if is_ident_char(c) => {
                                    let off = self.pos;
                                    let s = self.ident();
                                    args.push((PredArg::Str(s), off));
                                }
                                _ => return Err(self.err_syntax(self.pos)),
                            }
                        }
                        preds.push((start, name, args));
                        return Ok(None);
                    }
                    Some('(') | Some('[') | Some('"') | Some('.') => {
                        // grouped sequence
                        let items = self.children(preds, start)?;
                        Pat { kind: PatKind::Seq(items), quant: Quant::One, captures: vec![] }
                    }
                    Some(c) if is_ident_char(c) => {
                        let off = self.pos;
                        let mut name = self.ident();
                        let mut supertype = None;
                        if self.peek() == Some('/') {
                            self.pos += 1;
                            let sub_off = self.pos;
                            let sub = self.ident();
                            self.check_named(&name, off)?;
                            self.check_named(&sub, sub_off)?;
                            supertype = Some(name);
                            name = sub;
                        } else {
                            self.check_named(&name, off)?;
                        }
                        let kind = match name.as_str() {
                            "_" => KindMatch::AnyNamed,
                            "ERROR" => KindMatch::Error,
                            "MISSING" => {
                                self.skip_ws();
                                let inner = match self.peek() {
                                    Some('"') => Some(self.string()?),
                                    Some(c) if is_ident_char(c) => Some(self.ident()),
                                    _ => None,
                                };
                                KindMatch::Missing(inner)
                            }
                            _ => KindMatch::Named(name),
                        };
                        let mut negated = Vec::new();
                        let items = self.children_ex(preds, start, Some(&mut negated))?;
                        Pat { kind: PatKind::Node { kind, supertype, children: items, negated }, quant: Quant::One, captures: vec![] }
                    }
                    _ => return Err(self.err_syntax(self.pos)),
                }
            }
            _ => return Err(self.err_syntax(self.pos)),
        };
        self.suffixes(&mut pat)?;
        Ok(Some(pat))
    }

    fn children(
        &mut self,
        preds: &mut Vec<(usize, String, Vec<(PredArg, usize)>)>,
        start: usize,
    ) -> Result<Vec<Child>, QueryError> {
        self.children_ex(preds, start, None)
    }

    fn children_ex(
        &mut self,
        preds: &mut Vec<(usize, String, Vec<(PredArg, usize)>)>,
        _start: usize,
        mut negated: Option<&mut Vec<String>>,
    ) -> Result<Vec<Child>, QueryError> {
        let mut items: Vec<Child> = Vec::new();
        let mut anchor = false;
        loop {
            self.skip_ws();
            match self.peek() {
                None => return Err(self.err_syntax(self.pos)),
                Some(')') => {
                    self.pos += 1;
                    if anchor {
                        if let Some(last) = items.last_mut() {
                            last.anchor_after = true;
                        }
                    }
                    break;
                }
                Some('.') => {
                    self.pos += 1;
                    anchor = true;
                    continue;
                }
                Some('!') => {
                    self.pos += 1;
                    let off = self.pos;
                    let f = self.ident();
                    if !self.is_field(&f) {
                        return Err(self.err_name(off, "Invalid field name "));
                    }
                    match negated.as_mut() {
                        Some(n) => n.push(f),
                        None => return Err(self.err_syntax(off)),
                    }
                    continue;
                }
                _ => {}
            }
            // field?
            let save = self.pos;
            let mut field = None;
            if let Some(c) = self.peek() {
                if is_ident_char(c) && c != '_' || (c == '_' && self.peek2().map(is_ident_char).unwrap_or(false)) {
                    let off = self.pos;
                    let name = self.ident();
                    self.skip_ws();
                    if self.peek() == Some(':') {
                        self.pos += 1;
                        if !self.is_field(&name) {
                            return Err(self.err_name(off, "Invalid field name "));
                        }
                        field = Some(name);
                    } else {
                        self.pos = save;
                        return Err(self.err_syntax(save));
                    }
                }
            }
            match self.pattern(preds)? {
                Some(p) => {
                    items.push(Child { pat: p, field, anchor_before: anchor, anchor_after: false });
                    anchor = false;
                }
                None => {}
            }
        }
        Ok(items)
    }
}

type Bindings = Vec<(usize, NodeId)>;

struct Matcher<'a> {
    tree: &'a Tree,
    info: &'a LangInfo,
    budget: std::cell::Cell<usize>,
}

impl<'a> Matcher<'a> {
    fn kind_ok(&self, km: &KindMatch, supertype: &Option<String>, id: NodeId) -> bool {
        let n = self.tree.node(id);
        let base = match km {
            KindMatch::Named(k) => {
                if n.named && n.kind == k {
                    true
                } else if n.named {
                    // supertype match
                    self.info
                        .supertypes
                        .iter()
                        .any(|(s, members)| s == k && members.contains(&n.kind))
                } else {
                    false
                }
            }
            KindMatch::AnyNamed => n.named,
            KindMatch::Any => true,
            KindMatch::Anon(s) => !n.named && n.kind == s,
            KindMatch::Error => n.kind == "ERROR",
            KindMatch::Missing(k) => n.missing && k.as_ref().map(|k| k == n.kind).unwrap_or(true),
        };
        if !base {
            return false;
        }
        if let Some(st) = supertype {
            return self
                .info
                .supertypes
                .iter()
                .any(|(s, members)| s == st && members.contains(&n.kind));
        }
        true
    }

    /// Match a single pattern (ignoring its quantifier) against node `id`.
    fn match_node(&self, pat: &Pat, id: NodeId) -> Vec<Bindings> {
        let b = self.budget.get();
        if b == 0 {
            return vec![];
        }
        self.budget.set(b - 1);
        let mut results = match &pat.kind {
            PatKind::Node { kind, supertype, children, negated } => {
                if !self.kind_ok(kind, supertype, id) {
                    return vec![];
                }
                let n = self.tree.node(id);
                for f in negated {
                    if n.children.iter().any(|&c| self.tree.node(c).field == Some(f.as_str())) {
                        return vec![];
                    }
                }
                if children.is_empty() {
                    vec![vec![]]
                } else {
                    self.match_seq(children, &n.children, 0, 0, None, true)
                }
            }
            PatKind::Alt(alts) => {
                let mut out = Vec::new();
                for a in alts {
                    for r in self.match_node(a, id) {
                        out.push(r);
                    }
                }
                out
            }
            PatKind::Seq(_) => vec![],
        };
        if !pat.captures.is_empty() {
            for r in results.iter_mut() {
                for &c in &pat.captures {
                    r.push((c, id));
                }
            }
        }
        results
    }

    fn is_named(&self, id: NodeId) -> bool {
        self.tree.node(id).named
    }

    /// Match child items starting at item `i` against siblings starting at `pos`.
    /// `last` is the index of the previously matched sibling (for anchors).
    fn match_seq(
        &self,
        items: &[Child],
        sibs: &[NodeId],
        i: usize,
        pos: usize,
        last: Option<usize>,
        first: bool,
    ) -> Vec<Bindings> {
        if i == items.len() {
            return vec![vec![]];
        }
        let item = &items[i];
        let mut out: Vec<Bindings> = Vec::new();
        let anchor_ok = |j: usize| -> bool {
            if item.anchor_before {
                let from = match last {
                    Some(l) => l + 1,
                    None => {
                        if first {
                            0
                        } else {
                            pos
                        }
                    }
                };
                if from <= j && sibs[from..j].iter().any(|&s| self.is_named(s)) {
                    return false;
                }
            }
            if item.anchor_after && i + 1 == items.len() {
                if sibs[j + 1..].iter().any(|&s| self.is_named(s)) {
                    return false;
                }
            }
            true
        };
        let field_ok = |j: usize| -> bool {
            match &item.field {
                Some(f) => self.tree.node(sibs[j]).field == Some(f.as_str()),
                None => true,
            }
        };
        let single = |j: usize| -> Vec<Bindings> {
            if !field_ok(j) {
                return vec![];
            }
            match &item.pat.kind {
                PatKind::Seq(sub) => {
                    // nested sequence: match within siblings from j
                    let _ = sub;
                    vec![]
                }
                _ => self.match_node(&item.pat, sibs[j]),
            }
        };

        // Nested grouped sequences inside a parent: flatten semantics.
        if let PatKind::Seq(sub) = &item.pat.kind {
            let mut flat: Vec<Child> = sub.clone();
            for c in flat.iter_mut() {
                for &cap in &item.pat.captures {
                    c.pat.captures.push(cap);
                }
            }
            flat.extend(items[i + 1..].iter().cloned());
            if matches!(item.pat.quant, Quant::ZeroOrOne | Quant::ZeroOrMore) {
                out.extend(self.match_seq(items, sibs, i + 1, pos, last, first));
            }
            out.extend(self.match_seq(&flat, sibs, 0, pos, last, first));
            return out;
        }

        match item.pat.quant {
            Quant::One | Quant::ZeroOrOne => {
                if item.pat.quant == Quant::ZeroOrOne {
                    out.extend(self.match_seq(items, sibs, i + 1, pos, last, first));
                }
                for j in pos..sibs.len() {
                    if !anchor_ok(j) {
                        if item.anchor_before {
                            // anchored: later positions won't be ok either if named nodes intervene
                            continue;
                        }
                        continue;
                    }
                    let here = single(j);
                    if here.is_empty() {
                        continue;
                    }
                    let rest = self.match_seq(items, sibs, i + 1, j + 1, Some(j), false);
                    for h in &here {
                        for r in &rest {
                            let mut b = h.clone();
                            b.extend(r.iter().cloned());
                            out.push(b);
                        }
                    }
                    if self.budget.get() == 0 {
                        break;
                    }
                }
            }
            Quant::ZeroOrMore | Quant::OneOrMore => {
                if item.pat.quant == Quant::ZeroOrMore {
                    out.extend(self.match_seq(items, sibs, i + 1, pos, last, first));
                }
                // take all matching siblings in [pos, cut)
                let mut acc: Bindings = Vec::new();
                let mut count = 0;
                let mut last_j = None;
                for j in pos..sibs.len() {
                    let here = single(j);
                    if here.is_empty() {
                        continue;
                    }
                    if count == 0 && !anchor_ok(j) {
                        continue;
                    }
                    for h in &here {
                        acc.extend(h.iter().cloned());
                    }
                    count += 1;
                    last_j = Some(j);
                    let rest = self.match_seq(items, sibs, i + 1, j + 1, last_j, false);
                    for r in &rest {
                        let mut b = acc.clone();
                        b.extend(r.iter().cloned());
                        out.push(b);
                    }
                    if self.budget.get() == 0 {
                        break;
                    }
                }
            }
        }
        out
    }
}

impl Query {
    pub fn new(src: &str, info: &LangInfo) -> Result<Query, QueryError> {
        let mut p = Parser { src, pos: 0, info, capture_names: Vec::new() };
        let mut patterns: Vec<(usize, Pat, Vec<(usize, String, Vec<(PredArg, usize)>)>)> = Vec::new();
        loop {
            p.skip_ws();
            if p.pos >= src.len() {
                break;
            }
            let start = p.pos;
            let mut preds = Vec::new();
            let pat = p.pattern(&mut preds)?;
            match pat {
                Some(pat) => patterns.push((start, pat, preds)),
                None => {
                    // a top-level predicate forms its own (empty) pattern
                    patterns.push((
                        start,
                        Pat { kind: PatKind::Seq(vec![]), quant: Quant::One, captures: vec![] },
                        preds,
                    ));
                }
            }
        }
        let mut out = Vec::new();
        for (start, pat, preds) in patterns {
            let (row, _) = p.row_col(start);
            let perr = |msg: String| QueryError { row, column: 0, kind: "Invalid predicate: ", message: msg };
            let mut predicates = Vec::new();
            for (_off, name, args) in preds {
                let nargs = args.len();
                match name.as_str() {
                    "eq?" | "not-eq?" | "any-eq?" | "any-not-eq?" => {
                        if nargs != 2 {
                            return Err(perr(format!("Wrong number of arguments to #{name} predicate. Expected 2, got {}.", nargs)));
                        }
                        let cap = match &args[0].0 {
                            PredArg::Capture(c) => *c,
                            PredArg::Str(s) => return Err(perr(format!("First argument to #{name} predicate must be a capture name. Got literal \"{s}\"."))),
                        };
                        predicates.push(Predicate::Eq {
                            cap,
                            other: args[1].0.clone(),
                            positive: !name.contains("not-"),
                            all: !name.starts_with("any-"),
                        });
                    }
                    "match?" | "not-match?" | "any-match?" | "any-not-match?" => {
                        if nargs != 2 {
                            return Err(perr(format!("Wrong number of arguments to #{name} predicate. Expected 2, got {}.", nargs)));
                        }
                        let cap = match &args[0].0 {
                            PredArg::Capture(c) => *c,
                            PredArg::Str(s) => return Err(perr(format!("First argument to #{name} predicate must be a capture name. Got literal \"{s}\"."))),
                        };
                        let re_src = match &args[1].0 {
                            PredArg::Str(s) => s.clone(),
                            PredArg::Capture(c) => return Err(perr(format!("Second argument to #{name} predicate must be a literal. Got capture @{}.", p.capture_names[*c]))),
                        };
                        let re = regex::Regex::new(&re_src).map_err(|_| perr(format!("Invalid regex '{re_src}'")))?;
                        predicates.push(Predicate::Match {
                            cap,
                            re,
                            positive: !name.contains("not-"),
                            all: !name.starts_with("any-"),
                        });
                    }
                    "any-of?" | "not-any-of?" => {
                        if nargs < 1 {
                            return Err(perr(format!("Wrong number of arguments to #any-of? predicate. Expected at least 1, got {}.", nargs)));
                        }
                        let cap = match &args[0].0 {
                            PredArg::Capture(c) => *c,
                            PredArg::Str(s) => return Err(perr(format!("First argument to #any-of? predicate must be a capture name. Got literal \"{s}\"."))),
                        };
                        let mut values = Vec::new();
                        for a in &args[1..] {
                            match &a.0 {
                                PredArg::Str(s) => values.push(s.clone()),
                                PredArg::Capture(c) => return Err(perr(format!("Arguments to #any-of? predicate must be literals. Got capture @{}.", p.capture_names[*c]))),
                            }
                        }
                        predicates.push(Predicate::AnyOf { cap, values, positive: name == "any-of?" });
                    }
                    "is?" | "is-not?" | "set!" => {
                        if nargs == 0 {
                            return Err(perr(format!("Invalid arguments to {} predicate. Missing key argument", name.trim_start_matches('#'))));
                        }
                    }
                    _ => {}
                }
            }
            out.push(Pattern { root: pat, predicates });
        }
        let n = p.capture_names.len();
        Ok(Query { patterns: out, capture_names: p.capture_names, disabled: vec![false; n] })
    }

    pub fn disable_capture(&mut self, name: &str) {
        for (i, n) in self.capture_names.iter().enumerate() {
            if n == name {
                self.disabled[i] = true;
            }
        }
    }

    fn check_predicates(&self, pat: &Pattern, b: &Bindings, tree: &Tree, src: &str) -> bool {
        let text = |id: NodeId| {
            let n = tree.node(id);
            &src[n.start..n.end]
        };
        let nodes_of = |cap: usize| -> Vec<NodeId> {
            b.iter().filter(|(c, _)| *c == cap).map(|(_, n)| *n).collect()
        };
        for pred in &pat.predicates {
            match pred {
                Predicate::Eq { cap, other, positive, all } => {
                    let nodes = nodes_of(*cap);
                    let check = |id: NodeId| -> bool {
                        let t = text(id);
                        let eq = match other {
                            PredArg::Str(s) => t == s,
                            PredArg::Capture(c2) => {
                                let others = nodes_of(*c2);
                                others.iter().all(|&o| text(o) == t) && !others.is_empty()
                            }
                        };
                        eq == *positive
                    };
                    let ok = if *all {
                        nodes.iter().all(|&n| check(n))
                    } else {
                        nodes.iter().any(|&n| check(n))
                    };
                    if !ok {
                        return false;
                    }
                }
                Predicate::Match { cap, re, positive, all } => {
                    let nodes = nodes_of(*cap);
                    let check = |id: NodeId| re.is_match(text(id)) == *positive;
                    let ok = if *all {
                        nodes.iter().all(|&n| check(n))
                    } else {
                        nodes.iter().any(|&n| check(n))
                    };
                    if !ok {
                        return false;
                    }
                }
                Predicate::AnyOf { cap, values, positive } => {
                    let nodes = nodes_of(*cap);
                    let ok = nodes
                        .iter()
                        .all(|&n| values.iter().any(|v| v == text(n)) == *positive);
                    if !ok {
                        return false;
                    }
                }
            }
        }
        true
    }

    /// Run the query; returns (capture id, node id) pairs (deduplicated).
    pub fn captures(&self, tree: &Tree, src: &str, info: &LangInfo) -> Vec<(usize, NodeId)> {
        let m = Matcher { tree, info, budget: std::cell::Cell::new(5_000_000) };
        let mut seen: HashMap<(usize, NodeId), ()> = HashMap::new();
        let mut out = Vec::new();
        let n_nodes = tree.nodes.len() as NodeId;
        // Nodes reachable from root in pre-order
        let mut order = Vec::with_capacity(n_nodes as usize);
        let mut stack = vec![tree.root];
        while let Some(id) = stack.pop() {
            order.push(id);
            for &c in tree.node(id).children.iter().rev() {
                stack.push(c);
            }
        }
        for pat in &self.patterns {
            let mut add = |b: Bindings, out: &mut Vec<(usize, NodeId)>| {
                if !self.check_predicates(pat, &b, tree, src) {
                    return;
                }
                for (c, n) in b {
                    if self.disabled[c] {
                        continue;
                    }
                    if seen.insert((c, n), ()).is_none() {
                        out.push((c, n));
                    }
                }
            };
            match &pat.root.kind {
                PatKind::Seq(items) => {
                    if items.is_empty() {
                        continue;
                    }
                    for &id in &order {
                        let sibs = &tree.node(id).children;
                        for start in 0..sibs.len() {
                            let res = m.match_seq(items, sibs, 0, start, None, false);
                            // require first item to match at `start` to avoid duplicates
                            for b in res {
                                add(b, &mut out);
                            }
                        }
                    }
                }
                _ => {
                    for &id in &order {
                        for b in m.match_node(&pat.root, id) {
                            add(b, &mut out);
                        }
                    }
                }
            }
        }
        out
    }
}
EOF
echo ok"}

