    "@=", ":=", "==", "!=", "<=", ">=", "<>", "**", "//", "<<", ">>", "+", "-", "*", "/", "%",
    "@", "&", "|", "^", "~", "<", ">", "(", ")", "[", "]", "{", "}", ",", ":", ";", ".", "=",
    "!",
];

const KEYWORDS: &[&str] = &[
    "False", "None", "True", "and", "as", "assert", "async", "await", "break", "class",
    "continue", "def", "del", "elif", "else", "except", "finally", "for", "from", "global", "if",
    "import", "in", "is", "lambda", "nonlocal", "not", "or", "pass", "raise", "return", "try",
    "while", "with", "yield",
];

// Precedences (tree-sitter-python)
const P_OR: u8 = 10;
const P_BOR: u8 = 14;
const P_BAND: u8 = 15;
const P_XOR: u8 = 16;
const P_SHIFT: u8 = 17;
const P_PLUS: u8 = 18;
const P_TIMES: u8 = 19;
const P_UNARY: u8 = 20;
const P_POWER: u8 = 21;

fn binop_prec(op: &str) -> Option<(u8, bool)> {
    Some(match op {
        "+" | "-" => (P_PLUS, false),
        "*" | "@" | "/" | "%" | "//" => (P_TIMES, false),
        "**" => (P_POWER, true),
        "|" => (P_BOR, false),
        "&" => (P_BAND, false),
        "^" => (P_XOR, false),
        "<<" | ">>" => (P_SHIFT, false),
        _ => return None,
    })
}

const AUG_OPS: &[&str] = &[
    "+=", "-=", "*=", "/=", "@=", "//=", "%=", "**=", ">>=", "<<=", "&=", "^=", "|=",
];

struct Scan {
    found_eol: bool,
    indent: usize,
    first_comment: i64,
}

pub struct Py<'a> {
    src: &'a str,
    by: &'a [u8],
    b: Builder,
    pos: usize,
    tok: Option<Tok>,
    indents: Vec<usize>,
    depth: usize,
    /// Stop characters for interpolation parsing.
    in_interp: usize,
}

fn is_id_start(c: char) -> bool {
    c == '_' || c.is_alphabetic()
}
fn is_id_cont(c: char) -> bool {
    c == '_' || c.is_alphanumeric()
}

pub fn parse(src: &str) -> Tree {
    let mut p = Py {
        src,
        by: src.as_bytes(),
        b: Builder::new(),
        pos: 0,
        tok: None,
        indents: vec![0],
        depth: 0,
        in_interp: 0,
    };
    p.module();
    p.b.finish("module", src.len())
}

impl<'a> Py<'a> {
    // ------------------------------------------------------------------ lexing
    fn ch(&self, i: usize) -> Option<char> {
        self.src.get(i..).and_then(|s| s.chars().next())
    }

    fn text(&self, t: Tok) -> &'a str {
        &self.src[t.s..t.e]
    }

    /// Skip inline whitespace and comments; stops at newline (depth 0).
    fn skip_trivia(&mut self) {
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return,
            };
            match c {
                ' ' | '\t' | '\x0c' | '\r' | '\u{feff}' | '\u{2060}' | '\u{200b}' => {
                    self.pos += c.len_utf8()
                }
                '\n' if self.depth > 0 => self.pos += 1,
                '#' => {
                    let s = self.pos;
                    let mut e = s;
                    while e < self.by.len() && self.by[e] != b'\n' {
                        e += 1;
                    }
                    // exclude trailing \r
                    let mut ce = e;
                    if ce > s && self.by[ce - 1] == b'\r' {
                        ce -= 1;
                    }
                    self.b.extra("comment", s, ce);
                    self.pos = e;
                }
                '\\' => {
                    let s = self.pos;
                    let mut e = s + 1;
                    if e < self.by.len() && self.by[e] == b'\r' {
                        e += 1;
                    }
                    if e < self.by.len() && self.by[e] == b'\n' {
                        e += 1;
                        self.b.extra("line_continuation", s, e);
                        self.pos = e;
                    } else if e >= self.by.len() {
                        self.b.extra("line_continuation", s, e.min(self.by.len()));
                        self.pos = e.min(self.by.len());
                    } else {
                        return;
                    }
                }
                _ => return,
            }
        }
    }

    fn lex(&mut self) -> Tok {
        let s = self.pos;
        let c = match self.ch(s) {
            None => return Tok { k: TK::Eof, s, e: s },
            Some(c) => c,
        };
        if c == '\n' {
            return Tok { k: TK::LineEnd, s, e: s };
        }
        // strings
        if let Some(q) = self.string_prefix_len(s) {
            let _ = q;
            return Tok { k: TK::Str, s, e: s };
        }
        if is_id_start(c) {
            let mut e = s;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            return Tok { k: TK::Name, s, e };
        }
        if c.is_ascii_digit() || (c == '.' && self.ch(s + 1).map(|d| d.is_ascii_digit()).unwrap_or(false)) {
            return self.lex_number(s);
        }
        for op in OPS {
            if self.src[s..].starts_with(op) {
                return Tok { k: TK::Op, s, e: s + op.len() };
            }
        }
        Tok { k: TK::Err, s, e: s + c.len_utf8() }
    }

    fn lex_number(&self, s: usize) -> Tok {
        let by = self.by;
        let mut e = s;
        let mut float = false;
        let lower = |i: usize| by.get(i).map(|b| b.to_ascii_lowercase());
        if by[e] == b'0' && matches!(lower(e + 1), Some(b'x') | Some(b'o') | Some(b'b')) {
            e += 2;
            while e < by.len() && (by[e].is_ascii_hexdigit() || by[e] == b'_') {
                e += 1;
            }
        } else {
            while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                e += 1;
            }
            if e < by.len() && by[e] == b'.' {
                // not an attribute access like 1..x? keep simple
                float = true;
                e += 1;
                while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                    e += 1;
                }
            }
            if e < by.len() && (by[e] == b'e' || by[e] == b'E') {
                let mut f = e + 1;
                if f < by.len() && (by[f] == b'+' || by[f] == b'-') {
                    f += 1;
                }
                if f < by.len() && by[f].is_ascii_digit() {
                    float = true;
                    e = f;
                    while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                        e += 1;
                    }
                }
            }
        }
        if e < by.len() && matches!(by[e], b'j' | b'J' | b'l' | b'L') {
            e += 1;
        }
        Tok { k: if float { TK::Float } else { TK::Int }, s, e }
    }

    /// If a string starts at `s`, return the length of prefix+quotes.
    fn string_prefix_len(&self, s: usize) -> Option<usize> {
        let by = self.by;
        let mut i = s;
        while i < by.len() && i - s < 3 && matches!(by[i].to_ascii_lowercase(), b'r' | b'b' | b'u' | b'f') {
            i += 1;
        }
        if i < by.len() && (by[i] == b'"' || by[i] == b'\'') {
            let q = by[i];
            if i + 2 < by.len() && by[i + 1] == q && by[i + 2] == q {
                return Some(i + 3 - s);
            }
            return Some(i + 1 - s);
        }
        None
    }

    fn peek(&mut self) -> Tok {
        if let Some(t) = self.tok {
            return t;
        }
        self.skip_trivia();
        let t = self.lex();
        self.tok = Some(t);
        t
    }

    fn peek_text(&mut self) -> &'a str {
        let t = self.peek();
        self.text(t)
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        matches!(t.k, TK::Op | TK::Name) && self.text(t) == s
    }

    fn at_kw(&mut self, s: &str) -> bool {
        let t = self.peek();
        t.k == TK::Name && self.text(t) == s
    }

    /// Lookahead at the token after the current one (approximate, no side effects).
    fn peek2_text(&mut self) -> &'a str {
        let t = self.peek();
        let save_pos = self.pos;
        let save_tok = self.tok;
        // lex without emitting extras
        let mut i = t.e;
        while i < self.by.len() && matches!(self.by[i], b' ' | b'\t') {
            i += 1;
        }
        self.pos = i;
        let t2 = self.lex();
        self.pos = save_pos;
        self.tok = save_tok;
        if t2.k == TK::Str {
            return "\"";
        }
        self.text(t2)
    }

    fn bump_as(&mut self, kind: &'static str, named: bool) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        match self.text(t) {
            "(" | "[" | "{" => self.depth += 1,
            ")" | "]" | "}" => self.depth = self.depth.saturating_sub(1),
            _ => {}
        }
        id
    }

    /// Bump an anonymous token (keyword/operator).
    fn bump(&mut self) -> NodeId {
        let t = self.peek();
        let kind = intern(self.text(t));
        self.bump_as(kind, false)
    }

    fn expect(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            self.b.missing(intern(s), false);
            false
        }
    }

    // --------------------------------------------------------- indentation
    fn scan(&self) -> Scan {
        let by = self.by;
        let mut i = self.pos;
        let mut found_eol = false;
        let mut indent = 0usize;
        let mut first_comment: i64 = -1;
        loop {
            if i >= by.len() {
                indent = 0;
                found_eol = true;
                break;
            }
            match by[i] {
                b'\n' => {
                    found_eol = true;
                    indent = 0;
                    i += 1;
                }
                b' ' => {
                    indent += 1;
                    i += 1;
                }
                b'\r' | b'\x0c' => {
                    indent = 0;
                    i += 1;
                }
                b'\t' => {
                    indent += 8;
                    i += 1;
                }
                b'#' => {
                    if !found_eol {
                        return Scan { found_eol: false, indent, first_comment };
                    }
                    if first_comment == -1 {
                        first_comment = indent as i64;
                    }
                    while i < by.len() && by[i] != b'\n' {
                        i += 1;
                    }
                    i += 1;
                    indent = 0;
                }
                b'\\' => {
                    i += 1;
                    if i < by.len() && by[i] == b'\r' {
                        i += 1;
                    }
                    if i >= by.len() || by[i] == b'\n' {
                        i += 1;
                    } else {
                        return Scan { found_eol, indent, first_comment };
                    }
                }
                _ => break,
            }
        }
        Scan { found_eol, indent, first_comment }
    }

    fn cur_indent(&self) -> usize {
        *self.indents.last().unwrap()
    }

    fn should_dedent(&self) -> bool {
        if self.indents.len() <= 1 {
            return false;
        }
        let sc = self.scan();
        let cur = self.cur_indent();
        sc.found_eol && sc.indent < cur && sc.first_comment < cur as i64
    }

    /// At a line boundary: skip whitespace incl. newlines and at most one comment.
    /// Returns true if a comment/continuation was consumed.
    fn skip_line_trivia_one(&mut self) -> bool {
        self.tok = None;
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return false,
            };
            match c {
                ' ' | '\t' | '\x0c' | '\r' | '\n' | '\u{feff}' => self.pos += c.len_utf8(),
                '#' => {
                    let s = self.pos;
                    let mut e = s;
                    while e < self.by.len() && self.by[e] != b'\n' {
                        e += 1;
                    }
                    let mut ce = e;
                    if ce > s && self.by[ce - 1] == b'\r' {
                        ce -= 1;
                    }
                    self.b.extra("comment", s, ce);
                    self.pos = e;
                    return true;
                }
                '\\' => {
                    let s = self.pos;
                    let mut e = s + 1;
                    if e < self.by.len() && self.by[e] == b'\r' {
                        e += 1;
                    }
                    if e < self.by.len() && self.by[e] == b'\n' {
                        e += 1;
                        self.b.extra("line_continuation", s, e);
                        self.pos = e;
                        return true;
                    }
                    return false;
                }
                _ => return false,
            }
        }
    }

    // ------------------------------------------------------------ statements
    fn module(&mut self) {
        loop {
            if self.skip_line_trivia_one() {
                continue;
            }
            let t = self.peek();
            if t.k == TK::Eof {
                break;
            }
            let before = self.pos;
            self.statement();
            if self.pos == before && self.tok.map(|t| t.s) == Some(before) {
                // no progress: consume token as error
                self.error_line();
            }
        }
    }

    fn block_body(&mut self) {
        loop {
            self.tok = None;
            if self.should_dedent() {
                break;
            }
            if self.pos >= self.by.len() {
                break;
            }
            if self.skip_line_trivia_one() {
                continue;
            }
            let t = self.peek();
            if t.k == TK::Eof {
                break;
            }
            // A dedent might be required after skipping whitespace (line start)
            let before = self.pos;
            self.statement();
            if self.pos == before && self.tok.map(|t| t.s) == Some(before) {
                self.error_line();
            }
        }
    }

    fn error_line(&mut self) {
        let m = self.b.open();
        let mut n = 0;
        loop {
            let t = self.peek();
            if matches!(t.k, TK::LineEnd | TK::Eof) && self.depth == 0 {
                break;
            }
            if t.k == TK::Eof {
                break;
            }
            match t.k {
                TK::Name => {
                    if KEYWORDS.contains(&self.text(t)) {
                        self.bump();
                    } else {
                        self.bump_as("identifier", true);
                    }
                }
                TK::Str => {
                    self.string_or_concat();
                }
                TK::Int => {
                    self.bump_as("integer", true);
                }
                TK::Float => {
                    self.bump_as("float", true);
                }
                TK::Op => {
                    self.bump();
                }
                _ => {
                    self.bump_as("ERROR", true);
                }
            }
            n += 1;
            if n > 100000 {
                break;
            }
        }
        self.b.close(m, "ERROR");
        self.tok = None;
    }

    fn statement(&mut self) {
        let t = self.peek();
        if t.k == TK::Name {
            let w = self.text(t);
            match w {
                "def" | "class" | "if" | "for" | "while" | "try" | "with" => {
                    return self.compound(None);
                }
                "async" => {
                    let n = self.peek2_text();
                    if n == "def" || n == "for" || n == "with" {
                        return self.compound(Some(()));
                    }
                }
                "match" => {
                    if self.looks_like_match() {
                        return self.match_statement();
                    }
                }
                _ => {}
            }
        } else if t.k == TK::Op && self.text(t) == "@" {
            return self.decorated();
        }
        self.simple_statements();
    }

    fn looks_like_match(&mut self) -> bool {
        // `match <expr>:` at end of line
        let t = self.peek();
        let mut i = t.e;
        let by = self.by;
        // next char must not be an operator that makes it an expression
        while i < by.len() && (by[i] == b' ' || by[i] == b'\t') {
            i += 1;
        }
        if i >= by.len() || by[i] == b'\n' || by[i] == b'=' || by[i] == b'.' || by[i] == b')' || by[i] == b',' || by[i] == b':' {
            return false;
        }
        if by[i] == b'(' || by[i] == b'[' {
            // could be a call; check that line ends with ':'
        }
        // find end of logical line and check last non-space char is ':'
        let mut j = i;
        let mut depth = 0i32;
        let mut last = 0u8;
        while j < by.len() {
            let c = by[j];
            if c == b'#' && depth == 0 {
                break;
            }
            if c == b'\n' && depth == 0 {
                break;
            }
            if c == b'(' || c == b'[' || c == b'{' {
                depth += 1;
            }
            if c == b')' || c == b']' || c == b'}' {
                depth -= 1;
            }
            if !(c == b' ' || c == b'\t' || c == b'\r') {
                last = c;
            }
            j += 1;
        }
        last == b':'
    }

    fn simple_statements(&mut self) {
        loop {
            self.simple_statement();
            if self.at(";") {
                self.bump();
                let t = self.peek();
                if matches!(t.k, TK::LineEnd | TK::Eof) {
                    break;
                }
                continue;
            }
            break;
        }
        self.newline();
    }

    fn newline(&mut self) {
        let t = self.peek();
        if !matches!(t.k, TK::LineEnd | TK::Eof) {
            self.error_line();
        }
        self.b.flush_extras();
        self.tok = None;
    }

    fn simple_statement(&mut self) {
        let t = self.peek();
        let w = if t.k == TK::Name { self.text(t) } else { "" };
        let m = self.b.open();
        match w {
            "import" => {
                self.bump();
                self.import_list(false);
                self.b.close(m, "import_statement");
            }
            "from" => {
                self.bump();
                let is_future = self.peek_text() == "__future__";
                if is_future {
                    let mm = self.b.open();
                    let id = self.bump_as("identifier", true);
                    let _ = id;
                    // tree-sitter: '__future__' is anonymous keyword
                    self.b.abandon(mm);
                    if let Some(last) = self.b.last_child() {
                        self.b.set_kind(last, "__future__");
                        self.b.nodes[last as usize].named = false;
                    }
                    self.expect("import");
                    let paren = self.at("(");
                    if paren {
                        self.bump();
                    }
                    self.import_list(paren);
                    if paren {
                        self.expect(")");
                    }
                    self.b.close(m, "future_import_statement");
                } else {
                    // module name
                    if self.at(".") || self.at("...") {
                        let rm = self.b.open();
                        let pm = self.b.open();
                        while self.at(".") || self.at("...") {
                            self.bump();
                        }
                        self.b.close(pm, "import_prefix");
                        if self.peek().k == TK::Name && self.peek_text() != "import" {
                            self.dotted_name();
                        }
                        let r = self.b.close(rm, "relative_import");
                        self.b.set_field(r, "module_name");
                    } else {
                        let d = self.dotted_name();
                        self.b.set_field(d, "module_name");
                    }
                    self.expect("import");
                    if self.at("*") {
                        let wm = self.b.open();
                        self.bump();
                        self.b.close(wm, "wildcard_import");
                    } else {
                        let paren = self.at("(");
                        if paren {
                            self.bump();
                        }
                        self.import_list(paren);
                        if paren {
                            self.expect(")");
                        }
                    }
                    self.b.close(m, "import_from_statement");
                }
            }
            "assert" => {
                self.bump();
                self.expression();
                while self.at(",") {
                    self.bump();
                    self.expression();
                }
                self.b.close(m, "assert_statement");
            }
            "return" => {
                self.bump();
                if !self.at_stmt_end() {
                    self.expressions();
                }
                self.b.close(m, "return_statement");
            }
            "del" => {
                self.bump();
                self.expressions();
                self.b.close(m, "delete_statement");
            }
            "raise" => {
                self.bump();
                if !self.at_stmt_end() && !self.at_kw("from") {
                    self.expressions();
                }
                if self.at_kw("from") {
                    self.bump();
                    let c = self.expression();
                    self.b.set_field(c, "cause");
                }
                self.b.close(m, "raise_statement");
            }
            "pass" => {
                self.bump();
                self.b.close(m, "pass_statement");
            }
            "break" => {
                self.bump();
                self.b.close(m, "break_statement");
            }
            "continue" => {
                self.bump();
                self.b.close(m, "continue_statement");
            }
            "global" | "nonlocal" => {
                self.bump();
                self.identifier();
                while self.at(",") {
                    self.bump();
                    self.identifier();
                }
                self.b.close(m, if w == "global" { "global_statement" } else { "nonlocal_statement" });
            }
            "print" if self.is_print_stmt() => {
                self.bump();
                if self.at(">>") {
                    let cm = self.b.open();
                    self.bump();
                    self.expression();
                    let c = self.b.close(cm, "chevron");
                    let _ = c;
                    if self.at(",") {
                        self.bump();
                    }
                }
                if !self.at_stmt_end() {
                    let a = self.expression();
                    self.b.set_field(a, "argument");
                    while self.at(",") {
                        self.bump();
                        if self.at_stmt_end() {
                            break;
                        }
                        let a = self.expression();
                        self.b.set_field(a, "argument");
                    }
                }
                self.b.close(m, "print_statement");
            }
            "exec" if self.is_print_stmt() => {
                self.bump();
                let c = self.expression();
                self.b.set_field(c, "code");
                if self.at_kw("in") {
                    self.bump();
                    self.expression();
                    while self.at(",") {
                        self.bump();
                        self.expression();
                    }
                }
                self.b.close(m, "exec_statement");
            }
            "type" if self.is_type_alias() => {
                self.bump();
                let l = self.type_();
                self.b.set_field(l, "left");
                self.expect("=");
                let r = self.type_();
                self.b.set_field(r, "right");
                self.b.close(m, "type_alias_statement");
            }
            _ => {
                self.expression_statement_inner();
                self.b.close(m, "expression_statement");
            }
        }
    }

    fn is_print_stmt(&mut self) -> bool {
        let n = self.peek2_text();
        !(n.is_empty()
            || n == "("
            || n == "="
            || n == "."
            || n == ","
            || n == ")"
            || n == "["
            || n.ends_with('=') && n != "=="
            || binop_prec(n).is_some() && n != "-" && n != "*" && n != "~" && n != "+"
            || n == "\n")
            && {
                let t = self.peek();
                let mut i = t.e;
                while i < self.by.len() && (self.by[i] == b' ' || self.by[i] == b'\t') {
                    i += 1;
                }
                i < self.by.len() && self.by[i] != b'\n' && self.by[i] != b'#'
            }
    }

    fn is_type_alias(&mut self) -> bool {
        let n = self.peek2_text();
        if n.is_empty() || !n.chars().next().map(is_id_start).unwrap_or(false) {
            return false;
        }
        // look for '=' later on the line
        let t = self.peek();
        let rest = &self.src[t.e..];
        let line = rest.split('\n').next().unwrap_or("");
        line.contains('=') && !line.trim_start().starts_with('=')
    }

    fn at_stmt_end(&mut self) -> bool {
        let t = self.peek();
        matches!(t.k, TK::LineEnd | TK::Eof) || (t.k == TK::Op && matches!(self.text(t), ";" | ")" | "]" | "}"))
    }

    fn identifier(&mut self) -> NodeId {
        let t = self.peek();
        if t.k == TK::Name {
            self.bump_as("identifier", true)
        } else {
            self.b.missing("identifier", true)
        }
    }

    fn dotted_name(&mut self) -> NodeId {
        let m = self.b.open();
        self.identifier();
        while self.at(".") {
            self.bump();
            self.identifier();
        }
        self.b.close(m, "dotted_name")
    }

    fn import_list(&mut self, in_paren: bool) {
        loop {
            let t = self.peek();
            if t.k != TK::Name {
                break;
            }
            let d = self.dotted_name();
            if self.at_kw("as") {
                let am = self.b.open_before(d);
                self.b.set_field(d, "name");
                self.bump();
                let a = self.identifier();
                self.b.set_field(a, "alias");
                let al = self.b.close(am, "aliased_import");
                self.b.set_field(al, "name");
            } else {
                self.b.set_field(d, "name");
            }
            if self.at(",") {
                self.bump();
                if in_paren && self.at(")") {
                    break;
                }
                continue;
            }
            break;
        }
    }

    fn expressions(&mut self) -> NodeId {
        let e = self.expression_or_splat();
        if self.at(",") {
            let m = self.b.open_before(e);
            while self.at(",") {
                self.bump();
                if self.at_stmt_end() || self.at("=") || self.at(":") {
                    break;
                }
                self.expression_or_splat();
            }
            return self.b.close(m, "expression_list");
        }
        e
    }

    fn expression_or_splat(&mut self) -> NodeId {
        if self.at("*") {
            let m = self.b.open();
            self.bump();
            self.parse_binary(P_BOR);
            return self.b.close(m, "list_splat");
        }
        self.expression()
    }

    fn expression_statement_inner(&mut self) {
        if self.at_kw("yield") {
            let y = self.yield_();
            let _ = y;
            return;
        }
        let first = self.expressions();
        self.assignment_tail(first);
    }

    /// Possibly turn `lhs` into an assignment.
    fn assignment_tail(&mut self, lhs: NodeId) -> NodeId {
        let t = self.peek();
        let op = if t.k == TK::Op { self.text(t) } else { "" };
        if op == "=" {
            let m = self.b.open_before(lhs);
            self.to_pattern(lhs);
            self.b.set_field(lhs, "left");
            self.bump();
            let r = self.rhs();
            self.b.set_field(r, "right");
            return self.b.close(m, "assignment");
        }
        if op == ":" {
            let m = self.b.open_before(lhs);
            self.to_pattern(lhs);
            self.b.set_field(lhs, "left");
            self.bump();
            let ty = self.type_();
            self.b.set_field(ty, "type");
            if self.at("=") {
                self.bump();
                let r = self.rhs();
                self.b.set_field(r, "right");
            }
            return self.b.close(m, "assignment");
        }
        if AUG_OPS.contains(&op) {
            let m = self.b.open_before(lhs);
            self.to_pattern(lhs);
            self.b.set_field(lhs, "left");
            let o = self.bump();
            self.b.set_field(o, "operator");
            let r = self.rhs();
            self.b.set_field(r, "right");
            return self.b.close(m, "augmented_assignment");
        }
        lhs
    }

    fn rhs(&mut self) -> NodeId {
        if self.at_kw("yield") {
            return self.yield_();
        }
        let e = self.expressions();
        let t = self.peek();
        if t.k == TK::Op && (self.text(t) == "=" || AUG_OPS.contains(&self.text(t))) {
            return self.assignment_tail(e);
        }
        e
    }

    fn yield_(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump();
        if self.at_kw("from") {
            self.bump();
            self.expression();
        } else if !self.at_stmt_end() && !self.at("=") {
            self.expressions();
        }
        self.b.close(m, "yield")
    }

    /// Convert an expression node (already built) into a pattern.
    fn to_pattern(&mut self, id: NodeId) {
        let kind = self.b.kind(id);
        let new = match kind {
            "tuple" => "tuple_pattern",
            "list" => "list_pattern",
            "expression_list" => "pattern_list",
            "list_splat" => "list_splat_pattern",
            "parenthesized_expression" => {
                // (a) = 1 stays parenthesized? tree-sitter: tuple_pattern for (a, b)
                return;
            }
            _ => return,
        };
        self.b.set_kind(id, new);
        let children = self.b.nodes[id as usize].children.clone();
        for c in children {
            if self.b.nodes[c as usize].named {
                self.to_pattern(c);
            }
        }
    }

    // ------------------------------------------------------------- types
    fn type_(&mut self) -> NodeId {
        let m = self.b.open();
        if self.at("*") {
            let sm = self.b.open();
            self.bump();
            self.identifier();
            self.b.close(sm, "splat_type");
            return self.b.close(m, "type");
        }
        if self.at("**") {
            let sm = self.b.open();
            self.bump();
            self.identifier();
            self.b.close(sm, "splat_type");
            return self.b.close(m, "type");
        }
        let e = self.expression();
        self.generic_ify(e);
        self.b.close(m, "type")
    }

    /// Turn `Ident[...]` subscripts into generic_type nodes (in place).
    fn generic_ify(&mut self, id: NodeId) {
        if self.b.kind(id) != "subscript" {
            return;
        }
        let children = self.b.nodes[id as usize].children.clone();
        let value = children[0];
        if self.b.kind(value) != "identifier" {
            return;
        }
        // Build type_parameter from '[' ... ']'
        let mut tp_children = Vec::new();
        for &c in &children[1..] {
            let n = &self.b.nodes[c as usize];
            if n.named && !n.extra {
                // wrap into type
                self.b.nodes[c as usize].field = None;
                self.generic_ify(c);
                let (s, e) = (self.b.nodes[c as usize].start, self.b.nodes[c as usize].end);
                let t = self.b.new_node("type", true, s, e);
                self.b.nodes[t as usize].children = vec![c];
                tp_children.push(t);
            } else {
                tp_children.push(c);
            }
        }
        let s = self.b.nodes[tp_children[0] as usize].start;
        let e = self.b.nodes[*tp_children.last().unwrap() as usize].end;
        let tp = self.b.new_node("type_parameter", true, s, e);
        self.b.nodes[tp as usize].children = tp_children;
        self.b.nodes[id as usize].children = vec![value, tp];
        self.b.nodes[value as usize].field = None;
        self.b.set_kind(id, "generic_type");
    }

    // ------------------------------------------------------------- compound
    fn suite(&mut self, field: Option<&'static str>) -> NodeId {
        let t = self.peek();
        if matches!(t.k, TK::LineEnd | TK::Eof) {
            self.tok = None;
            let sc = self.scan();
            if sc.found_eol && sc.indent > self.cur_indent() {
                self.b.flush_extras();
                self.indents.push(sc.indent);
                // leading comments belong to the parent
                while self.skip_line_trivia_one() {}
                let m = self.b.open();
                self.block_body();
                self.b.flush_extras();
                if self.indents.len() > 1 {
                    self.indents.pop();
                }
                let id = self.b.close(m, "block");
                if let Some(f) = field {
                    self.b.set_field(id, f);
                }
                return id;
            }
            let m = self.b.open();
            let id = self.b.close(m, "block");
            if let Some(f) = field {
                self.b.set_field(id, f);
            }
            return id;
        }
        let m = self.b.open();
        self.simple_statements();
        let id = self.b.close(m, "block");
        if let Some(f) = field {
            self.b.set_field(id, f);
        }
        id
    }

    /// Check for a continuation keyword (elif/else/except/finally) at this level.
    fn continuation(&mut self, kws: &[&str]) -> Option<&'a str> {
        loop {
            self.tok = None;
            if self.should_dedent() {
                return None;
            }
            let sc = self.scan();
            if sc.found_eol && sc.indent > self.cur_indent() {
                return None;
            }
            if self.skip_line_trivia_one() {
                continue;
            }
            break;
        }
        let t = self.peek();
        if t.k == TK::Name {
            let w = self.text(t);
            if kws.contains(&w) {
                return Some(w);
            }
        }
        None
    }

    fn compound(&mut self, is_async: Option<()>) {
        let first = if is_async.is_some() { self.peek2_text() } else { self.peek_text() };
        match first {
            "def" => self.function_def(),
            "class" => self.class_def(),
            "if" => self.if_stmt(),
            "for" => self.for_stmt(),
            "while" => self.while_stmt(),
            "try" => self.try_stmt(),
            "with" => self.with_stmt(),
            _ => self.simple_statements(),
        }
    }

    fn function_def(&mut self) -> NodeId {
        let m = self.b.open();
        if self.at_kw("async") {
            self.bump();
        }
        self.expect("def");
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at("[") {
            let tp = self.type_parameter();
            self.b.set_field(tp, "type_parameters");
        }
        let pm = self.b.open();
        self.expect("(");
        self.parameters(")");
        self.expect(")");
        let ps = self.b.close(pm, "parameters");
        self.b.set_field(ps, "parameters");
        if self.at("->") {
            self.bump();
            let r = self.type_();
            self.b.set_field(r, "return_type");
        }
        self.expect(":");
        self.suite(Some("body"));
        self.b.close(m, "function_definition")
    }

    fn type_parameter(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // [
        loop {
            if self.at("]") {
                break;
            }
            self.type_();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("]");
        self.b.close(m, "type_parameter")
    }

    fn parameters(&mut self, close: &str) {
        loop {
            if self.at(close) || matches!(self.peek().k, TK::Eof) {
                break;
            }
            if close == ":" && self.at(":") {
                break;
            }
            self.parameter(close == ")");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
    }

    fn parameter(&mut self, allow_types: bool) {
        let m = self.b.open();
        if self.at("*") {
            let sm = self.b.open();
            self.bump();
            if self.at(",") || self.at(")") || self.at(":") {
                self.b.abandon(sm);
                self.b.close(m, "keyword_separator");
                return;
            }
            self.identifier();
            let sp = self.b.close(sm, "list_splat_pattern");
            if allow_types && self.at(":") {
                self.bump();
                let t = self.type_();
                self.b.set_field(t, "type");
                self.b.close(m, "typed_parameter");
                return;
            }
            let _ = sp;
            self.b.abandon(m);
            return;
        }
        if self.at("**") {
            let sm = self.b.open();
            self.bump();
            self.identifier();
            self.b.close(sm, "dictionary_splat_pattern");
            if allow_types && self.at(":") {
                self.bump();
                let t = self.type_();
                self.b.set_field(t, "type");
                self.b.close(m, "typed_parameter");
                return;
            }
            self.b.abandon(m);
            return;
        }
        if self.at("/") {
            self.bump();
            self.b.close(m, "positional_separator");
            return;
        }
        if self.at("(") {
            // tuple pattern (py2)
            let tm = self.b.open();
            self.bump();
            loop {
                if self.at(")") {
                    break;
                }
                self.identifier();
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect(")");
            let tp = self.b.close(tm, "tuple_pattern");
            if self.at("=") {
                self.b.set_field(tp, "name");
                self.bump();
                let v = self.expression();
                self.b.set_field(v, "value");
                self.b.close(m, "default_parameter");
                return;
            }
            self.b.abandon(m);
            return;
        }
        let id = self.identifier();
        if allow_types && self.at(":") {
            self.bump();
            let t = self.type_();
            self.b.set_field(t, "type");
            if self.at("=") {
                self.b.set_field(id, "name");
                self.bump();
                let v = self.expression();
                self.b.set_field(v, "value");
                self.b.close(m, "typed_default_parameter");
            } else {
                self.b.close(m, "typed_parameter");
            }
            return;
        }
        if self.at("=") {
            self.b.set_field(id, "name");
            self.bump();
            let v = self.expression();
            self.b.set_field(v, "value");
            self.b.close(m, "default_parameter");
            return;
        }
        self.b.abandon(m);
    }

    fn class_def(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("class");
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at("[") {
            let tp = self.type_parameter();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at("(") {
            let a = self.argument_list();
            self.b.set_field(a, "superclasses");
        }
        self.expect(":");
        self.suite(Some("body"));
        self.b.close(m, "class_definition")
    }

    fn decorated(&mut self) {
        let m = self.b.open();
        while self.at("@") {
            let dm = self.b.open();
            self.bump();
            self.expression();
            self.b.close(dm, "decorator");
            self.newline();
            // skip to next line
            loop {
                if self.skip_line_trivia_one() {
                    continue;
                }
                break;
            }
        }
        let t = self.peek();
        let w = self.text(t);
        let d = if w == "class" {
            Some(self.class_def())
        } else if w == "def" || w == "async" {
            Some(self.function_def())
        } else {
            None
        };
        if let Some(d) = d {
            self.b.set_field(d, "definition");
        }
        self.b.close(m, "decorated_definition");
    }

    fn if_stmt(&mut self) {
        let m = self.b.open();
        self.bump(); // if
        let c = self.expression();
        self.b.set_field(c, "condition");
        self.expect(":");
        self.suite(Some("consequence"));
        loop {
            match self.continuation(&["elif", "else"]) {
                Some("elif") => {
                    let em = self.b.open();
                    self.bump();
                    let c = self.expression();
                    self.b.set_field(c, "condition");
                    self.expect(":");
                    self.suite(Some("consequence"));
                    let e = self.b.close(em, "elif_clause");
                    self.b.set_field(e, "alternative");
                }
                Some("else") => {
                    let e = self.else_clause();
                    self.b.set_field(e, "alternative");
                    break;
                }
                _ => break,
            }
        }
        self.b.close(m, "if_statement");
    }

    fn else_clause(&mut self) -> NodeId {
        let em = self.b.open();
        self.bump();
        self.expect(":");
        self.suite(Some("body"));
        self.b.close(em, "else_clause")
    }

    fn for_stmt(&mut self) {
        let m = self.b.open();
        if self.at_kw("async") {
            self.bump();
        }
        self.expect("for");
        let l = self.targets();
        self.b.set_field(l, "left");
        self.expect("in");
        let r = self.expressions();
        self.b.set_field(r, "right");
        self.expect(":");
        self.suite(Some("body"));
        if self.continuation(&["else"]).is_some() {
            let e = self.else_clause();
            self.b.set_field(e, "alternative");
        }
        self.b.close(m, "for_statement");
    }

    /// Assignment targets (for loops, comprehensions): no comparisons.
    fn targets(&mut self) -> NodeId {
        let first = self.target();
        if self.at(",") {
            let m = self.b.open_before(first);
            while self.at(",") {
                self.bump();
                if self.at_kw("in") || self.at("=") {
                    break;
                }
                self.target();
            }
            let id = self.b.close(m, "pattern_list");
            return id;
        }
        first
    }

    fn target(&mut self) -> NodeId {
        let e = if self.at("*") {
            let m = self.b.open();
            self.bump();
            self.parse_binary(P_BOR);
            self.b.close(m, "list_splat")
        } else {
            self.parse_binary(P_BOR)
        };
        self.to_pattern(e);
        e
    }

    fn while_stmt(&mut self) {
        let m = self.b.open();
        self.bump();
        let c = self.expression();
        self.b.set_field(c, "condition");
        self.expect(":");
        self.suite(Some("body"));
        if self.continuation(&["else"]).is_some() {
            let e = self.else_clause();
            self.b.set_field(e, "alternative");
        }
        self.b.close(m, "while_statement");
    }

    fn try_stmt(&mut self) {
        let m = self.b.open();
        self.bump();
        self.expect(":");
        self.suite(Some("body"));
        loop {
            match self.continuation(&["except", "else", "finally"]) {
                Some("except") => {
                    let em = self.b.open();
                    self.bump();
                    let mut group = false;
                    if self.at("*") {
                        self.bump();
                        group = true;
                    }
                    if !self.at(":") {
                        let v = self.expression();
                        let v = if self.at_kw("as") {
                            self.as_pattern(v)
                        } else if self.at(",") {
                            self.bump();
                            let a = self.expression();
                            self.b.set_field(a, "alias");
                            v
                        } else {
                            v
                        };
                        self.b.set_field(v, "value");
                    }
                    let _ = group;
                    self.expect(":");
                    self.suite(None);
                    self.b.close(em, "except_clause");
                }
                Some("else") => {
                    self.else_clause();
                }
                Some("finally") => {
                    let fm = self.b.open();
                    self.bump();
                    self.expect(":");
                    self.suite(None);
                    self.b.close(fm, "finally_clause");
                    break;
                }
                _ => break,
            }
        }
        self.b.close(m, "try_statement");
    }

    fn as_pattern(&mut self, v: NodeId) -> NodeId {
        let am = self.b.open_before(v);
        self.bump(); // as
        let tm = self.b.open();
        self.expression();
        let t = self.b.close(tm, "as_pattern_target");
        self.b.set_field(t, "alias");
        self.b.close(am, "as_pattern")
    }

    fn with_stmt(&mut self) {
        let m = self.b.open();
        if self.at_kw("async") {
            self.bump();
        }
        self.expect("with");
        let cm = self.b.open();
        // parenthesized with items: `with (a as b, c):`
        let paren = self.at("(") && self.with_parens_are_items();
        if paren {
            self.bump();
        }
        loop {
            if paren && self.at(")") {
                break;
            }
            let im = self.b.open();
            let v = self.expression();
            let v = if self.at_kw("as") { self.as_pattern(v) } else { v };
            self.b.set_field(v, "value");
            self.b.close(im, "with_item");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        if paren {
            self.expect(")");
        }
        self.b.close(cm, "with_clause");
        self.expect(":");
        self.suite(Some("body"));
        self.b.close(m, "with_statement");
    }

    fn with_parens_are_items(&mut self) -> bool {
        // `with (a, b):` or `with (a as b):` -> items; `with (a)(b):` -> expression
        let t = self.peek();
        let by = self.by;
        let mut i = t.s;
        let mut depth = 0i32;
        while i < by.len() {
            match by[i] {
                b'(' | b'[' | b'{' => depth += 1,
                b')' | b']' | b'}' => {
                    depth -= 1;
                    if depth == 0 {
                        let mut j = i + 1;
                        while j < by.len() && (by[j] == b' ' || by[j] == b'\t') {
                            j += 1;
                        }
                        return j < by.len() && by[j] == b':';
                    }
                }
                b'\n' if depth == 0 => return false,
                _ => {}
            }
            i += 1;
        }
        false
    }

    fn match_statement(&mut self) {
        let m = self.b.open();
        self.bump(); // match
        let s = self.expression();
        self.b.set_field(s, "subject");
        while self.at(",") {
            self.bump();
            if self.at(":") {
                break;
            }
            let s = self.expression();
            self.b.set_field(s, "subject");
        }
        self.expect(":");
        // body: block of case clauses
        let t = self.peek();
        if matches!(t.k, TK::LineEnd | TK::Eof) {
            self.tok = None;
            let sc = self.scan();
            if sc.found_eol && sc.indent > self.cur_indent() {
                self.b.flush_extras();
                self.indents.push(sc.indent);
                while self.skip_line_trivia_one() {}
                let bm = self.b.open();
                loop {
                    self.tok = None;
                    if self.should_dedent() || self.pos >= self.by.len() {
                        break;
                    }
                    if self.skip_line_trivia_one() {
                        continue;
                    }
                    if self.at_kw("case") {
                        let c = self.case_clause();
                        self.b.set_field(c, "alternative");
                    } else {
                        let before = self.pos;
                        self.statement();
                        if self.pos == before {
                            self.error_line();
                        }
                    }
                }
                self.b.flush_extras();
                if self.indents.len() > 1 {
                    self.indents.pop();
                }
                let bl = self.b.close(bm, "block");
                self.b.set_field(bl, "body");
            }
        }
        self.b.close(m, "match_statement");
    }

    fn case_clause(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // case
        loop {
            self.case_pattern_top();
            if self.at(",") {
                self.bump();
                if self.at(":") || self.at_kw("if") {
                    break;
                }
                continue;
            }
            break;
        }
        if self.at_kw("if") {
            let gm = self.b.open();
            self.bump();
            self.expression();
            let g = self.b.close(gm, "if_clause");
            self.b.set_field(g, "guard");
        }
        self.expect(":");
        self.suite(Some("consequence"));
        self.b.close(m, "case_clause")
    }

    fn case_pattern_top(&mut self) -> NodeId {
        let m = self.b.open();
        self.case_pattern_inner();
        self.b.close(m, "case_pattern")
    }

    /// Parses a pattern (possibly union / as) inside a case_pattern wrapper.
    fn case_pattern_inner(&mut self) -> NodeId {
        let first = self.case_closed_pattern();
        let mut res = first;
        if self.at("|") {
            let um = self.b.open_before(first);
            while self.at("|") {
                self.bump();
                self.case_closed_pattern();
            }
            res = self.b.close(um, "union_pattern");
        }
        if self.at_kw("as") {
            let am = self.b.open_before(res);
            self.bump();
            self.identifier();
            res = self.b.close(am, "as_pattern");
        }
        res
    }

    fn case_closed_pattern(&mut self) -> NodeId {
        let t = self.peek();
        let txt = self.text(t);
        match t.k {
            TK::Name if txt == "_" => {
                // wildcard: case_pattern with '_' anonymous
                self.bump()
            }
            TK::Name if txt == "None" => self.bump_as("none", true),
            TK::Name if txt == "True" => self.bump_as("true", true),
            TK::Name if txt == "False" => self.bump_as("false", true),
            TK::Name => {
                let d = self.dotted_name();
                if self.at("(") {
                    let cm = self.b.open_before(d);
                    self.bump();
                    loop {
                        if self.at(")") {
                            break;
                        }
                        let pm = self.b.open();
                        let t2 = self.peek();
                        if t2.k == TK::Name && self.peek2_text() == "=" {
                            let km = self.b.open();
                            self.identifier();
                            self.bump();
                            self.case_pattern_inner();
                            self.b.close(km, "keyword_pattern");
                        } else {
                            self.case_pattern_inner();
                        }
                        self.b.close(pm, "case_pattern");
                        if self.at(",") {
                            self.bump();
                            continue;
                        }
                        break;
                    }
                    self.expect(")");
                    return self.b.close(cm, "class_pattern");
                }
                d
            }
            TK::Op if txt == "[" || txt == "(" => {
                let close = if txt == "[" { "]" } else { ")" };
                let m = self.b.open();
                self.bump();
                let mut n = 0;
                let mut comma = false;
                loop {
                    if self.at(close) {
                        break;
                    }
                    let pm = self.b.open();
                    if self.at("*") {
                        let sm = self.b.open();
                        self.bump();
                        self.identifier();
                        self.b.close(sm, "splat_pattern");
                    } else {
                        self.case_pattern_inner();
                    }
                    self.b.close(pm, "case_pattern");
                    n += 1;
                    if self.at(",") {
                        self.bump();
                        comma = true;
                        continue;
                    }
                    break;
                }
                self.expect(close);
                let kind = if close == "]" { "list_pattern" } else if n == 1 && !comma { "case_pattern" } else { "tuple_pattern" };
                self.b.close(m, kind)
            }
            TK::Op if txt == "{" => {
                let m = self.b.open();
                self.bump();
                loop {
                    if self.at("}") {
                        break;
                    }
                    if self.at("**") {
                        let sm = self.b.open();
                        self.bump();
                        self.identifier();
                        self.b.close(sm, "splat_pattern");
                    } else {
                        let k = self.case_closed_pattern();
                        self.b.set_field(k, "key");
                        self.expect(":");
                        let vm = self.b.open();
                        self.case_pattern_inner();
                        let v = self.b.close(vm, "case_pattern");
                        self.b.set_field(v, "value");
                    }
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.expect("}");
                self.b.close(m, "dict_pattern")
            }
            TK::Op if txt == "-" => {
                let m = self.b.open();
                self.bump();
                let t2 = self.peek();
                if t2.k == TK::Float {
                    self.bump_as("float", true);
                } else {
                    self.bump_as("integer", true);
                }
                self.b.close(m, "unary_operator")
            }
            TK::Str => self.string_or_concat(),
            TK::Int | TK::Float => {
                let first = if t.k == TK::Int { self.bump_as("integer", true) } else { self.bump_as("float", true) };
                if self.at("+") || self.at("-") {
                    let m = self.b.open_before(first);
                    self.bump();
                    let t2 = self.peek();
                    if t2.k == TK::Float {
                        self.bump_as("float", true);
                    } else {
                        self.bump_as("integer", true);
                    }
                    return self.b.close(m, "complex_pattern");
                }
                first
            }
            _ => self.expression(),
        }
    }

    // ------------------------------------------------------------ expressions
    fn expression(&mut self) -> NodeId {
        if self.at_kw("lambda") {
            return self.lambda(true);
        }
        let e = self.or_test();
        // named expression
        if self.at(":=") && self.b.kind(e) == "identifier" {
            let m = self.b.open_before(e);
            self.b.set_field(e, "name");
            self.bump();
            let v = self.expression();
            self.b.set_field(v, "value");
            return self.b.close(m, "named_expression");
        }
        if self.at_kw("if") && self.in_interp_ok() {
            let m = self.b.open_before(e);
            self.bump();
            self.or_test();
            self.expect("else");
            self.expression();
            return self.b.close(m, "conditional_expression");
        }
        e
    }

    fn in_interp_ok(&self) -> bool {
        true
    }

    /// Expression without conditional (used in comprehension iterables).
    fn expression_no_cond(&mut self) -> NodeId {
        if self.at_kw("lambda") {
            return self.lambda(false);
        }
        self.or_test()
    }

    fn lambda(&mut self, allow_cond: bool) -> NodeId {
        let m = self.b.open();
        self.bump();
        if !self.at(":") {
            let pm = self.b.open();
            self.parameters(":");
            let p = self.b.close(pm, "lambda_parameters");
            self.b.set_field(p, "parameters");
        }
        self.expect(":");
        let body = if allow_cond { self.expression() } else { self.expression_no_cond() };
        self.b.set_field(body, "body");
        self.b.close(m, "lambda")
    }

    fn or_test(&mut self) -> NodeId {
        let mut left = self.and_test();
        while self.at_kw("or") {
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            let o = self.bump();
            self.b.set_field(o, "operator");
            let r = self.and_test();
            self.b.set_field(r, "right");
            left = self.b.close(m, "boolean_operator");
        }
        left
    }

    fn and_test(&mut self) -> NodeId {
        let mut left = self.not_test();
        while self.at_kw("and") {
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            let o = self.bump();
            self.b.set_field(o, "operator");
            let r = self.not_test();
            self.b.set_field(r, "right");
            left = self.b.close(m, "boolean_operator");
        }
        left
    }

    fn not_test(&mut self) -> NodeId {
        if self.at_kw("not") {
            let m = self.b.open();
            self.bump();
            let a = self.not_test();
            self.b.set_field(a, "argument");
            return self.b.close(m, "not_operator");
        }
        self.comparison()
    }

    fn comp_op(&mut self) -> bool {
        let t = self.peek();
        let txt = self.text(t);
        match t.k {
            TK::Op => matches!(txt, "<" | "<=" | "==" | "!=" | ">=" | ">" | "<>"),
            TK::Name => {
                txt == "in" || txt == "is" || (txt == "not" && self.peek2_text() == "in")
            }
            _ => false,
        }
    }

    fn comparison(&mut self) -> NodeId {
        let first = self.parse_binary(P_BOR);
        if !self.comp_op() {
            return first;
        }
        let m = self.b.open_before(first);
        while self.comp_op() {
            let t = self.peek();
            let txt = self.text(t);
            if txt == "not" {
                // `not in`
                let s = t.s;
                self.bump();
                let t2 = self.peek();
                let e = t2.e;
                self.pos = e;
                self.tok = None;
                // replace last two leaves by a single "not in" token
                let cur = self.b.last_child().unwrap();
                self.b.nodes[cur as usize].kind = "not in";
                self.b.nodes[cur as usize].end = e;
                self.b.last_end = e;
                self.b.set_field(cur, "operators");
                let _ = s;
            } else if txt == "is" {
                let o = self.bump();
                self.b.set_field(o, "operators");
                if self.at_kw("not") {
                    let t2 = self.peek();
                    self.pos = t2.e;
                    self.tok = None;
                    self.b.nodes[o as usize].kind = "is not";
                    self.b.nodes[o as usize].end = t2.e;
                    self.b.last_end = t2.e;
                }
            } else {
                let o = self.bump();
                self.b.set_field(o, "operators");
            }
            self.parse_binary(P_BOR);
        }
        self.b.close(m, "comparison_operator")
    }

    fn parse_binary(&mut self, min: u8) -> NodeId {
        let mut left = self.unary();
        loop {
            let t = self.peek();
            if t.k != TK::Op {
                break;
            }
            let op = self.text(t);
            let (p, right_assoc) = match binop_prec(op) {
                Some(x) => x,
                None => break,
            };
            if p < min {
                break;
            }
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            let o = self.bump();
            self.b.set_field(o, "operator");
            let r = self.parse_binary(if right_assoc { p } else { p + 1 });
            self.b.set_field(r, "right");
            left = self.b.close(m, "binary_operator");
        }
        left
    }

    fn unary(&mut self) -> NodeId {
        let t = self.peek();
        if t.k == TK::Op && matches!(self.text(t), "-" | "+" | "~") {
            let m = self.b.open();
            let o = self.bump();
            self.b.set_field(o, "operator");
            let a = self.parse_binary(P_POWER);
            self.b.set_field(a, "argument");
            return self.b.close(m, "unary_operator");
        }
        if t.k == TK::Name && self.text(t) == "await" {
            let n = self.peek2_text();
            if !(n.is_empty() || n == "=" || n == "." || n == ")" || n == "," || n == ":") {
                let m = self.b.open();
                self.bump();
                self.parse_binary(P_POWER);
                return self.b.close(m, "await");
            }
        }
        let _ = P_UNARY;
        self.primary()
    }

    fn primary(&mut self) -> NodeId {
        let mut e = self.atom();
        loop {
            let t = self.peek();
            if t.k != TK::Op {
                break;
            }
            match self.text(t) {
                "." => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "object");
                    self.bump();
                    let a = self.identifier();
                    self.b.set_field(a, "attribute");
                    e = self.b.close(m, "attribute");
                }
                "(" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let a = self.call_args();
                    self.b.set_field(a, "arguments");
                    e = self.b.close(m, "call");
                }
                "[" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "value");
                    self.bump();
                    loop {
                        if self.at("]") {
                            break;
                        }
                        let s = self.subscript_item();
                        self.b.set_field(s, "subscript");
                        if self.at(",") {
                            self.bump();
                            continue;
                        }
                        break;
                    }
                    self.expect("]");
                    e = self.b.close(m, "subscript");
                }
                _ => break,
            }
        }
        e
    }

    fn subscript_item(&mut self) -> NodeId {
        if self.at(":") {
            let m = self.b.open();
            self.slice_rest();
            return self.b.close(m, "slice");
        }
        let e = self.expression();
        if self.at(":") {
            let m = self.b.open_before(e);
            self.slice_rest();
            return self.b.close(m, "slice");
        }
        e
    }

    fn slice_rest(&mut self) {
        // at ':'
        self.bump();
        if !self.at(":") && !self.at("]") && !self.at(",") {
            self.expression();
        }
        if self.at(":") {
            self.bump();
            if !self.at("]") && !self.at(",") {
                self.expression();
            }
        }
    }

    fn call_args(&mut self) -> NodeId {
        // generator expression as sole argument?
        let m = self.b.open();
        self.bump(); // (
        let mut items = 0;
        loop {
            if self.at(")") || self.peek().k == TK::Eof {
                break;
            }
            let t = self.peek();
            let item;
            if self.at("*") {
                let sm = self.b.open();
                self.bump();
                self.expression();
                item = self.b.close(sm, "list_splat");
            } else if self.at("**") {
                let sm = self.b.open();
                self.bump();
                self.expression();
                item = self.b.close(sm, "dictionary_splat");
            } else if t.k == TK::Name && self.peek2_text() == "=" {
                let km = self.b.open();
                let n = self.identifier();
                self.b.set_field(n, "name");
                self.bump();
                let v = self.expression();
                self.b.set_field(v, "value");
                item = self.b.close(km, "keyword_argument");
            } else {
                let e = self.expression();
                if items == 0 && (self.at_kw("for") || self.at_kw("async")) {
                    // generator expression replaces the argument list
                    self.b.set_field(e, "body");
                    self.comprehension_clauses();
                    self.expect(")");
                    return self.b.close(m, "generator_expression");
                }
                item = e;
            }
            let _ = item;
            items += 1;
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(")");
        self.b.close(m, "argument_list")
    }

    fn argument_list(&mut self) -> NodeId {
        self.call_args()
    }

    fn comprehension_clauses(&mut self) {
        loop {
            if self.at_kw("for") || (self.at_kw("async") && self.peek2_text() == "for") {
                let m = self.b.open();
                if self.at_kw("async") {
                    self.bump();
                }
                self.bump();
                let l = self.targets();
                self.b.set_field(l, "left");
                self.expect("in");
                let r = self.expression_no_cond();
                self.b.set_field(r, "right");
                while self.at(",") {
                    self.bump();
                    if self.at(")") || self.at("]") || self.at("}") {
                        break;
                    }
                    let r = self.expression_no_cond();
                    self.b.set_field(r, "right");
                }
                self.b.close(m, "for_in_clause");
            } else if self.at_kw("if") {
                let m = self.b.open();
                self.bump();
                self.expression_no_cond();
                self.b.close(m, "if_clause");
            } else {
                break;
            }
        }
    }

    fn atom(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Name => {
                let w = self.text(t);
                match w {
                    "True" => self.bump_as("true", true),
                    "False" => self.bump_as("false", true),
                    "None" => self.bump_as("none", true),
                    "lambda" => self.lambda(true),
                    "yield" => self.yield_(),
                    "not" => self.not_test(),
                    _ => {
                        if KEYWORDS.contains(&w) && !matches!(w, "async" | "await") {
                            // unexpected keyword
                            return self.b.missing("identifier", true);
                        }
                        self.bump_as("identifier", true)
                    }
                }
            }
            TK::Int => self.bump_as("integer", true),
            TK::Float => self.bump_as("float", true),
            TK::Str => self.string_or_concat(),
            TK::Op => {
                let w = self.text(t);
                match w {
                    "..." => self.bump_as("ellipsis", true),
                    "(" => self.paren(),
                    "[" => self.list(),
                    "{" => self.brace(),
                    "*" => {
                        let m = self.b.open();
                        self.bump();
                        self.parse_binary(P_BOR);
                        self.b.close(m, "list_splat")
                    }
                    _ => self.b.missing("identifier", true),
                }
            }
            _ => self.b.missing("identifier", true),
        }
    }

    fn collection_item(&mut self) -> NodeId {
        if self.at("*") {
            let m = self.b.open();
            self.bump();
            self.expression();
            return self.b.close(m, "list_splat");
        }
        if self.at_kw("yield") {
            return self.yield_();
        }
        self.expression()
    }

    fn paren(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump();
        if self.at(")") {
            self.bump();
            return self.b.close(m, "tuple");
        }
        if self.at_kw("yield") {
            self.yield_();
            self.expect(")");
            return self.b.close(m, "parenthesized_expression");
        }
        let first = self.collection_item();
        if self.at_kw("for") || self.at_kw("async") {
            self.b.set_field(first, "body");
            self.comprehension_clauses();
            self.expect(")");
            return self.b.close(m, "generator_expression");
        }
        if self.at(",") {
            while self.at(",") {
                self.bump();
                if self.at(")") {
                    break;
                }
                self.collection_item();
            }
            self.expect(")");
            return self.b.close(m, "tuple");
        }
        self.expect(")");
        let kind = if self.b.kind(first) == "list_splat" { "parenthesized_list_splat" } else { "parenthesized_expression" };
        self.b.close(m, kind)
    }

    fn list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump();
        if self.at("]") {
            self.bump();
            return self.b.close(m, "list");
        }
        let first = self.collection_item();
        if self.at_kw("for") || self.at_kw("async") {
            self.b.set_field(first, "body");
            self.comprehension_clauses();
            self.expect("]");
            return self.b.close(m, "list_comprehension");
        }
        while self.at(",") {
            self.bump();
            if self.at("]") {
                break;
            }
            self.collection_item();
        }
        self.expect("]");
        self.b.close(m, "list")
    }

    fn brace(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump();
        if self.at("}") {
            self.bump();
            return self.b.close(m, "dictionary");
        }
        let mut is_dict = false;
        let first;
        if self.at("**") {
            let sm = self.b.open();
            self.bump();
            self.expression();
            first = self.b.close(sm, "dictionary_splat");
            is_dict = true;
        } else {
            let k = self.collection_item();
            if self.at(":") {
                let pm = self.b.open_before(k);
                self.b.set_field(k, "key");
                self.bump();
                let v = self.expression();
                self.b.set_field(v, "value");
                first = self.b.close(pm, "pair");
                is_dict = true;
            } else {
                first = k;
            }
        }
        if self.at_kw("for") || self.at_kw("async") {
            self.b.set_field(first, "body");
            self.comprehension_clauses();
            self.expect("}");
            return self.b.close(m, if is_dict { "dictionary_comprehension" } else { "set_comprehension" });
        }
        while self.at(",") {
            self.bump();
            if self.at("}") {
                break;
            }
            if is_dict {
                if self.at("**") {
                    let sm = self.b.open();
                    self.bump();
                    self.expression();
                    self.b.close(sm, "dictionary_splat");
                } else {
                    let k = self.expression();
                    let pm = self.b.open_before(k);
                    self.b.set_field(k, "key");
                    self.expect(":");
                    let v = self.expression();
                    self.b.set_field(v, "value");
                    self.b.close(pm, "pair");
                }
            } else {
                self.collection_item();
            }
        }
        self.expect("}");
        self.b.close(m, if is_dict { "dictionary" } else { "set" })
    }

    // ------------------------------------------------------------- strings
    fn string_or_concat(&mut self) -> NodeId {
        let first = self.string();
        if self.peek().k == TK::Str {
            let m = self.b.open_before(first);
            while self.peek().k == TK::Str {
                self.string();
            }
            return self.b.close(m, "concatenated_string");
        }
        first
    }

    fn string(&mut self) -> NodeId {
        let t = self.peek();
        let s = t.s;
        let plen = self.string_prefix_len(s).unwrap_or(1);
        let by = self.by;
        let prefix: String = self.src[s..s + plen]
            .chars()
            .filter(|c| c.is_ascii_alphabetic())
            .map(|c| c.to_ascii_lowercase())
            .collect();
        let raw = prefix.contains('r');
        let bytes = prefix.contains('b');
        let fmt = prefix.contains('f');
        let qlen = if plen >= 3 && by[s + plen - 1] == by[s + plen - 2] && by[s + plen - 2] == by[s + plen - 3] && (by[s + plen - 1] == b'"' || by[s + plen - 1] == b'\'') && plen - prefix.len() == 3 { 3 } else { 1 };
        let qchar = by[s + plen - 1];
        let m = self.b.open();
        self.b.leaf("string_start", true, s, s + plen);
        self.tok = None;
        let mut i = s + plen;
        // content segments
        let mut content_start: Option<usize> = None;
        let mut content_children: Vec<(usize, usize, &'static str)> = Vec::new();
        let saved_depth = self.depth;
        loop {
            if i >= by.len() {
                break;
            }
            let c = by[i];
            // closing quote?
            if c == qchar {
                if qlen == 1 || (i + 2 < by.len() + 0 && i + 2 <= by.len() - 1 && by[i + 1] == qchar && by[i + 2] == qchar) {
                    break;
                }
                if content_start.is_none() {
                    content_start = Some(i);
                }
                i += 1;
                continue;
            }
            if c == b'\n' && qlen == 1 {
                break;
            }
            if c == b'\\' {
                if content_start.is_none() {
                    content_start = Some(i);
                }
                if raw {
                    i += 1;
                    if i < by.len() && (by[i] == qchar || by[i] == b'\\') {
                        i += 1;
                    } else if i < by.len() && by[i] == b'\r' {
                        i += 1;
                        if i < by.len() && by[i] == b'\n' {
                            i += 1;
                        }
                    } else if i < by.len() && by[i] == b'\n' {
                        i += 1;
                    }
                    continue;
                }
                // escape sequence
                let len = self.escape_len(i, bytes);
                if len > 0 {
                    content_children.push((i, i + len, "escape_sequence"));
                    i += len;
                } else {
                    i += 1;
                }
                continue;
            }
            if fmt && (c == b'{' || c == b'}') {
                if i + 1 < by.len() && by[i + 1] == c {
                    if content_start.is_none() {
                        content_start = Some(i);
                    }
                    content_children.push((i, i + 2, "escape_interpolation"));
                    i += 2;
                    continue;
                }
                if c == b'{' {
                    // flush content
                    if let Some(cs) = content_start.take() {
                        self.emit_content(cs, i, &mut content_children);
                    }
                    self.pos = i;
                    self.tok = None;
                    self.interpolation(qchar, qlen, "interpolation");
                    i = self.pos;
                    continue;
                }
                // stray '}'
                if content_start.is_none() {
                    content_start = Some(i);
                }
                i += 1;
                continue;
            }
            if content_start.is_none() {
                content_start = Some(i);
            }
            i += 1;
        }
        if let Some(cs) = content_start.take() {
            self.emit_content(cs, i, &mut content_children);
        }
        self.depth = saved_depth;
        if i < by.len() && by[i] == qchar {
            let e = (i + qlen).min(by.len());
            self.b.leaf("string_end", true, i, e);
            self.pos = e;
        } else {
            self.b.missing("string_end", true);
            self.pos = i;
        }
        self.tok = None;
        self.b.close(m, "string")
    }

    fn emit_content(&mut self, s: usize, e: usize, children: &mut Vec<(usize, usize, &'static str)>) {
        if e <= s {
            children.clear();
            return;
        }
        let m = self.b.open();
        // a content node: create leaf children
        let _ = m;
        for (cs, ce, k) in children.drain(..) {
            self.b.leaf(k, true, cs, ce);
        }
        // ensure range spans [s, e)
        let id = self.b.close(m, "string_content");
        self.b.nodes[id as usize].start = s;
        self.b.nodes[id as usize].end = e;
        self.b.last_end = e;
    }

    fn escape_len(&self, i: usize, bytes: bool) -> usize {
        let by = self.by;
        let n = match by.get(i + 1) {
            Some(n) => *n,
            None => return 0,
        };
        let hex = |from: usize, cnt: usize| -> bool {
            (from..from + cnt).all(|j| by.get(j).map(|b| b.is_ascii_hexdigit()).unwrap_or(false))
        };
        match n {
            b'u' if !bytes => {
                if hex(i + 2, 4) {
                    6
                } else {
                    0
                }
            }
            b'U' if !bytes => {
                if hex(i + 2, 8) {
                    10
                } else {
                    0
                }
            }
            b'x' => {
                if hex(i + 2, 2) {
                    4
                } else {
                    0
                }
            }
            b'0'..=b'7' | b'8' | b'9' => {
                let mut j = i + 1;
                while j < by.len() && j < i + 4 && by[j].is_ascii_digit() {
                    j += 1;
                }
                j - i
            }
            b'\r' => {
                if by.get(i + 2) == Some(&b'\n') {
                    3
                } else {
                    0
                }
            }
            b'\n' => 2,
            b'\'' | b'"' | b'a' | b'b' | b'f' | b'r' | b'n' | b't' | b'v' | b'\\' => 2,
            b'N' if !bytes => {
                if by.get(i + 2) == Some(&b'{') {
                    let mut j = i + 3;
                    while j < by.len() && by[j] != b'}' && by[j] != b'\n' {
                        j += 1;
                    }
                    if j < by.len() && by[j] == b'}' && j > i + 3 {
                        return j + 1 - i;
                    }
                }
                0
            }
            _ => 0,
        }
    }

    fn interpolation(&mut self, qchar: u8, qlen: usize, kind: &'static str) {
        let m = self.b.open();
        // '{'
        let s = self.pos;
        self.b.leaf("{", false, s, s + 1);
        self.pos = s + 1;
        self.tok = None;
        self.depth += 1;
        self.in_interp += 1;
        let saved_indents = std::mem::replace(&mut self.indents, vec![0]);
        let e = if self.at_kw("yield") {
            self.yield_()
        } else {
            let first = self.expression_or_splat();
            if self.at(",") {
                let lm = self.b.open_before(first);
                while self.at(",") {
                    self.bump();
                    if self.at("}") {
                        break;
                    }
                    self.expression_or_splat();
                }
                self.b.close(lm, "expression_list")
            } else {
                first
            }
        };
        self.b.set_field(e, "expression");
        self.indents = saved_indents;
        // '=' self-documenting
        let t = self.peek();
        if t.k == TK::Op && self.text(t) == "=" {
            self.bump();
        }
        // type conversion
        let t = self.peek();
        if t.k == TK::Op && self.text(t) == "!" {
            let s = t.s;
            let mut e = s + 1;
            while e < self.by.len() && self.by[e].is_ascii_lowercase() {
                e += 1;
            }
            let id = self.b.leaf("type_conversion", true, s, e);
            self.b.set_field(id, "type_conversion");
            self.pos = e;
            self.tok = None;
        }
        let t = self.peek();
        if t.k == TK::Op && self.text(t) == ":" {
            // format specifier: raw scan
            let fm = self.b.open();
            self.b.leaf(":", false, t.s, t.e);
            let mut i = t.e;
            self.tok = None;
            let by = self.by;
            loop {
                if i >= by.len() {
                    break;
                }
                let c = by[i];
                if c == b'}' {
                    break;
                }
                if c == qchar && (qlen == 1 || (i + 2 < by.len() && by[i + 1] == qchar && by[i + 2] == qchar)) {
                    break;
                }
                if c == b'{' {
                    self.pos = i;
                    self.tok = None;
                    let saved = self.depth;
                    self.interpolation(qchar, qlen, "format_expression");
                    self.depth = saved;
                    i = self.pos;
                    continue;
                }
                if c == b'\n' {
                    break;
                }
                i += 1;
            }
            let fs = self.b.close(fm, "format_specifier");
            self.b.nodes[fs as usize].end = i.max(self.b.nodes[fs as usize].end);
            self.b.set_field(fs, "format_specifier");
            self.pos = i;
            self.tok = None;
            self.b.last_end = i;
        }
        // closing '}'
        let t = self.peek();
        if t.k == TK::Op && self.text(t) == "}" {
            self.bump();
        } else {
            self.b.missing("}", false);
        }
        self.depth = self.depth.saturating_sub(0);
        self.in_interp -= 1;
        self.b.close(m, kind);
        self.tok = None;
    }
}

/// Intern a token text into a static str (for anonymous node kinds).
pub fn intern(s: &str) -> &'static str {
    use std::collections::HashSet;
    use std::sync::Mutex;
    static POOL: std::sync::OnceLock<Mutex<HashSet<&'static str>>> = std::sync::OnceLock::new();
    let pool = POOL.get_or_init(|| Mutex::new(HashSet::new()));
    let mut g = pool.lock().unwrap();
    if let Some(v) = g.get(s) {
        return v;
    }
    let leaked: &'static str = Box::leak(s.to_string().into_boxed_str());
    g.insert(leaked);
    leaked
}
