}

pub struct LanguageScoper {
    lang: &'static Lang,
    queries: Vec<CompiledQuery>,
}

fn compile(lang: &'static Lang, src: &str, filter: Option<(String, regex::Regex)>) -> Result<CompiledQuery, String> {
    let q = Query::new(src, lang.info)
        .map_err(|e| format!("Error occurred while creating a tree-sitter query: {e}"))?;
    let ignore_query = if q.capture_names.iter().any(|n| n == IGNORE) {
        let mut iq = Query::new(src, lang.info).map_err(|e| format!("{e}"))?;
        let names = iq.capture_names.clone();
        for n in names {
            if n != IGNORE {
                trace!(target: "srgn::scoping::langs", "Disabling capture for: {:?}", n);
                iq.disable_capture(&n);
            }
        }
        Some(iq)
    } else {
        None
    };
    Ok(CompiledQuery { query: q, ignore_query, name_filter: filter })
}

impl LanguageScoper {
    fn ranges_for(&self, cq: &CompiledQuery, tree: &Tree, input: &str) -> Vec<std::ops::Range<usize>> {
        trace!(target: "srgn::scoping::langs", "Running query: {:?}", cq.query.capture_names);
        let caps = cq.query.captures(tree, input, self.lang.info);
        let mut ranges: Vec<std::ops::Range<usize>> = Vec::new();
        for (c, n) in &caps {
            let node = tree.node(*n);
            if let Some((name, re)) = &cq.name_filter {
                let _ = (name, re);
            }
            let _ = c;
            ranges.push(node.start..node.end);
        }
        let ranges = merge_ranges(ranges);
        match &cq.ignore_query {
            Some(iq) => {
                let icaps = iq.captures(tree, input, self.lang.info);
                let ign: Vec<std::ops::Range<usize>> = icaps
                    .iter()
                    .map(|(_, n)| {
                        let node = tree.node(*n);
                        node.start..node.end
                    })
                    .collect();
                let ign = merge_ranges(ign);
                subtract_ranges(&ranges, &ign)
            }
            None => ranges,
        }
    }
}

