    fn scope_raw(&self, input: &str) -> Result<RawRanges, String> {
        trace!(target: "srgn::scoping::langs", "Parsing into AST: {:?}", input);
        let tree = (self.lang.parse)(input);
        debug!(target: "srgn::scoping::langs", "S expression of parsed source code is: {:?}", tree.to_sexp());
        let mut all = Vec::new();
        for cq in &self.queries {
            all.extend(self.ranges_for(cq, &tree, input));
        }
        let merged = if self.queries.len() > 1 { merge_ranges(all) } else { all };
        Ok(merged.into_iter().filter(|r| !r.is_empty()).map(|r| (r, None)).collect())
    }
}

pub fn build_scopers(sel: &LangSelection, join: bool) -> Result<Vec<Box<dyn Scoper + Sync>>, String> {
    let lang = lang(sel.lang);
    let mut compiled = Vec::new();
    for p in &sel.prepared {
        let pq = (lang.prepared)(&p.name, p.pattern.as_ref());
        compiled.push(compile(lang, &pq.query, pq.name_filter)?);
    }
    for q in &sel.queries {
        compiled.push(compile(lang, q, None)?);
    }
    for f in &sel.query_files {
        let text = std::fs::read_to_string(f).map_err(|e| format!("Error reading query file: {e}"))?;
        compiled.push(compile(lang, &text, None)?);
    }
    let mut out: Vec<Box<dyn Scoper + Sync>> = Vec::new();
    if join {
