    } else {
        for c in compiled {
            out.push(Box::new(LanguageScoper { lang, queries: vec![c] }));
        }
    }
    Ok(out)
}

pub fn is_valid_path(lang: &str, path: &Path) -> bool {
    let ext = path.extension().map(|e| e.to_string_lossy().to_string());
    match lang {
