                        let re = regex::Regex::new(r"^#!.*\bpython3?$").unwrap();
                        re.is_match(first)
                    }
                    Err(_) => false,
                }
            }
        },
        "rust" => ext.as_deref() == Some("rs"),
        "go" => ext.as_deref() == Some("go"),
        "typescript" => matches!(ext.as_deref(), Some("ts") | Some("tsx")),
        "csharp" => ext.as_deref() == Some("cs"),
