        }
        for p in PUNCTS {
            if self.src[s..].starts_with(p) {
                return Tok { k: TK::Punct, s, e: s + p.len() };
            }
        }
        Tok { k: TK::Err, s, e: s + c.len_utf8() }
    }

    fn char_end(&self, s: usize) -> Option<usize> {
        // s at opening quote
        let by = self.by;
        let mut i = s + 1;
        if i >= by.len() {
            return None;
        }
        if by[i] == b'\\' {
            i += 1;
            if i >= by.len() {
                return None;
            }
            if by[i] == b'u' && by.get(i + 1) == Some(&b'{') {
                while i < by.len() && by[i] != b'}' {
                    i += 1;
                }
                i += 1;
            } else if by[i] == b'x' {
                i += 3;
            } else {
                i += 1;
            }
        } else {
            let c = self.ch(i)?;
            if c == '\'' || c == '\n' {
                return None;
            }
            i += c.len_utf8();
        }
        if by.get(i) == Some(&b'\'') {
            Some(i + 1)
        } else {
            None
        }
    }

    fn lex_number(&self, s: usize) -> Tok {
        let by = self.by;
        let mut e = s;
        let mut float = false;
        if by[e] == b'0' && matches!(by.get(e + 1), Some(b'x') | Some(b'o') | Some(b'b')) {
            let hex = by[e + 1] == b'x';
            e += 2;
            while e < by.len() && (by[e].is_ascii_hexdigit() && (hex || by[e].is_ascii_digit()) || by[e] == b'_') {
                e += 1;
            }
        } else {
            while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                e += 1;
            }
            if e < by.len() && by[e] == b'.' && by.get(e + 1) != Some(&b'.') && !self.ch(e + 1).map(is_id_start).unwrap_or(false) {
                float = true;
                e += 1;
                while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                    e += 1;
                }
            }
            if e < by.len() && (by[e] == b'e' || by[e] == b'E') {
                let mut f = e + 1;
                if f < by.len() && (by[f] == b'+' || by[f] == b'-') {
                    f += 1;
                }
                if f < by.len() && by[f].is_ascii_digit() {
                    float = true;
                    e = f;
                    while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                        e += 1;
                    }
                }
            }
        }
        // suffix
        let suf_start = e;
        while let Some(c) = self.ch(e) {
            if is_id_cont(c) {
                e += c.len_utf8();
            } else {
                break;
            }
        }
        let suf = &self.src[suf_start..e];
        if suf.starts_with('f') {
            // f32/f64 suffix on an integer remains integer_literal in tree-sitter
        }
        Tok { k: if float { TK::Float } else { TK::Int }, s, e }
    }

    fn peek(&mut self) -> Tok {
        if let Some(t) = self.tok {
            return t;
        }
        self.skip_trivia();
        let t = self.lex();
        self.tok = Some(t);
        t
    }

    fn peek_text(&mut self) -> &'a str {
        let t = self.peek();
        if matches!(t.k, TK::Str | TK::RawStr) {
            return "\"";
        }
        self.text(t)
    }

    /// Text of the n-th token after current (no side effects). n=1 → next.
    fn peek_nth(&mut self, n: usize) -> (TK, &'a str) {
        let t = self.peek();
        let save_pos = self.pos;
        let save_tok = self.tok;
        let save_nodes = self.b.nodes.len();
        let mut res = (t.k, self.text(t));
        let mut cur = t;
        for _ in 0..n {
            self.pos = cur.e;
            if matches!(cur.k, TK::Str | TK::RawStr) {
                // skip string quickly
                self.pos = self.skip_string_raw(cur);
            }
            // skip trivia without emitting (we truncate nodes afterwards)
            let pending_before = self.b.has_pending();
            let _ = pending_before;
            self.skip_trivia_silent();
            cur = self.lex();
            res = (cur.k, if matches!(cur.k, TK::Str | TK::RawStr) { "\"" } else { self.text(cur) });
        }
        self.pos = save_pos;
        self.tok = save_tok;
        self.b.nodes.truncate(save_nodes);
        res
    }

    fn skip_string_raw(&self, t: Tok) -> usize {
        let by = self.by;
        let mut i = t.s;
        if t.k == TK::RawStr {
            while by[i] != b'#' && by[i] != b'"' {
                i += 1;
            }
            let mut hashes = 0;
            while by[i] == b'#' {
                hashes += 1;
                i += 1;
            }
            i += 1;
            loop {
                if i >= by.len() {
                    return by.len();
                }
                if by[i] == b'"' {
                    let mut j = i + 1;
                    let mut h = 0;
                    while h < hashes && j < by.len() && by[j] == b'#' {
                        h += 1;
                        j += 1;
                    }
                    if h == hashes {
                        return j;
                    }
                }
                i += 1;
            }
        }
        while by[i] != b'"' {
            i += 1;
        }
        i += 1;
        while i < by.len() {
            if by[i] == b'\\' {
                i += 2;
                continue;
            }
            if by[i] == b'"' {
                return i + 1;
            }
            i += 1;
        }
        by.len()
    }

    fn skip_trivia_silent(&mut self) {
        let by = self.by;
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return,
            };
            if c.is_whitespace() {
                self.pos += c.len_utf8();
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'/') {
                while self.pos < by.len() && by[self.pos] != b'\n' {
                    self.pos += 1;
                }
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'*') {
                let mut i = self.pos + 2;
                let mut depth = 1;
                while i < by.len() && depth > 0 {
                    if by[i] == b'/' && by.get(i + 1) == Some(&b'*') {
                        depth += 1;
                        i += 2;
                    } else if by[i] == b'*' && by.get(i + 1) == Some(&b'/') {
                        depth -= 1;
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                self.pos = i.min(by.len());
                continue;
            }
            return;
        }
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        matches!(t.k, TK::Punct | TK::Ident) && self.text(t) == s
    }

    /// Check for a '>'-composed operator (since '>' is lexed singly).
    fn at_gt_op(&mut self) -> Option<&'static str> {
        let t = self.peek();
        if t.k != TK::Punct || self.text(t) != ">" {
            return None;
        }
        let by = self.by;
        let n1 = by.get(t.e).copied();
        let n2 = by.get(t.e + 1).copied();
        match (n1, n2) {
            (Some(b'>'), Some(b'=')) => Some(">>="),
            (Some(b'>'), _) => Some(">>"),
            (Some(b'='), _) => Some(">="),
            _ => Some(">"),
        }
    }

    fn bump_n(&mut self, kind: &'static str, named: bool, len: usize) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.s + len);
        self.pos = t.s + len;
        self.tok = None;
        id
    }

    fn bump_as(&mut self, kind: &'static str, named: bool) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        id
    }

    fn bump(&mut self) -> NodeId {
        let t = self.peek();
        let k = intern(self.text(t));
        self.bump_as(k, false)
    }

    fn expect(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else if s == ">" {
            // '>' may be part of '>>' / '>=': split
            let t = self.peek();
            if t.k == TK::Punct && self.text(t).starts_with('>') {
                self.bump_n(">", false, 1);
                return true;
            }
            self.b.missing(">", false);
            false
        } else {
            self.b.missing(intern(s), false);
            false
        }
    }

    fn is_ident(&mut self) -> bool {
        let t = self.peek();
        t.k == TK::Ident && !KEYWORDS.contains(&self.text(t))
    }

    fn identifier(&mut self) -> NodeId {
        let t = self.peek();
        if t.k == TK::Ident {
            self.bump_as("identifier", true)
        } else {
            self.b.missing("identifier", true)
        }
    }

    fn ident_as(&mut self, kind: &'static str) -> NodeId {
        let t = self.peek();
        if t.k == TK::Ident {
            self.bump_as(kind, true)
        } else {
            self.b.missing(kind, true)
        }
    }

    // ---------------------------------------------------------------- items
    fn source_file(&mut self) {
        // shebang
        if self.src.starts_with("#!") && !self.src.starts_with("#![") {
            let e = self.src.find('\n').unwrap_or(self.src.len());
            self.b.leaf("shebang", true, 0, e);
            self.pos = e;
        }
        loop {
            let t = self.peek();
            if t.k == TK::Eof {
                break;
            }
            let before = t.s;
            if self.at("}") {
                // stray
                let m = self.b.open();
                self.bump();
                self.b.close(m, "ERROR");
                continue;
            }
            self.statement(true);
            if self.pos <= before && self.tok.map(|t| t.s) == Some(before) {
                let m = self.b.open();
                self.bump();
                self.b.close(m, "ERROR");
            }
        }
    }

    fn visibility(&mut self) -> Option<NodeId> {
        if self.at("pub") {
            let m = self.b.open();
            self.bump();
            if self.at("(") {
                let (_, n1) = self.peek_nth(1);
                if matches!(n1, "crate" | "self" | "super" | "in") {
                    self.bump();
                    if self.at("in") {
                        self.bump();
                        self.path_expr();
                    } else {
                        let w = self.peek_text();
                        let k = intern(w);
                        self.bump_as(k, true);
                    }
                    self.expect(")");
                }
            }
            return Some(self.b.close(m, "visibility_modifier"));
        }
        if self.at("crate") {
            let (_, n1) = self.peek_nth(1);
            if n1 != "::" {
                let m = self.b.open();
                self.bump_as("crate", true);
                return Some(self.b.close(m, "visibility_modifier"));
            }
        }
        None
    }

    fn is_item_start(&mut self) -> bool {
        let t = self.peek();
        if t.k != TK::Ident {
            return self.at("#");
        }
        let w = self.text(t);
        match w {
            "pub" | "fn" | "struct" | "enum" | "union" | "trait" | "impl" | "mod" | "use" | "type" | "static" | "extern" | "macro_rules" => {
                if w == "union" {
                    let (k, _) = self.peek_nth(1);
                    return k == TK::Ident;
                }
                if w == "macro_rules" {
                    let (_, n) = self.peek_nth(1);
                    return n == "!";
                }
                true
            }
            "const" => {
                let (_, n) = self.peek_nth(1);
                n != "{"
            }
            "unsafe" => {
                let (_, n) = self.peek_nth(1);
                n != "{"
            }
            "async" => {
                let (_, n) = self.peek_nth(1);
                n == "fn" || n == "unsafe"
            }
            "default" => {
                let (_, n) = self.peek_nth(1);
                n == "fn" || n == "impl" || n == "unsafe" || n == "async" || n == "const" || n == "type"
            }
            _ => false,
        }
    }

    /// Parse a statement. `top` = item context (source_file / declaration_list).
    fn statement(&mut self, top: bool) {
        if self.at(";") {
            let m = self.b.open();
            self.bump();
            self.b.close(m, "empty_statement");
            return;
        }
        if self.at("#") {
            self.attribute_item();
            return;
        }
        if self.at("let") {
            self.let_declaration();
            return;
        }
        if self.is_item_start() {
            self.item();
            return;
        }
        if top {
            // expression statements are allowed at top level by the grammar
        }
        self.expression_statement();
    }

    fn attribute_item(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // #
        let inner = if self.at("!") {
            self.bump();
            true
        } else {
            false
        };
        self.expect("[");
        self.attribute();
        self.expect("]");
        self.b.close(m, if inner { "inner_attribute_item" } else { "attribute_item" })
    }

    fn attribute(&mut self) {
        let m = self.b.open();
        if self.at("unsafe") {
            // unsafe(...) attribute
        }
        self.path_expr();
        if self.at("=") {
            self.bump();
            let v = self.expression();
            self.b.set_field(v, "value");
        } else if self.at("(") || self.at("[") || self.at("{") {
            let tt = self.token_tree();
            self.b.set_field(tt, "arguments");
        }
        self.b.close(m, "attribute");
    }

    fn item(&mut self) {
        let m = self.b.open();
        self.visibility();
        let t = self.peek();
        let w = self.text(t);
        match w {
            "fn" | "async" | "const" | "unsafe" | "extern" | "default" => {
                // could be function, const item, extern block/crate, unsafe impl/trait
                if w == "const" {
                    let (_, n) = self.peek_nth(1);
                    if n != "fn" && n != "unsafe" && n != "async" && n != "extern" {
                        return self.const_item(m);
                    }
                }
                if w == "extern" {
                    let (k1, n1) = self.peek_nth(1);
                    if n1 == "crate" {
                        return self.extern_crate(m);
                    }
                    let n2 = if k1 == TK::Str { self.peek_nth(2).1 } else { n1 };
                    if n2 == "{" || n1 == "{" {
                        return self.foreign_mod(m);
                    }
                }
                if w == "unsafe" {
                    let (_, n1) = self.peek_nth(1);
                    if n1 == "impl" {
                        return self.impl_item(m);
                    }
                    if n1 == "trait" || n1 == "auto" {
                        return self.trait_item(m);
                    }
                    if n1 == "extern" {
                        let (k2, n2) = self.peek_nth(2);
                        let n3 = if k2 == TK::Str { self.peek_nth(3).1 } else { n2 };
                        if n3 == "{" || n2 == "{" {
                            return self.foreign_mod(m);
                        }
                    }
                    if n1 == "mod" {
                        self.bump();
                        return self.mod_item(m);
                    }
                }
                if w == "default" {
                    let (_, n1) = self.peek_nth(1);
                    if n1 == "impl" {
                        self.bump();
                        return self.impl_item(m);
                    }
                }
                self.function(m)
            }
            "struct" => self.struct_item(m, "struct", "struct_item"),
            "union" => self.struct_item(m, "union", "union_item"),
            "enum" => self.enum_item(m),
            "trait" => self.trait_item(m),
            "impl" => self.impl_item(m),
            "mod" => self.mod_item(m),
            "use" => self.use_declaration(m),
            "type" => self.type_item(m),
            "static" => self.static_item(m),
            "macro_rules" => self.macro_definition(m),
            _ => {
                self.b.close(m, "ERROR");
            }
        }
    }

    fn function_modifiers(&mut self) -> Option<NodeId> {
        let m = self.b.open();
        let mut any = false;
        loop {
            if self.at("async") || self.at("const") || self.at("unsafe") || self.at("default") {
                self.bump();
                any = true;
            } else if self.at("extern") {
                let em = self.b.open();
                self.bump();
                let t = self.peek();
                if t.k == TK::Str || t.k == TK::RawStr {
                    self.string_literal();
                }
                self.b.close(em, "extern_modifier");
                any = true;
            } else {
                break;
            }
        }
        if any {
            Some(self.b.close(m, "function_modifiers"))
        } else {
            self.b.abandon(m);
            None
        }
    }

    fn function(&mut self, m: crate::ts::builder::Marker) {
        self.function_modifiers();
        self.expect("fn");
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        let ps = self.parameters();
        self.b.set_field(ps, "parameters");
        if self.at("->") {
            self.bump();
            let r = self.type_();
            self.b.set_field(r, "return_type");
        }
        if self.at("where") {
            self.where_clause();
        }
        if self.at(";") {
            self.bump();
            self.b.close(m, "function_signature_item");
            return;
        }
        let body = self.block();
        self.b.set_field(body, "body");
        self.b.close(m, "function_item");
    }

    fn parameters(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("(");
        loop {
            if self.at(")") || self.peek().k == TK::Eof {
                break;
            }
            while self.at("#") {
                self.attribute_item();
            }
            self.parameter();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(")");
        self.b.close(m, "parameters")
    }

    fn parameter(&mut self) {
        // self parameter forms
        let save_pos = self.pos;
        let _ = save_pos;
        if self.at("&") || self.at("self") || (self.at("mut") && self.peek_nth(1).1 == "self") {
            // check for self parameter
            let (_, n1) = self.peek_nth(1);
            let (_, n2) = self.peek_nth(2);
            let (_, n3) = self.peek_nth(3);
            let is_self_param = if self.at("&") {
                n1 == "self" || (n1 == "mut" && n2 == "self") || (n1.starts_with('\'') && (n2 == "self" || (n2 == "mut" && n3 == "self")))
            } else if self.at("mut") {
                n2 != ":"
            } else {
                n1 != ":"
            };
            if is_self_param {
                let m = self.b.open();
                if self.at("&") {
                    self.bump();
                    if self.peek().k == TK::Lifetime {
                        self.lifetime();
                    }
                }
                if self.at("mut") {
                    self.mutable_specifier();
                }
                self.bump_as("self", true);
                self.b.close(m, "self_parameter");
                return;
            }
        }
        if self.at("...") {
            let m = self.b.open();
            self.bump();
            self.b.close(m, "variadic_parameter");
            return;
        }
        // pattern ':' type, or bare type (fn pointer / trait fn)
        if self.param_has_colon() {
            let m = self.b.open();
            if self.at("mut") && self.peek_nth(1).0 == TK::Ident && self.peek_nth(2).1 == ":" {
                self.mutable_specifier();
            }
            if self.at("self") {
                let s = self.bump_as("self", true);
                self.b.set_field(s, "pattern");
            } else if self.at("_") {
                self.bump();
            } else {
                let p = self.pattern();
                self.b.set_field(p, "pattern");
            }
            self.expect(":");
            let t = self.type_();
            self.b.set_field(t, "type");
            self.b.close(m, "parameter");
            return;
        }
        if self.at("_") {
            self.bump();
            return;
        }
        self.type_();
    }

    fn param_has_colon(&mut self) -> bool {
        // scan tokens at depth 0 until ',' or ')' looking for ':' (not '::')
        let save_pos = self.pos;
        let save_tok = self.tok;
        let save_nodes = self.b.nodes.len();
        let save_pending = self.b.pending_starts().len();
        let _ = save_pending;
        let mut depth = 0i32;
        let mut found = false;
        let t = self.peek();
        let mut cur = t;
        let mut n = 0;
        loop {
            n += 1;
            if n > 10000 {
                break;
            }
            match cur.k {
                TK::Eof => break,
                TK::Punct => {
                    let s = self.text(cur);
                    match s {
                        "(" | "[" | "{" | "<" => depth += 1,
                        ")" | "]" | "}" | ">" => {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                        }
                        "," if depth == 0 => break,
                        ":" if depth == 0 => {
                            found = true;
                            break;
                        }
                        "->" => {}
                        _ => {}
                    }
                }
                _ => {}
            }
            self.pos = if matches!(cur.k, TK::Str | TK::RawStr) { self.skip_string_raw(cur) } else { cur.e };
            self.skip_trivia_silent();
            cur = self.lex();
        }
        self.pos = save_pos;
        self.tok = save_tok;
        self.b.nodes.truncate(save_nodes);
        found
    }

    fn mutable_specifier(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump();
        self.b.close(m, "mutable_specifier")
    }

    fn lifetime(&mut self) -> NodeId {
        let t = self.peek();
        let m = self.b.open();
        self.b.leaf("'", false, t.s, t.s + 1);
        let id_end = t.e;
        self.b.leaf("identifier", true, t.s + 1, id_end);
        self.pos = t.e;
        self.tok = None;
        self.b.close(m, "lifetime")
    }

    fn label(&mut self) -> NodeId {
        let t = self.peek();
        let m = self.b.open();
        self.b.leaf("'", false, t.s, t.s + 1);
        self.b.leaf("identifier", true, t.s + 1, t.e);
        self.pos = t.e;
        self.tok = None;
        self.b.close(m, "label")
    }

    fn type_parameters(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // <
        loop {
            if self.at(">") || self.peek().k == TK::Eof {
                break;
            }
            while self.at("#") {
                self.attribute_item();
            }
            let t = self.peek();
            if t.k == TK::Lifetime {
                let pm = self.b.open();
                let l = self.lifetime();
                self.b.set_field(l, "name");
                if self.at(":") {
                    let b = self.trait_bounds();
                    self.b.set_field(b, "bounds");
                }
                self.b.close(pm, "lifetime_parameter");
            } else if self.at("const") {
                let pm = self.b.open();
                self.bump();
                let n = self.identifier();
                self.b.set_field(n, "name");
                self.expect(":");
                let ty = self.type_();
                self.b.set_field(ty, "type");
                if self.at("=") {
                    self.bump();
                    let v = if self.at("{") { self.block() } else { self.primary_expr() };
                    self.b.set_field(v, "value");
                }
                self.b.close(pm, "const_parameter");
            } else if self.at("$") {
                self.metavariable();
            } else {
                let pm = self.b.open();
                let n = self.ident_as("type_identifier");
                self.b.set_field(n, "name");
                if self.at(":") {
                    let b = self.trait_bounds();
                    self.b.set_field(b, "bounds");
                }
                if self.at("=") {
                    self.bump();
                    let d = self.type_();
                    self.b.set_field(d, "default_type");
                }
                self.b.close(pm, "type_parameter");
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(">");
        self.b.close(m, "type_parameters")
    }

    fn trait_bounds(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // :
        loop {
            let t = self.peek();
            if t.k == TK::Lifetime {
                self.lifetime();
            } else if self.at("?") {
                let rm = self.b.open();
                self.bump();
                self.type_no_bounds();
                self.b.close(rm, "removed_trait_bound");
            } else if self.at("for") {
                self.higher_ranked();
            } else if self.at("(") {
                self.type_no_bounds();
            } else if t.k == TK::Ident || self.at("::") || self.at("<") {
                self.type_no_bounds();
            } else {
                break;
            }
            if self.at("+") {
                self.bump();
                continue;
            }
            break;
        }
        self.b.close(m, "trait_bounds")
    }

    fn higher_ranked(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // for
        let tp = self.type_parameters();
        self.b.set_field(tp, "type_parameters");
        let ty = self.type_no_bounds();
        self.b.set_field(ty, "type");
        self.b.close(m, "higher_ranked_trait_bound")
    }

    fn where_clause(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // where
        loop {
            let t = self.peek();
            if self.at("{") || self.at(";") || t.k == TK::Eof || self.at("=") {
                break;
            }
            let pm = self.b.open();
            let l = if t.k == TK::Lifetime {
                self.lifetime()
            } else if self.at("for") {
                self.higher_ranked()
            } else {
                self.type_no_bounds()
            };
            self.b.set_field(l, "left");
            if self.at(":") {
                let b = self.trait_bounds();
                self.b.set_field(b, "bounds");
            }
            self.b.close(pm, "where_predicate");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.b.close(m, "where_clause")
    }

    fn struct_item(&mut self, m: crate::ts::builder::Marker, kw: &str, kind: &'static str) {
        self.expect(kw);
        let n = self.ident_as("type_identifier");
        self.b.set_field(n, "name");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at("where") {
            self.where_clause();
        }
        if self.at("{") {
            let b = self.field_declaration_list();
            self.b.set_field(b, "body");
        } else if self.at("(") {
            let b = self.ordered_field_declaration_list();
            self.b.set_field(b, "body");
            if self.at("where") {
                self.where_clause();
            }
            self.expect(";");
        } else {
            self.expect(";");
        }
        self.b.close(m, kind);
    }

    fn field_declaration_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // {
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            while self.at("#") {
                self.attribute_item();
            }
            if self.at("}") {
                break;
            }
            let fm = self.b.open();
            self.visibility();
            let n = self.ident_as("field_identifier");
            self.b.set_field(n, "name");
            self.expect(":");
            let t = self.type_();
            self.b.set_field(t, "type");
            self.b.close(fm, "field_declaration");
            if self.at(",") {
                self.bump();
                continue;
            }
            if !self.at("}") {
                // error recovery
                if self.peek().k == TK::Eof {
                    break;
                }
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
                continue;
            }
            break;
        }
        self.expect("}");
        self.b.close(m, "field_declaration_list")
    }

    fn ordered_field_declaration_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // (
        loop {
            if self.at(")") || self.peek().k == TK::Eof {
                break;
            }
            while self.at("#") {
                self.attribute_item();
            }
            self.visibility();
            let t = self.type_();
            self.b.set_field(t, "type");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(")");
        self.b.close(m, "ordered_field_declaration_list")
    }

    fn enum_item(&mut self, m: crate::ts::builder::Marker) {
        self.bump(); // enum
        let n = self.ident_as("type_identifier");
        self.b.set_field(n, "name");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at("where") {
            self.where_clause();
        }
        let lm = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            while self.at("#") {
                self.attribute_item();
            }
            if self.at("}") {
                break;
            }
            let vm = self.b.open();
            self.visibility();
            let n = self.identifier();
            self.b.set_field(n, "name");
            if self.at("{") {
                let b = self.field_declaration_list();
                self.b.set_field(b, "body");
            } else if self.at("(") {
                let b = self.ordered_field_declaration_list();
                self.b.set_field(b, "body");
            }
            if self.at("=") {
                self.bump();
                let v = self.expression();
                self.b.set_field(v, "value");
            }
            self.b.close(vm, "enum_variant");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        let l = self.b.close(lm, "enum_variant_list");
        self.b.set_field(l, "body");
        self.b.close(m, "enum_item");
    }

    fn declaration_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let before = self.peek().s;
            self.statement(true);
            if self.peek().s == before {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.expect("}");
        self.b.close(m, "declaration_list")
    }

    fn trait_item(&mut self, m: crate::ts::builder::Marker) {
        if self.at("unsafe") {
            self.bump();
        }
        if self.at("auto") {
            self.bump();
        }
        self.expect("trait");
        let n = self.ident_as("type_identifier");
        self.b.set_field(n, "name");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at(":") {
            let b = self.trait_bounds();
            self.b.set_field(b, "bounds");
        }
        if self.at("where") {
            self.where_clause();
        }
        let b = self.declaration_list();
        self.b.set_field(b, "body");
        self.b.close(m, "trait_item");
    }

    fn impl_item(&mut self, m: crate::ts::builder::Marker) {
        if self.at("unsafe") {
            self.bump();
        }
        self.expect("impl");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at("!") {
            self.bump();
            let t = self.type_no_bounds();
            self.b.set_field(t, "trait");
            self.expect("for");
            let ty = self.type_();
            self.b.set_field(ty, "type");
        } else {
            let first = self.type_();
            if self.at("for") {
                self.b.set_field(first, "trait");
                self.bump();
                let ty = self.type_();
                self.b.set_field(ty, "type");
            } else {
                self.b.set_field(first, "type");
            }
        }
        if self.at("where") {
            self.where_clause();
        }
        if self.at(";") {
            self.bump();
        } else {
            let b = self.declaration_list();
            self.b.set_field(b, "body");
        }
        self.b.close(m, "impl_item");
    }

    fn mod_item(&mut self, m: crate::ts::builder::Marker) {
        self.expect("mod");
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at(";") {
            self.bump();
        } else {
            let b = self.declaration_list();
            self.b.set_field(b, "body");
        }
        self.b.close(m, "mod_item");
    }

    fn foreign_mod(&mut self, m: crate::ts::builder::Marker) {
        if self.at("unsafe") {
            self.bump();
        }
        let em = self.b.open();
        self.bump(); // extern
        let t = self.peek();
        if t.k == TK::Str || t.k == TK::RawStr {
            self.string_literal();
        }
        self.b.close(em, "extern_modifier");
        if self.at(";") {
            self.bump();
        } else {
            let b = self.declaration_list();
            self.b.set_field(b, "body");
        }
        self.b.close(m, "foreign_mod_item");
    }

    fn extern_crate(&mut self, m: crate::ts::builder::Marker) {
        self.bump(); // extern
        self.bump_as("crate", true);
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at("as") {
            self.bump();
            let a = self.identifier();
            self.b.set_field(a, "alias");
        }
        self.expect(";");
        self.b.close(m, "extern_crate_declaration");
    }

    fn const_item(&mut self, m: crate::ts::builder::Marker) {
        self.bump(); // const
        let n = if self.at("_") { self.bump() } else { self.identifier() };
        self.b.set_field(n, "name");
        if self.at(":") {
            self.bump();
            let t = self.type_();
            self.b.set_field(t, "type");
        }
        if self.at("=") {
            self.bump();
            let v = self.expression();
            self.b.set_field(v, "value");
        }
        self.expect(";");
        self.b.close(m, "const_item");
    }

    fn static_item(&mut self, m: crate::ts::builder::Marker) {
        self.bump(); // static
        if self.at("ref") {
            self.bump();
        }
        if self.at("mut") {
            self.mutable_specifier();
        }
        let n = self.identifier();
        self.b.set_field(n, "name");
        self.expect(":");
        let t = self.type_();
        self.b.set_field(t, "type");
        if self.at("=") {
            self.bump();
            let v = self.expression();
            self.b.set_field(v, "value");
        }
        self.expect(";");
        self.b.close(m, "static_item");
    }

    fn type_item(&mut self, m: crate::ts::builder::Marker) {
        self.bump(); // type
        let n = self.ident_as("type_identifier");
        self.b.set_field(n, "name");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at(":") {
            // associated type with bounds
            let b = self.trait_bounds();
            self.b.set_field(b, "bounds");
            if self.at("where") {
                self.where_clause();
            }
            self.expect(";");
            self.b.close(m, "associated_type");
            return;
        }
        if self.at(";") {
            self.bump();
            self.b.close(m, "associated_type");
            return;
        }
        if self.at("where") {
            self.where_clause();
        }
        self.expect("=");
        let t = self.type_();
        self.b.set_field(t, "type");
        if self.at("where") {
            self.where_clause();
        }
        self.expect(";");
        self.b.close(m, "type_item");
    }

    fn use_declaration(&mut self, m: crate::ts::builder::Marker) {
        self.bump(); // use
        let a = self.use_clause();
        self.b.set_field(a, "argument");
        self.expect(";");
        self.b.close(m, "use_declaration");
    }

    fn use_clause(&mut self) -> NodeId {
        if self.at("{") {
            return self.use_list();
        }
        if self.at("*") {
            let m = self.b.open();
            self.bump();
            return self.b.close(m, "use_wildcard");
        }
        if self.at("::") {
            // leading :: path
            let m = self.b.open();
            self.bump();
            if self.at("{") {
                let l = self.use_list();
                self.b.set_field(l, "list");
                return self.b.close(m, "scoped_use_list");
            }
            if self.at("*") {
                self.bump();
                return self.b.close(m, "use_wildcard");
            }
            let n = self.path_segment_ident();
            self.b.set_field(n, "name");
            let mut cur = self.b.close(m, "scoped_identifier");
            return self.use_path_continue(&mut cur);
        }
        let mut cur = self.path_segment_ident();
        self.use_path_continue(&mut cur)
    }

    fn use_path_continue(&mut self, cur: &mut NodeId) -> NodeId {
        loop {
            if self.at("::") {
                let (_, n1) = self.peek_nth(1);
                if n1 == "{" {
                    let m = self.b.open_before(*cur);
                    self.b.set_field(*cur, "path");
                    self.bump();
                    let l = self.use_list();
                    self.b.set_field(l, "list");
                    return self.b.close(m, "scoped_use_list");
                }
                if n1 == "*" {
                    let m = self.b.open_before(*cur);
                    self.bump();
                    self.bump();
                    return self.b.close(m, "use_wildcard");
                }
                let m = self.b.open_before(*cur);
                self.b.set_field(*cur, "path");
                self.bump();
                let n = self.path_segment_ident();
                self.b.set_field(n, "name");
                *cur = self.b.close(m, "scoped_identifier");
                continue;
            }
            break;
        }
        if self.at("as") {
            let m = self.b.open_before(*cur);
            self.b.set_field(*cur, "path");
            self.bump();
            let a = if self.at("_") { self.bump() } else { self.identifier() };
            self.b.set_field(a, "alias");
            return self.b.close(m, "use_as_clause");
        }
        *cur
    }

    fn path_segment_ident(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.text(t);
        match w {
            "self" => self.bump_as("self", true),
            "super" => self.bump_as("super", true),
            "crate" => self.bump_as("crate", true),
            _ => {
                if self.at("$") {
                    return self.metavariable();
                }
                self.identifier()
            }
        }
    }

    fn use_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // {
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            self.use_clause();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        self.b.close(m, "use_list")
    }

    fn macro_definition(&mut self, m: crate::ts::builder::Marker) {
        self.bump(); // macro_rules
        self.bump(); // !
        let n = self.identifier();
        self.b.set_field(n, "name");
        let (open, close) = match self.peek_text() {
            "(" => ("(", ")"),
            "[" => ("[", "]"),
            _ => ("{", "}"),
        };
        self.expect(open);
        loop {
            if self.at(close) || self.peek().k == TK::Eof {
                break;
            }
            let rm = self.b.open();
            let l = self.token_tree_pattern();
            self.b.set_field(l, "left");
            self.expect("=>");
            let r = self.token_tree();
            self.b.set_field(r, "right");
            self.b.close(rm, "macro_rule");
            if self.at(";") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(close);
        if close != "}" {
            self.expect(";");
        }
        self.b.close(m, "macro_definition");
    }

    fn metavariable(&mut self) -> NodeId {
        let t = self.peek();
        // '$' followed by identifier
        let s = t.s;
        self.pos = t.e;
        self.tok = None;
        let t2 = self.peek();
        if t2.k == TK::Ident && t2.s == s + 1 {
            let id = self.b.leaf("metavariable", true, s, t2.e);
            self.pos = t2.e;
            self.tok = None;
            return id;
        }
        self.b.leaf("$", false, s, s + 1)
    }

    fn token_tree_pattern(&mut self) -> NodeId {
        let m = self.b.open();
        let close = match self.peek_text() {
            "(" => ")",
            "[" => "]",
            "{" => "}",
            _ => {
                return self.b.close(m, "token_tree_pattern");
            }
        };
        self.bump();
        loop {
            if self.at(close) || self.peek().k == TK::Eof {
                break;
            }
            if self.at("(") || self.at("[") || self.at("{") {
                self.token_tree_pattern();
                continue;
            }
            if self.at("$") {
                let t = self.peek();
                let next = self.by.get(t.e).copied();
                if next == Some(b'(') {
                    // repetition pattern
                    let rm = self.b.open();
                    self.bump();
                    self.expect("(");
                    loop {
                        if self.at(")") || self.peek().k == TK::Eof {
                            break;
                        }
                        if self.at("(") || self.at("[") || self.at("{") {
                            self.token_tree_pattern();
                            continue;
                        }
                        self.tt_pattern_token();
                    }
                    self.expect(")");
                    // separator and repetition operator
                    if !(self.at("*") || self.at("+") || self.at("?")) {
                        self.tt_simple_token();
                    }
                    if self.at("*") || self.at("+") || self.at("?") {
                        self.bump();
                    }
                    self.b.close(rm, "token_repetition_pattern");
                    continue;
                }
            }
            self.tt_pattern_token();
        }
        self.expect(close);
        self.b.close(m, "token_tree_pattern")
    }

    fn tt_pattern_token(&mut self) {
        if self.at("$") {
            let t = self.peek();
            let next = self.ch(t.e);
            if next.map(is_id_start).unwrap_or(false) {
                let s = t.s;
                let mv = self.metavariable();
                let _ = s;
                if self.at(":") {
                    let bm = self.b.open_before(mv);
                    self.b.set_field(mv, "name");
                    self.bump();
                    let f = self.ident_as("fragment_specifier");
                    self.b.set_field(f, "type");
                    self.b.close(bm, "token_binding_pattern");
                }
                return;
            }
        }
        self.tt_simple_token();
    }

    fn tt_simple_token(&mut self) {
        let t = self.peek();
        match t.k {
            TK::Ident => {
                let w = self.text(t);
                if PRIMITIVES.contains(&w) {
                    self.bump_as("primitive_type", true);
                } else if w == "self" {
                    self.bump_as("self", true);
                } else if w == "super" {
                    self.bump_as("super", true);
                } else if w == "crate" {
                    self.bump_as("crate", true);
                } else if w == "mut" {
                    self.mutable_specifier();
                } else if w == "true" || w == "false" {
                    self.bump_as("boolean_literal", true);
                } else if KEYWORDS.contains(&w) {
                    self.bump();
                } else {
                    self.bump_as("identifier", true);
                }
            }
            TK::Lifetime => {
                // in token trees, lifetimes are "'" + identifier
                let s = t.s;
                self.b.leaf("'", false, s, s + 1);
                self.b.leaf("identifier", true, s + 1, t.e);
                self.pos = t.e;
                self.tok = None;
            }
            TK::Int => {
                self.bump_as("integer_literal", true);
            }
            TK::Float => {
                self.bump_as("float_literal", true);
            }
            TK::Str | TK::RawStr => {
                self.string_literal();
            }
            TK::Char => {
                self.bump_as("char_literal", true);
            }
            TK::Eof => {}
            _ => {
                if self.at("$") {
                    let t2 = self.peek();
                    if self.ch(t2.e).map(is_id_start).unwrap_or(false) {
                        self.metavariable();
                        return;
                    }
                }
                self.bump();
            }
        }
    }

    fn token_tree(&mut self) -> NodeId {
        let m = self.b.open();
        let close = match self.peek_text() {
            "(" => ")",
            "[" => "]",
            "{" => "}",
            _ => {
                return self.b.close(m, "token_tree");
            }
        };
        self.bump();
        loop {
            if self.at(close) || self.peek().k == TK::Eof {
                break;
            }
            if self.at("(") || self.at("[") || self.at("{") {
                self.token_tree();
                continue;
            }
            if self.at(")") || self.at("]") || self.at("}") {
                // mismatched closer
                break;
            }
            if self.at("$") {
                let t = self.peek();
                let next = self.by.get(t.e).copied();
                if next == Some(b'(') {
                    let rm = self.b.open();
                    self.bump();
                    self.expect("(");
                    loop {
                        if self.at(")") || self.peek().k == TK::Eof {
                            break;
                        }
                        if self.at("(") || self.at("[") || self.at("{") {
                            self.token_tree();
                            continue;
                        }
                        self.tt_simple_token();
                    }
                    self.expect(")");
                    if !(self.at("*") || self.at("+") || self.at("?")) {
                        self.tt_simple_token();
                    }
                    if self.at("*") || self.at("+") || self.at("?") {
                        self.bump();
                    }
                    self.b.close(rm, "token_repetition");
                    continue;
                }
            }
            self.tt_simple_token();
        }
        self.expect(close);
        self.b.close(m, "token_tree")
    }

    // ----------------------------------------------------------------- types
    fn type_(&mut self) -> NodeId {
        let t = self.type_no_bounds();
        if self.at("+") && self.type_can_bound(t) {
            let m = self.b.open_before(t);
            while self.at("+") {
                self.bump();
                let t2 = self.peek();
                if t2.k == TK::Lifetime {
                    self.lifetime();
                } else if self.at("?") {
                    let rm = self.b.open();
                    self.bump();
                    self.type_no_bounds();
                    self.b.close(rm, "removed_trait_bound");
                } else {
                    self.type_no_bounds();
                }
            }
            return self.b.close(m, "bounded_type");
        }
        t
    }

    fn type_can_bound(&self, _t: NodeId) -> bool {
        true
    }

    fn type_no_bounds(&mut self) -> NodeId {
        let t = self.peek();
        let w = if t.k == TK::Ident || t.k == TK::Punct { self.text(t) } else { "" };
        if t.k == TK::Lifetime {
            return self.lifetime();
        }
        match w {
            "&" | "&&" => {
                let m = self.b.open();
                if w == "&&" {
                    // treat as two references
                    self.bump_n("&", false, 1);
                    let inner = self.b.open();
                    let t2 = self.peek();
                    let _ = t2;
                    self.b.leaf("&", false, t.s + 1, t.s + 2);
                    self.pos = t.s + 2;
                    self.tok = None;
                    self.reference_rest();
                    let it = self.b.close(inner, "reference_type");
                    self.b.set_field(it, "type");
                    return self.b.close(m, "reference_type");
                }
                self.bump();
                self.reference_rest();
                self.b.close(m, "reference_type")
            }
            "*" => {
                let m = self.b.open();
                self.bump();
                if self.at("const") {
                    self.bump();
                } else if self.at("mut") {
                    self.mutable_specifier();
                }
                let ty = self.type_no_bounds();
                self.b.set_field(ty, "type");
                self.b.close(m, "pointer_type")
            }
            "(" => {
                let m = self.b.open();
                self.bump();
                if self.at(")") {
                    self.bump();
                    return self.b.close(m, "unit_type");
                }
                let mut n = 0;
                let mut comma = false;
                loop {
                    if self.at(")") || self.peek().k == TK::Eof {
                        break;
                    }
                    self.type_();
                    n += 1;
                    if self.at(",") {
                        self.bump();
                        comma = true;
                        continue;
                    }
                    break;
                }
                self.expect(")");
                if n == 1 && !comma {
                    // parenthesized type: tree-sitter has no node; treat as tuple_type? keep inner
                    return self.b.close(m, "tuple_type");
                }
                self.b.close(m, "tuple_type")
            }
            "[" => {
                let m = self.b.open();
                self.bump();
                let e = self.type_();
                self.b.set_field(e, "element");
                if self.at(";") {
                    self.bump();
                    let l = self.expression();
                    self.b.set_field(l, "length");
                }
                self.expect("]");
                self.b.close(m, "array_type")
            }
            "!" => {
                let m = self.b.open();
                self.bump();
                self.b.close(m, "never_type")
            }
            "impl" => {
                let m = self.b.open();
                self.bump();
                let tr = self.type_no_bounds();
                self.b.set_field(tr, "trait");
                if self.at("+") {
                    // impl A + B: bounded within abstract type? tree-sitter: abstract_type trait: bounded_type
                    let bm = self.b.open_before(tr);
                    while self.at("+") {
                        self.bump();
                        let t2 = self.peek();
                        if t2.k == TK::Lifetime {
                            self.lifetime();
                        } else {
                            self.type_no_bounds();
                        }
                    }
                    let bt = self.b.close(bm, "bounded_type");
                    self.b.set_field(bt, "trait");
                    self.b.nodes[tr as usize].field = None;
                }
                self.b.close(m, "abstract_type")
            }
            "dyn" => {
                let m = self.b.open();
                self.bump();
                let tr = self.type_no_bounds();
                self.b.set_field(tr, "trait");
                self.b.close(m, "dynamic_type")
            }
            "fn" | "unsafe" | "extern" | "for" => {
                let m = self.b.open();
                if self.at("for") {
                    let fm = self.b.open();
                    self.bump();
                    self.expect("<");
                    loop {
                        if self.peek().k == TK::Lifetime {
                            self.lifetime();
                        }
                        if self.at(",") {
                            self.bump();
                            continue;
                        }
                        break;
                    }
                    self.expect(">");
                    self.b.close(fm, "for_lifetimes");
                    if !self.at("fn") && !self.at("unsafe") && !self.at("extern") {
                        // for<'a> Trait
                        let ty = self.type_no_bounds();
                        let _ = ty;
                        return self.b.close(m, "higher_ranked_trait_bound");
                    }
                }
                self.function_modifiers();
                self.expect("fn");
                let ps = self.parameters();
                self.b.set_field(ps, "parameters");
                if self.at("->") {
                    self.bump();
                    let r = self.type_();
                    self.b.set_field(r, "return_type");
                }
                self.b.close(m, "function_type")
            }
            "<" => {
                // qualified path type
                let bt = self.bracketed_type();
                self.scoped_type_rest(bt)
            }
            "$" => self.metavariable(),
            "_" => self.bump(),
            _ => {
                if t.k == TK::Ident {
                    self.type_path()
                } else if w == "::" {
                    self.type_path()
                } else {
                    self.b.missing("type_identifier", true)
                }
            }
        }
    }

    fn reference_rest(&mut self) {
        if self.peek().k == TK::Lifetime {
            self.lifetime();
        }
        if self.at("mut") {
            self.mutable_specifier();
        }
        let ty = self.type_no_bounds();
        self.b.set_field(ty, "type");
    }

    fn bracketed_type(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // <
        let ty = self.type_();
        if self.at("as") {
            let qm = self.b.open_before(ty);
            self.b.set_field(ty, "type");
            self.bump();
            let a = self.type_();
            self.b.set_field(a, "alias");
            self.b.close(qm, "qualified_type");
        }
        self.expect(">");
        self.b.close(m, "bracketed_type")
    }

    fn scoped_type_rest(&mut self, mut cur: NodeId) -> NodeId {
        while self.at("::") {
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "path");
            self.bump();
            let n = self.ident_as("type_identifier");
            self.b.set_field(n, "name");
            cur = self.b.close(m, "scoped_type_identifier");
            if self.at("<") {
                cur = self.generic_args_on(cur, "generic_type");
            }
        }
        cur
    }

    /// Type path: Ident, path::Ident, generics, Fn(A) -> B sugar.
    fn type_path(&mut self) -> NodeId {
        // collect path segments
        let t = self.peek();
        let w = self.text(t);
        if t.k == TK::Ident && PRIMITIVES.contains(&w) && self.peek_nth(1).1 != "::" {
            return self.bump_as("primitive_type", true);
        }
        // first segment
        let mut cur;
        let leading = self.at("::");
        if leading {
            let m = self.b.open();
            self.bump();
            let n = self.ident_as("type_identifier");
            self.b.set_field(n, "name");
            cur = self.b.close(m, "scoped_type_identifier");
        } else {
            let (_, n1) = self.peek_nth(1);
            if n1 == "::" {
                cur = self.path_segment_ident();
            } else {
                if w == "Self" || !KEYWORDS.contains(&w) {
                    cur = self.ident_as("type_identifier");
                } else if w == "self" || w == "super" || w == "crate" {
                    cur = self.path_segment_ident();
                } else {
                    cur = self.ident_as("type_identifier");
                }
                // generics / fn sugar
                return self.type_suffix(cur);
            }
        }
        // middle segments: identifiers with possible generics, last becomes type_identifier
        loop {
            if !self.at("::") {
                break;
            }
            let (_, n1) = self.peek_nth(1);
            if n1 == "<" {
                // turbofish in type path: Foo::<T>
                self.bump();
                cur = self.generic_args_on(cur, "generic_type");
                continue;
            }
            let (_, n2) = self.peek_nth(2);
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "path");
            self.bump();
            if n2 == "::" {
                let n = self.path_segment_ident();
                self.b.set_field(n, "name");
                cur = self.b.close(m, "scoped_identifier");
                // generics in the middle: path::Foo<T>::Bar
                if self.at("<") {
                    self.b.set_kind(cur, "scoped_type_identifier");
                    let nn = self.b.nodes[cur as usize].children.last().copied();
                    if let Some(nn) = nn {
                        self.b.set_kind(nn, "type_identifier");
                    }
                    cur = self.generic_args_on(cur, "generic_type");
                }
            } else {
                let n = self.ident_as("type_identifier");
                self.b.set_field(n, "name");
                cur = self.b.close(m, "scoped_type_identifier");
                return self.type_suffix(cur);
            }
        }
        cur
    }

    fn type_suffix(&mut self, cur: NodeId) -> NodeId {
        if self.at("<") {
            return self.generic_args_on(cur, "generic_type");
        }
        if self.at("(") {
            // Fn(A, B) -> C sugar
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "trait");
            let ps = self.parameters();
            self.b.set_field(ps, "parameters");
            if self.at("->") {
                self.bump();
                let r = self.type_();
                self.b.set_field(r, "return_type");
            }
            return self.b.close(m, "function_type");
        }
        if self.at("!") {
            // macro in type position
            let m = self.b.open_before(cur);
            self.b.set_kind(cur, "identifier");
            self.b.set_field(cur, "macro");
            self.bump();
            self.token_tree();
            return self.b.close(m, "macro_invocation");
        }
        cur
    }

    fn generic_args_on(&mut self, cur: NodeId, kind: &'static str) -> NodeId {
        let m = self.b.open_before(cur);
        self.b.set_field(cur, "type");
        let ta = self.type_arguments();
        self.b.set_field(ta, "type_arguments");
        self.b.close(m, kind)
    }

    fn type_arguments(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // <
        loop {
            if self.at(">") || self.peek().k == TK::Eof {
                break;
            }
            let t = self.peek();
            if t.k == TK::Lifetime {
                self.lifetime();
            } else if matches!(t.k, TK::Int | TK::Float | TK::Str | TK::Char) || self.at("-") || self.at("true") || self.at("false") {
                self.literal();
            } else if self.at("{") {
                self.block();
            } else if t.k == TK::Ident && (self.peek_nth(1).1 == "=" || (self.peek_nth(1).1 == ":" && self.peek_nth(2).1 != ":")) {
                let bm = self.b.open();
                let n = self.ident_as("type_identifier");
                self.b.set_field(n, "name");
                if self.at(":") {
                    let b = self.trait_bounds();
                    self.b.set_field(b, "bounds");
                    self.b.close(bm, "trait_bounds_binding");
                } else {
                    self.bump();
                    let ty = self.type_();
                    self.b.set_field(ty, "type");
                    self.b.close(bm, "type_binding");
                }
            } else {
                self.type_();
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(">");
        self.b.close(m, "type_arguments")
    }

    // ------------------------------------------------------------ statements
    fn let_declaration(&mut self) {
        let m = self.b.open();
        self.bump(); // let
        if self.at("mut") && !self.pattern_starts_after_mut() {
            self.mutable_specifier();
        }
        let p = self.pattern();
        self.b.set_field(p, "pattern");
        if self.at(":") {
            self.bump();
            let t = self.type_();
            self.b.set_field(t, "type");
        }
        if self.at("=") {
            self.bump();
            let v = self.expression();
            self.b.set_field(v, "value");
        }
        if self.at("else") {
            self.bump();
            let b = self.block();
            self.b.set_field(b, "alternative");
        }
        self.expect(";");
        self.b.close(m, "let_declaration");
    }

    fn pattern_starts_after_mut(&mut self) -> bool {
        false
    }

    fn expression_statement(&mut self) {
        let m = self.b.open();
        let e = self.expression_stmt_expr();
        let kind = self.b.kind(e);
        let block_like = is_block_like(kind) && self.stmt_ended_with_block;
        if self.at(";") {
            self.bump();
            self.b.close(m, "expression_statement");
            return;
        }
        if block_like {
            self.b.close(m, "expression_statement");
            return;
        }
        if self.at("}") {
            // trailing expression of a block: no wrapper
            self.b.abandon(m);
            return;
        }
        if self.peek().k == TK::Eof {
            self.b.abandon(m);
            return;
        }
        self.expect(";");
        self.b.close(m, "expression_statement");
    }
}

fn is_block_like(kind: &str) -> bool {
    matches!(
        kind,
        "unsafe_block" | "async_block" | "gen_block" | "try_block" | "block" | "if_expression" | "match_expression" | "while_expression" | "loop_expression" | "for_expression" | "const_block"
    )
}
