    // ----------------------------------------------------------- expressions
    fn starts_block_like(&mut self) -> bool {
        let t = self.peek();
        if t.k == TK::Lifetime {
            let (_, n1) = self.peek_nth(1);
            return n1 == ":";
        }
        let w = self.peek_text();
        match w {
            "{" | "if" | "match" | "while" | "loop" | "for" => true,
            "unsafe" => self.peek_nth(1).1 == "{",
            "async" => {
                let (_, n1) = self.peek_nth(1);
                n1 == "{" || (n1 == "move" && self.peek_nth(2).1 == "{")
            }
            "const" => self.peek_nth(1).1 == "{",
            "try" => self.peek_nth(1).1 == "{",
            _ => false,
        }
    }

    fn expression_stmt_expr(&mut self) -> NodeId {
        self.ended_with_block = false;
        if self.starts_block_like() {
            let e = self.block_like_expr();
            if self.at(".") || self.at("?") {
                let e = self.postfix(e);
                let e = self.binary_rest(e, 0);
                return self.assign_rest(e);
            }
            self.ended_with_block = true;
            return e;
        }
        self.expression()
    }

    fn expression(&mut self) -> NodeId {
        let e = self.range_expr();
        self.assign_rest(e)
    }

    fn expression_no_struct(&mut self) -> NodeId {
        let saved = self.no_struct;
        self.no_struct = true;
        let e = self.expression();
        self.no_struct = saved;
        e
    }

    fn assign_rest(&mut self, left: NodeId) -> NodeId {
        let t = self.peek();
        if t.k != TK::Punct {
            return left;
        }
        let w = self.text(t);
        let mut cur = left;
        if w == "=" {
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "left");
            self.bump();
            let r = self.range_expr();
            self.b.set_field(r, "right");
            cur = self.b.close(m, "assignment_expression");
            return self.assign_rest(cur);
        }
        let gt = self.at_gt_op();
        let op: Option<&'static str> = match w {
            "+=" | "-=" | "*=" | "/=" | "%=" | "^=" | "&=" | "|=" | "<<=" => Some(intern(w)),
            _ => {
                if gt == Some(">>=") {
                    Some(">>=")
                } else {
                    None
                }
            }
        };
        if let Some(op) = op {
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "left");
            let o = self.bump_n(op, false, op.len());
            self.b.set_field(o, "operator");
            let r = self.range_expr();
            self.b.set_field(r, "right");
            cur = self.b.close(m, "compound_assignment_expr");
            return self.assign_rest(cur);
        }
        cur
    }

    fn range_expr(&mut self) -> NodeId {
        if self.at("..") || self.at("..=") || self.at("...") {
            let m = self.b.open();
            self.bump();
            if self.range_operand_follows() {
                self.binary(P_OR);
            }
            return self.b.close(m, "range_expression");
        }
        let left = self.binary(P_OR);
        if self.at("..") || self.at("..=") || self.at("...") {
            let m = self.b.open_before(left);
            self.bump();
            if self.range_operand_follows() {
                self.binary(P_OR);
            }
            return self.b.close(m, "range_expression");
        }
        left
    }

    fn range_operand_follows(&mut self) -> bool {
        let t = self.peek();
        match t.k {
            TK::Eof => false,
            TK::Punct => {
                let w = self.text(t);
                !matches!(w, ")" | "]" | "}" | "," | ";" | "=>" | "=" | ".")
                    && !(w == "{" && self.no_struct)
            }
            TK::Ident => !matches!(self.text(t), "as"),
            _ => true,
        }
    }

    fn binop(&mut self) -> Option<(&'static str, u8)> {
        let t = self.peek();
        if t.k == TK::Ident && self.text(t) == "as" {
            return Some(("as", P_CAST));
        }
        if t.k != TK::Punct {
            return None;
        }
        let w = self.text(t);
        if w == ">" {
            return match self.at_gt_op() {
                Some(">>") => Some((">>", P_SHIFT)),
                Some(">=") => Some((">=", P_CMP)),
                Some(">>=") => None,
                _ => Some((">", P_CMP)),
            };
        }
        Some(match w {
            "||" => ("||", P_OR),
            "&&" => ("&&", P_AND),
            "==" => ("==", P_CMP),
            "!=" => ("!=", P_CMP),
            "<" => ("<", P_CMP),
            "<=" => ("<=", P_CMP),
            "|" => ("|", P_BOR),
            "^" => ("^", P_XOR),
            "&" => ("&", P_BAND),
            "<<" => ("<<", P_SHIFT),
            "+" => ("+", P_ADD),
            "-" => ("-", P_ADD),
            "*" => ("*", P_MUL),
            "/" => ("/", P_MUL),
            "%" => ("%", P_MUL),
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) -> NodeId {
        let left = self.unary();
        self.binary_rest(left, min)
    }

    fn binary_rest(&mut self, mut left: NodeId, min: u8) -> NodeId {
        loop {
            let (op, p) = match self.binop() {
                Some(x) => x,
                None => break,
            };
            if p < min.max(1) {
                break;
            }
            if op == "as" {
                let m = self.b.open_before(left);
                self.b.set_field(left, "value");
                self.bump();
                let t = self.type_no_bounds();
                self.b.set_field(t, "type");
                left = self.b.close(m, "type_cast_expression");
                continue;
            }
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            let o = self.bump_n(op, false, op.len());
            self.b.set_field(o, "operator");
            let r = self.binary(p + 1);
            self.b.set_field(r, "right");
            left = self.b.close(m, "binary_expression");
        }
        left
    }

    fn unary(&mut self) -> NodeId {
        let t = self.peek();
        if t.k == TK::Punct {
            match self.text(t) {
                "-" | "!" | "*" => {
                    let m = self.b.open();
                    self.bump();
                    self.unary();
                    return self.b.close(m, "unary_expression");
                }
                "&" | "&&" => {
                    let m = self.b.open();
                    if self.text(t) == "&&" {
                        self.bump_n("&", false, 1);
                        let im = self.b.open();
                        self.b.leaf("&", false, t.s + 1, t.s + 2);
                        self.pos = t.s + 2;
                        self.tok = None;
                        self.reference_expr_rest();
                        let inner = self.b.close(im, "reference_expression");
                        self.b.set_field(inner, "value");
                        return self.b.close(m, "reference_expression");
                    }
                    self.bump();
                    self.reference_expr_rest();
                    return self.b.close(m, "reference_expression");
                }
                _ => {}
            }
        }
        let p = self.primary_expr();
        self.postfix(p)
    }

    fn reference_expr_rest(&mut self) {
        if self.at("raw") && (self.peek_nth(1).1 == "const" || self.peek_nth(1).1 == "mut") {
            self.bump();
            if self.at("const") {
                self.bump();
            } else {
                self.mutable_specifier();
            }
        } else if self.at("mut") {
            self.mutable_specifier();
        }
        let v = self.unary();
        self.b.set_field(v, "value");
    }

    fn postfix(&mut self, mut e: NodeId) -> NodeId {
        loop {
            let t = self.peek();
            if t.k != TK::Punct {
                break;
            }
            match self.text(t) {
                "?" => {
                    let m = self.b.open_before(e);
                    self.bump();
                    e = self.b.close(m, "try_expression");
                }
                "." => {
                    let (k1, n1) = self.peek_nth(1);
                    if n1 == "await" {
                        let m = self.b.open_before(e);
                        self.bump();
                        self.bump();
                        e = self.b.close(m, "await_expression");
                        continue;
                    }
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "value");
                    self.bump();
                    let f = if k1 == TK::Int {
                        self.bump_as("integer_literal", true)
                    } else if k1 == TK::Float {
                        // x.0.1 lexed as float: split
                        let t2 = self.peek();
                        let txt = self.text(t2);
                        if let Some(dot) = txt.find('.') {
                            let id = self.b.leaf("integer_literal", true, t2.s, t2.s + dot);
                            self.pos = t2.s + dot;
                            self.tok = None;
                            id
                        } else {
                            self.bump_as("integer_literal", true)
                        }
                    } else {
                        self.ident_as("field_identifier")
                    };
                    self.b.set_field(f, "field");
                    e = self.b.close(m, "field_expression");
                    if self.at("::") && self.peek_nth(1).1 == "<" {
                        let gm = self.b.open_before(e);
                        self.b.set_field(e, "function");
                        self.bump();
                        let ta = self.type_arguments();
                        self.b.set_field(ta, "type_arguments");
                        e = self.b.close(gm, "generic_function");
                    }
                }
                "(" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let a = self.arguments();
                    self.b.set_field(a, "arguments");
                    e = self.b.close(m, "call_expression");
                }
                "[" => {
                    let m = self.b.open_before(e);
                    self.bump();
                    let saved = self.no_struct;
                    self.no_struct = false;
                    self.expression();
                    self.no_struct = saved;
                    self.expect("]");
                    e = self.b.close(m, "index_expression");
                }
                _ => break,
            }
        }
        e
    }

    fn arguments(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // (
        let saved = self.no_struct;
        self.no_struct = false;
        loop {
            if self.at(")") || self.peek().k == TK::Eof {
                break;
            }
            while self.at("#") {
                self.attribute_item();
            }
            self.expression();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.no_struct = saved;
        self.expect(")");
        self.b.close(m, "arguments")
    }

    fn block_like_expr(&mut self) -> NodeId {
        let t = self.peek();
        if t.k == TK::Lifetime {
            // labeled loop / block
            let (_, n2) = self.peek_nth(2);
            match n2 {
                "loop" | "while" | "for" => {
                    let m = self.b.open();
                    self.label();
                    self.bump(); // :
                    return self.loop_like(m);
                }
                _ => {
                    // labeled block
                    let m = self.b.open();
                    self.label();
                    self.bump();
                    self.block_inner();
                    return self.b.close(m, "block");
                }
            }
        }
        let w = self.peek_text();
        match w {
            "{" => self.block(),
            "if" => self.if_expression(),
            "match" => self.match_expression(),
            "while" | "loop" | "for" => {
                let m = self.b.open();
                self.loop_like(m)
            }
            "unsafe" => {
                let m = self.b.open();
                self.bump();
                self.block();
                self.b.close(m, "unsafe_block")
            }
            "async" => {
                let m = self.b.open();
                self.bump();
                if self.at("move") {
                    self.bump();
                }
                self.block();
                self.b.close(m, "async_block")
            }
            "const" => {
                let m = self.b.open();
                self.bump();
                let b = self.block();
                self.b.set_field(b, "body");
                self.b.close(m, "const_block")
            }
            "try" => {
                let m = self.b.open();
                self.bump();
                self.block();
                self.b.close(m, "try_block")
            }
            _ => self.primary_expr(),
        }
    }

    fn loop_like(&mut self, m: crate::ts::builder::Marker) -> NodeId {
        let w = self.peek_text();
        match w {
            "loop" => {
                self.bump();
                let b = self.block();
                self.b.set_field(b, "body");
                self.b.close(m, "loop_expression")
            }
            "while" => {
                self.bump();
                let c = self.condition();
                self.b.set_field(c, "condition");
                let b = self.block();
                self.b.set_field(b, "body");
                self.b.close(m, "while_expression")
            }
            _ => {
                self.bump(); // for
                let p = self.pattern();
                self.b.set_field(p, "pattern");
                self.expect("in");
                let v = self.expression_no_struct();
                self.b.set_field(v, "value");
                let b = self.block();
                self.b.set_field(b, "body");
                self.b.close(m, "for_expression")
            }
        }
    }

    fn condition(&mut self) -> NodeId {
        let first = self.condition_atom();
        if self.at("&&") {
            // let chain if any let_condition is involved
            let has_let = self.b.kind(first) == "let_condition" || self.chain_has_let();
            if has_let {
                let m = self.b.open_before(first);
                while self.at("&&") {
                    self.bump();
                    self.condition_atom();
                }
                return self.b.close(m, "let_chain");
            }
        }
        first
    }

    fn chain_has_let(&mut self) -> bool {
        // look ahead for `&& let` before the block
        let save_pos = self.pos;
        let save_tok = self.tok;
        let save_nodes = self.b.nodes.len();
        let mut depth = 0i32;
        let mut prev_and = false;
        let mut found = false;
        let mut cur = self.peek();
        let mut n = 0;
        loop {
            n += 1;
            if n > 5000 {
                break;
            }
            match cur.k {
                TK::Eof => break,
                TK::Punct => {
                    let w = self.text(cur);
                    match w {
                        "(" | "[" => depth += 1,
                        ")" | "]" => depth -= 1,
                        "{" if depth == 0 => break,
                        _ => {}
                    }
                    prev_and = w == "&&" && depth == 0;
                }
                TK::Ident => {
                    if prev_and && self.text(cur) == "let" {
                        found = true;
                        break;
                    }
                    prev_and = false;
                }
                _ => prev_and = false,
            }
            self.pos = if matches!(cur.k, TK::Str | TK::RawStr) { self.skip_string_raw(cur) } else { cur.e };
            self.skip_trivia_silent();
            cur = self.lex();
        }
        self.pos = save_pos;
        self.tok = save_tok;
        self.b.nodes.truncate(save_nodes);
        found
    }

    fn condition_atom(&mut self) -> NodeId {
        if self.at("let") {
            let m = self.b.open();
            self.bump();
            let p = self.pattern();
            self.b.set_field(p, "pattern");
            self.expect("=");
            let saved = self.no_struct;
            self.no_struct = true;
            let v = self.binary(P_AND + 1);
            self.no_struct = saved;
            self.b.set_field(v, "value");
            return self.b.close(m, "let_condition");
        }
        let saved = self.no_struct;
        self.no_struct = true;
        let e = if self.chain_has_let() { self.binary(P_AND + 1) } else { self.expression() };
        self.no_struct = saved;
        e
    }

    fn if_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // if
        let c = self.condition();
        self.b.set_field(c, "condition");
        let b = self.block();
        self.b.set_field(b, "consequence");
        if self.at("else") {
            let em = self.b.open();
            self.bump();
            if self.at("if") {
                self.if_expression();
            } else {
                self.block();
            }
            let e = self.b.close(em, "else_clause");
            self.b.set_field(e, "alternative");
        }
        self.b.close(m, "if_expression")
    }

    fn match_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // match
        let v = self.expression_no_struct();
        self.b.set_field(v, "value");
        let bm = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let am = self.b.open();
            while self.at("#") {
                self.attribute_item();
            }
            let pm = self.b.open();
            if self.at("|") {
                self.bump();
            }
            if !self.at("_") || self.peek_nth(1).1 != "=>" {
                self.pattern();
            } else {
                self.bump();
            }
            if self.at("if") {
                self.bump();
                let c = self.condition();
                self.b.set_field(c, "condition");
            }
            let mp = self.b.close(pm, "match_pattern");
            self.b.set_field(mp, "pattern");
            self.expect("=>");
            let saved = self.no_struct;
            self.no_struct = false;
            let v = if self.starts_block_like() {
                let e = self.block_like_expr();
                if self.at(".") || self.at("?") {
                    let e = self.postfix(e);
                    let e = self.binary_rest(e, 0);
                    self.assign_rest(e)
                } else {
                    e
                }
            } else {
                self.expression()
            };
            self.no_struct = saved;
            self.b.set_field(v, "value");
            if self.at(",") {
                self.bump();
            }
            self.b.close(am, "match_arm");
        }
        self.expect("}");
        let mb = self.b.close(bm, "match_block");
        self.b.set_field(mb, "body");
        self.b.close(m, "match_expression")
    }

    fn block(&mut self) -> NodeId {
        let m = self.b.open();
        self.block_inner();
        self.b.close(m, "block")
    }

    fn block_inner(&mut self) {
        let saved = self.no_struct;
        self.no_struct = false;
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let before = self.peek().s;
            self.statement(false);
            if self.peek().s == before && !self.at("}") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.expect("}");
        self.no_struct = saved;
    }

    fn closure(&mut self) -> NodeId {
        let m = self.b.open();
        if self.at("static") {
            self.bump();
        }
        if self.at("async") {
            self.bump();
        }
        if self.at("move") {
            self.bump();
        }
        let pm = self.b.open();
        if self.at("||") {
            self.bump();
        } else {
            self.bump(); // |
            loop {
                if self.at("|") || self.peek().k == TK::Eof {
                    break;
                }
                let par = self.b.open();
                let p = self.pattern_no_or();
                if self.at(":") {
                    self.b.set_field(p, "pattern");
                    self.bump();
                    let t = self.type_();
                    self.b.set_field(t, "type");
                    self.b.close(par, "parameter");
                } else {
                    self.b.abandon(par);
                }
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect("|");
        }
        let ps = self.b.close(pm, "closure_parameters");
        self.b.set_field(ps, "parameters");
        if self.at("->") {
            self.bump();
            let r = self.type_();
            self.b.set_field(r, "return_type");
            let b = self.block();
            self.b.set_field(b, "body");
        } else if self.at("_") {
            let b = self.bump();
            self.b.set_field(b, "body");
        } else {
            let b = self.expression();
            self.b.set_field(b, "body");
        }
        self.b.close(m, "closure_expression")
    }

    fn literal(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Int => self.bump_as("integer_literal", true),
            TK::Float => self.bump_as("float_literal", true),
            TK::Str | TK::RawStr => self.string_literal(),
            TK::Char => self.bump_as("char_literal", true),
            _ => {
                if self.at("true") || self.at("false") {
                    return self.bump_as("boolean_literal", true);
                }
                if self.at("-") {
                    let m = self.b.open();
                    self.bump();
                    self.literal();
                    return self.b.close(m, "negative_literal");
                }
                self.b.missing("integer_literal", true)
            }
        }
    }

    fn primary_expr(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Int | TK::Float | TK::Str | TK::RawStr | TK::Char => return self.literal(),
            TK::Lifetime => {
                if self.peek_nth(1).1 == ":" {
                    return self.block_like_expr();
                }
                return self.lifetime();
            }
            TK::Eof => return self.b.missing("identifier", true),
            _ => {}
        }
        let w = self.text(t);
        match w {
            "(" => {
                let m = self.b.open();
                self.bump();
                let saved = self.no_struct;
                self.no_struct = false;
                if self.at(")") {
                    self.bump();
                    self.no_struct = saved;
                    return self.b.close(m, "unit_expression");
                }
                while self.at("#") {
                    self.attribute_item();
                }
                self.expression();
                if self.at(",") {
                    while self.at(",") {
                        self.bump();
                        if self.at(")") {
                            break;
                        }
                        self.expression();
                    }
                    self.expect(")");
                    self.no_struct = saved;
                    return self.b.close(m, "tuple_expression");
                }
                self.expect(")");
                self.no_struct = saved;
                return self.b.close(m, "parenthesized_expression");
            }
            "[" => {
                let m = self.b.open();
                self.bump();
                let saved = self.no_struct;
                self.no_struct = false;
                if !self.at("]") {
                    while self.at("#") {
                        self.attribute_item();
                    }
                    self.expression();
                    if self.at(";") {
                        self.bump();
                        let l = self.expression();
                        self.b.set_field(l, "length");
                    } else {
                        while self.at(",") {
                            self.bump();
                            if self.at("]") {
                                break;
                            }
                            self.expression();
                        }
                    }
                }
                self.expect("]");
                self.no_struct = saved;
                return self.b.close(m, "array_expression");
            }
            "|" | "||" | "move" | "static" => return self.closure(),
            "async" => {
                let (_, n1) = self.peek_nth(1);
                if n1 == "{" || n1 == "move" && self.peek_nth(2).1 == "{" {
                    return self.block_like_expr();
                }
                return self.closure();
            }
            "{" | "if" | "match" | "while" | "loop" | "for" => return self.block_like_expr(),
            "unsafe" | "const" | "try" if self.peek_nth(1).1 == "{" => return self.block_like_expr(),
            "return" => {
                let m = self.b.open();
                self.bump();
                if self.expr_follows() {
                    self.expression();
                }
                return self.b.close(m, "return_expression");
            }
            "yield" => {
                let m = self.b.open();
                self.bump();
                if self.expr_follows() {
                    self.expression();
                }
                return self.b.close(m, "yield_expression");
            }
            "break" => {
                let m = self.b.open();
                self.bump();
                if self.peek().k == TK::Lifetime {
                    self.label();
                }
                if self.expr_follows() {
                    self.expression();
                }
                return self.b.close(m, "break_expression");
            }
            "continue" => {
                let m = self.b.open();
                self.bump();
                if self.peek().k == TK::Lifetime {
                    self.label();
                }
                return self.b.close(m, "continue_expression");
            }
            "true" | "false" => return self.bump_as("boolean_literal", true),
            "<" => {
                // qualified path expression <T as Trait>::f
                let bt = self.bracketed_type();
                let mut cur = bt;
                while self.at("::") {
                    let m = self.b.open_before(cur);
                    self.b.set_field(cur, "path");
                    self.bump();
                    let n = self.identifier();
                    self.b.set_field(n, "name");
                    cur = self.b.close(m, "scoped_identifier");
                }
                return cur;
            }
            "$" => return self.metavariable(),
            "::" => {}
            _ => {}
        }
        if t.k == TK::Ident || w == "::" {
            return self.path_expression_full();
        }
        // unknown
        self.b.missing("identifier", true)
    }

    fn expr_follows(&mut self) -> bool {
        let t = self.peek();
        match t.k {
            TK::Eof => false,
            TK::Punct => !matches!(self.text(t), ")" | "]" | "}" | "," | ";" | "=>"),
            TK::Ident => !matches!(self.text(t), "else"),
            _ => true,
        }
    }

    /// Path expression possibly followed by generics, macro invocation, or struct literal.
    fn path_expression_full(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.text(t);
        let (_, n1) = self.peek_nth(1);
        // macro invocation
        if n1 == "!" && t.k == TK::Ident && !KEYWORDS.contains(&w) {
            let (_, n2) = self.peek_nth(2);
            if n2 == "(" || n2 == "[" || n2 == "{" {
                let m = self.b.open();
                let id = self.identifier();
                self.b.set_field(id, "macro");
                self.bump(); // !
                self.token_tree();
                return self.b.close(m, "macro_invocation");
            }
        }
        if w == "self" && n1 != "::" {
            return self.bump_as("self", true);
        }
        if PRIMITIVES.contains(&w) && n1 != "::" {
            return self.bump_as("identifier", true);
        }
        let mut cur = if self.at("::") {
            let m = self.b.open();
            self.bump();
            let n = self.identifier();
            self.b.set_field(n, "name");
            self.b.close(m, "scoped_identifier")
        } else if n1 == "::" || n1 == "{" && !self.no_struct {
            self.path_segment_ident()
        } else {
            let id = self.path_segment_ident();
            return id;
        };
        loop {
            if !self.at("::") {
                break;
            }
            let (k1, n1) = self.peek_nth(1);
            if n1 == "<" {
                // turbofish
                let (_, after) = (k1, n1);
                let _ = after;
                let m = self.b.open_before(cur);
                self.b.set_field(cur, "function");
                self.bump();
                let ta = self.type_arguments();
                self.b.set_field(ta, "type_arguments");
                cur = self.b.close(m, "generic_function");
                // Foo::<T>::bar → scoped_identifier with generic_type path
                if self.at("::") {
                    self.b.set_kind(cur, "generic_type");
                    let ch = self.b.nodes[cur as usize].children.clone();
                    if let Some(&first) = ch.first() {
                        self.b.set_field(first, "type");
                        if self.b.kind(first) == "identifier" {
                            self.b.set_kind(first, "type_identifier");
                        }
                    }
                    continue;
                }
                break;
            }
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "path");
            self.bump();
            let n = self.path_segment_ident();
            self.b.set_field(n, "name");
            cur = self.b.close(m, "scoped_identifier");
            // macro on path
            if self.at("!") {
                let (_, n2) = self.peek_nth(1);
                if n2 == "(" || n2 == "[" || n2 == "{" {
                    let mm = self.b.open_before(cur);
                    self.b.set_field(cur, "macro");
                    self.bump();
                    self.token_tree();
                    return self.b.close(mm, "macro_invocation");
                }
            }
        }
        if self.at("{") && !self.no_struct {
            // struct expression
            let kind = self.b.kind(cur);
            if kind == "identifier" || kind == "scoped_identifier" || kind == "generic_function" || kind == "generic_type" {
                return self.struct_expression(cur);
            }
        }
        cur
    }

    fn struct_expression(&mut self, name: NodeId) -> NodeId {
        // convert name kinds
        match self.b.kind(name) {
            "identifier" => self.b.set_kind(name, "type_identifier"),
            "scoped_identifier" => {
                self.b.set_kind(name, "scoped_type_identifier");
                let last = self.b.nodes[name as usize].children.last().copied();
                if let Some(l) = last {
                    if self.b.kind(l) == "identifier" {
                        self.b.set_kind(l, "type_identifier");
                    }
                }
            }
            "generic_function" => {
                self.b.set_kind(name, "generic_type");
                let ch = self.b.nodes[name as usize].children.clone();
                if let Some(&first) = ch.first() {
                    self.b.set_field(first, "type");
                    if self.b.kind(first) == "identifier" {
                        self.b.set_kind(first, "type_identifier");
                    }
                }
            }
            _ => {}
        }
        let m = self.b.open_before(name);
        self.b.set_field(name, "name");
        let lm = self.b.open();
        self.bump(); // {
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            while self.at("#") {
                self.attribute_item();
            }
            if self.at("..") {
                let bm = self.b.open();
                self.bump();
                self.expression();
                self.b.close(bm, "base_field_initializer");
            } else {
                let t = self.peek();
                let (_, n1) = self.peek_nth(1);
                if n1 == ":" {
                    let fm = self.b.open();
                    let f = if t.k == TK::Int { self.bump_as("integer_literal", true) } else { self.ident_as("field_identifier") };
                    self.b.set_field(f, "field");
                    self.bump();
                    let v = self.expression();
                    self.b.set_field(v, "value");
                    self.b.close(fm, "field_initializer");
                } else {
                    let fm = self.b.open();
                    self.identifier();
                    self.b.close(fm, "shorthand_field_initializer");
                }
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        let l = self.b.close(lm, "field_initializer_list");
        self.b.set_field(l, "body");
        self.b.close(m, "struct_expression")
    }

    fn path_expr(&mut self) -> NodeId {
        let mut cur = if self.at("::") {
            let m = self.b.open();
            self.bump();
            let n = self.identifier();
            self.b.set_field(n, "name");
            self.b.close(m, "scoped_identifier")
        } else {
            self.path_segment_ident()
        };
        while self.at("::") {
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "path");
            self.bump();
            let n = self.path_segment_ident();
            self.b.set_field(n, "name");
            cur = self.b.close(m, "scoped_identifier");
        }
        cur
    }

    // -------------------------------------------------------------- patterns
    fn pattern(&mut self) -> NodeId {
        let lead = self.at("|");
        let m = if lead { Some(self.b.open()) } else { None };
        if lead {
            self.bump();
        }
        let first = self.pattern_no_or();
        if self.at("|") || lead {
            let om = match m {
                Some(m) => m,
                None => self.b.open_before(first),
            };
            while self.at("|") {
                self.bump();
                self.pattern_no_or();
            }
            return self.b.close(om, "or_pattern");
        }
        first
    }

    fn pattern_no_or(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.text(t);
        let p = match t.k {
            TK::Int | TK::Float | TK::Str | TK::RawStr | TK::Char => self.literal(),
            TK::Punct => match w {
                "-" => self.literal(),
                "(" => {
                    let m = self.b.open();
                    self.bump();
                    loop {
                        if self.at(")") || self.peek().k == TK::Eof {
                            break;
                        }
                        self.pattern();
                        if self.at(",") {
                            self.bump();
                            continue;
                        }
                        break;
                    }
                    self.expect(")");
                    self.b.close(m, "tuple_pattern")
                }
                "[" => {
                    let m = self.b.open();
                    self.bump();
                    loop {
                        if self.at("]") || self.peek().k == TK::Eof {
                            break;
                        }
                        self.pattern();
                        if self.at(",") {
                            self.bump();
                            continue;
                        }
                        break;
                    }
                    self.expect("]");
                    self.b.close(m, "slice_pattern")
                }
                "&" | "&&" => {
                    let m = self.b.open();
                    self.bump();
                    if self.at("mut") {
                        self.mutable_specifier();
                    }
                    self.pattern_no_or();
                    self.b.close(m, "reference_pattern")
                }
                ".." => {
                    let m = self.b.open();
                    self.bump();
                    self.b.close(m, "remaining_field_pattern")
                }
                "..=" => {
                    let m = self.b.open();
                    self.bump();
                    self.literal();
                    self.b.close(m, "range_pattern")
                }
                "$" => self.metavariable(),
                "::" | "<" => self.path_pattern(),
                _ => self.b.missing("identifier", true),
            },
            TK::Ident => match w {
                "_" => self.bump(),
                "ref" => {
                    let m = self.b.open();
                    self.bump();
                    if self.at("mut") {
                        self.mutable_specifier();
                    }
                    self.pattern_no_or();
                    self.b.close(m, "ref_pattern")
                }
                "mut" => {
                    let m = self.b.open();
                    self.mutable_specifier();
                    self.pattern_no_or();
                    self.b.close(m, "mut_pattern")
                }
                "true" | "false" => self.bump_as("boolean_literal", true),
                "box" => {
                    let m = self.b.open();
                    self.bump();
                    self.pattern_no_or();
                    self.b.close(m, "box_pattern")
                }
                "const" if self.peek_nth(1).1 == "{" => self.block_like_expr(),
                _ => self.path_pattern(),
            },
            _ => self.b.missing("identifier", true),
        };
        // range pattern
        if self.at("..=") || self.at("...") || (self.at("..") && self.range_pat_continues()) {
            let m = self.b.open_before(p);
            self.b.set_field(p, "left");
            self.bump();
            let t2 = self.peek();
            if matches!(t2.k, TK::Int | TK::Float | TK::Char | TK::Ident) || self.at("-") {
                let r = if t2.k == TK::Ident { self.path_pattern() } else { self.literal() };
                self.b.set_field(r, "right");
            }
            return self.b.close(m, "range_pattern");
        }
        p
    }

    fn range_pat_continues(&mut self) -> bool {
        let (k, n) = self.peek_nth(1);
        matches!(k, TK::Int | TK::Float | TK::Char) || n == "-"
    }

    fn path_pattern(&mut self) -> NodeId {
        let t = self.peek();
        let (_, n1) = self.peek_nth(1);
        // captured pattern: ident @ pat
        if t.k == TK::Ident && n1 == "@" {
            let m = self.b.open();
            self.identifier();
            self.bump();
            self.pattern_no_or();
            return self.b.close(m, "captured_pattern");
        }
        // macro in pattern
        if t.k == TK::Ident && n1 == "!" {
            let m = self.b.open();
            let id = self.identifier();
            self.b.set_field(id, "macro");
            self.bump();
            self.token_tree();
            return self.b.close(m, "macro_invocation");
        }
        let cur = if self.at("<") {
            let bt = self.bracketed_type();
            let mut c = bt;
            while self.at("::") {
                let m = self.b.open_before(c);
                self.b.set_field(c, "path");
                self.bump();
                let n = self.identifier();
                self.b.set_field(n, "name");
                c = self.b.close(m, "scoped_identifier");
            }
            c
        } else {
            let mut c = self.path_expr_generic();
            let _ = &mut c;
            c
        };
        if self.at("(") {
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "type");
            self.bump();
            loop {
                if self.at(")") || self.peek().k == TK::Eof {
                    break;
                }
                self.pattern();
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect(")");
            return self.b.close(m, "tuple_struct_pattern");
        }
        if self.at("{") {
            // struct pattern
            match self.b.kind(cur) {
                "identifier" => self.b.set_kind(cur, "type_identifier"),
                "scoped_identifier" => {
                    self.b.set_kind(cur, "scoped_type_identifier");
                    let last = self.b.nodes[cur as usize].children.last().copied();
                    if let Some(l) = last {
                        if self.b.kind(l) == "identifier" {
                            self.b.set_kind(l, "type_identifier");
                        }
                    }
                }
                _ => {}
            }
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "type");
            self.bump();
            loop {
                if self.at("}") || self.peek().k == TK::Eof {
                    break;
                }
                while self.at("#") {
                    self.attribute_item();
                }
                if self.at("..") {
                    let rm = self.b.open();
                    self.bump();
                    self.b.close(rm, "remaining_field_pattern");
                } else {
                    let fm = self.b.open();
                    if self.at("ref") {
                        self.bump();
                    }
                    if self.at("mut") {
                        self.mutable_specifier();
                    }
                    let (_, n1) = self.peek_nth(1);
                    if n1 == ":" {
                        let n = self.ident_as("field_identifier");
                        self.b.set_field(n, "name");
                        self.bump();
                        let p = self.pattern();
                        self.b.set_field(p, "pattern");
                    } else {
                        let n = self.ident_as("shorthand_field_identifier");
                        self.b.set_field(n, "name");
                    }
                    self.b.close(fm, "field_pattern");
                }
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect("}");
            return self.b.close(m, "struct_pattern");
        }
        cur
    }

    fn path_expr_generic(&mut self) -> NodeId {
        let mut cur = if self.at("::") {
            let m = self.b.open();
            self.bump();
            let n = self.identifier();
            self.b.set_field(n, "name");
            self.b.close(m, "scoped_identifier")
        } else {
            let t = self.peek();
            let w = self.text(t);
            if w == "self" || w == "super" || w == "crate" {
                self.path_segment_ident()
            } else {
                self.identifier()
            }
        };
        while self.at("::") {
            let (_, n1) = self.peek_nth(1);
            if n1 == "<" {
                let m = self.b.open_before(cur);
                self.b.set_field(cur, "type");
                if self.b.kind(cur) == "identifier" {
                    self.b.set_kind(cur, "type_identifier");
                }
                self.bump();
                let ta = self.type_arguments();
                self.b.set_field(ta, "type_arguments");
                cur = self.b.close(m, "generic_type");
                continue;
            }
            let m = self.b.open_before(cur);
            self.b.set_field(cur, "path");
            self.bump();
            let n = self.path_segment_ident();
            self.b.set_field(n, "name");
            cur = self.b.close(m, "scoped_identifier");
        }
        cur
    }

    // --------------------------------------------------------------- strings
    fn string_literal(&mut self) -> NodeId {
        let t = self.peek();
        let by = self.by;
        let s = t.s;
        if t.k == TK::RawStr {
            let m = self.b.open();
            let mut i = s;
            while by[i] != b'#' && by[i] != b'"' {
                i += 1;
            }
            let mut hashes = 0;
            while i < by.len() && by[i] == b'#' {
                hashes += 1;
                i += 1;
            }
            i += 1; // quote
            self.b.leaf("raw_string_literal_start", false, s, i);
            let cs = i;
            let mut end = by.len();
            let mut close_end = by.len();
            while i < by.len() {
                if by[i] == b'"' {
                    let mut j = i + 1;
                    let mut h = 0;
                    while h < hashes && j < by.len() && by[j] == b'#' {
                        h += 1;
                        j += 1;
                    }
                    if h == hashes {
                        end = i;
                        close_end = j;
                        break;
                    }
                }
                i += 1;
            }
            if end > cs {
                self.b.leaf("string_content", true, cs, end);
            }
            if close_end <= by.len() && end < by.len() {
                self.b.leaf("raw_string_literal_end", false, end, close_end);
            }
            self.pos = close_end.min(by.len());
            self.tok = None;
            return self.b.close(m, "raw_string_literal");
        }
        let m = self.b.open();
        let mut i = s;
        while by[i] != b'"' {
            i += 1;
        }
        self.b.leaf("\"", false, s, i + 1);
        i += 1;
        let mut cs: Option<usize> = None;
        while i < by.len() {
            let c = by[i];
            if c == b'"' {
                break;
            }
            if c == b'\\' {
                if let Some(st) = cs.take() {
                    self.b.leaf("string_content", true, st, i);
                }
                let len = self.escape_len(i);
                if len > 0 {
                    self.b.leaf("escape_sequence", true, i, i + len);
                    i += len;
                } else {
                    cs = Some(i);
                    i += 1;
                }
                continue;
            }
            if cs.is_none() {
                cs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = cs.take() {
            self.b.leaf("string_content", true, st, i);
        }
        if i < by.len() {
            self.b.leaf("\"", false, i, i + 1);
            self.pos = i + 1;
        } else {
            self.b.missing("\"", false);
            self.pos = i;
        }
        self.tok = None;
        self.b.close(m, "string_literal")
    }

    fn escape_len(&self, i: usize) -> usize {
        let by = self.by;
        match by.get(i + 1) {
            None => 0,
            Some(b'u') => {
                if by.get(i + 2) == Some(&b'{') {
                    let mut j = i + 3;
                    while j < by.len() && by[j] != b'}' && by[j] != b'"' {
                        j += 1;
                    }
                    if by.get(j) == Some(&b'}') {
                        return j + 1 - i;
                    }
                }
                0
            }
            Some(b'x') => {
                if by.get(i + 2).map(|b| b.is_ascii_hexdigit()).unwrap_or(false) && by.get(i + 3).map(|b| b.is_ascii_hexdigit()).unwrap_or(false) {
                    4
                } else {
                    0
                }
            }
            Some(b'\n') => {
                let mut j = i + 2;
                while j < by.len() && (by[j] == b' ' || by[j] == b'\t' || by[j] == b'\n' || by[j] == b'\r') {
                    j += 1;
                }
                j - i
            }
            Some(b'\r') => {
                let mut j = i + 2;
                while j < by.len() && (by[j] == b' ' || by[j] == b'\t' || by[j] == b'\n' || by[j] == b'\r') {
                    j += 1;
                }
                j - i
            }
            Some(_) => {
                // any char
                let c = self.ch(i + 1).unwrap();
                1 + c.len_utf8()
            }
        }
    }
}
