    In(&'viewee str, Option<CaptureGroups>),
    /// Out of scope.
    Out(&'viewee str),
}

impl<'viewee> Scope<'viewee> {
    #[must_use]
    pub fn is_in(&self) -> bool {
        matches!(self, Self::In(..))
    }

