//! Go parser producing tree-sitter-go compatible trees.

use super::python::intern;
use crate::ts::builder::{Builder, Marker};
use crate::ts::{NodeId, Tree};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK {
    Ident,
    Int,
    Float,
    Imag,
    Rune,
    Str,
    RawStr,
    Punct,
    Newline,
    Eof,
    Err,
}

#[derive(Clone, Copy, Debug)]
struct Tok {
    k: TK,
    s: usize,
    e: usize,
}

const PUNCTS: &[&str] = &[
    "<<=", ">>=", "&^=", "...", "&&", "||", "<-", "++", "--", "==", "!=", "<=", ">=", ":=", "+=",
    "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "&^", "+", "-", "*", "/", "%", "&", "|",
    "^", "<", ">", "=", "!", "(", ")", "[", "]", "{", "}", ",", ";", ".", ":", "~",
];

const KEYWORDS: &[&str] = &[
    "break", "case", "chan", "const", "continue", "default", "defer", "else", "fallthrough",
    "for", "func", "go", "goto", "if", "import", "interface", "map", "package", "range",
    "return", "select", "struct", "switch", "type", "var",
];

pub struct Go<'a> {
    src: &'a str,
    by: &'a [u8],
    b: Builder,
    pos: usize,
    tok: Option<Tok>,
    /// Whether the last consumed token allows automatic semicolon insertion.
    semi_ok: bool,
    no_composite: bool,
}

pub fn parse(src: &str) -> Tree {
    let mut p = Go { src, by: src.as_bytes(), b: Builder::new(), pos: 0, tok: None, semi_ok: false, no_composite: false };
    p.source_file();
    p.b.finish("source_file", src.len())
}

fn is_id_start(c: char) -> bool {
    c == '_' || c.is_alphabetic()
}
fn is_id_cont(c: char) -> bool {
    c == '_' || c.is_alphanumeric()
}

impl<'a> Go<'a> {
    fn ch(&self, i: usize) -> Option<char> {
        self.src.get(i..).and_then(|s| s.chars().next())
    }
    fn text(&self, t: Tok) -> &'a str {
        &self.src[t.s..t.e]
    }

    /// Skip whitespace and comments; returns position of a newline that acts as terminator.
    fn skip_trivia(&mut self) -> Option<usize> {
        let by = self.by;
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return None,
            };
            if c == '\n' {
                if self.semi_ok {
                    return Some(self.pos);
                }
                self.pos += 1;
                continue;
            }
            if c.is_whitespace() {
                self.pos += c.len_utf8();
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'/') {
                let s = self.pos;
                let mut e = s;
                while e < by.len() && by[e] != b'\n' {
                    e += 1;
                }
                let mut ce = e;
                if ce > s && by[ce - 1] == b'\r' {
                    ce -= 1;
                }
                self.b.extra("comment", s, ce);
                self.pos = e;
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'*') {
                let s = self.pos;
                let mut i = s + 2;
                while i + 1 < by.len() && !(by[i] == b'*' && by[i + 1] == b'/') {
                    i += 1;
                }
                let e = if i + 1 < by.len() { i + 2 } else { by.len() };
                self.b.extra("comment", s, e);
                self.pos = e;
                continue;
            }
            return None;
        }
    }

    fn lex(&mut self) -> Tok {
        let s = self.pos;
        let by = self.by;
        let c = match self.ch(s) {
            None => return Tok { k: TK::Eof, s, e: s },
            Some(c) => c,
        };
        if c == '"' {
            return Tok { k: TK::Str, s, e: s };
        }
        if c == '`' {
            return Tok { k: TK::RawStr, s, e: s };
        }
        if c == '\'' {
            let mut i = s + 1;
            while i < by.len() && by[i] != b'\'' && by[i] != b'\n' {
                if by[i] == b'\\' {
                    i += 1;
                }
                i += 1;
            }
            return Tok { k: TK::Rune, s, e: (i + 1).min(by.len()) };
        }
        if is_id_start(c) {
            let mut e = s;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            return Tok { k: TK::Ident, s, e };
        }
        if c.is_ascii_digit() || (c == '.' && by.get(s + 1).map(|b| b.is_ascii_digit()).unwrap_or(false)) {
            return self.lex_number(s);
        }
        for p in PUNCTS {
            if self.src[s..].starts_with(p) {
                return Tok { k: TK::Punct, s, e: s + p.len() };
            }
        }
        Tok { k: TK::Err, s, e: s + c.len_utf8() }
    }

    fn lex_number(&self, s: usize) -> Tok {
        let by = self.by;
        let mut e = s;
        let mut float = false;
        if by[e] == b'0' && matches!(by.get(e + 1), Some(b'x') | Some(b'X') | Some(b'o') | Some(b'O') | Some(b'b') | Some(b'B')) {
            e += 2;
            while e < by.len() && (by[e].is_ascii_hexdigit() || by[e] == b'_') {
                e += 1;
            }
            if e < by.len() && by[e] == b'.' {
                float = true;
                e += 1;
                while e < by.len() && (by[e].is_ascii_hexdigit() || by[e] == b'_') {
                    e += 1;
                }
            }
            if e < by.len() && (by[e] == b'p' || by[e] == b'P') {
                float = true;
                e += 1;
                if e < by.len() && (by[e] == b'+' || by[e] == b'-') {
                    e += 1;
                }
                while e < by.len() && by[e].is_ascii_digit() {
                    e += 1;
                }
            }
        } else {
            while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                e += 1;
            }
            if e < by.len() && by[e] == b'.' && by.get(e + 1) != Some(&b'.') {
                float = true;
                e += 1;
                while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                    e += 1;
                }
            }
            if e < by.len() && (by[e] == b'e' || by[e] == b'E') {
                let mut f = e + 1;
                if f < by.len() && (by[f] == b'+' || by[f] == b'-') {
                    f += 1;
                }
                if f < by.len() && by[f].is_ascii_digit() {
                    float = true;
                    e = f;
                    while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                        e += 1;
                    }
                }
            }
        }
        if e < by.len() && by[e] == b'i' {
            return Tok { k: TK::Imag, s, e: e + 1 };
        }
        Tok { k: if float { TK::Float } else { TK::Int }, s, e }
    }

    fn peek(&mut self) -> Tok {
        if let Some(t) = self.tok {
            return t;
        }
        if let Some(nl) = self.skip_trivia() {
            let t = Tok { k: TK::Newline, s: nl, e: nl + 1 };
            self.tok = Some(t);
            return t;
        }
        let t = self.lex();
        self.tok = Some(t);
        t
    }

    fn peek_text(&mut self) -> &'a str {
        let t = self.peek();
        match t.k {
            TK::Str | TK::RawStr => "\"",
            TK::Newline => "\n",
            _ => self.text(t),
        }
    }

    /// Peek the token after the current, ignoring newlines (no side effects).
    fn peek_nth(&mut self, n: usize) -> (TK, &'a str) {
        let t = self.peek();
        let save_pos = self.pos;
        let save_tok = self.tok;
        let save_semi = self.semi_ok;
        let save_nodes = self.b.nodes.len();
        let save_pending = self.b.pending_count();
        let mut cur = t;
        let mut res = (t.k, self.peek_text());
        for _ in 0..n {
            self.pos = match cur.k {
                TK::Str | TK::RawStr => self.skip_string(cur),
                _ => cur.e,
            };
            self.semi_ok = false;
            self.tok = None;
            cur = self.peek();
            res = (cur.k, self.peek_text());
        }
        self.pos = save_pos;
        self.tok = save_tok;
        self.semi_ok = save_semi;
        self.b.truncate_pending(save_pending);
        self.b.nodes.truncate(save_nodes);
        res
    }

    fn skip_string(&self, t: Tok) -> usize {
        let by = self.by;
        let mut i = t.s + 1;
        if t.k == TK::RawStr {
            while i < by.len() && by[i] != b'`' {
                i += 1;
            }
            return (i + 1).min(by.len());
        }
        while i < by.len() && by[i] != b'"' && by[i] != b'\n' {
            if by[i] == b'\\' {
                i += 1;
            }
            i += 1;
        }
        (i + 1).min(by.len())
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        matches!(t.k, TK::Punct | TK::Ident) && self.text(t) == s
    }

    fn set_semi(&mut self, t: Tok) {
        self.semi_ok = match t.k {
            TK::Ident => {
                let w = self.text(t);
                !KEYWORDS.contains(&w) || matches!(w, "break" | "continue" | "fallthrough" | "return")
            }
            TK::Int | TK::Float | TK::Imag | TK::Rune | TK::Str | TK::RawStr => true,
            TK::Punct => matches!(self.text(t), "++" | "--" | ")" | "]" | "}"),
            _ => false,
        };
    }

    fn bump_as(&mut self, kind: &'static str, named: bool) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        self.set_semi(t);
        id
    }

    fn bump(&mut self) -> NodeId {
        let t = self.peek();
        let k = intern(self.text(t));
        self.bump_as(k, false)
    }

    fn expect(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            self.b.missing(intern(s), false);
            false
        }
    }

    fn identifier(&mut self) -> NodeId {
        self.ident_as("identifier")
    }

    fn ident_as(&mut self, kind: &'static str) -> NodeId {
        let t = self.peek();
        if t.k == TK::Ident {
            self.bump_as(kind, true)
        } else {
            self.b.missing(kind, true)
        }
    }

    /// Consume a terminator (newline or ';') if present.
    fn terminator(&mut self) -> bool {
        let t = self.peek();
        match t.k {
            TK::Newline => {
                self.b.leaf("\n", false, t.s, t.e);
                self.pos = t.e;
                self.tok = None;
                self.semi_ok = false;
                true
            }
            TK::Punct if self.text(t) == ";" => {
                self.bump();
                self.semi_ok = false;
                true
            }
            _ => false,
        }
    }

    fn skip_newlines(&mut self) {
        loop {
            let t = self.peek();
            if t.k == TK::Newline {
                self.pos = t.e;
                self.tok = None;
                self.semi_ok = false;
            } else {
                break;
            }
        }
    }

    // ------------------------------------------------------------- top level
    fn source_file(&mut self) {
        loop {
            self.skip_newlines();
            let t = self.peek();
            if t.k == TK::Eof {
                break;
            }
            let before = t.s;
            if self.at("package") {
                let m = self.b.open();
                self.bump();
                self.ident_as("package_identifier");
                self.b.close(m, "package_clause");
            } else if self.at("import") {
                self.import_declaration();
            } else if self.at("func") {
                self.function_or_method();
            } else {
                self.statement();
            }
            if !self.terminator() {
                let t = self.peek();
                if t.k != TK::Eof && t.s == before {
