                    self.bump();
                    self.b.close(m, "ERROR");
                }
            }
        }
    }

    fn import_declaration(&mut self) {
        let m = self.b.open();
        self.bump();
        if self.at("(") {
            let lm = self.b.open();
            self.bump();
            loop {
                self.skip_newlines();
                if self.at(")") || self.peek().k == TK::Eof {
