                if !self.terminator() {
                    break;
                }
            }
            self.skip_newlines();
            self.expect(")");
            self.b.close(lm, "import_spec_list");
        } else {
            self.import_spec();
        }
        self.b.close(m, "import_declaration");
    }

    fn import_spec(&mut self) {
        let m = self.b.open();
