            let w = self.text(t);
            let n = if w == "_" { self.bump_as("blank_identifier", true) } else { self.bump_as("package_identifier", true) };
            self.b.set_field(n, "name");
        } else if self.at(".") {
            let n = self.bump_as("dot", true);
            self.b.set_field(n, "name");
        }
        let p = self.string_literal();
        self.b.set_field(p, "path");
        self.b.close(m, "import_spec");
    }

