            let b = self.block();
            self.b.set_field(b, "body");
        }
        self.b.close(m, if is_method { "method_declaration" } else { "function_declaration" });
    }

    fn result(&mut self) {
        let t = self.peek();
        if self.at("(") {
            let r = self.parameter_list();
            self.b.set_field(r, "result");
        } else if self.type_starts(t) {
            let r = self.type_();
            self.b.set_field(r, "result");
        }
    }

    fn type_starts(&mut self, t: Tok) -> bool {
        match t.k {
            TK::Ident => {
                let w = self.text(t);
                !KEYWORDS.contains(&w) || matches!(w, "func" | "map" | "chan" | "struct" | "interface")
            }
