//! TypeScript parser producing tree-sitter-typescript compatible trees.

use super::python::intern;
use crate::ts::builder::{Builder, Marker};
use crate::ts::{NodeId, Tree};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK {
    Ident,
    PrivIdent,
    Num,
    Str,
    Template,
    Regex,
    Punct,
    Eof,
    Err,
}

#[derive(Clone, Copy, Debug)]
struct Tok {
    k: TK,
    s: usize,
    e: usize,
    /// newline between previous token and this one
    nl: bool,
}

const PUNCTS: &[&str] = &[
    ">>>=", "...", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??=", "=>", "==",
    "!=", "<=", ">=", "&&", "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=",
    "|=", "^=", "**", "<<", ">>", "+", "-", "*", "/", "%", "&", "|", "^", "!", "~", "<", ">",
    "=", "?", ":", ";", ",", ".", "(", ")", "[", "]", "{", "}", "@", "#",
];

const RESERVED: &[&str] = &[
    "break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete",
    "do", "else", "export", "extends", "finally", "for", "function", "if", "import", "in",
    "instanceof", "new", "return", "super", "switch", "this", "throw", "try", "typeof", "var",
    "void", "while", "with", "null", "true", "false",
];

const PREDEFINED: &[&str] = &[
    "any", "number", "boolean", "string", "symbol", "void", "unknown", "never", "object", "bigint",
];

pub struct Ts<'a> {
    src: &'a str,
    by: &'a [u8],
    b: Builder,
    pos: usize,
    tok: Option<Tok>,
    /// whether a regex may start at the current position
    regex_ok: bool,
    no_in: bool,
}

pub fn parse(src: &str) -> Tree {
    let mut p = Ts { src, by: src.as_bytes(), b: Builder::new(), pos: 0, tok: None, regex_ok: true, no_in: false };
    p.program();
    p.b.finish("program", src.len())
}

fn is_id_start(c: char) -> bool {
    c == '_' || c == '$' || c.is_alphabetic()
}
fn is_id_cont(c: char) -> bool {
    c == '_' || c == '$' || c.is_alphanumeric()
}

impl<'a> Ts<'a> {
    fn ch(&self, i: usize) -> Option<char> {
        self.src.get(i..).and_then(|s| s.chars().next())
    }
    fn text(&self, t: Tok) -> &'a str {
        &self.src[t.s..t.e]
    }

    fn skip_trivia(&mut self, emit: bool) -> bool {
        let by = self.by;
        let mut nl = false;
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return nl,
            };
            if c == '\n' {
                nl = true;
                self.pos += 1;
                continue;
            }
            if c.is_whitespace() || c == '\u{feff}' {
                self.pos += c.len_utf8();
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'/') {
                let s = self.pos;
                let mut e = s;
                while e < by.len() && by[e] != b'\n' {
                    e += 1;
                }
                let mut ce = e;
                if ce > s && by[ce - 1] == b'\r' {
                    ce -= 1;
                }
                if emit {
                    self.b.extra("comment", s, ce);
                }
                self.pos = e;
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'*') {
                let s = self.pos;
                let mut i = s + 2;
                while i + 1 < by.len() && !(by[i] == b'*' && by[i + 1] == b'/') {
                    if by[i] == b'\n' {
                        nl = true;
                    }
                    i += 1;
                }
                let e = if i + 1 < by.len() { i + 2 } else { by.len() };
                if emit {
                    self.b.extra("comment", s, e);
                }
                self.pos = e;
                continue;
            }
            if c == '#' && self.pos == 0 && by.get(1) == Some(&b'!') {
                let mut e = 0;
                while e < by.len() && by[e] != b'\n' {
                    e += 1;
                }
                if emit {
                    self.b.leaf("hash_bang_line", true, 0, e);
                }
                self.pos = e;
                continue;
            }
            return nl;
        }
    }

    fn lex(&mut self, nl: bool) -> Tok {
        let s = self.pos;
        let by = self.by;
        let c = match self.ch(s) {
            None => return Tok { k: TK::Eof, s, e: s, nl: true },
            Some(c) => c,
        };
        if c == '"' || c == '\'' {
            return Tok { k: TK::Str, s, e: s, nl };
        }
        if c == '`' {
            return Tok { k: TK::Template, s, e: s, nl };
        }
        if c == '/' && self.regex_ok && by.get(s + 1) != Some(&b'/') && by.get(s + 1) != Some(&b'*') {
            return Tok { k: TK::Regex, s, e: s, nl };
        }
        if c == '#' && self.ch(s + 1).map(is_id_start).unwrap_or(false) {
            let mut e = s + 1;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            return Tok { k: TK::PrivIdent, s, e, nl };
        }
        if is_id_start(c) || c == '\\' {
            let mut e = s;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            if e == s {
                e = s + 1;
            }
            return Tok { k: TK::Ident, s, e, nl };
        }
        if c.is_ascii_digit() || (c == '.' && by.get(s + 1).map(|b| b.is_ascii_digit()).unwrap_or(false)) {
            let mut e = s;
            if by[e] == b'0' && matches!(by.get(e + 1), Some(b'x') | Some(b'X') | Some(b'o') | Some(b'O') | Some(b'b') | Some(b'B')) {
                e += 2;
                while e < by.len() && (by[e].is_ascii_hexdigit() || by[e] == b'_') {
                    e += 1;
                }
            } else {
                while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                    e += 1;
                }
                if e < by.len() && by[e] == b'.' {
                    e += 1;
                    while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                        e += 1;
                    }
                }
                if e < by.len() && (by[e] == b'e' || by[e] == b'E') {
                    let mut f = e + 1;
                    if f < by.len() && (by[f] == b'+' || by[f] == b'-') {
                        f += 1;
                    }
                    if f < by.len() && by[f].is_ascii_digit() {
                        e = f;
                        while e < by.len() && by[e].is_ascii_digit() {
                            e += 1;
                        }
                    }
                }
            }
            if e < by.len() && by[e] == b'n' {
                e += 1;
            }
            return Tok { k: TK::Num, s, e, nl };
        }
        for p in PUNCTS {
            if self.src[s..].starts_with(p) {
                // `?.` followed by digit is `?` then `.5`
                if *p == "?." && by.get(s + 2).map(|b| b.is_ascii_digit()).unwrap_or(false) {
                    continue;
                }
                return Tok { k: TK::Punct, s, e: s + p.len(), nl };
            }
        }
        Tok { k: TK::Err, s, e: s + c.len_utf8(), nl }
    }

    fn peek(&mut self) -> Tok {
        if let Some(t) = self.tok {
            return t;
        }
        let nl = self.skip_trivia(true);
        let t = self.lex(nl);
        self.tok = Some(t);
        t
    }

    fn peek_text(&mut self) -> &'a str {
        let t = self.peek();
        match t.k {
            TK::Str => "\"",
            TK::Template => "`",
            TK::Regex => "/",
            _ => self.text(t),
        }
    }

    fn save(&self) -> (usize, Option<Tok>, bool, usize, usize) {
        (self.pos, self.tok, self.regex_ok, self.b.nodes.len(), self.b.pending_count())
    }

    fn restore(&mut self, s: (usize, Option<Tok>, bool, usize, usize)) {
        self.pos = s.0;
        self.tok = s.1;
        self.regex_ok = s.2;
        self.b.truncate_pending(s.4);
        self.b.nodes.truncate(s.3);
    }

    /// The n-th token after the current one (approximate; strings skipped).
    fn peek_nth(&mut self, n: usize) -> (TK, &'a str) {
        let st = self.save();
        let mut cur = self.peek();
        for _ in 0..n {
            self.pos = self.skip_token(cur);
            self.tok = None;
            self.regex_ok = false;
            let nl = self.skip_trivia(false);
            cur = self.lex(nl);
            self.tok = Some(cur);
        }
        let k = cur.k;
        let t = match cur.k {
            TK::Str => "\"",
            TK::Template => "`",
            TK::Regex => "/",
            _ => self.text(cur),
        };
        self.restore(st);
        (k, t)
    }

    fn skip_token(&self, t: Tok) -> usize {
        let by = self.by;
        match t.k {
            TK::Str => {
                let q = by[t.s];
                let mut i = t.s + 1;
                while i < by.len() && by[i] != q && by[i] != b'\n' {
                    if by[i] == b'\\' {
                        i += 1;
                    }
                    i += 1;
                }
                (i + 1).min(by.len())
            }
            TK::Template => {
                let mut i = t.s + 1;
                let mut depth = 0;
                while i < by.len() {
                    if by[i] == b'\\' {
                        i += 2;
                        continue;
                    }
                    if depth == 0 && by[i] == b'`' {
                        break;
                    }
                    if by[i] == b'$' && by.get(i + 1) == Some(&b'{') {
                        depth += 1;
                        i += 2;
                        continue;
                    }
                    if by[i] == b'}' && depth > 0 {
                        depth -= 1;
                    }
                    i += 1;
                }
                (i + 1).min(by.len())
            }
            TK::Regex => self.regex_end(t.s).0,
            _ => t.e,
        }
    }

    fn regex_end(&self, s: usize) -> (usize, usize) {
        // returns (end, pattern_end)
        let by = self.by;
        let mut i = s + 1;
        let mut in_class = false;
        while i < by.len() && by[i] != b'\n' {
            match by[i] {
                b'\\' => {
                    i += 2;
                    continue;
                }
                b'[' => in_class = true,
                b']' => in_class = false,
                b'/' if !in_class => break,
                _ => {}
            }
            i += 1;
        }
        let pe = i.min(by.len());
        let mut e = pe + 1;
        while e < by.len() && (by[e] as char).is_ascii_alphabetic() {
            e += 1;
        }
        (e.min(by.len()), pe)
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        matches!(t.k, TK::Punct | TK::Ident) && self.text(t) == s
    }

    fn set_regex_ok(&mut self, t: Tok) {
        self.regex_ok = match t.k {
            TK::Ident => {
                let w = self.text(t);
                matches!(w, "return" | "typeof" | "instanceof" | "in" | "of" | "new" | "delete" | "void" | "throw" | "case" | "do" | "else" | "yield" | "await")
            }
            TK::Num | TK::Str | TK::Template | TK::Regex | TK::PrivIdent => false,
            TK::Punct => !matches!(self.text(t), ")" | "]" | "}" | "++" | "--"),
            _ => true,
        };
    }

    fn bump_as(&mut self, kind: &'static str, named: bool) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        self.set_regex_ok(t);
        id
    }

    fn bump(&mut self) -> NodeId {
        let t = self.peek();
        let k = intern(self.text(t));
        self.bump_as(k, false)
    }

    /// Bump the first `len` bytes of the current token as an anonymous token.
    fn bump_part(&mut self, len: usize) -> NodeId {
        let t = self.peek();
        let k = intern(&self.src[t.s..t.s + len]);
        let id = self.b.leaf(k, false, t.s, t.s + len);
        self.pos = t.s + len;
        self.tok = None;
        self.regex_ok = true;
        id
    }

    fn expect(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else if s == ">" && self.peek_text().starts_with('>') {
            self.bump_part(1);
            true
        } else {
            self.b.missing(intern(s), false);
            false
        }
    }

    fn ident_as(&mut self, kind: &'static str) -> NodeId {
        let t = self.peek();
        if t.k == TK::Ident {
            self.bump_as(kind, true)
        } else {
            self.b.missing(kind, true)
        }
    }

    fn semicolon(&mut self) {
        if self.at(";") {
            self.bump();
            return;
        }
        // automatic semicolon insertion: newline, '}' or EOF
    }

    // ------------------------------------------------------------- program
    fn program(&mut self) {
        loop {
            let t = self.peek();
            if t.k == TK::Eof {
                break;
            }
            let before = t.s;
            self.statement();
            let t = self.peek();
            if t.s == before && t.k != TK::Eof {
                let m = self.b.open();
                self.bump();
                self.b.close(m, "ERROR");
            }
        }
    }

    fn statement(&mut self) {
        let t = self.peek();
        let w = if matches!(t.k, TK::Ident | TK::Punct) { self.text(t) } else { "" };
        match w {
            "{" => {
                self.statement_block();
            }
            ";" => {
                let m = self.b.open();
                self.bump();
                self.b.close(m, "empty_statement");
            }
            "import" => {
                let (_, n1) = self.peek_nth(1);
                if n1 == "(" || n1 == "." {
                    self.expression_statement();
                } else {
                    self.import_statement();
                }
            }
            "export" => self.export_statement(),
            "var" => {
                self.variable_declaration("variable_declaration");
            }
            "let" | "const" => {
                let (k1, n1) = self.peek_nth(1);
                if w == "const" && n1 == "enum" {
                    self.enum_declaration();
                } else if k1 == TK::Ident || n1 == "[" || n1 == "{" {
                    self.variable_declaration("lexical_declaration");
                } else {
                    self.expression_statement();
                }
            }
            "function" => {
                self.function_declaration(None);
            }
            "async" if self.peek_nth(1).1 == "function" && !self.peek_nth_newline(1) => {
                self.function_declaration(None);
            }
            "class" => {
                self.class_declaration(None, false);
            }
            "@" => {
                // decorators before class
                let m = self.b.open();
                while self.at("@") {
                    let d = self.decorator();
                    self.b.set_field(d, "decorator");
                }
                if self.at("export") {
                    self.b.abandon(m);
                    self.export_statement();
                } else if self.at("abstract") {
                    self.bump();
                    self.class_rest(m, "abstract_class_declaration", true);
                } else {
                    self.class_rest(m, "class_declaration", true);
                }
            }
            "abstract" if self.peek_nth(1).1 == "class" => {
                let m = self.b.open();
                self.bump();
                self.class_rest(m, "abstract_class_declaration", true);
            }
            "interface" if self.peek_nth(1).0 == TK::Ident => self.interface_declaration(),
            "type" if self.peek_nth(1).0 == TK::Ident && !self.peek_nth_newline(1) => {
                let (_, n2) = self.peek_nth(2);
                if n2 == "=" || n2 == "<" {
                    self.type_alias_declaration();
                } else {
                    self.expression_statement();
                }
            }
            "enum" if self.peek_nth(1).0 == TK::Ident => self.enum_declaration(),
            "namespace" | "module" if self.peek_nth(1).0 == TK::Ident || (w == "module" && self.peek_nth(1).0 == TK::Str) => {
                if w == "module" {
                    let m = self.b.open();
                    self.bump();
                    self.module_rest(m, "module");
                } else {
                    // namespace is an expression statement wrapping internal_module
                    let em = self.b.open();
                    let m = self.b.open();
                    self.bump();
                    self.module_rest(m, "internal_module");
                    self.b.close(em, "expression_statement");
                }
            }
            "declare" if !self.peek_nth_newline(1) && matches!(self.peek_nth(1).0, TK::Ident) => {
                let m = self.b.open();
                self.bump();
                if self.at("global") {
                    let gm = self.b.open();
                    self.bump();
                    let b = self.statement_block();
                    self.b.set_field(b, "body");
                    self.b.close(gm, "module");
                } else if self.at("module") && self.peek_nth(1).1 == "." {
                    self.bump();
                } else {
                    self.statement();
                }
                self.b.close(m, "ambient_declaration");
            }
            "if" => self.if_statement(),
            "for" => self.for_statement(),
            "while" => {
                let m = self.b.open();
                self.bump();
                let c = self.parenthesized_expression();
                self.b.set_field(c, "condition");
                let b = self.statement_node();
                self.b.set_field(b, "body");
                self.b.close(m, "while_statement");
            }
            "do" => {
                let m = self.b.open();
                self.bump();
                let b = self.statement_node();
                self.b.set_field(b, "body");
                self.expect("while");
                let c = self.parenthesized_expression();
                self.b.set_field(c, "condition");
                self.semicolon();
                self.b.close(m, "do_statement");
            }
            "try" => self.try_statement(),
            "switch" => self.switch_statement(),
            "return" => {
                let m = self.b.open();
                self.bump();
                let t2 = self.peek();
                if !t2.nl && !self.at(";") && !self.at("}") && t2.k != TK::Eof {
                    self.expressions();
                }
                self.semicolon();
                self.b.close(m, "return_statement");
            }
            "throw" => {
                let m = self.b.open();
                self.bump();
                self.expressions();
                self.semicolon();
                self.b.close(m, "throw_statement");
            }
            "break" | "continue" => {
                let m = self.b.open();
                self.bump();
                let t2 = self.peek();
                if t2.k == TK::Ident && !t2.nl {
                    let l = self.bump_as("statement_identifier", true);
                    self.b.set_field(l, "label");
                }
                self.semicolon();
                self.b.close(m, if w == "break" { "break_statement" } else { "continue_statement" });
            }
            "debugger" => {
                let m = self.b.open();
                self.bump();
                self.semicolon();
                self.b.close(m, "debugger_statement");
            }
            _ => {
                if t.k == TK::Ident && !RESERVED.contains(&w) && self.peek_nth(1).1 == ":" {
                    let m = self.b.open();
                    let l = self.bump_as("statement_identifier", true);
                    self.b.set_field(l, "label");
                    self.bump();
                    let b = self.statement_node();
                    self.b.set_field(b, "body");
                    self.b.close(m, "labeled_statement");
                    return;
                }
                self.expression_statement();
            }
        }
    }

    fn peek_nth_newline(&mut self, n: usize) -> bool {
        let st = self.save();
        let mut cur = self.peek();
        for _ in 0..n {
            self.pos = self.skip_token(cur);
            self.tok = None;
            let nl = self.skip_trivia(false);
            cur = self.lex(nl);
        }
        let r = cur.nl;
        self.restore(st);
        r
    }

    /// Parse a statement and return its node id.
    fn statement_node(&mut self) -> NodeId {
        self.statement();
        self.b.last_child().unwrap_or(0)
    }

    fn expression_statement(&mut self) {
        let m = self.b.open();
        self.expressions();
        self.semicolon();
        self.b.close(m, "expression_statement");
    }

    fn statement_block(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("{");
        loop {
            let t = self.peek();
            if self.at("}") || t.k == TK::Eof {
                break;
            }
            let before = t.s;
            self.statement();
            let t = self.peek();
            if t.s == before && t.k != TK::Eof && !self.at("}") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.expect("}");
        self.regex_ok = true;
        self.b.close(m, "statement_block")
    }

    fn module_rest(&mut self, m: Marker, kind: &'static str) {
        let t = self.peek();
        let n = if t.k == TK::Str {
            self.string()
        } else {
            let first = self.ident_as("identifier");
            let mut cur = first;
            while self.at(".") {
                let nm = self.b.open_before(cur);
                self.b.set_field(cur, "object");
                self.bump();
                let p = self.ident_as("identifier");
                self.b.set_field(p, "property");
                cur = self.b.close(nm, "nested_identifier");
            }
            cur
        };
        self.b.set_field(n, "name");
        if self.at("{") {
            let b = self.statement_block();
            self.b.set_field(b, "body");
        } else {
            self.semicolon();
        }
        self.b.close(m, kind);
    }

    fn variable_declaration(&mut self, kind: &'static str) {
        let m = self.b.open();
        self.bump(); // var/let/const
        loop {
            self.variable_declarator();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.semicolon();
        self.b.close(m, kind);
    }

    fn variable_declarator(&mut self) {
        let m = self.b.open();
        let n = self.binding_pattern();
        self.b.set_field(n, "name");
        if self.at("!") {
            self.bump();
        }
        if self.at(":") {
            let t = self.type_annotation();
            self.b.set_field(t, "type");
        }
        if self.at("=") {
            self.bump();
            let v = self.assignment_expr();
            self.b.set_field(v, "value");
        }
        self.b.close(m, "variable_declarator");
    }

    fn binding_pattern(&mut self) -> NodeId {
        if self.at("[") {
            let e = self.primary();
            self.to_pattern(e);
            return e;
        }
        if self.at("{") {
            let e = self.object_literal();
            self.to_pattern(e);
            return e;
        }
        self.ident_as("identifier")
    }

    fn to_pattern(&mut self, id: NodeId) {
        let kind = self.b.kind(id);
        match kind {
            "array" => self.b.set_kind(id, "array_pattern"),
            "object" => self.b.set_kind(id, "object_pattern"),
            "spread_element" => self.b.set_kind(id, "rest_pattern"),
            "shorthand_property_identifier" => self.b.set_kind(id, "shorthand_property_identifier_pattern"),
            "pair" => self.b.set_kind(id, "pair_pattern"),
            "assignment_expression" => {
                self.b.set_kind(id, "assignment_pattern");
            }
            "object_assignment_pattern" => {}
            _ => return,
        }
        let children = self.b.nodes[id as usize].children.clone();
        for c in children {
            let cn = &self.b.nodes[c as usize];
            if !cn.named {
                continue;
            }
            // only convert values (not keys)
            if cn.field == Some("key") {
                continue;
            }
            if self.b.kind(id) == "assignment_pattern" && cn.field == Some("right") {
                continue;
            }
            if self.b.kind(id) == "object_pattern" && self.b.kind(c) == "assignment_expression" {
                // {a = 1} → object_assignment_pattern
                self.b.set_kind(c, "object_assignment_pattern");
                let gc = self.b.nodes[c as usize].children.clone();
                if let Some(&l) = gc.first() {
                    if self.b.kind(l) == "identifier" {
                        self.b.set_kind(l, "shorthand_property_identifier_pattern");
                    }
                }
                continue;
            }
            self.to_pattern(c);
        }
    }

    fn import_statement(&mut self) {
        let m = self.b.open();
        self.bump(); // import
        if self.at("type") {
            let (k1, n1) = self.peek_nth(1);
            if k1 == TK::Ident && n1 != "from" || n1 == "{" || n1 == "*" {
                self.bump();
            }
        }
        let t = self.peek();
        if t.k == TK::Str {
            let s = self.string();
            self.b.set_field(s, "source");
        } else {
            if t.k == TK::Ident && self.peek_nth(1).1 == "=" {
                // import x = require("...")
                let rm = self.b.open();
                self.ident_as("identifier");
                self.bump();
                if self.at("require") {
                    let em = self.b.open();
                    self.bump();
                    self.expect("(");
                    let s = self.string();
                    self.b.set_field(s, "source");
                    self.expect(")");
                    self.b.close(em, "external_module_reference");
                } else {
                    self.expression();
                }
                self.b.close(rm, "import_require_clause");
                self.semicolon();
                self.b.close(m, "import_statement");
                return;
            }
            let cm = self.b.open();
            loop {
                if self.at("*") {
                    let nm = self.b.open();
                    self.bump();
                    self.expect("as");
                    self.ident_as("identifier");
                    self.b.close(nm, "namespace_import");
                } else if self.at("{") {
                    self.named_imports();
                } else if self.peek().k == TK::Ident && !self.at("from") {
                    self.ident_as("identifier");
                } else {
                    break;
                }
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.b.close(cm, "import_clause");
            self.expect("from");
            let s = self.string();
            self.b.set_field(s, "source");
        }
        if self.at("assert") || self.at("with") {
            let am = self.b.open();
            self.bump();
            self.object_literal();
            self.b.close(am, "import_attribute");
        }
        self.semicolon();
        self.b.close(m, "import_statement");
    }

    fn named_imports(&mut self) {
        let m = self.b.open();
        self.bump(); // {
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let sm = self.b.open();
            if self.at("type") && self.peek_nth(1).0 == TK::Ident && self.peek_nth(1).1 != "as" {
                self.bump();
            }
            let n = if self.peek().k == TK::Str { self.string() } else { self.ident_as("identifier") };
            self.b.set_field(n, "name");
            if self.at("as") {
                self.bump();
                let a = self.ident_as("identifier");
                self.b.set_field(a, "alias");
            }
            self.b.close(sm, "import_specifier");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        self.b.close(m, "named_imports");
    }

    fn export_statement(&mut self) {
        let m = self.b.open();
        while self.at("@") {
            let d = self.decorator();
            self.b.set_field(d, "decorator");
        }
        self.bump(); // export
        if self.at("default") {
            self.bump();
            let w = self.peek_text();
            if w == "function" || (w == "async" && self.peek_nth(1).1 == "function") {
                let d = self.function_declaration(None);
                self.b.set_field(d, "declaration");
            } else if w == "class" {
                let (k1, n1) = self.peek_nth(1);
                if k1 == TK::Ident && n1 != "extends" && n1 != "implements" {
                    let d = self.class_declaration(None, false);
                    self.b.set_field(d, "declaration");
                } else {
                    let v = self.class_expression();
                    self.b.set_field(v, "value");
                }
            } else if w == "interface" || w == "abstract" {
                self.statement();
                if let Some(d) = self.b.last_child() {
                    self.b.set_field(d, "declaration");
                }
            } else {
                let v = self.expression();
                self.b.set_field(v, "value");
                self.semicolon();
            }
        } else if self.at("*") {
            self.bump();
            if self.at("as") {
                let nm = self.b.open();
                self.bump();
                self.ident_as("identifier");
                self.b.close(nm, "namespace_export");
            }
            self.expect("from");
            let s = self.string();
            self.b.set_field(s, "source");
            self.semicolon();
        } else if self.at("{") || (self.at("type") && self.peek_nth(1).1 == "{") {
            if self.at("type") {
                self.bump();
            }
            let cm = self.b.open();
            self.bump();
            loop {
                if self.at("}") || self.peek().k == TK::Eof {
                    break;
                }
                let sm = self.b.open();
                let n = if self.peek().k == TK::Str { self.string() } else { self.ident_as("identifier") };
                self.b.set_field(n, "name");
                if self.at("as") {
                    self.bump();
                    let a = if self.peek().k == TK::Str { self.string() } else { self.ident_as("identifier") };
                    self.b.set_field(a, "alias");
                }
                self.b.close(sm, "export_specifier");
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect("}");
            self.b.close(cm, "export_clause");
            if self.at("from") {
                self.bump();
                let s = self.string();
                self.b.set_field(s, "source");
            }
            self.semicolon();
        } else if self.at("=") {
            self.bump();
            self.expression();
            self.semicolon();
        } else {
            self.statement();
            if let Some(d) = self.b.last_child() {
                self.b.set_field(d, "declaration");
            }
        }
        self.b.close(m, "export_statement");
    }

    fn decorator(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // @
        // member/call expression
        let mut e = self.ident_as("identifier");
        loop {
            if self.at(".") {
                let mm = self.b.open_before(e);
                self.b.set_field(e, "object");
                self.bump();
                let p = self.ident_as("property_identifier");
                self.b.set_field(p, "property");
                e = self.b.close(mm, "member_expression");
            } else if self.at("(") {
                let cm = self.b.open_before(e);
                self.b.set_field(e, "function");
                let a = self.arguments();
                self.b.set_field(a, "arguments");
                e = self.b.close(cm, "call_expression");
            } else {
                break;
            }
        }
        self.b.close(m, "decorator")
    }

    fn function_declaration(&mut self, m: Option<Marker>) -> NodeId {
        let m = m.unwrap_or_else(|| self.b.open());
        if self.at("async") {
            self.bump();
        }
        self.expect("function");
        let generator = if self.at("*") {
            self.bump();
            true
        } else {
            false
        };
        if self.peek().k == TK::Ident && !self.at("(") {
            let n = self.ident_as("identifier");
            self.b.set_field(n, "name");
        }
        self.call_signature();
        if self.at("{") {
            let b = self.statement_block();
            self.b.set_field(b, "body");
            self.b.close(m, if generator { "generator_function_declaration" } else { "function_declaration" })
        } else {
            self.semicolon();
            self.b.close(m, "function_signature")
        }
    }

    fn call_signature(&mut self) {
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        let ps = self.formal_parameters();
        self.b.set_field(ps, "parameters");
        if self.at(":") {
            let r = self.return_type_annotation();
            self.b.set_field(r, "return_type");
        }
    }

    fn return_type_annotation(&mut self) -> NodeId {
        // `: x is T` predicates or `asserts x`
        let m = self.b.open();
        self.bump(); // :
        let t = self.peek();
        if t.k == TK::Ident && self.peek_nth(1).1 == "is" && !self.at("asserts") {
            let pm = self.b.open();
            let n = if self.at("this") { self.bump_as("this", true) } else { self.ident_as("identifier") };
            self.b.set_field(n, "name");
            self.bump();
            let ty = self.type_();
            self.b.set_field(ty, "type");
            self.b.close(pm, "type_predicate");
            return self.b.close(m, "type_predicate_annotation");
        }
        if self.at("asserts") && self.peek_nth(1).0 == TK::Ident {
            let am = self.b.open();
            self.bump();
            if self.peek_nth(1).1 == "is" {
                let pm = self.b.open();
                let n = self.ident_as("identifier");
                self.b.set_field(n, "name");
                self.bump();
                let ty = self.type_();
                self.b.set_field(ty, "type");
                self.b.close(pm, "type_predicate");
            } else {
                self.ident_as("identifier");
            }
            self.b.close(am, "asserts");
            return self.b.close(m, "asserts_annotation");
        }
        self.type_();
        self.b.close(m, "type_annotation")
    }

    fn formal_parameters(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("(");
        loop {
            if self.at(")") || self.peek().k == TK::Eof {
                break;
            }
            let pm = self.b.open();
            while self.at("@") {
                let d = self.decorator();
                self.b.set_field(d, "decorator");
            }
            loop {
                let w = self.peek_text();
                if matches!(w, "public" | "private" | "protected") && self.param_modifier_follows() {
                    let am = self.b.open();
                    self.bump();
                    self.b.close(am, "accessibility_modifier");
                } else if w == "override" && self.param_modifier_follows() {
                    let om = self.b.open();
                    self.bump();
                    self.b.close(om, "override_modifier");
                } else if w == "readonly" && self.param_modifier_follows() {
                    self.bump();
                } else {
                    break;
                }
            }
            let pat = if self.at("...") {
                let rm = self.b.open();
                self.bump();
                self.binding_pattern();
                self.b.close(rm, "rest_pattern")
            } else if self.at("this") {
                self.bump_as("this", true)
            } else {
                self.binding_pattern()
            };
            self.b.set_field(pat, "pattern");
            let mut optional = false;
            if self.at("?") {
                self.bump();
                optional = true;
            }
            if self.at(":") {
                let t = self.type_annotation();
                self.b.set_field(t, "type");
            }
            if self.at("=") {
                self.bump();
                let v = self.assignment_expr();
                self.b.set_field(v, "value");
            }
            self.b.close(pm, if optional { "optional_parameter" } else { "required_parameter" });
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(")");
        self.regex_ok = false;
        self.b.close(m, "formal_parameters")
    }

    fn param_modifier_follows(&mut self) -> bool {
        let (k, n) = self.peek_nth(1);
        k == TK::Ident || n == "{" || n == "[" || n == "..."
    }

    fn type_parameters(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // <
        loop {
            if self.at(">") || self.peek().k == TK::Eof {
                break;
            }
            let pm = self.b.open();
            if self.at("const") || self.at("in") || self.at("out") {
                if self.peek_nth(1).0 == TK::Ident {
                    self.bump();
                }
            }
            let n = self.ident_as("type_identifier");
            self.b.set_field(n, "name");
            if self.at("extends") {
                let cm = self.b.open();
                self.bump();
                self.type_();
                let c = self.b.close(cm, "constraint");
                self.b.set_field(c, "constraint");
            }
            if self.at("=") {
                let dm = self.b.open();
                self.bump();
                self.type_();
                let d = self.b.close(dm, "default_type");
                self.b.set_field(d, "value");
            }
            self.b.close(pm, "type_parameter");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(">");
        self.b.close(m, "type_parameters")
    }

    fn class_declaration(&mut self, m: Option<Marker>, _abs: bool) -> NodeId {
        let m = m.unwrap_or_else(|| self.b.open());
        self.class_rest(m, "class_declaration", true)
    }

    fn class_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.class_rest(m, "class", false)
    }

    fn class_rest(&mut self, m: Marker, kind: &'static str, _decl: bool) -> NodeId {
        self.expect("class");
        let t = self.peek();
        if t.k == TK::Ident && !self.at("extends") && !self.at("implements") && !self.at("{") {
            let n = self.ident_as("type_identifier");
            self.b.set_field(n, "name");
        }
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at("extends") || self.at("implements") {
            let hm = self.b.open();
            if self.at("extends") {
                let em = self.b.open();
                self.bump();
                loop {
                    let v = self.lhs_expression();
                    self.b.set_field(v, "value");
                    if self.at("<") {
                        let ta = self.type_arguments();
                        self.b.set_field(ta, "type_arguments");
                    }
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.b.close(em, "extends_clause");
            }
            if self.at("implements") {
                let im = self.b.open();
                self.bump();
                loop {
                    self.type_();
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.b.close(im, "implements_clause");
            }
            self.b.close(hm, "class_heritage");
        }
        let b = self.class_body();
        self.b.set_field(b, "body");
        self.b.close(m, kind)
    }

    fn class_body(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            if self.at(";") {
                self.bump();
                continue;
            }
            if self.at("@") {
                let d = self.decorator();
                self.b.set_field(d, "decorator");
                continue;
            }
            let before = self.peek().s;
            self.class_member();
            if self.at(";") {
                self.bump();
            }
            if self.peek().s == before && !self.at("}") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.expect("}");
        self.regex_ok = true;
        self.b.close(m, "class_body")
    }

    fn is_modifier_word(&mut self, w: &str) -> bool {
        if !matches!(w, "public" | "private" | "protected" | "static" | "readonly" | "abstract" | "override" | "declare" | "async" | "get" | "set" | "accessor") {
            return false;
        }
        let (k, n) = self.peek_nth(1);
        let nl = self.peek_nth_newline(1);
        if w == "async" && nl {
            return false;
        }
        k == TK::Ident || k == TK::PrivIdent || k == TK::Str || k == TK::Num || n == "[" || n == "*" || (n == "{" && w == "static") || n == "#"
    }

    fn class_member(&mut self) {
        let m = self.b.open();
        // static block
        if self.at("static") && self.peek_nth(1).1 == "{" {
            self.bump();
            let b = self.statement_block();
            self.b.set_field(b, "body");
            self.b.close(m, "class_static_block");
            return;
        }
        let mut is_abstract = false;
        let mut accessor_kw = false;
        loop {
            let w = self.peek_text();
            if !self.is_modifier_word(w) {
                break;
            }
            match w {
                "public" | "private" | "protected" => {
                    let am = self.b.open();
                    self.bump();
                    self.b.close(am, "accessibility_modifier");
                }
                "override" => {
                    let om = self.b.open();
                    self.bump();
                    self.b.close(om, "override_modifier");
                }
                "abstract" => {
                    is_abstract = true;
                    self.bump();
                }
                "get" | "set" => {
                    accessor_kw = true;
                    self.bump();
                }
                _ => {
                    self.bump();
                }
            }
        }
        let _ = accessor_kw;
        if self.at("*") {
            self.bump();
        }
        // index signature
        if self.at("[") && self.is_index_signature() {
            self.index_signature_rest(m);
            return;
        }
        let n = self.property_name();
        self.b.set_field(n, "name");
        if self.at("?") || self.at("!") {
            self.bump();
        }
        if self.at("(") || self.at("<") {
            self.call_signature();
            if self.at("{") {
                let b = self.statement_block();
                self.b.set_field(b, "body");
                self.b.close(m, "method_definition");
            } else {
                self.semicolon();
                self.b.close(m, if is_abstract { "abstract_method_signature" } else { "method_signature" });
            }
            return;
        }
        if self.at(":") {
            let t = self.type_annotation();
            self.b.set_field(t, "type");
        }
        if self.at("=") {
            self.bump();
            let v = self.assignment_expr();
            self.b.set_field(v, "value");
        }
        self.semicolon();
        self.b.close(m, "public_field_definition");
    }

    fn is_index_signature(&mut self) -> bool {
        let (k1, _) = self.peek_nth(1);
        let (_, n2) = self.peek_nth(2);
        k1 == TK::Ident && (n2 == ":" || n2 == "in")
    }

    fn index_signature_rest(&mut self, m: Marker) -> NodeId {
        self.bump(); // [
        let (_, n1) = self.peek_nth(1);
        if n1 == "in" {
            let mm = self.b.open();
            self.ident_as("type_identifier");
            self.bump();
            self.type_();
            if self.at("as") {
                self.bump();
                self.type_();
            }
            self.b.close(mm, "mapped_type_clause");
        } else {
            let n = self.ident_as("identifier");
            self.b.set_field(n, "name");
            self.expect(":");
            let it = self.type_();
            self.b.set_field(it, "index_type");
        }
        self.expect("]");
        if self.at("?") || self.at("-") || self.at("+") {
            self.bump();
            if self.at("?") {
                self.bump();
            }
        }
        if self.at(":") {
            let t = self.type_annotation();
            self.b.set_field(t, "type");
        }
        self.semicolon();
        self.b.close(m, "index_signature")
    }

    fn property_name(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Str => self.string(),
            TK::Num => self.bump_as("number", true),
            TK::PrivIdent => self.bump_as("private_property_identifier", true),
            TK::Ident => self.bump_as("property_identifier", true),
            _ => {
                if self.at("[") {
                    let m = self.b.open();
                    self.bump();
                    self.assignment_expr();
                    self.expect("]");
                    return self.b.close(m, "computed_property_name");
                }
                self.b.missing("property_identifier", true)
            }
        }
    }

    fn interface_declaration(&mut self) {
        let m = self.b.open();
        self.bump(); // interface
        let n = self.ident_as("type_identifier");
        self.b.set_field(n, "name");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        if self.at("extends") {
            let em = self.b.open();
            self.bump();
            loop {
                self.type_();
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.b.close(em, "extends_type_clause");
        }
        let b = self.object_type_body("interface_body");
        self.b.set_field(b, "body");
        self.b.close(m, "interface_declaration");
    }

    fn object_type_body(&mut self, kind: &'static str) -> NodeId {
        let m = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let before = self.peek().s;
            self.type_member();
            if self.at(";") || self.at(",") {
                self.bump();
            }
            if self.peek().s == before && !self.at("}") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.expect("}");
        self.b.close(m, kind)
    }

    fn type_member(&mut self) {
        let m = self.b.open();
        if self.at("(") || self.at("<") {
            self.call_signature();
            self.b.close(m, "call_signature");
            return;
        }
        if self.at("new") && (self.peek_nth(1).1 == "(" || self.peek_nth(1).1 == "<") {
            self.bump();
            if self.at("<") {
                let tp = self.type_parameters();
                self.b.set_field(tp, "type_parameters");
            }
            let ps = self.formal_parameters();
            self.b.set_field(ps, "parameters");
            if self.at(":") {
                let t = self.type_annotation();
                self.b.set_field(t, "type");
            }
            self.b.close(m, "construct_signature");
            return;
        }
        loop {
            let w = self.peek_text();
            if (w == "readonly" || w == "get" || w == "set" || w == "-" || w == "+") && {
                let (k, n) = self.peek_nth(1);
                k == TK::Ident || k == TK::Str || n == "[" || w == "-" || w == "+"
            } {
                self.bump();
            } else {
                break;
            }
        }
        if self.at("[") && self.is_index_signature() {
            self.index_signature_rest(m);
            return;
        }
        let n = self.property_name();
        self.b.set_field(n, "name");
        if self.at("?") {
            self.bump();
        }
        if self.at("(") || self.at("<") {
            self.call_signature();
            self.b.close(m, "method_signature");
            return;
        }
        if self.at(":") {
            let t = self.type_annotation();
            self.b.set_field(t, "type");
        }
        self.b.close(m, "property_signature");
    }

    fn type_alias_declaration(&mut self) {
        let m = self.b.open();
        self.bump(); // type
        let n = self.ident_as("type_identifier");
        self.b.set_field(n, "name");
        if self.at("<") {
            let tp = self.type_parameters();
            self.b.set_field(tp, "type_parameters");
        }
        self.expect("=");
        let v = self.type_();
        self.b.set_field(v, "value");
        self.semicolon();
        self.b.close(m, "type_alias_declaration");
    }

    fn enum_declaration(&mut self) {
        let m = self.b.open();
        if self.at("const") {
            self.bump();
        }
        self.bump(); // enum
        let n = self.ident_as("identifier");
        self.b.set_field(n, "name");
        let bm = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let name = self.property_name();
            if self.at("=") {
                let am = self.b.open_before(name);
                self.b.set_field(name, "name");
                self.bump();
                let v = self.assignment_expr();
                self.b.set_field(v, "value");
                self.b.close(am, "enum_assignment");
            } else {
                self.b.set_field(name, "name");
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        let b = self.b.close(bm, "enum_body");
        self.b.set_field(b, "body");
        self.b.close(m, "enum_declaration");
    }

    fn if_statement(&mut self) {
        let m = self.b.open();
        self.bump();
        let c = self.parenthesized_expression();
        self.b.set_field(c, "condition");
        let s = self.statement_node();
        self.b.set_field(s, "consequence");
        if self.at("else") {
            let em = self.b.open();
            self.bump();
            self.statement();
            let e = self.b.close(em, "else_clause");
            self.b.set_field(e, "alternative");
        }
        self.b.close(m, "if_statement");
    }

    fn parenthesized_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("(");
        self.expressions();
        self.expect(")");
        self.regex_ok = true;
        self.b.close(m, "parenthesized_expression")
    }

    fn for_statement(&mut self) {
        let m = self.b.open();
        self.bump(); // for
        if self.at("await") {
            self.bump();
        }
        self.expect("(");
        // for-in/of detection
        let w = self.peek_text();
        let is_decl = matches!(w, "var" | "let" | "const") && {
            let (k, n) = self.peek_nth(1);
            k == TK::Ident || n == "[" || n == "{"
        };
        // try in/of
        let st = self.save();
        let lm = self.b.open();
        if is_decl {
            self.bump();
            let l = self.binding_pattern();
            self.b.set_field(l, "left");
        } else if !self.at(";") {
            self.no_in = true;
            let l = self.lhs_expression();
            self.no_in = false;
            self.to_pattern(l);
            self.b.set_field(l, "left");
        }
        if self.at("in") || self.at("of") {
            self.b.abandon(lm);
            self.bump();
            let r = self.expressions();
            self.b.set_field(r, "right");
            self.expect(")");
            let b = self.statement_node();
            self.b.set_field(b, "body");
            self.b.close(m, "for_in_statement");
            return;
        }
        // not in/of: rewind
        self.b.abandon(lm);
        self.restore(st);
        // drop frames children pushed after save: restore truncated nodes; children lists may still hold ids
        self.b.truncate_children_to_nodes();
        // initializer
        if self.at(";") {
            let em = self.b.open();
            self.bump();
            let e = self.b.close(em, "empty_statement");
            self.b.set_field(e, "initializer");
        } else if is_decl {
            let dm = self.b.open();
            let kw = self.peek_text();
            self.bump();
            loop {
                self.no_in = true;
                self.variable_declarator();
                self.no_in = false;
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect(";");
            let d = self.b.close(dm, if kw == "var" { "variable_declaration" } else { "lexical_declaration" });
            self.b.set_field(d, "initializer");
        } else {
            let em = self.b.open();
            self.no_in = true;
            self.expressions();
            self.no_in = false;
            self.expect(";");
            let e = self.b.close(em, "expression_statement");
            self.b.set_field(e, "initializer");
        }
        if self.at(";") {
            let em = self.b.open();
            self.bump();
            let e = self.b.close(em, "empty_statement");
            self.b.set_field(e, "condition");
        } else {
            let em = self.b.open();
            self.expressions();
            self.expect(";");
            let e = self.b.close(em, "expression_statement");
            self.b.set_field(e, "condition");
            // tree-sitter: condition is expression_statement? keep plain expression
            let ch = self.b.nodes[e as usize].children.clone();
            if let Some(&first) = ch.first() {
                let _ = first;
            }
        }
        if !self.at(")") {
            let inc = self.expressions();
            self.b.set_field(inc, "increment");
        }
        self.expect(")");
        let b = self.statement_node();
        self.b.set_field(b, "body");
        self.b.close(m, "for_statement");
    }

    fn try_statement(&mut self) {
        let m = self.b.open();
        self.bump();
        let b = self.statement_block();
        self.b.set_field(b, "body");
        if self.at("catch") {
            let cm = self.b.open();
            self.bump();
            if self.at("(") {
                self.bump();
                let p = self.binding_pattern();
                self.b.set_field(p, "parameter");
                if self.at(":") {
                    let t = self.type_annotation();
                    self.b.set_field(t, "type");
                }
                self.expect(")");
            }
            let cb = self.statement_block();
            self.b.set_field(cb, "body");
            let c = self.b.close(cm, "catch_clause");
            self.b.set_field(c, "handler");
        }
        if self.at("finally") {
            let fm = self.b.open();
            self.bump();
            let fb = self.statement_block();
            self.b.set_field(fb, "body");
            let f = self.b.close(fm, "finally_clause");
            self.b.set_field(f, "finalizer");
        }
        self.b.close(m, "try_statement");
    }

    fn switch_statement(&mut self) {
        let m = self.b.open();
        self.bump();
        let v = self.parenthesized_expression();
        self.b.set_field(v, "value");
        let bm = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let cm = self.b.open();
            let is_case = self.at("case");
            if is_case {
                self.bump();
                let v = self.expressions();
                self.b.set_field(v, "value");
            } else if self.at("default") {
                self.bump();
            } else {
                self.b.abandon(cm);
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
                continue;
            }
            self.expect(":");
            loop {
                if self.at("case") || self.at("default") || self.at("}") || self.peek().k == TK::Eof {
                    break;
                }
                let s = self.statement_node();
                self.b.set_field(s, "body");
            }
            self.b.close(cm, if is_case { "switch_case" } else { "switch_default" });
        }
        self.expect("}");
        let b = self.b.close(bm, "switch_body");
        self.b.set_field(b, "body");
        self.b.close(m, "switch_statement");
    }
}
