                        cur = self.lex(nl);
                        break;
                    }
                }
                self.pos = self.skip_token(cur);
                self.regex_ok = false;
                let nl = self.skip_trivia(false);
                cur = self.lex(nl);
            }
            if self.text(cur) != "(" {
                self.restore(st);
                return false;
            }
        }
        loop {
            n += 1;
            if n > 20000 || cur.k == TK::Eof {
                break;
            }
            let w = if cur.k == TK::Punct { self.text(cur) } else { "" };
            match w {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => {
                    depth -= 1;
                    if depth == 0 {
                        self.pos = cur.e;
                        self.regex_ok = false;
                        let nl = self.skip_trivia(false);
