            let p = self.ident_as("identifier");
            self.b.set_field(p, "parameter");
        } else {
            self.call_signature();
        }
        self.expect("=>");
        if self.at("{") {
            let b = self.statement_block();
            self.b.set_field(b, "body");
        } else {
            let b = self.assignment_expr();
            self.b.set_field(b, "body");
        }
        self.b.close(m, "arrow_function")
    }

    fn conditional(&mut self) -> NodeId {
        let c = self.binary(0);
        if self.at("?") {
            let m = self.b.open_before(c);
            self.b.set_field(c, "condition");
            self.bump();
            let saved = self.no_in;
            self.no_in = false;
            let a = self.assignment_expr();
            self.no_in = saved;
            self.b.set_field(a, "consequence");
            self.expect(":");
            let b = self.assignment_expr();
            self.b.set_field(b, "alternative");
            return self.b.close(m, "ternary_expression");
        }
        c
    }

    fn binop(&mut self) -> Option<(&'a str, u8, bool)> {
        let t = self.peek();
        let w = self.text(t);
        if t.k == TK::Ident {
            return match w {
                "instanceof" => Some((w, 8, false)),
                "in" if !self.no_in => Some((w, 8, false)),
                "as" | "satisfies" if !t.nl => Some((w, 9, false)),
                _ => None,
            };
        }
        if t.k != TK::Punct {
            return None;
        }
        Some(match w {
            "??" => (w, 1, false),
            "||" => (w, 2, false),
            "&&" => (w, 3, false),
            "|" => (w, 4, false),
            "^" => (w, 5, false),
            "&" => (w, 6, false),
            "==" | "!=" | "===" | "!==" => (w, 7, false),
            "<" | ">" | "<=" | ">=" => (w, 8, false),
            "<<" | ">>" | ">>>" => (w, 9, false),
            "+" | "-" => (w, 10, false),
            "*" | "/" | "%" => (w, 11, false),
            "**" => (w, 12, true),
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) -> NodeId {
        let mut left = self.unary();
        loop {
            // '>' sequences for shift operators are lexed as '>' singles only in types; here ">>" fine
            let (op, p, right) = match self.binop() {
                Some(x) => x,
                None => break,
            };
            if p < min {
                break;
            }
            if op == "as" || op == "satisfies" {
                let m = self.b.open_before(left);
                self.bump();
                if op == "as" && self.at("const") {
                    self.bump();
                } else {
                    self.type_();
                }
                left = self.b.close(m, if op == "as" { "as_expression" } else { "satisfies_expression" });
                continue;
            }
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            let o = self.bump();
            self.b.set_field(o, "operator");
            let r = self.binary(if right { p } else { p + 1 });
            self.b.set_field(r, "right");
            left = self.b.close(m, "binary_expression");
        }
        // non-null assertion applies loosely in tree-sitter-typescript
        left
    }

    fn unary(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.peek_text();
        if t.k == TK::Punct && matches!(w, "!" | "~" | "-" | "+") {
            let m = self.b.open();
            let o = self.bump();
            self.b.set_field(o, "operator");
            let a = self.unary();
            self.b.set_field(a, "argument");
            return self.b.close(m, "unary_expression");
        }
        if t.k == TK::Ident && matches!(w, "typeof" | "void" | "delete") {
            let m = self.b.open();
            let o = self.bump();
            self.b.set_field(o, "operator");
            let a = self.unary();
            self.b.set_field(a, "argument");
            return self.b.close(m, "unary_expression");
        }
        if t.k == TK::Punct && (w == "++" || w == "--") {
            let m = self.b.open();
            let o = self.bump();
            self.b.set_field(o, "operator");
            let a = self.unary();
            self.b.set_field(a, "argument");
            return self.b.close(m, "update_expression");
        }
