            self.b.set_field(e, "argument");
            let o = self.bump();
            self.b.set_field(o, "operator");
            return self.b.close(m, "update_expression");
        }
        e
    }

    fn lhs_expression(&mut self) -> NodeId {
        let p = if self.at("new") {
            self.new_expression()
        } else {
            self.primary()
        };
        self.postfix(p, true)
    }

    fn new_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // new
        if self.at(".") {
            // new.target
            self.bump();
            self.ident_as("property_identifier");
            return self.b.close(m, "meta_property");
        }
        let c = if self.at("new") { self.new_expression() } else { self.primary() };
        let c = self.postfix(c, false);
        self.b.set_field(c, "constructor");
        if self.at("<") && self.type_args_ahead() {
            let ta = self.type_arguments();
            self.b.set_field(ta, "type_arguments");
        }
        if self.at("(") {
            let a = self.arguments();
            self.b.set_field(a, "arguments");
        }
        self.b.close(m, "new_expression")
    }

    fn type_args_ahead(&mut self) -> bool {
        // heuristically decide if '<' starts type arguments followed by '(' or '`'
        let st = self.save();
        let mut depth = 0i32;
        let mut cur = self.peek();
        let mut n = 0;
        let mut ok = false;
        loop {
            n += 1;
            if n > 2000 || cur.k == TK::Eof {
                break;
            }
            let w = self.text(cur);
            match w {
                "<" => depth += 1,
                ">" | ">>" | ">>>" => {
                    depth -= w.len() as i32;
                    if depth <= 0 {
                        self.pos = cur.e;
                        self.regex_ok = false;
                        let nl = self.skip_trivia(false);
                        let nx = self.lex(nl);
                        let nw = self.text(nx);
                        ok = depth == 0 && (nw == "(" || nx.k == TK::Template || nw == ")" || nw == "," || nw == ";" || nw == "." || nw == "?." || nx.k == TK::Eof || nx.nl);
                        break;
                    }
                }
                ";" | "{" | "}" | "=" | "&&" | "||" => break,
                _ => {}
            }
            self.pos = self.skip_token(cur);
            self.regex_ok = false;
            let nl = self.skip_trivia(false);
            cur = self.lex(nl);
        }
        self.restore(st);
        ok
    }

    fn postfix(&mut self, mut e: NodeId, allow_call: bool) -> NodeId {
        loop {
            let t = self.peek();
            match t.k {
                TK::Template => {
