                    e = self.b.close(m, "member_expression");
                }
                "[" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "object");
                    self.bump();
                    let saved = self.no_in;
                    self.no_in = false;
                    let i = self.expressions();
                    self.no_in = saved;
                    self.b.set_field(i, "index");
                    self.expect("]");
                    e = self.b.close(m, "subscript_expression");
                }
                "(" if allow_call => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let a = self.arguments();
                    self.b.set_field(a, "arguments");
                    e = self.b.close(m, "call_expression");
                }
                "<" if allow_call && self.type_args_ahead() => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let ta = self.type_arguments();
                    self.b.set_field(ta, "type_arguments");
                    if self.at("(") {
                        let a = self.arguments();
                        self.b.set_field(a, "arguments");
                        e = self.b.close(m, "call_expression");
                    } else if self.peek().k == TK::Template {
                        let a = self.template_string();
                        self.b.set_field(a, "arguments");
                        e = self.b.close(m, "call_expression");
