        match t.k {
            TK::Num => return self.bump_as("number", true),
            TK::Str => return self.string(),
            TK::Template => return self.template_string(),
            TK::Regex => return self.regex(),
            TK::PrivIdent => return self.bump_as("private_property_identifier", true),
