                        let sm = self.b.open();
                        self.bump();
                        self.assignment_expr();
                        self.b.close(sm, "spread_element");
                    } else {
                        self.assignment_expr();
                    }
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
