                    let n = self.ident_as("identifier");
                    self.b.set_field(n, "name");
                }
                self.call_signature();
                let b = self.statement_block();
                self.b.set_field(b, "body");
                self.regex_ok = false;
                return self.b.close(m, if generator { "generator_function" } else { "function_expression" });
            }
            "async" if self.peek_nth(1).1 == "function" => {
                let m = self.b.open();
                self.bump();
                self.bump();
                let generator = if self.at("*") {
                    self.bump();
                    true
                } else {
                    false
                };
                if self.peek().k == TK::Ident && !self.at("(") {
                    let n = self.ident_as("identifier");
                    self.b.set_field(n, "name");
                }
                self.call_signature();
                let b = self.statement_block();
                self.b.set_field(b, "body");
                self.regex_ok = false;
                return self.b.close(m, if generator { "generator_function" } else { "function_expression" });
