        self.b.close(m, "object")
    }

    fn object_member(&mut self) {
        let m = self.b.open();
        // modifiers: async, get, set, *
        loop {
            let w = self.peek_text();
            if matches!(w, "async" | "get" | "set") {
                let (k, n) = self.peek_nth(1);
                if k == TK::Ident || k == TK::Str || k == TK::Num || n == "[" || n == "*" {
                    self.bump();
                    continue;
                }
            }
            break;
        }
        if self.at("*") {
            self.bump();
        }
        let t = self.peek();
        let (_, n1) = self.peek_nth(1);
        if t.k == TK::Ident && (n1 == "," || n1 == "}" || n1 == "=") && !self.b.current_children().iter().any(|_| false) {
            if n1 == "=" {
                // shorthand with default (in patterns)
                let id = self.ident_as("identifier");
                let am = self.b.open_before(id);
                self.b.set_field(id, "left");
                self.bump();
                let r = self.assignment_expr();
                self.b.set_field(r, "right");
                self.b.close(am, "assignment_expression");
                self.b.abandon(m);
                return;
            }
            self.b.abandon(m);
            self.bump_as("shorthand_property_identifier", true);
            return;
        }
        let k = self.property_name();
        if self.at("(") || self.at("<") {
            self.b.set_field(k, "name");
            self.call_signature();
            let b = self.statement_block();
            self.b.set_field(b, "body");
            self.b.close(m, "method_definition");
            return;
        }
        self.b.set_field(k, "key");
        self.expect(":");
        let v = self.assignment_expr();
        self.b.set_field(v, "value");
        self.b.close(m, "pair");
    }

    fn string(&mut self) -> NodeId {
        let t = self.peek();
        let by = self.by;
        let s = t.s;
        if t.k != TK::Str {
            return self.b.missing("string", true);
        }
        let q = by[s];
        let m = self.b.open();
        self.b.leaf(if q == b'"' { "\"" } else { "'" }, false, s, s + 1);
        let mut i = s + 1;
        let mut fs: Option<usize> = None;
        while i < by.len() && by[i] != q && by[i] != b'\n' {
            if by[i] == b'\\' {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let len = self.escape_len(i);
                self.b.leaf("escape_sequence", true, i, i + len);
                i += len;
                continue;
            }
            if fs.is_none() {
                fs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = fs.take() {
            self.b.leaf("string_fragment", true, st, i);
        }
        if i < by.len() && by[i] == q {
            self.b.leaf(if q == b'"' { "\"" } else { "'" }, false, i, i + 1);
            self.pos = i + 1;
        } else {
            self.b.missing(if q == b'"' { "\"" } else { "'" }, false);
            self.pos = i;
        }
        self.tok = None;
        self.regex_ok = false;
        self.b.close(m, "string")
    }

    fn escape_len(&self, i: usize) -> usize {
        let by = self.by;
        match by.get(i + 1) {
            None => 1,
            Some(b'u') => {
                if by.get(i + 2) == Some(&b'{') {
                    let mut j = i + 3;
                    while j < by.len() && by[j] != b'}' {
                        j += 1;
                    }
                    return (j + 1 - i).min(by.len() - i);
                }
                6.min(by.len() - i)
            }
            Some(b'x') => 4.min(by.len() - i),
            Some(b'\r') => {
                if by.get(i + 2) == Some(&b'\n') {
                    3
                } else {
                    2
                }
            }
            Some(b'0'..=b'7') => {
                let mut j = i + 1;
                while j < by.len() && j < i + 4 && (b'0'..=b'7').contains(&by[j]) {
                    j += 1;
                }
                j - i
            }
            Some(_) => 1 + self.ch(i + 1).map(|c| c.len_utf8()).unwrap_or(1),
        }
    }

    fn template_string(&mut self) -> NodeId {
        let t = self.peek();
        let by = self.by;
        let s = t.s;
        let m = self.b.open();
        self.b.leaf("`", false, s, s + 1);
        self.tok = None;
        let mut i = s + 1;
        let mut fs: Option<usize> = None;
        loop {
            if i >= by.len() {
                break;
            }
            let c = by[i];
            if c == b'`' {
                break;
            }
            if c == b'\\' {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let len = self.escape_len(i);
                self.b.leaf("escape_sequence", true, i, i + len);
                i += len;
                continue;
            }
            if c == b'$' && by.get(i + 1) == Some(&b'{') {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let sm = self.b.open();
                self.b.leaf("${", false, i, i + 2);
                self.pos = i + 2;
                self.tok = None;
                self.regex_ok = true;
                self.expressions();
                let t2 = self.peek();
                if self.text(t2) == "}" {
                    self.b.leaf("}", false, t2.s, t2.e);
                    i = t2.e;
                } else {
                    self.b.missing("}", false);
                    i = t2.s;
                }
                self.tok = None;
                self.b.close(sm, "template_substitution");
                continue;
            }
            if fs.is_none() {
                fs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = fs.take() {
            self.b.leaf("string_fragment", true, st, i);
        }
        if i < by.len() {
            self.b.leaf("`", false, i, i + 1);
            self.pos = i + 1;
        } else {
            self.b.missing("`", false);
            self.pos = i;
        }
        self.tok = None;
        self.regex_ok = false;
        self.b.close(m, "template_string")
    }

    fn regex(&mut self) -> NodeId {
        let t = self.peek();
        let (e, pe) = self.regex_end(t.s);
        let m = self.b.open();
        self.b.leaf("/", false, t.s, t.s + 1);
        let p = self.b.leaf("regex_pattern", true, t.s + 1, pe);
        self.b.set_field(p, "pattern");
        if pe < self.by.len() {
            self.b.leaf("/", false, pe, pe + 1);
        }
        if e > pe + 1 {
            let f = self.b.leaf("regex_flags", true, pe + 1, e);
            self.b.set_field(f, "flags");
        }
        self.pos = e;
        self.tok = None;
        self.regex_ok = false;
        self.b.close(m, "regex")
    }

    // ----------------------------------------------------------------- types
    fn type_annotation(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // :
        self.type_();
        self.b.close(m, "type_annotation")
    }

    fn type_(&mut self) -> NodeId {
        // function types
        if self.at("(") && self.is_arrow_ahead() || self.at("<") {
            let m = self.b.open();
            if self.at("<") {
                let tp = self.type_parameters();
                self.b.set_field(tp, "type_parameters");
            }
            let ps = self.formal_parameters();
            self.b.set_field(ps, "parameters");
            self.expect("=>");
            let r = self.type_();
            self.b.set_field(r, "return_type");
            return self.b.close(m, "function_type");
        }
        if self.at("new") || (self.at("abstract") && self.peek_nth(1).1 == "new") {
            let m = self.b.open();
            if self.at("abstract") {
                self.bump();
            }
            self.bump();
            if self.at("<") {
                let tp = self.type_parameters();
                self.b.set_field(tp, "type_parameters");
            }
            let ps = self.formal_parameters();
            self.b.set_field(ps, "parameters");
            self.expect("=>");
            let r = self.type_();
            self.b.set_field(r, "type");
            return self.b.close(m, "constructor_type");
        }
        let t = self.conditional_type();
        t
    }

    fn conditional_type(&mut self) -> NodeId {
        let left = self.union_type();
        if self.at("extends") && !self.peek().nl {
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            self.bump();
            let r = self.union_type();
            self.b.set_field(r, "right");
            self.expect("?");
            let c = self.type_();
            self.b.set_field(c, "consequence");
            self.expect(":");
            let a = self.type_();
            self.b.set_field(a, "alternative");
            return self.b.close(m, "conditional_type");
        }
        left
    }

    fn union_type(&mut self) -> NodeId {
        let lead = self.at("|");
        let m0 = if lead { Some(self.b.open()) } else { None };
        if lead {
            self.bump();
        }
        let mut left = self.intersection_type();
        if let Some(m) = m0 {
            if !self.at("|") {
                left = self.b.close(m, "union_type");
                return left;
            }
            self.b.abandon(m);
        }
        while self.at("|") {
            let m = self.b.open_before(left);
            self.bump();
            self.intersection_type();
            left = self.b.close(m, "union_type");
        }
        left
    }

    fn intersection_type(&mut self) -> NodeId {
        if self.at("&") {
            self.bump();
        }
        let mut left = self.type_operator();
        while self.at("&") {
            let m = self.b.open_before(left);
            self.bump();
            self.type_operator();
            left = self.b.close(m, "intersection_type");
        }
        left
    }

    fn type_operator(&mut self) -> NodeId {
        let w = self.peek_text();
        match w {
            "keyof" => {
                let m = self.b.open();
                self.bump();
                self.type_operator();
                self.b.close(m, "index_type_query")
            }
            "typeof" => {
                let m = self.b.open();
                self.bump();
                let mut e = self.ident_as("identifier");
                loop {
                    if self.at(".") {
                        let mm = self.b.open_before(e);
                        self.b.set_field(e, "object");
                        self.bump();
                        let p = self.ident_as("property_identifier");
                        self.b.set_field(p, "property");
                        e = self.b.close(mm, "member_expression");
                    } else {
                        break;
                    }
                }
                let q = self.b.close(m, "type_query");
                self.array_suffix(q)
            }
            "readonly" => {
                let m = self.b.open();
                self.bump();
                self.type_operator();
                self.b.close(m, "readonly_type")
            }
            "infer" => {
                let m = self.b.open();
                self.bump();
                self.ident_as("type_identifier");
                if self.at("extends") {
                    self.bump();
                    self.type_operator();
                }
                self.b.close(m, "infer_type")
            }
            "unique" => {
                self.bump();
                self.type_operator()
            }
            _ => {
                let p = self.primary_type();
                self.array_suffix(p)
            }
        }
    }

    fn array_suffix(&mut self, mut t: NodeId) -> NodeId {
        loop {
            if self.at("[") && !self.peek().nl {
                let (_, n1) = self.peek_nth(1);
                let m = self.b.open_before(t);
                self.bump();
                if n1 == "]" {
                    self.bump();
                    t = self.b.close(m, "array_type");
                } else {
                    self.type_();
                    self.expect("]");
                    t = self.b.close(m, "lookup_type");
                }
            } else {
                break;
            }
        }
        t
    }

    fn primary_type(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Str => {
                let m = self.b.open();
                self.string();
                return self.b.close(m, "literal_type");
            }
            TK::Num => {
                let m = self.b.open();
                self.bump_as("number", true);
                return self.b.close(m, "literal_type");
            }
            TK::Template => {
                return self.template_literal_type();
            }
            _ => {}
        }
        let w = self.text(t);
        match w {
            "-" => {
                let m = self.b.open();
                let um = self.b.open();
                self.bump();
                self.bump_as("number", true);
                self.b.close(um, "unary_expression");
                return self.b.close(m, "literal_type");
            }
            "(" => {
                let m = self.b.open();
                self.bump();
                self.type_();
                self.expect(")");
                return self.b.close(m, "parenthesized_type");
            }
            "[" => {
                let m = self.b.open();
                self.bump();
                loop {
                    if self.at("]") || self.peek().k == TK::Eof {
                        break;
                    }
                    if self.at("...") {
                        let rm = self.b.open();
                        self.bump();
                        self.type_();
                        self.b.close(rm, "rest_type");
                    } else if self.peek().k == TK::Ident && (self.peek_nth(1).1 == ":" || (self.peek_nth(1).1 == "?" && self.peek_nth(2).1 == ":")) {
                        let nm = self.b.open();
                        self.ident_as("identifier");
                        if self.at("?") {
                            self.bump();
                        }
                        self.bump();
                        self.type_();
                        self.b.close(nm, "named_tuple_member");
                    } else {
                        let ty = self.type_();
                        if self.at("?") {
                            let om = self.b.open_before(ty);
                            self.bump();
                            self.b.close(om, "optional_type");
                        }
                    }
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.expect("]");
                return self.b.close(m, "tuple_type");
            }
            "{" => {
                // object type or mapped type
                return self.object_type_body("object_type");
            }
            "true" | "false" | "null" | "undefined" => {
                if w == "undefined" || w == "null" {
                    if w == "null" {
                        let m = self.b.open();
                        self.bump_as("null", true);
                        return self.b.close(m, "literal_type");
                    }
                    let m = self.b.open();
                    self.bump_as("undefined", true);
                    return self.b.close(m, "literal_type");
                }
                let m = self.b.open();
                self.bump_as(if w == "true" { "true" } else { "false" }, true);
                return self.b.close(m, "literal_type");
            }
            "this" => return self.bump_as("this_type", true),
            "void" => {
                return self.bump_as("predefined_type", true);
            }
            "*" => {
                return self.bump_as("existential_type", true);
            }
            _ => {}
        }
        if t.k == TK::Ident {
            if PREDEFINED.contains(&w) && self.peek_nth(1).1 != "." {
                let m = self.b.open();
                self.bump();
                return self.b.close(m, "predefined_type");
            }
            // possibly nested name A.B.C
            let (_, n1) = self.peek_nth(1);
            let base = if n1 == "." {
                let mm = self.b.open();
                let mut cur = self.ident_as("identifier");
                loop {
                    let (_, n1) = self.peek_nth(1);
                    let (_, n2) = self.peek_nth(2);
                    if self.at(".") && n2 == "." {
                        let nm = self.b.open_before(cur);
                        self.b.set_field(cur, "object");
                        self.bump();
                        let p = self.ident_as("property_identifier");
                        self.b.set_field(p, "property");
                        cur = self.b.close(nm, "nested_identifier");
                        let _ = n1;
                        continue;
                    }
                    break;
                }
                self.b.set_field(cur, "module");
                self.expect(".");
                let n = self.ident_as("type_identifier");
                self.b.set_field(n, "name");
                self.b.close(mm, "nested_type_identifier")
            } else {
                self.ident_as("type_identifier")
            };
            if self.at("<") && !self.peek().nl {
                let m = self.b.open_before(base);
                self.b.set_field(base, "name");
                let ta = self.type_arguments();
                self.b.set_field(ta, "type_arguments");
                return self.b.close(m, "generic_type");
            }
            return base;
        }
        self.b.missing("type_identifier", true)
    }

    fn template_literal_type(&mut self) -> NodeId {
        let t = self.peek();
        let by = self.by;
        let s = t.s;
        let m = self.b.open();
        self.b.leaf("`", false, s, s + 1);
        self.tok = None;
        let mut i = s + 1;
        let mut fs: Option<usize> = None;
        loop {
            if i >= by.len() || by[i] == b'`' {
                break;
            }
            if by[i] == b'$' && by.get(i + 1) == Some(&b'{') {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let sm = self.b.open();
                self.b.leaf("${", false, i, i + 2);
                self.pos = i + 2;
                self.tok = None;
                self.type_();
                let t2 = self.peek();
                self.b.leaf("}", false, t2.s, t2.e);
                i = t2.e;
                self.tok = None;
                self.b.close(sm, "template_type");
                continue;
            }
            if fs.is_none() {
                fs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = fs.take() {
            self.b.leaf("string_fragment", true, st, i);
        }
        if i < by.len() {
            self.b.leaf("`", false, i, i + 1);
            self.pos = i + 1;
        }
        self.tok = None;
        self.b.close(m, "template_literal_type")
    }

    fn type_arguments(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // <
        loop {
            if self.peek_text().starts_with('>') || self.peek().k == TK::Eof {
                break;
            }
            self.type_();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(">");
        self.regex_ok = false;
        self.b.close(m, "type_arguments")
    }
}
