    // ----------------------------------------------------------- expressions
    fn expressions(&mut self) -> NodeId {
        let first = self.assignment_expr();
        if self.at(",") {
            let m = self.b.open_before(first);
            while self.at(",") {
                self.bump();
                self.assignment_expr();
            }
            return self.b.close(m, "sequence_expression");
        }
