    }

    fn expression(&mut self) -> NodeId {
        self.assignment_expr()
    }

    fn is_arrow_ahead(&mut self) -> bool {
        // at '(' or '<': scan to matching ')' and check for '=>' (or ':' return type then =>)
        let st = self.save();
        let mut depth = 0i32;
        let mut cur = self.peek();
        let mut n = 0;
        let mut result = false;
        if self.text(cur) == "<" {
            // generic arrow: skip type params
            let mut d = 0;
            loop {
                n += 1;
                if n > 5000 || cur.k == TK::Eof {
                    break;
                }
                let w = self.text(cur);
                if w == "<" {
                    d += 1;
                } else if w == ">" {
                    d -= 1;
                    if d == 0 {
                        self.pos = cur.e;
                        self.tok = None;
                        self.regex_ok = false;
                        let nl = self.skip_trivia(false);
                        cur = self.lex(nl);
                        break;
                    }
                }
                self.pos = self.skip_token(cur);
                self.regex_ok = false;
                let nl = self.skip_trivia(false);
                cur = self.lex(nl);
            }
            if self.text(cur) != "(" {
                self.restore(st);
                return false;
            }
        }
        loop {
            n += 1;
            if n > 20000 || cur.k == TK::Eof {
                break;
            }
            let w = if cur.k == TK::Punct { self.text(cur) } else { "" };
            match w {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => {
                    depth -= 1;
                    if depth == 0 {
                        self.pos = cur.e;
                        self.regex_ok = false;
                        let nl = self.skip_trivia(false);
                        let nx = self.lex(nl);
                        let nw = self.text(nx);
                        if nw == "=>" {
                            result = true;
                        } else if nw == ":" {
                            // return type annotation: scan until => at depth 0
                            self.pos = nx.e;
                            let mut d2 = 0i32;
                            let mut m2 = 0;
                            loop {
                                m2 += 1;
                                if m2 > 5000 {
                                    break;
                                }
                                let nl = self.skip_trivia(false);
                                let c2 = self.lex(nl);
                                if c2.k == TK::Eof {
                                    break;
                                }
                                let w2 = self.text(c2);
                                match w2 {
                                    "(" | "[" | "{" | "<" => d2 += 1,
                                    ")" | "]" | "}" | ">" => {
                                        if d2 == 0 {
                                            break;
                                        }
                                        d2 -= 1;
                                    }
                                    "=>" if d2 == 0 => {
                                        result = true;
                                        break;
                                    }
                                    ";" | "=" | "," if d2 == 0 => break,
                                    _ => {}
                                }
                                self.pos = self.skip_token(c2);
                            }
                        }
                        break;
                    }
                }
                _ => {}
            }
            self.pos = self.skip_token(cur);
            self.regex_ok = false;
            let nl = self.skip_trivia(false);
            cur = self.lex(nl);
        }
        self.restore(st);
        result
    }

    fn assignment_expr(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.peek_text();
        // arrow functions
        if t.k == TK::Ident && w == "async" && !self.peek_nth_newline(1) {
            let (k1, n1) = self.peek_nth(1);
            if (k1 == TK::Ident && self.peek_nth(2).1 == "=>") || ((n1 == "(" || n1 == "<") && {
                let st = self.save();
                self.bump();
                let r = self.is_arrow_ahead();
                self.restore(st);
                self.b.truncate_children_to_nodes();
                r
            }) {
                return self.arrow_function();
            }
        }
        if t.k == TK::Ident && !RESERVED.contains(&w) && self.peek_nth(1).1 == "=>" {
            return self.arrow_function();
        }
        if (w == "(" || w == "<") && self.is_arrow_ahead() {
            return self.arrow_function();
        }
        if w == "yield" {
            let m = self.b.open();
            self.bump();
            if self.at("*") {
                self.bump();
            }
            let t2 = self.peek();
            if !t2.nl && !matches!(self.peek_text(), ")" | "]" | "}" | ";" | "," | ":") && t2.k != TK::Eof {
                self.assignment_expr();
            }
            return self.b.close(m, "yield_expression");
        }
        let left = self.conditional();
        let t = self.peek();
        if t.k == TK::Punct {
            let op = self.text(t);
            if op == "=" {
                let m = self.b.open_before(left);
                self.to_pattern(left);
                self.b.set_field(left, "left");
                self.bump();
                let r = self.assignment_expr();
                self.b.set_field(r, "right");
                return self.b.close(m, "assignment_expression");
            }
            if matches!(op, "+=" | "-=" | "*=" | "/=" | "%=" | "^=" | "&=" | "|=" | ">>=" | ">>>=" | "<<=" | "**=" | "&&=" | "||=" | "??=") {
                let m = self.b.open_before(left);
                self.b.set_field(left, "left");
                let o = self.bump();
                self.b.set_field(o, "operator");
                let r = self.assignment_expr();
                self.b.set_field(r, "right");
                return self.b.close(m, "augmented_assignment_expression");
            }
        }
        left
    }

    fn arrow_function(&mut self) -> NodeId {
        let m = self.b.open();
        if self.at("async") {
            self.bump();
        }
        if self.peek().k == TK::Ident && !self.at("(") {
            let p = self.ident_as("identifier");
            self.b.set_field(p, "parameter");
        } else {
            self.call_signature();
        }
        self.expect("=>");
        if self.at("{") {
            let b = self.statement_block();
            self.b.set_field(b, "body");
        } else {
            let b = self.assignment_expr();
            self.b.set_field(b, "body");
        }
        self.b.close(m, "arrow_function")
    }

    fn conditional(&mut self) -> NodeId {
        let c = self.binary(0);
        if self.at("?") {
            let m = self.b.open_before(c);
            self.b.set_field(c, "condition");
            self.bump();
            let saved = self.no_in;
            self.no_in = false;
            let a = self.assignment_expr();
            self.no_in = saved;
            self.b.set_field(a, "consequence");
            self.expect(":");
            let b = self.assignment_expr();
            self.b.set_field(b, "alternative");
            return self.b.close(m, "ternary_expression");
        }
        c
    }

    fn binop(&mut self) -> Option<(&'a str, u8, bool)> {
        let t = self.peek();
        let w = self.text(t);
        if t.k == TK::Ident {
            return match w {
                "instanceof" => Some((w, 8, false)),
                "in" if !self.no_in => Some((w, 8, false)),
                "as" | "satisfies" if !t.nl => Some((w, 9, false)),
                _ => None,
            };
        }
        if t.k != TK::Punct {
            return None;
        }
        Some(match w {
            "??" => (w, 1, false),
            "||" => (w, 2, false),
            "&&" => (w, 3, false),
            "|" => (w, 4, false),
            "^" => (w, 5, false),
            "&" => (w, 6, false),
            "==" | "!=" | "===" | "!==" => (w, 7, false),
            "<" | ">" | "<=" | ">=" => (w, 8, false),
            "<<" | ">>" | ">>>" => (w, 9, false),
            "+" | "-" => (w, 10, false),
            "*" | "/" | "%" => (w, 11, false),
            "**" => (w, 12, true),
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) -> NodeId {
        let mut left = self.unary();
        loop {
            // '>' sequences for shift operators are lexed as '>' singles only in types; here ">>" fine
            let (op, p, right) = match self.binop() {
                Some(x) => x,
                None => break,
            };
            if p < min {
                break;
            }
            if op == "as" || op == "satisfies" {
                let m = self.b.open_before(left);
                self.bump();
                if op == "as" && self.at("const") {
                    self.bump();
                } else {
                    self.type_();
                }
                left = self.b.close(m, if op == "as" { "as_expression" } else { "satisfies_expression" });
                continue;
            }
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            let o = self.bump();
            self.b.set_field(o, "operator");
            let r = self.binary(if right { p } else { p + 1 });
            self.b.set_field(r, "right");
            left = self.b.close(m, "binary_expression");
        }
        // non-null assertion applies loosely in tree-sitter-typescript
        left
    }

    fn unary(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.peek_text();
        if t.k == TK::Punct && matches!(w, "!" | "~" | "-" | "+") {
            let m = self.b.open();
            let o = self.bump();
            self.b.set_field(o, "operator");
            let a = self.unary();
            self.b.set_field(a, "argument");
            return self.b.close(m, "unary_expression");
        }
        if t.k == TK::Ident && matches!(w, "typeof" | "void" | "delete") {
            let m = self.b.open();
            let o = self.bump();
            self.b.set_field(o, "operator");
            let a = self.unary();
            self.b.set_field(a, "argument");
            return self.b.close(m, "unary_expression");
        }
        if t.k == TK::Punct && (w == "++" || w == "--") {
            let m = self.b.open();
            let o = self.bump();
            self.b.set_field(o, "operator");
            let a = self.unary();
            self.b.set_field(a, "argument");
            return self.b.close(m, "update_expression");
        }
        if t.k == TK::Ident && w == "await" {
            let (k1, n1) = self.peek_nth(1);
            if !(n1 == ")" || n1 == ";" || n1 == "," || n1 == "=" || n1 == "." || k1 == TK::Eof) {
                let m = self.b.open();
                self.bump();
                self.unary();
                return self.b.close(m, "await_expression");
            }
        }
        if t.k == TK::Punct && w == "<" {
            // type assertion <T>expr
            let m = self.b.open();
            let ta = self.type_arguments();
            let _ = ta;
            self.unary();
            return self.b.close(m, "type_assertion");
        }
        let e = self.lhs_expression();
        // postfix update
        let t2 = self.peek();
        if t2.k == TK::Punct && !t2.nl && (self.text(t2) == "++" || self.text(t2) == "--") {
            let m = self.b.open_before(e);
            self.b.set_field(e, "argument");
            let o = self.bump();
            self.b.set_field(o, "operator");
            return self.b.close(m, "update_expression");
        }
        e
    }

    fn lhs_expression(&mut self) -> NodeId {
        let p = if self.at("new") {
            self.new_expression()
        } else {
            self.primary()
        };
        self.postfix(p, true)
    }

    fn new_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // new
        if self.at(".") {
            // new.target
            self.bump();
            self.ident_as("property_identifier");
            return self.b.close(m, "meta_property");
        }
        let c = if self.at("new") { self.new_expression() } else { self.primary() };
        let c = self.postfix(c, false);
        self.b.set_field(c, "constructor");
        if self.at("<") && self.type_args_ahead() {
            let ta = self.type_arguments();
            self.b.set_field(ta, "type_arguments");
        }
        if self.at("(") {
            let a = self.arguments();
            self.b.set_field(a, "arguments");
        }
        self.b.close(m, "new_expression")
    }

    fn type_args_ahead(&mut self) -> bool {
        // heuristically decide if '<' starts type arguments followed by '(' or '`'
        let st = self.save();
        let mut depth = 0i32;
        let mut cur = self.peek();
        let mut n = 0;
        let mut ok = false;
        loop {
            n += 1;
            if n > 2000 || cur.k == TK::Eof {
                break;
            }
            let w = self.text(cur);
            match w {
                "<" => depth += 1,
                ">" | ">>" | ">>>" => {
                    depth -= w.len() as i32;
                    if depth <= 0 {
                        self.pos = cur.e;
                        self.regex_ok = false;
                        let nl = self.skip_trivia(false);
                        let nx = self.lex(nl);
                        let nw = self.text(nx);
                        ok = depth == 0 && (nw == "(" || nx.k == TK::Template || nw == ")" || nw == "," || nw == ";" || nw == "." || nw == "?." || nx.k == TK::Eof || nx.nl);
                        break;
                    }
                }
                ";" | "{" | "}" | "=" | "&&" | "||" => break,
                _ => {}
            }
            self.pos = self.skip_token(cur);
            self.regex_ok = false;
            let nl = self.skip_trivia(false);
            cur = self.lex(nl);
        }
        self.restore(st);
        ok
    }

    fn postfix(&mut self, mut e: NodeId, allow_call: bool) -> NodeId {
        loop {
            let t = self.peek();
            match t.k {
                TK::Template => {
                    // tagged template
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let a = self.template_string();
                    self.b.set_field(a, "arguments");
                    e = self.b.close(m, "call_expression");
                    continue;
                }
                TK::Punct => {}
                _ => break,
            }
            let w = self.text(t);
            match w {
                "." | "?." => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "object");
                    if w == "?." {
                        let oc = self.b.open();
                        self.bump();
                        let o = self.b.close(oc, "optional_chain");
                        self.b.set_field(o, "optional_chain");
                        if self.at("(") {
                            let a = self.arguments();
                            self.b.set_field(a, "arguments");
                            self.b.set_field(e, "function");
                            e = self.b.close(m, "call_expression");
                            continue;
                        }
                        if self.at("[") {
                            self.bump();
                            let i = self.expressions();
                            self.b.set_field(i, "index");
                            self.expect("]");
                            e = self.b.close(m, "subscript_expression");
                            continue;
                        }
                    } else {
                        self.bump();
                    }
                    let t2 = self.peek();
                    let p = if t2.k == TK::PrivIdent { self.bump_as("private_property_identifier", true) } else { self.ident_as("property_identifier") };
                    self.b.set_field(p, "property");
                    e = self.b.close(m, "member_expression");
                }
                "[" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "object");
                    self.bump();
                    let saved = self.no_in;
                    self.no_in = false;
                    let i = self.expressions();
                    self.no_in = saved;
                    self.b.set_field(i, "index");
                    self.expect("]");
                    e = self.b.close(m, "subscript_expression");
                }
                "(" if allow_call => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let a = self.arguments();
                    self.b.set_field(a, "arguments");
                    e = self.b.close(m, "call_expression");
                }
                "<" if allow_call && self.type_args_ahead() => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let ta = self.type_arguments();
                    self.b.set_field(ta, "type_arguments");
                    if self.at("(") {
                        let a = self.arguments();
                        self.b.set_field(a, "arguments");
                        e = self.b.close(m, "call_expression");
                    } else if self.peek().k == TK::Template {
                        let a = self.template_string();
                        self.b.set_field(a, "arguments");
                        e = self.b.close(m, "call_expression");
                    } else {
                        self.b.nodes[e as usize].field = None;
                        e = self.b.close(m, "instantiation_expression");
                    }
                }
                "!" if !t.nl => {
                    // non-null assertion (not `!=`)
                    let m = self.b.open_before(e);
                    self.bump();
                    e = self.b.close(m, "non_null_expression");
                    self.regex_ok = false;
                }
                _ => break,
            }
        }
        e
    }

    fn arguments(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // (
        let saved = self.no_in;
        self.no_in = false;
        loop {
            if self.at(")") || self.peek().k == TK::Eof {
                break;
            }
            if self.at("...") {
                let sm = self.b.open();
                self.bump();
                self.assignment_expr();
                self.b.close(sm, "spread_element");
            } else {
                self.assignment_expr();
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.no_in = saved;
        self.expect(")");
        self.regex_ok = false;
        self.b.close(m, "arguments")
    }

    fn primary(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Num => return self.bump_as("number", true),
            TK::Str => return self.string(),
            TK::Template => return self.template_string(),
            TK::Regex => return self.regex(),
            TK::PrivIdent => return self.bump_as("private_property_identifier", true),
            TK::Eof => return self.b.missing("identifier", true),
            _ => {}
        }
        let w = self.text(t);
        match w {
            "(" => {
                let m = self.b.open();
                self.bump();
                let saved = self.no_in;
                self.no_in = false;
                self.expressions();
                if self.at(":") {
                    // (x: T) type annotation in parenthesized expr (rare)
                    self.type_annotation();
                }
                self.no_in = saved;
                self.expect(")");
                self.regex_ok = false;
                return self.b.close(m, "parenthesized_expression");
            }
            "[" => {
                let m = self.b.open();
                self.bump();
                let saved = self.no_in;
                self.no_in = false;
                loop {
                    if self.at("]") || self.peek().k == TK::Eof {
                        break;
                    }
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    if self.at("...") {
                        let sm = self.b.open();
                        self.bump();
                        self.assignment_expr();
                        self.b.close(sm, "spread_element");
                    } else {
                        self.assignment_expr();
                    }
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.no_in = saved;
                self.expect("]");
                self.regex_ok = false;
                return self.b.close(m, "array");
            }
            "{" => return self.object_literal(),
            "function" => {
                let m = self.b.open();
                self.bump();
                let generator = if self.at("*") {
                    self.bump();
                    true
                } else {
                    false
                };
                if self.peek().k == TK::Ident && !self.at("(") {
                    let n = self.ident_as("identifier");
                    self.b.set_field(n, "name");
                }
                self.call_signature();
                let b = self.statement_block();
                self.b.set_field(b, "body");
                self.regex_ok = false;
                return self.b.close(m, if generator { "generator_function" } else { "function_expression" });
            }
            "async" if self.peek_nth(1).1 == "function" => {
                let m = self.b.open();
                self.bump();
                self.bump();
                let generator = if self.at("*") {
                    self.bump();
                    true
                } else {
                    false
                };
                if self.peek().k == TK::Ident && !self.at("(") {
                    let n = self.ident_as("identifier");
                    self.b.set_field(n, "name");
                }
                self.call_signature();
                let b = self.statement_block();
                self.b.set_field(b, "body");
                self.regex_ok = false;
                return self.b.close(m, if generator { "generator_function" } else { "function_expression" });
            }
            "class" => return self.class_expression(),
            "this" => return self.bump_as("this", true),
            "super" => return self.bump_as("super", true),
            "true" => return self.bump_as("true", true),
            "false" => return self.bump_as("false", true),
            "null" => return self.bump_as("null", true),
            "undefined" => return self.bump_as("undefined", true),
            "import" => return self.bump_as("import", true),
            _ => {}
        }
        if t.k == TK::Ident {
            return self.bump_as("identifier", true);
        }
        self.b.missing("identifier", true)
    }

    fn object_literal(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // {
        let saved = self.no_in;
        self.no_in = false;
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            if self.at("...") {
                let sm = self.b.open();
                self.bump();
                self.assignment_expr();
                self.b.close(sm, "spread_element");
            } else {
                self.object_member();
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.no_in = saved;
        self.expect("}");
        self.regex_ok = false;
        self.b.close(m, "object")
    }

    fn object_member(&mut self) {
        let m = self.b.open();
        // modifiers: async, get, set, *
        loop {
            let w = self.peek_text();
            if matches!(w, "async" | "get" | "set") {
                let (k, n) = self.peek_nth(1);
                if k == TK::Ident || k == TK::Str || k == TK::Num || n == "[" || n == "*" {
                    self.bump();
                    continue;
                }
            }
            break;
        }
        if self.at("*") {
            self.bump();
        }
        let t = self.peek();
        let (_, n1) = self.peek_nth(1);
        if t.k == TK::Ident && (n1 == "," || n1 == "}" || n1 == "=") && !self.b.current_children().iter().any(|_| false) {
            if n1 == "=" {
                // shorthand with default (in patterns)
                let id = self.ident_as("identifier");
                let am = self.b.open_before(id);
                self.b.set_field(id, "left");
                self.bump();
                let r = self.assignment_expr();
                self.b.set_field(r, "right");
                self.b.close(am, "assignment_expression");
                self.b.abandon(m);
                return;
            }
            self.b.abandon(m);
            self.bump_as("shorthand_property_identifier", true);
            return;
        }
        let k = self.property_name();
        if self.at("(") || self.at("<") {
            self.b.set_field(k, "name");
            self.call_signature();
            let b = self.statement_block();
            self.b.set_field(b, "body");
            self.b.close(m, "method_definition");
            return;
        }
        self.b.set_field(k, "key");
        self.expect(":");
        let v = self.assignment_expr();
        self.b.set_field(v, "value");
        self.b.close(m, "pair");
    }

    fn string(&mut self) -> NodeId {
        let t = self.peek();
        let by = self.by;
        let s = t.s;
        if t.k != TK::Str {
            return self.b.missing("string", true);
        }
        let q = by[s];
        let m = self.b.open();
        self.b.leaf(if q == b'"' { "\"" } else { "'" }, false, s, s + 1);
        let mut i = s + 1;
        let mut fs: Option<usize> = None;
        while i < by.len() && by[i] != q && by[i] != b'\n' {
            if by[i] == b'\\' {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let len = self.escape_len(i);
                self.b.leaf("escape_sequence", true, i, i + len);
                i += len;
                continue;
            }
            if fs.is_none() {
                fs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = fs.take() {
            self.b.leaf("string_fragment", true, st, i);
        }
        if i < by.len() && by[i] == q {
            self.b.leaf(if q == b'"' { "\"" } else { "'" }, false, i, i + 1);
            self.pos = i + 1;
        } else {
            self.b.missing(if q == b'"' { "\"" } else { "'" }, false);
            self.pos = i;
        }
        self.tok = None;
        self.regex_ok = false;
        self.b.close(m, "string")
    }

    fn escape_len(&self, i: usize) -> usize {
        let by = self.by;
        match by.get(i + 1) {
            None => 1,
            Some(b'u') => {
                if by.get(i + 2) == Some(&b'{') {
                    let mut j = i + 3;
                    while j < by.len() && by[j] != b'}' {
                        j += 1;
                    }
                    return (j + 1 - i).min(by.len() - i);
                }
                6.min(by.len() - i)
            }
            Some(b'x') => 4.min(by.len() - i),
            Some(b'\r') => {
                if by.get(i + 2) == Some(&b'\n') {
                    3
                } else {
                    2
                }
            }
            Some(b'0'..=b'7') => {
                let mut j = i + 1;
                while j < by.len() && j < i + 4 && (b'0'..=b'7').contains(&by[j]) {
                    j += 1;
                }
                j - i
            }
            Some(_) => 1 + self.ch(i + 1).map(|c| c.len_utf8()).unwrap_or(1),
        }
    }

    fn template_string(&mut self) -> NodeId {
        let t = self.peek();
        let by = self.by;
        let s = t.s;
        let m = self.b.open();
        self.b.leaf("`", false, s, s + 1);
        self.tok = None;
        let mut i = s + 1;
        let mut fs: Option<usize> = None;
        loop {
            if i >= by.len() {
                break;
            }
            let c = by[i];
            if c == b'`' {
                break;
            }
            if c == b'\\' {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let len = self.escape_len(i);
                self.b.leaf("escape_sequence", true, i, i + len);
                i += len;
                continue;
            }
            if c == b'$' && by.get(i + 1) == Some(&b'{') {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let sm = self.b.open();
                self.b.leaf("${", false, i, i + 2);
                self.pos = i + 2;
                self.tok = None;
                self.regex_ok = true;
                self.expressions();
                let t2 = self.peek();
                if self.text(t2) == "}" {
                    self.b.leaf("}", false, t2.s, t2.e);
                    i = t2.e;
                } else {
                    self.b.missing("}", false);
                    i = t2.s;
                }
                self.tok = None;
                self.b.close(sm, "template_substitution");
                continue;
            }
            if fs.is_none() {
                fs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = fs.take() {
            self.b.leaf("string_fragment", true, st, i);
        }
        if i < by.len() {
            self.b.leaf("`", false, i, i + 1);
            self.pos = i + 1;
        } else {
            self.b.missing("`", false);
            self.pos = i;
        }
        self.tok = None;
        self.regex_ok = false;
        self.b.close(m, "template_string")
    }

    fn regex(&mut self) -> NodeId {
        let t = self.peek();
        let (e, pe) = self.regex_end(t.s);
        let m = self.b.open();
        self.b.leaf("/", false, t.s, t.s + 1);
        let p = self.b.leaf("regex_pattern", true, t.s + 1, pe);
        self.b.set_field(p, "pattern");
        if pe < self.by.len() {
            self.b.leaf("/", false, pe, pe + 1);
        }
        if e > pe + 1 {
            let f = self.b.leaf("regex_flags", true, pe + 1, e);
            self.b.set_field(f, "flags");
        }
        self.pos = e;
        self.tok = None;
        self.regex_ok = false;
        self.b.close(m, "regex")
    }

    // ----------------------------------------------------------------- types
    fn type_annotation(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // :
        self.type_();
        self.b.close(m, "type_annotation")
    }

    fn type_(&mut self) -> NodeId {
        // function types
        if self.at("(") && self.is_arrow_ahead() || self.at("<") {
            let m = self.b.open();
            if self.at("<") {
                let tp = self.type_parameters();
                self.b.set_field(tp, "type_parameters");
            }
            let ps = self.formal_parameters();
            self.b.set_field(ps, "parameters");
            self.expect("=>");
            let r = self.type_();
            self.b.set_field(r, "return_type");
            return self.b.close(m, "function_type");
        }
        if self.at("new") || (self.at("abstract") && self.peek_nth(1).1 == "new") {
            let m = self.b.open();
            if self.at("abstract") {
                self.bump();
            }
            self.bump();
            if self.at("<") {
                let tp = self.type_parameters();
                self.b.set_field(tp, "type_parameters");
            }
            let ps = self.formal_parameters();
            self.b.set_field(ps, "parameters");
            self.expect("=>");
            let r = self.type_();
            self.b.set_field(r, "type");
            return self.b.close(m, "constructor_type");
        }
        let t = self.conditional_type();
        t
    }

    fn conditional_type(&mut self) -> NodeId {
        let left = self.union_type();
        if self.at("extends") && !self.peek().nl {
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            self.bump();
            let r = self.union_type();
            self.b.set_field(r, "right");
            self.expect("?");
            let c = self.type_();
            self.b.set_field(c, "consequence");
            self.expect(":");
            let a = self.type_();
            self.b.set_field(a, "alternative");
            return self.b.close(m, "conditional_type");
        }
        left
    }

    fn union_type(&mut self) -> NodeId {
        let lead = self.at("|");
        let m0 = if lead { Some(self.b.open()) } else { None };
        if lead {
            self.bump();
        }
        let mut left = self.intersection_type();
        if let Some(m) = m0 {
            if !self.at("|") {
                left = self.b.close(m, "union_type");
                return left;
            }
            self.b.abandon(m);
        }
        while self.at("|") {
            let m = self.b.open_before(left);
            self.bump();
            self.intersection_type();
            left = self.b.close(m, "union_type");
        }
        left
    }

    fn intersection_type(&mut self) -> NodeId {
        if self.at("&") {
            self.bump();
        }
        let mut left = self.type_operator();
        while self.at("&") {
            let m = self.b.open_before(left);
            self.bump();
            self.type_operator();
            left = self.b.close(m, "intersection_type");
        }
        left
    }

    fn type_operator(&mut self) -> NodeId {
        let w = self.peek_text();
        match w {
            "keyof" => {
                let m = self.b.open();
                self.bump();
                self.type_operator();
                self.b.close(m, "index_type_query")
            }
            "typeof" => {
                let m = self.b.open();
                self.bump();
                let mut e = self.ident_as("identifier");
                loop {
                    if self.at(".") {
                        let mm = self.b.open_before(e);
                        self.b.set_field(e, "object");
                        self.bump();
                        let p = self.ident_as("property_identifier");
                        self.b.set_field(p, "property");
                        e = self.b.close(mm, "member_expression");
                    } else {
                        break;
                    }
                }
                let q = self.b.close(m, "type_query");
                self.array_suffix(q)
            }
            "readonly" => {
                let m = self.b.open();
                self.bump();
                self.type_operator();
                self.b.close(m, "readonly_type")
            }
            "infer" => {
                let m = self.b.open();
                self.bump();
                self.ident_as("type_identifier");
                if self.at("extends") {
                    self.bump();
                    self.type_operator();
                }
                self.b.close(m, "infer_type")
            }
            "unique" => {
                self.bump();
                self.type_operator()
            }
            _ => {
                let p = self.primary_type();
                self.array_suffix(p)
            }
        }
    }

    fn array_suffix(&mut self, mut t: NodeId) -> NodeId {
        loop {
            if self.at("[") && !self.peek().nl {
                let (_, n1) = self.peek_nth(1);
                let m = self.b.open_before(t);
                self.bump();
                if n1 == "]" {
                    self.bump();
                    t = self.b.close(m, "array_type");
                } else {
                    self.type_();
                    self.expect("]");
                    t = self.b.close(m, "lookup_type");
                }
            } else {
                break;
            }
        }
        t
    }

    fn primary_type(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Str => {
                let m = self.b.open();
                self.string();
                return self.b.close(m, "literal_type");
            }
            TK::Num => {
                let m = self.b.open();
                self.bump_as("number", true);
                return self.b.close(m, "literal_type");
            }
            TK::Template => {
                return self.template_literal_type();
            }
            _ => {}
        }
        let w = self.text(t);
        match w {
            "-" => {
                let m = self.b.open();
                let um = self.b.open();
                self.bump();
                self.bump_as("number", true);
                self.b.close(um, "unary_expression");
                return self.b.close(m, "literal_type");
            }
            "(" => {
                let m = self.b.open();
                self.bump();
                self.type_();
                self.expect(")");
                return self.b.close(m, "parenthesized_type");
            }
            "[" => {
                let m = self.b.open();
                self.bump();
                loop {
                    if self.at("]") || self.peek().k == TK::Eof {
                        break;
                    }
                    if self.at("...") {
                        let rm = self.b.open();
                        self.bump();
                        self.type_();
                        self.b.close(rm, "rest_type");
                    } else if self.peek().k == TK::Ident && (self.peek_nth(1).1 == ":" || (self.peek_nth(1).1 == "?" && self.peek_nth(2).1 == ":")) {
                        let nm = self.b.open();
                        self.ident_as("identifier");
                        if self.at("?") {
                            self.bump();
                        }
                        self.bump();
                        self.type_();
                        self.b.close(nm, "named_tuple_member");
                    } else {
                        let ty = self.type_();
                        if self.at("?") {
                            let om = self.b.open_before(ty);
                            self.bump();
                            self.b.close(om, "optional_type");
                        }
                    }
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.expect("]");
                return self.b.close(m, "tuple_type");
            }
            "{" => {
                // object type or mapped type
                return self.object_type_body("object_type");
            }
            "true" | "false" | "null" | "undefined" => {
                if w == "undefined" || w == "null" {
                    if w == "null" {
                        let m = self.b.open();
                        self.bump_as("null", true);
                        return self.b.close(m, "literal_type");
                    }
                    let m = self.b.open();
                    self.bump_as("undefined", true);
                    return self.b.close(m, "literal_type");
                }
                let m = self.b.open();
                self.bump_as(if w == "true" { "true" } else { "false" }, true);
                return self.b.close(m, "literal_type");
            }
            "this" => return self.bump_as("this_type", true),
            "void" => {
                return self.bump_as("predefined_type", true);
            }
            "*" => {
                return self.bump_as("existential_type", true);
            }
            _ => {}
        }
        if t.k == TK::Ident {
            if PREDEFINED.contains(&w) && self.peek_nth(1).1 != "." {
                let m = self.b.open();
                self.bump();
                return self.b.close(m, "predefined_type");
            }
            // possibly nested name A.B.C
            let (_, n1) = self.peek_nth(1);
            let base = if n1 == "." {
                let mm = self.b.open();
                let mut cur = self.ident_as("identifier");
                loop {
                    let (_, n1) = self.peek_nth(1);
                    let (_, n2) = self.peek_nth(2);
                    if self.at(".") && n2 == "." {
                        let nm = self.b.open_before(cur);
                        self.b.set_field(cur, "object");
                        self.bump();
                        let p = self.ident_as("property_identifier");
                        self.b.set_field(p, "property");
                        cur = self.b.close(nm, "nested_identifier");
                        let _ = n1;
                        continue;
                    }
                    break;
                }
                self.b.set_field(cur, "module");
                self.expect(".");
                let n = self.ident_as("type_identifier");
                self.b.set_field(n, "name");
                self.b.close(mm, "nested_type_identifier")
            } else {
                self.ident_as("type_identifier")
            };
            if self.at("<") && !self.peek().nl {
                let m = self.b.open_before(base);
                self.b.set_field(base, "name");
                let ta = self.type_arguments();
                self.b.set_field(ta, "type_arguments");
                return self.b.close(m, "generic_type");
            }
            return base;
        }
        self.b.missing("type_identifier", true)
    }

    fn template_literal_type(&mut self) -> NodeId {
        let t = self.peek();
        let by = self.by;
        let s = t.s;
        let m = self.b.open();
        self.b.leaf("`", false, s, s + 1);
        self.tok = None;
        let mut i = s + 1;
        let mut fs: Option<usize> = None;
        loop {
            if i >= by.len() || by[i] == b'`' {
                break;
            }
            if by[i] == b'$' && by.get(i + 1) == Some(&b'{') {
                if let Some(st) = fs.take() {
                    self.b.leaf("string_fragment", true, st, i);
                }
                let sm = self.b.open();
                self.b.leaf("${", false, i, i + 2);
                self.pos = i + 2;
                self.tok = None;
                self.type_();
                let t2 = self.peek();
                self.b.leaf("}", false, t2.s, t2.e);
                i = t2.e;
                self.tok = None;
                self.b.close(sm, "template_type");
                continue;
            }
            if fs.is_none() {
                fs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = fs.take() {
            self.b.leaf("string_fragment", true, st, i);
        }
        if i < by.len() {
            self.b.leaf("`", false, i, i + 1);
            self.pos = i + 1;
        }
        self.tok = None;
        self.b.close(m, "template_literal_type")
    }

    fn type_arguments(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // <
        loop {
            if self.peek_text().starts_with('>') || self.peek().k == TK::Eof {
                break;
            }
            self.type_();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(">");
        self.regex_ok = false;
        self.b.close(m, "type_arguments")
    }
}
