//! C# parser producing tree-sitter-c-sharp compatible trees.

use super::python::intern;
use crate::ts::builder::{Builder, Marker};
use crate::ts::{NodeId, Tree};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK {
    Ident,
    Int,
    Real,
    Str,
    Char,
    Punct,
    Eof,
    Err,
}

#[derive(Clone, Copy, Debug)]
struct Tok {
    k: TK,
    s: usize,
    e: usize,
}

const PUNCTS: &[&str] = &[
    ">>>=", "<<=", "??=", "=>", "??", "?.", "::", "++", "--", "&&", "||", "==", "!=", "<=",
    "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", "->", "..", "+", "-", "*", "/", "%",
    "&", "|", "^", "!", "~", "<", ">", "=", "?", ":", ";", ",", ".", "(", ")", "[", "]", "{",
    "}", "@", "#",
];

const PREDEFINED: &[&str] = &[
    "bool", "byte", "char", "decimal", "double", "float", "int", "long", "object", "sbyte",
    "short", "string", "uint", "ulong", "ushort", "void", "nint", "nuint", "dynamic",
];

const MODIFIERS: &[&str] = &[
    "abstract", "async", "const", "extern", "fixed", "internal", "new", "override", "partial",
    "private", "protected", "public", "readonly", "required", "sealed", "static", "unsafe",
    "virtual", "volatile", "file", "ref", "scoped",
];

const KEYWORDS: &[&str] = &[
    "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked",
    "class", "const", "continue", "decimal", "default", "delegate", "do", "double", "else",
    "enum", "event", "explicit", "extern", "false", "finally", "fixed", "float", "for",
    "foreach", "goto", "if", "implicit", "in", "int", "interface", "internal", "is", "lock",
    "long", "namespace", "new", "null", "object", "operator", "out", "override", "params",
    "private", "protected", "public", "readonly", "ref", "return", "sbyte", "sealed", "short",
    "sizeof", "stackalloc", "static", "string", "struct", "switch", "this", "throw", "true",
    "try", "typeof", "uint", "ulong", "unchecked", "unsafe", "ushort", "using", "virtual",
    "void", "volatile", "while",
];

pub struct Cs<'a> {
    src: &'a str,
    by: &'a [u8],
    b: Builder,
    pos: usize,
    tok: Option<Tok>,
}

pub fn parse(src: &str) -> Tree {
    let mut p = Cs { src, by: src.as_bytes(), b: Builder::new(), pos: 0, tok: None };
    p.compilation_unit();
    p.b.finish("compilation_unit", src.len())
}

fn is_id_start(c: char) -> bool {
    c == '_' || c.is_alphabetic()
}
fn is_id_cont(c: char) -> bool {
    c == '_' || c.is_alphanumeric()
}

impl<'a> Cs<'a> {
    fn ch(&self, i: usize) -> Option<char> {
        self.src.get(i..).and_then(|s| s.chars().next())
    }
    fn text(&self, t: Tok) -> &'a str {
        &self.src[t.s..t.e]
    }

    fn skip_trivia(&mut self, emit: bool) {
        let by = self.by;
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return,
            };
            if c.is_whitespace() || c == '\u{feff}' {
                self.pos += c.len_utf8();
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'/') {
                let s = self.pos;
                let mut e = s;
                while e < by.len() && by[e] != b'\n' {
                    e += 1;
                }
                let mut ce = e;
                if ce > s && by[ce - 1] == b'\r' {
                    ce -= 1;
                }
                if emit {
                    self.b.extra("comment", s, ce);
                }
                self.pos = e;
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'*') {
                let s = self.pos;
                let mut i = s + 2;
                while i + 1 < by.len() && !(by[i] == b'*' && by[i + 1] == b'/') {
                    i += 1;
                }
                let e = if i + 1 < by.len() { i + 2 } else { by.len() };
                if emit {
                    self.b.extra("comment", s, e);
                }
                self.pos = e;
                continue;
            }
            if c == '#' && self.at_line_start(self.pos) {
                // preprocessor directive
                let s = self.pos;
                let mut e = s;
                while e < by.len() && by[e] != b'\n' {
                    e += 1;
                }
                let line = &self.src[s..e];
                let word: String = line[1..].trim_start().chars().take_while(|c| c.is_alphabetic()).collect();
                let kind = match word.as_str() {
                    "region" => "preproc_region",
                    "endregion" => "preproc_endregion",
                    "pragma" => "preproc_pragma",
                    "nullable" => "preproc_nullable",
                    "define" => "preproc_define",
                    "undef" => "preproc_undef",
                    "line" => "preproc_line",
                    "error" => "preproc_error",
                    "warning" => "preproc_warning",
                    "if" => "preproc_if",
                    "elif" => "preproc_elif",
                    "else" => "preproc_else",
                    "endif" => "preproc_endif",
                    _ => "preproc_pragma",
                };
                let mut ce = e;
                if ce > s && by[ce - 1] == b'\r' {
                    ce -= 1;
                }
                if emit {
                    self.b.extra(kind, s, ce);
                }
                self.pos = e;
                continue;
            }
            return;
        }
    }

    fn at_line_start(&self, i: usize) -> bool {
        let mut j = i;
        while j > 0 {
            let c = self.by[j - 1];
            if c == b'\n' {
                return true;
            }
            if c != b' ' && c != b'\t' {
                return false;
            }
            j -= 1;
        }
        true
    }

    fn lex(&mut self) -> Tok {
        let s = self.pos;
        let by = self.by;
        let c = match self.ch(s) {
            None => return Tok { k: TK::Eof, s, e: s },
            Some(c) => c,
        };
        if c == '"' || ((c == '$' || c == '@') && matches!(by.get(s + 1), Some(b'"') | Some(b'@') | Some(b'$'))) {
            if c != '"' {
                // $" @" $@" @$"
                let n = by.get(s + 1).copied();
                if n == Some(b'"') || ((n == Some(b'@') || n == Some(b'$')) && by.get(s + 2) == Some(&b'"')) {
                    return Tok { k: TK::Str, s, e: s };
                }
            } else {
                return Tok { k: TK::Str, s, e: s };
            }
        }
        if c == '\'' {
            let mut i = s + 1;
            while i < by.len() && by[i] != b'\'' && by[i] != b'\n' {
                if by[i] == b'\\' {
                    i += 1;
                }
                i += 1;
            }
            return Tok { k: TK::Char, s, e: (i + 1).min(by.len()) };
        }
        if c == '@' && self.ch(s + 1).map(is_id_start).unwrap_or(false) {
            let mut e = s + 1;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            return Tok { k: TK::Ident, s, e };
        }
        if is_id_start(c) {
            let mut e = s;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            return Tok { k: TK::Ident, s, e };
        }
        if c.is_ascii_digit() || (c == '.' && by.get(s + 1).map(|b| b.is_ascii_digit()).unwrap_or(false)) {
            let mut e = s;
            let mut real = false;
            if by[e] == b'0' && matches!(by.get(e + 1), Some(b'x') | Some(b'X') | Some(b'b') | Some(b'B')) {
                e += 2;
                while e < by.len() && (by[e].is_ascii_hexdigit() || by[e] == b'_') {
                    e += 1;
                }
            } else {
                while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                    e += 1;
                }
                if e < by.len() && by[e] == b'.' && by.get(e + 1).map(|b| b.is_ascii_digit()).unwrap_or(false) {
                    real = true;
                    e += 1;
                    while e < by.len() && (by[e].is_ascii_digit() || by[e] == b'_') {
                        e += 1;
                    }
                }
                if e < by.len() && (by[e] == b'e' || by[e] == b'E') {
                    let mut f = e + 1;
                    if f < by.len() && (by[f] == b'+' || by[f] == b'-') {
                        f += 1;
                    }
                    if f < by.len() && by[f].is_ascii_digit() {
                        real = true;
                        e = f;
                        while e < by.len() && by[e].is_ascii_digit() {
                            e += 1;
                        }
                    }
                }
                if e < by.len() && matches!(by[e], b'f' | b'F' | b'd' | b'D' | b'm' | b'M') {
                    real = true;
                    e += 1;
                }
            }
            while e < by.len() && matches!(by[e], b'u' | b'U' | b'l' | b'L') {
                e += 1;
            }
            return Tok { k: if real { TK::Real } else { TK::Int }, s, e };
        }
        for p in PUNCTS {
            if self.src[s..].starts_with(p) {
                return Tok { k: TK::Punct, s, e: s + p.len() };
            }
        }
        Tok { k: TK::Err, s, e: s + c.len_utf8() }
    }

    fn peek(&mut self) -> Tok {
        if let Some(t) = self.tok {
            return t;
        }
        self.skip_trivia(true);
        let t = self.lex();
        self.tok = Some(t);
        t
    }

    fn peek_text(&mut self) -> &'a str {
        let t = self.peek();
        if t.k == TK::Str {
            return "\"";
        }
        self.text(t)
    }

    fn save(&self) -> (usize, Option<Tok>, usize, usize) {
        (self.pos, self.tok, self.b.nodes.len(), self.b.pending_count())
    }

    fn restore(&mut self, s: (usize, Option<Tok>, usize, usize)) {
        self.pos = s.0;
        self.tok = s.1;
        self.b.truncate_pending(s.3);
        self.b.nodes.truncate(s.2);
        self.b.truncate_children_to_nodes();
    }

    fn skip_tok(&self, t: Tok) -> usize {
        if t.k == TK::Str {
            return self.string_end(t.s).0;
        }
        t.e
    }

    fn peek_nth(&mut self, n: usize) -> (TK, &'a str) {
        let st = self.save();
        let mut cur = self.peek();
        for _ in 0..n {
            self.pos = self.skip_tok(cur);
            self.skip_trivia(false);
            cur = self.lex();
        }
        let r = (cur.k, if cur.k == TK::Str { "\"" } else { self.text(cur) });
        self.restore(st);
        r
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        matches!(t.k, TK::Punct | TK::Ident) && self.text(t) == s
    }

    fn bump_as(&mut self, kind: &'static str, named: bool) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        id
    }

    fn bump(&mut self) -> NodeId {
        let t = self.peek();
        let k = intern(self.text(t));
        self.bump_as(k, false)
    }

    fn bump_gt(&mut self) -> NodeId {
        // consume a single '>' (tokens are lexed singly)
        self.bump()
    }

    fn expect(&mut self, s: &str) -> bool {
        if self.at(s) {
            self.bump();
            true
        } else {
            self.b.missing(intern(s), false);
            false
        }
    }

    fn identifier(&mut self) -> NodeId {
        let t = self.peek();
        if t.k == TK::Ident {
            self.bump_as("identifier", true)
        } else {
            self.b.missing("identifier", true)
        }
    }

    // --------------------------------------------------------------- top level
    fn compilation_unit(&mut self) {
        loop {
            let t = self.peek();
            if t.k == TK::Eof {
                break;
            }
            let before = t.s;
            self.top_level_item();
            let t = self.peek();
            if t.s == before && t.k != TK::Eof {
                let m = self.b.open();
                self.bump();
                self.b.close(m, "ERROR");
            }
        }
    }

    fn top_level_item(&mut self) {
        if self.at("using") && self.peek_nth(1).1 != "(" && !(self.peek_nth(1).1 == "var") {
            return self.using_directive();
        }
        if self.at("extern") && self.peek_nth(1).1 == "alias" {
            let m = self.b.open();
            self.bump();
            self.bump();
            self.identifier();
            self.expect(";");
            self.b.close(m, "extern_alias_directive");
            return;
        }
        if self.at("[") && {
            let (_, n1) = self.peek_nth(1);
            let (_, n2) = self.peek_nth(2);
            (n1 == "assembly" || n1 == "module") && n2 == ":"
        } {
            let m = self.b.open();
            self.attribute_list();
            self.b.close(m, "global_attribute");
            return;
        }
        if self.is_declaration_start() {
            self.declaration();
            return;
        }
        // top-level statements
        let m = self.b.open();
        self.statement();
        self.b.close(m, "global_statement");
    }

    fn using_directive(&mut self) {
        let m = self.b.open();
        if self.at("global") {
            self.bump();
        }
        self.bump(); // using
        if self.at("static") {
            self.bump();
        }
        if self.peek().k == TK::Ident && self.peek_nth(1).1 == "=" {
            let n = self.identifier();
            self.b.set_field(n, "name");
            self.bump();
        }
        self.type_();
        self.expect(";");
        self.b.close(m, "using_directive");
    }

    fn is_declaration_start(&mut self) -> bool {
        let st = self.save();
        // skip attributes and modifiers
        let mut cur = self.peek();
        let mut n = 0;
        let mut result = false;
        loop {
            n += 1;
            if n > 200 {
                break;
            }
            let w = self.text(cur);
            if cur.k == TK::Punct && w == "[" {
                // skip attribute list
                let mut depth = 0;
                loop {
                    let w2 = self.text(cur);
                    if w2 == "[" {
                        depth += 1;
                    } else if w2 == "]" {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    if cur.k == TK::Eof {
                        break;
                    }
                    self.pos = self.skip_tok(cur);
                    self.skip_trivia(false);
                    cur = self.lex();
                }
                self.pos = cur.e;
                self.skip_trivia(false);
                cur = self.lex();
                continue;
            }
            if cur.k == TK::Ident && MODIFIERS.contains(&w) {
                self.pos = cur.e;
                self.skip_trivia(false);
                cur = self.lex();
                continue;
            }
            result = cur.k == TK::Ident && matches!(w, "class" | "struct" | "interface" | "enum" | "record" | "delegate" | "namespace");
            break;
        }
        self.restore(st);
        result
    }

    fn modifiers(&mut self) {
        loop {
            let t = self.peek();
            if t.k != TK::Ident {
                break;
            }
            let w = self.text(t);
            if !MODIFIERS.contains(&w) {
                break;
            }
            // `partial`/`async`/`file`/`required`/`scoped` can be identifiers
            if matches!(w, "partial" | "async" | "file" | "required" | "scoped") {
                let (k1, n1) = self.peek_nth(1);
                if !(k1 == TK::Ident) || n1 == "=" || n1 == "(" {
                    if !(w == "async" && (n1 == "(" || k1 == TK::Ident)) {
                        break;
                    }
                }
            }
            let m = self.b.open();
            self.bump();
            self.b.close(m, "modifier");
        }
    }

    fn attribute_lists(&mut self) {
        while self.at("[") {
            self.attribute_list();
        }
    }

    fn attribute_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // [
        if self.peek().k == TK::Ident && self.peek_nth(1).1 == ":" && self.peek_nth(2).1 != ":" {
            let tm = self.b.open();
            self.bump();
            self.bump();
            self.b.close(tm, "attribute_target_specifier");
        }
        loop {
            if self.at("]") || self.peek().k == TK::Eof {
                break;
            }
            let am = self.b.open();
            let n = self.name_type();
            self.b.set_field(n, "name");
            if self.at("(") {
                let lm = self.b.open();
                self.bump();
                loop {
                    if self.at(")") || self.peek().k == TK::Eof {
                        break;
                    }
                    let argm = self.b.open();
                    if self.peek().k == TK::Ident && (self.peek_nth(1).1 == "=" || (self.peek_nth(1).1 == ":" && self.peek_nth(2).1 != ":")) {
                        let n = self.identifier();
                        self.b.set_field(n, "name");
                        self.bump();
                    }
                    self.expression();
                    self.b.close(argm, "attribute_argument");
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.expect(")");
                self.b.close(lm, "attribute_argument_list");
            }
            self.b.close(am, "attribute");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("]");
        self.b.close(m, "attribute_list")
    }

    fn declaration(&mut self) {
        let m = self.b.open();
        self.attribute_lists();
        self.modifiers();
        let w = self.peek_text();
        match w {
            "class" | "struct" | "interface" | "record" => self.type_declaration(m, w),
            "enum" => self.enum_declaration(m),
            "delegate" => self.delegate_declaration(m),
            "namespace" => self.namespace_declaration(m),
            _ => {
                self.member_rest(m);
            }
        }
    }

    fn namespace_declaration(&mut self, m: Marker) {
        self.bump();
        let n = self.name_type();
        self.b.set_field(n, "name");
        if self.at(";") {
            self.bump();
            self.b.close(m, "file_scoped_namespace_declaration");
            return;
        }
        let b = self.declaration_list();
        self.b.set_field(b, "body");
        if self.at(";") {
            self.bump();
        }
        self.b.close(m, "namespace_declaration");
    }

    fn declaration_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let before = self.peek().s;
            if self.at("using") {
                self.using_directive();
            } else {
                self.member();
            }
            if self.peek().s == before && !self.at("}") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.expect("}");
        self.b.close(m, "declaration_list")
    }

    fn type_declaration(&mut self, m: Marker, w: &str) {
        let kind = match w {
            "class" => "class_declaration",
            "struct" => "struct_declaration",
            "interface" => "interface_declaration",
            _ => "record_declaration",
        };
        self.bump();
        if w == "record" && (self.at("class") || self.at("struct")) {
            self.bump();
        }
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at("<") {
            self.type_parameter_list();
        }
        if self.at("(") {
            self.parameter_list();
        }
        if self.at(":") {
            let bm = self.b.open();
            self.bump();
            loop {
                let t = self.type_();
                if self.at("(") {
                    let pm = self.b.open_before(t);
                    self.argument_list();
                    self.b.close(pm, "primary_constructor_base_type");
                }
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.b.close(bm, "base_list");
        }
        while self.at("where") {
            self.constraints_clause();
        }
        if self.at("{") {
            let b = self.declaration_list();
            self.b.set_field(b, "body");
        }
        if self.at(";") {
            self.bump();
        }
        self.b.close(m, kind);
    }

    fn type_parameter_list(&mut self) {
        let m = self.b.open();
        self.bump(); // <
        loop {
            if self.at(">") || self.peek().k == TK::Eof {
                break;
            }
            let pm = self.b.open();
            self.attribute_lists();
            if self.at("in") || self.at("out") {
                self.bump();
            }
            let n = self.identifier();
            self.b.set_field(n, "name");
            self.b.close(pm, "type_parameter");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(">");
        self.b.close(m, "type_parameter_list");
    }

    fn constraints_clause(&mut self) {
        let m = self.b.open();
        self.bump(); // where
        self.identifier();
        self.expect(":");
        loop {
            let cm = self.b.open();
            let w = self.peek_text();
            match w {
                "class" | "struct" | "notnull" | "unmanaged" | "default" => {
                    self.bump();
                    if self.at("?") {
                        self.bump();
                    }
                }
                "new" if self.peek_nth(1).1 == "(" => {
                    let nm = self.b.open();
                    self.bump();
                    self.bump();
                    self.expect(")");
                    self.b.close(nm, "constructor_constraint");
                }
                _ => {
                    let t = self.type_();
                    self.b.set_field(t, "type");
                }
            }
            self.b.close(cm, "type_parameter_constraint");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.b.close(m, "type_parameter_constraints_clause");
    }

    fn enum_declaration(&mut self, m: Marker) {
        self.bump();
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at(":") {
            let bm = self.b.open();
            self.bump();
            self.type_();
            self.b.close(bm, "base_list");
        }
        let lm = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let em = self.b.open();
            self.attribute_lists();
            let n = self.identifier();
            self.b.set_field(n, "name");
            if self.at("=") {
                self.bump();
                let v = self.expression();
                self.b.set_field(v, "value");
            }
            self.b.close(em, "enum_member_declaration");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        let l = self.b.close(lm, "enum_member_declaration_list");
        self.b.set_field(l, "body");
        if self.at(";") {
            self.bump();
        }
        self.b.close(m, "enum_declaration");
    }

    fn delegate_declaration(&mut self, m: Marker) {
        self.bump();
        let t = self.type_();
        self.b.set_field(t, "type");
        let n = self.identifier();
        self.b.set_field(n, "name");
        if self.at("<") {
            self.type_parameter_list();
        }
        let p = self.parameter_list();
        self.b.set_field(p, "parameters");
        while self.at("where") {
            self.constraints_clause();
        }
        self.expect(";");
        self.b.close(m, "delegate_declaration");
    }

    fn member(&mut self) {
        let m = self.b.open();
        self.attribute_lists();
        self.modifiers();
        let w = self.peek_text();
        match w {
            "class" | "struct" | "interface" | "record" if !(w == "record" && self.peek_nth(1).1 == "(") => self.type_declaration(m, w),
            "enum" => self.enum_declaration(m),
            "delegate" => self.delegate_declaration(m),
            "namespace" => self.namespace_declaration(m),
            _ => self.member_rest(m),
        }
    }

    fn member_rest(&mut self, m: Marker) {
        let t = self.peek();
        let w = self.text(t);
        // destructor
        if w == "~" {
            self.bump();
            let n = self.identifier();
            self.b.set_field(n, "name");
            let p = self.parameter_list();
            self.b.set_field(p, "parameters");
            self.body_or_semicolon();
            self.b.close(m, "destructor_declaration");
            return;
        }
        if w == "event" {
            self.bump();
            let t = self.type_();
            if self.peek_nth(1).1 == "{" || (self.peek().k == TK::Ident && self.peek_nth(1).1 == ".") {
                self.b.set_field(t, "type");
                let n = self.identifier();
                self.b.set_field(n, "name");
                let a = self.accessor_list();
                self.b.set_field(a, "accessors");
                self.b.close(m, "event_declaration");
                return;
            }
            let vm = self.b.open_before(t);
            self.b.set_field(t, "type");
            self.variable_declarators();
            self.b.close(vm, "variable_declaration");
            self.expect(";");
            self.b.close(m, "event_field_declaration");
            return;
        }
        if w == "implicit" || w == "explicit" {
            self.bump();
            self.expect("operator");
            let t = self.type_();
            self.b.set_field(t, "type");
            let p = self.parameter_list();
            self.b.set_field(p, "parameters");
            self.body_or_semicolon();
            self.b.close(m, "conversion_operator_declaration");
            return;
        }
        // constructor: Identifier '('
        if t.k == TK::Ident && self.peek_nth(1).1 == "(" && !PREDEFINED.contains(&w) {
            let n = self.identifier();
            self.b.set_field(n, "name");
            let p = self.parameter_list();
            self.b.set_field(p, "parameters");
            if self.at(":") {
                let cm = self.b.open();
                self.bump();
                if self.at("base") || self.at("this") {
                    self.bump();
                }
                self.argument_list();
                self.b.close(cm, "constructor_initializer");
            }
            self.body_or_semicolon();
            self.b.close(m, "constructor_declaration");
            return;
        }
        // type then name
        let ty = self.type_();
        if self.at("operator") {
            self.b.set_field(ty, "type");
            self.bump();
            // operator token
            let t2 = self.peek();
            if t2.k == TK::Punct {
                if self.text(t2) == ">" && self.by.get(t2.e) == Some(&b'>') {
                    self.bump();
                    self.bump();
                } else {
                    self.bump();
                }
            } else {
                self.bump();
            }
            let p = self.parameter_list();
            self.b.set_field(p, "parameters");
            self.body_or_semicolon();
            self.b.close(m, "operator_declaration");
            return;
        }
        if self.at("this") {
            // indexer
            self.b.set_field(ty, "type");
            self.bump();
            let pm = self.b.open();
            self.bump(); // [
            self.parameters_until("]");
            self.expect("]");
            let p = self.b.close(pm, "bracketed_parameter_list");
            self.b.set_field(p, "parameters");
            if self.at("=>") {
                let a = self.arrow_clause();
                self.b.set_field(a, "value");
                self.expect(";");
            } else {
                let a = self.accessor_list();
                self.b.set_field(a, "accessors");
            }
            self.b.close(m, "indexer_declaration");
            return;
        }
        // explicit interface member: Type IFace.Name
        let t2 = self.peek();
        let (_, n1) = self.peek_nth(1);
        if t2.k == TK::Ident && n1 == "." {
            let em = self.b.open();
            self.name_type();
            self.expect(".");
            self.b.close(em, "explicit_interface_specifier");
        }
        let t2 = self.peek();
        let (_, n1) = self.peek_nth(1);
        if t2.k == TK::Ident && (n1 == "(" || n1 == "<") {
            // method
            self.b.set_field(ty, "returns");
            let n = self.identifier();
            self.b.set_field(n, "name");
            if self.at("<") {
                let st = self.b.last_child();
                let _ = st;
                self.type_parameter_list();
                if let Some(tp) = self.b.last_child() {
                    self.b.set_field(tp, "type_parameters");
                }
            }
            let p = self.parameter_list();
            self.b.set_field(p, "parameters");
            while self.at("where") {
                self.constraints_clause();
            }
            self.body_or_semicolon();
            self.b.close(m, "method_declaration");
            return;
        }
        if t2.k == TK::Ident && (n1 == "{" || n1 == "=>") {
            // property
            self.b.set_field(ty, "type");
            let n = self.identifier();
            self.b.set_field(n, "name");
            if self.at("=>") {
                let a = self.arrow_clause();
                self.b.set_field(a, "value");
                self.expect(";");
            } else {
                let a = self.accessor_list();
                self.b.set_field(a, "accessors");
                if self.at("=") {
                    self.bump();
                    let v = self.expression();
                    self.b.set_field(v, "value");
                    self.expect(";");
                }
            }
            self.b.close(m, "property_declaration");
            return;
        }
        // field
        let vm = self.b.open_before(ty);
        self.b.set_field(ty, "type");
        self.variable_declarators();
        self.b.close(vm, "variable_declaration");
        self.expect(";");
        self.b.close(m, "field_declaration");
    }

    fn arrow_clause(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // =>
        self.expression();
        self.b.close(m, "arrow_expression_clause")
    }

    fn body_or_semicolon(&mut self) {
        if self.at("{") {
            let b = self.block();
            self.b.set_field(b, "body");
        } else if self.at("=>") {
            let a = self.arrow_clause();
            self.b.set_field(a, "body");
            self.expect(";");
        } else {
            self.expect(";");
        }
    }

    fn accessor_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let am = self.b.open();
            self.attribute_lists();
            self.modifiers();
            let t = self.peek();
            if t.k == TK::Ident {
                self.bump();
            } else {
                self.b.missing("get", false);
            }
            if self.at("{") {
                let b = self.block();
                self.b.set_field(b, "body");
            } else if self.at("=>") {
                let a = self.arrow_clause();
                self.b.set_field(a, "body");
                self.expect(";");
            } else {
                self.expect(";");
            }
            self.b.close(am, "accessor_declaration");
        }
        self.expect("}");
        self.b.close(m, "accessor_list")
    }

    fn parameter_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("(");
        self.parameters_until(")");
        self.expect(")");
        self.b.close(m, "parameter_list")
    }

    fn parameters_until(&mut self, close: &str) {
        loop {
            if self.at(close) || self.peek().k == TK::Eof {
                break;
            }
            if self.at("params") {
                self.bump();
                let t = self.type_();
                self.b.set_field(t, "type");
                let n = self.identifier();
                self.b.set_field(n, "name");
            } else {
                let pm = self.b.open();
                self.attribute_lists();
                while matches!(self.peek_text(), "ref" | "out" | "in" | "this" | "scoped" | "readonly") && self.peek_nth(1).0 == TK::Ident {
                    let mm = self.b.open();
                    self.bump();
                    self.b.close(mm, "modifier");
                }
                // type name, or just name (lambda)
                let (_, n1) = self.peek_nth(1);
                if self.peek().k == TK::Ident && (n1 == "," || n1 == ")" || n1 == "=") && !PREDEFINED.contains(&self.peek_text()) {
                    let n = self.identifier();
                    self.b.set_field(n, "name");
                } else {
                    let t = self.type_();
                    self.b.set_field(t, "type");
                    let n = self.identifier();
                    self.b.set_field(n, "name");
                }
                if self.at("=") {
                    self.bump();
                    self.expression();
                }
                self.b.close(pm, "parameter");
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
    }

    fn variable_declarators(&mut self) {
        loop {
            let m = self.b.open();
            if self.at("(") {
                self.tuple_pattern();
            } else {
                let n = self.identifier();
                self.b.set_field(n, "name");
            }
            if self.at("[") {
                // fixed size buffer / array rank
                self.bracketed_argument_list();
            }
            if self.at("=") {
                self.bump();
                if self.at("{") {
                    self.initializer_expression();
                } else {
                    self.expression();
                }
            }
            self.b.close(m, "variable_declarator");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
    }

    fn tuple_pattern(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // (
        loop {
            if self.at(")") || self.peek().k == TK::Eof {
                break;
            }
            if self.at("(") {
                self.tuple_pattern();
            } else if self.at("_") {
                let d = self.b.open();
                self.bump();
                self.b.close(d, "discard");
            } else {
                let n = self.identifier();
                self.b.set_field(n, "name");
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(")");
        self.b.close(m, "tuple_pattern")
    }

    // ----------------------------------------------------------------- types
    fn name_type(&mut self) -> NodeId {
        let mut cur = self.simple_name();
        loop {
            if self.at("::") {
                let m = self.b.open_before(cur);
                self.bump();
                self.simple_name();
                cur = self.b.close(m, "alias_qualified_name");
                continue;
            }
            if self.at(".") && self.peek_nth(1).0 == TK::Ident {
                let m = self.b.open_before(cur);
                self.b.set_field(cur, "qualifier");
                self.bump();
                let n = self.simple_name();
                self.b.set_field(n, "name");
                cur = self.b.close(m, "qualified_name");
                continue;
            }
            break;
        }
        cur
    }

    fn simple_name(&mut self) -> NodeId {
        let id = self.identifier();
        if self.at("<") && self.is_type_args_ahead() {
            let m = self.b.open_before(id);
            self.type_argument_list();
            return self.b.close(m, "generic_name");
        }
        id
    }

    fn type_argument_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // <
        loop {
            if self.at(">") || self.at(",") && false || self.peek().k == TK::Eof {
                break;
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            self.type_();
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(">");
        self.b.close(m, "type_argument_list")
    }

    fn is_type_args_ahead(&mut self) -> bool {
        let st = self.save();
        let mut depth = 0i32;
        let mut cur = self.peek();
        let mut n = 0;
        let mut ok = false;
        loop {
            n += 1;
            if n > 500 || cur.k == TK::Eof {
                break;
            }
            let w = self.text(cur);
            match (cur.k, w) {
                (TK::Punct, "<") => depth += 1,
                (TK::Punct, ">") => {
                    depth -= 1;
                    if depth == 0 {
                        self.pos = cur.e;
                        self.skip_trivia(false);
                        let nx = self.lex();
                        let nw = self.text(nx);
                        ok = matches!(nw, "(" | ")" | "]" | "}" | ":" | ";" | "," | "." | "?" | "==" | "!=" | "|" | "^" | "&&" | "||" | "&" | "[" | ">" | "=" | "=>" | "{")
                            || nx.k == TK::Ident
                            || nx.k == TK::Eof;
                        break;
                    }
                }
                (TK::Punct, ",") | (TK::Punct, ".") | (TK::Punct, "?") | (TK::Punct, "[") | (TK::Punct, "]") | (TK::Punct, "::") | (TK::Punct, "*") => {}
                (TK::Punct, "(") | (TK::Punct, ")") => {}
                (TK::Ident, _) => {}
                _ => break,
            }
            self.pos = self.skip_tok(cur);
            self.skip_trivia(false);
            cur = self.lex();
        }
        self.restore(st);
        ok
    }

    fn type_(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.text(t);
        let mut ty = if t.k == TK::Ident && PREDEFINED.contains(&w) {
            self.bump_as("predefined_type", true)
        } else if t.k == TK::Ident && w == "var" && self.peek_nth(1).0 == TK::Ident {
            self.bump_as("implicit_type", true)
        } else if w == "(" {
            let m = self.b.open();
            self.bump();
            loop {
                if self.at(")") || self.peek().k == TK::Eof {
                    break;
                }
                let em = self.b.open();
                let et = self.type_();
                self.b.set_field(et, "type");
                if self.peek().k == TK::Ident {
                    let n = self.identifier();
                    self.b.set_field(n, "name");
                }
                self.b.close(em, "tuple_element");
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect(")");
            self.b.close(m, "tuple_type")
        } else if w == "ref" {
            let m = self.b.open();
            self.bump();
            if self.at("readonly") {
                self.bump();
            }
            let inner = self.type_();
            self.b.set_field(inner, "type");
            return self.b.close(m, "ref_type");
        } else if t.k == TK::Ident {
            self.name_type()
        } else {
            return self.b.missing("identifier", true);
        };
        loop {
            if self.at("?") && self.nullable_ok() {
                let m = self.b.open_before(ty);
                self.b.set_field(ty, "type");
                self.bump();
                ty = self.b.close(m, "nullable_type");
                continue;
            }
            if self.at("[") && matches!(self.peek_nth(1).1, "]" | ",") {
                let m = self.b.open_before(ty);
                self.b.set_field(ty, "type");
                let rm = self.b.open();
                self.bump();
                while self.at(",") {
                    self.bump();
                }
                self.expect("]");
                let r = self.b.close(rm, "array_rank_specifier");
                self.b.set_field(r, "rank");
                ty = self.b.close(m, "array_type");
                continue;
            }
            if self.at("*") && self.pointer_ok() {
                let m = self.b.open_before(ty);
                self.b.set_field(ty, "type");
                self.bump();
                ty = self.b.close(m, "pointer_type");
                continue;
            }
            break;
        }
        ty
    }

    fn nullable_ok(&mut self) -> bool {
        let (k1, n1) = self.peek_nth(1);
        k1 == TK::Ident || matches!(n1, ">" | "," | ")" | "]" | "[" | "?" | "=" | ";" | "{")
    }

    fn pointer_ok(&mut self) -> bool {
        let (k1, n1) = self.peek_nth(1);
        k1 == TK::Ident || matches!(n1, ">" | "," | ")" | "*")
    }
}
