    // ------------------------------------------------------------ statements
    fn block(&mut self) -> NodeId {
        let m = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let before = self.peek().s;
            self.statement();
            if self.peek().s == before && !self.at("}") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.expect("}");
        self.b.close(m, "block")
    }

    fn embedded_statement(&mut self) -> NodeId {
        self.statement();
        self.b.last_child().unwrap_or(0)
    }

    fn statement(&mut self) {
        let t = self.peek();
        let w = if matches!(t.k, TK::Ident | TK::Punct) { self.text(t) } else { "" };
        match w {
            "{" => {
                self.block();
            }
            ";" => {
                let m = self.b.open();
                self.bump();
                self.b.close(m, "empty_statement");
            }
            "if" => {
                let m = self.b.open();
                self.bump();
                self.expect("(");
                let c = self.expression();
                self.b.set_field(c, "condition");
                self.expect(")");
                let s = self.embedded_statement();
                self.b.set_field(s, "consequence");
                if self.at("else") {
                    self.bump();
                    let a = self.embedded_statement();
                    self.b.set_field(a, "alternative");
                }
                self.b.close(m, "if_statement");
            }
            "while" => {
                let m = self.b.open();
                self.bump();
                self.expect("(");
                let c = self.expression();
                self.b.set_field(c, "condition");
                self.expect(")");
                let b = self.embedded_statement();
                self.b.set_field(b, "body");
                self.b.close(m, "while_statement");
            }
            "do" => {
                let m = self.b.open();
                self.bump();
                let b = self.embedded_statement();
                self.b.set_field(b, "body");
                self.expect("while");
                self.expect("(");
                let c = self.expression();
                self.b.set_field(c, "condition");
                self.expect(")");
                self.expect(";");
                self.b.close(m, "do_statement");
            }
            "for" => self.for_statement(),
            "foreach" => {
                let m = self.b.open();
                self.bump();
                if self.at("await") {
                    self.bump();
                }
                self.expect("(");
                let ty = self.type_();
                self.b.set_field(ty, "type");
                let l = if self.at("(") { self.tuple_pattern() } else { self.identifier() };
                self.b.set_field(l, "left");
                self.expect("in");
                let r = self.expression();
                self.b.set_field(r, "right");
                self.expect(")");
                let b = self.embedded_statement();
                self.b.set_field(b, "body");
                self.b.close(m, "foreach_statement");
            }
            "switch" => self.switch_statement(),
            "try" => self.try_statement(),
            "return" => {
                let m = self.b.open();
                self.bump();
                if !self.at(";") {
                    self.expression();
                }
                self.expect(";");
                self.b.close(m, "return_statement");
            }
            "throw" => {
                let m = self.b.open();
                self.bump();
                if !self.at(";") {
                    self.expression();
                }
                self.expect(";");
                self.b.close(m, "throw_statement");
            }
            "break" | "continue" => {
                let m = self.b.open();
                self.bump();
                self.expect(";");
                self.b.close(m, if w == "break" { "break_statement" } else { "continue_statement" });
            }
            "goto" => {
                let m = self.b.open();
                self.bump();
                if self.at("case") {
                    self.bump();
                    self.expression();
                } else if self.at("default") {
                    self.bump();
                } else {
                    self.identifier();
                }
                self.expect(";");
                self.b.close(m, "goto_statement");
            }
            "yield" if matches!(self.peek_nth(1).1, "return" | "break") => {
                let m = self.b.open();
                self.bump();
                if self.at("return") {
                    self.bump();
                    self.expression();
                } else {
                    self.bump();
                }
                self.expect(";");
                self.b.close(m, "yield_statement");
            }
            "lock" => {
                let m = self.b.open();
                self.bump();
                self.expect("(");
                self.expression();
                self.expect(")");
                let b = self.embedded_statement();
                self.b.set_field(b, "body");
                self.b.close(m, "lock_statement");
            }
            "checked" | "unchecked" if self.peek_nth(1).1 == "{" => {
                let m = self.b.open();
                self.bump();
                self.block();
                self.b.close(m, "checked_statement");
            }
            "unsafe" if self.peek_nth(1).1 == "{" => {
                let m = self.b.open();
                self.bump();
                self.block();
                self.b.close(m, "unsafe_statement");
            }
            "fixed" => {
                let m = self.b.open();
                self.bump();
                self.expect("(");
                let vm = self.b.open();
                let ty = self.type_();
                self.b.set_field(ty, "type");
                self.variable_declarators();
                self.b.close(vm, "variable_declaration");
                self.expect(")");
                let b = self.embedded_statement();
                self.b.set_field(b, "body");
                self.b.close(m, "fixed_statement");
            }
            "using" if self.peek_nth(1).1 == "(" => {
                let m = self.b.open();
                self.bump();
                self.expect("(");
                if self.is_local_declaration() {
                    let vm = self.b.open();
                    let ty = self.type_();
                    self.b.set_field(ty, "type");
                    self.variable_declarators();
                    self.b.close(vm, "variable_declaration");
                } else {
                    self.expression();
                }
                self.expect(")");
                let b = self.embedded_statement();
                self.b.set_field(b, "body");
                self.b.close(m, "using_statement");
            }
            _ => {
                // labeled statement
                if t.k == TK::Ident && self.peek_nth(1).1 == ":" && self.peek_nth(2).1 != ":" && !KEYWORDS.contains(&w) {
                    let m = self.b.open();
                    self.identifier();
                    self.bump();
                    self.statement();
                    self.b.close(m, "labeled_statement");
                    return;
                }
                // local function / declaration
                let m = self.b.open();
                let mut has_mods = false;
                if self.at("using") || self.at("await") && self.peek_nth(1).1 == "using" {
                    if self.at("await") {
                        self.bump();
                    }
                    self.bump();
                    has_mods = true;
                }
                while matches!(self.peek_text(), "const" | "static" | "async" | "unsafe" | "extern" | "readonly" | "ref" | "scoped") && self.peek_nth(1).0 == TK::Ident {
                    let w2 = self.peek_text();
                    if w2 == "ref" || w2 == "scoped" || w2 == "readonly" {
                        break;
                    }
                    let mm = self.b.open();
                    self.bump();
                    self.b.close(mm, "modifier");
                    has_mods = true;
                }
                if self.is_local_function() {
                    let ty = self.type_();
                    self.b.set_field(ty, "type");
                    let n = self.identifier();
                    self.b.set_field(n, "name");
                    if self.at("<") {
                        self.type_parameter_list();
                        if let Some(tp) = self.b.last_child() {
                            self.b.set_field(tp, "type_parameters");
                        }
                    }
                    let p = self.parameter_list();
                    self.b.set_field(p, "parameters");
                    while self.at("where") {
                        self.constraints_clause();
                    }
                    self.body_or_semicolon();
                    self.b.close(m, "local_function_statement");
                    return;
                }
                if has_mods || self.is_local_declaration() {
                    let vm = self.b.open();
                    let ty = self.type_();
                    self.b.set_field(ty, "type");
                    self.variable_declarators();
                    self.b.close(vm, "variable_declaration");
                    self.expect(";");
                    self.b.close(m, "local_declaration_statement");
                    return;
                }
                self.expression();
                self.expect(";");
                self.b.close(m, "expression_statement");
            }
        }
    }

    /// Lookahead: does a type followed by an identifier (and then `=`, `;`, `,`, `in`, `)`) start here?
    fn is_local_declaration(&mut self) -> bool {
        let t = self.peek();
        if t.k != TK::Ident && !self.at("(") {
            return false;
        }
        let st = self.save();
        let m = self.b.open();
        let _ = self.type_();
        let t2 = self.peek();
        let mut ok = false;
        if t2.k == TK::Ident && !matches!(self.text(t2), "is" | "as" | "switch" | "when" | "and" | "or" | "with") {
            let (_, n1) = self.peek_nth(1);
            ok = matches!(n1, "=" | ";" | "," | "in" | ")" | "[");
        } else if self.at("(") && self.text(t) == "var" {
            ok = true;
        }
        self.b.abandon(m);
        self.restore(st);
        ok
    }

    fn is_local_function(&mut self) -> bool {
        let t = self.peek();
        if t.k != TK::Ident && !self.at("(") {
            return false;
        }
        let st = self.save();
        let m = self.b.open();
        let _ = self.type_();
        let t2 = self.peek();
        let mut ok = false;
        if t2.k == TK::Ident {
            let (_, n1) = self.peek_nth(1);
            ok = n1 == "(" || n1 == "<";
            if ok && n1 == "(" {
                // distinguish `Foo bar(...)` (local function) from call: need a type before
            }
        }
        self.b.abandon(m);
        self.restore(st);
        ok
    }

    fn for_statement(&mut self) {
        let m = self.b.open();
        self.bump();
        self.expect("(");
        if !self.at(";") {
            if self.is_local_declaration() {
                let vm = self.b.open();
                let ty = self.type_();
                self.b.set_field(ty, "type");
                self.variable_declarators();
                let v = self.b.close(vm, "variable_declaration");
                self.b.set_field(v, "initializer");
            } else {
                loop {
                    let e = self.expression();
                    self.b.set_field(e, "initializer");
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
            }
        }
        self.expect(";");
        if !self.at(";") {
            let c = self.expression();
            self.b.set_field(c, "condition");
        }
        self.expect(";");
        loop {
            if self.at(")") {
                break;
            }
            let u = self.expression();
            self.b.set_field(u, "update");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect(")");
        let b = self.embedded_statement();
        self.b.set_field(b, "body");
        self.b.close(m, "for_statement");
    }

    fn switch_statement(&mut self) {
        let m = self.b.open();
        self.bump();
        if self.at("(") {
            // tree-sitter: value is the inner expression (parens anonymous) unless tuple
            self.bump();
            let v = self.expression();
            self.b.set_field(v, "value");
            if self.at(",") {
                // tuple switch
                while self.at(",") {
                    self.bump();
                    self.expression();
                }
            }
            self.expect(")");
        } else {
            let v = self.expression();
            self.b.set_field(v, "value");
        }
        let bm = self.b.open();
        self.expect("{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let sm = self.b.open();
            let mut any_label = false;
            loop {
                if self.at("case") {
                    self.bump();
                    self.pattern();
                    if self.at("when") {
                        let wm = self.b.open();
                        self.bump();
                        self.expression();
                        self.b.close(wm, "when_clause");
                    }
                    self.expect(":");
                    any_label = true;
                } else if self.at("default") && self.peek_nth(1).1 == ":" {
                    self.bump();
                    self.bump();
                    any_label = true;
                } else {
                    break;
                }
            }
            if !any_label {
                self.b.abandon(sm);
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
                continue;
            }
            loop {
                if self.at("case") || (self.at("default") && self.peek_nth(1).1 == ":") || self.at("}") || self.peek().k == TK::Eof {
                    break;
                }
                let before = self.peek().s;
                self.statement();
                if self.peek().s == before {
                    break;
                }
            }
            self.b.close(sm, "switch_section");
        }
        self.expect("}");
        let b = self.b.close(bm, "switch_body");
        self.b.set_field(b, "body");
        self.b.close(m, "switch_statement");
    }

    fn try_statement(&mut self) {
        let m = self.b.open();
        self.bump();
        let b = self.block();
        self.b.set_field(b, "body");
        while self.at("catch") {
            let cm = self.b.open();
            self.bump();
            if self.at("(") {
                let dm = self.b.open();
                self.bump();
                let t = self.type_();
                self.b.set_field(t, "type");
                if self.peek().k == TK::Ident {
                    let n = self.identifier();
                    self.b.set_field(n, "name");
                }
                self.expect(")");
                self.b.close(dm, "catch_declaration");
            }
            if self.at("when") {
                let fm = self.b.open();
                self.bump();
                self.expect("(");
                self.expression();
                self.expect(")");
                self.b.close(fm, "catch_filter_clause");
            }
            let cb = self.block();
            self.b.set_field(cb, "body");
            self.b.close(cm, "catch_clause");
        }
        if self.at("finally") {
            let fm = self.b.open();
            self.bump();
            self.block();
            self.b.close(fm, "finally_clause");
        }
        self.b.close(m, "try_statement");
    }

    // -------------------------------------------------------------- patterns
    fn pattern(&mut self) -> NodeId {
        let left = self.pattern_unary();
        let mut cur = left;
        loop {
            if self.at("and") {
                let m = self.b.open_before(cur);
                self.b.set_field(cur, "left");
                self.bump();
                let r = self.pattern_unary();
                self.b.set_field(r, "right");
                cur = self.b.close(m, "and_pattern");
                continue;
            }
            if self.at("or") {
                let m = self.b.open_before(cur);
                self.b.set_field(cur, "left");
                self.bump();
                let r = self.pattern_unary();
                self.b.set_field(r, "right");
                cur = self.b.close(m, "or_pattern");
                continue;
            }
            break;
        }
        cur
    }

    fn pattern_unary(&mut self) -> NodeId {
        let w = self.peek_text();
        match w {
            "not" => {
                let m = self.b.open();
                self.bump();
                self.pattern_unary();
                self.b.close(m, "negated_pattern")
            }
            "<" | ">" | "<=" | ">=" => {
                let m = self.b.open();
                self.bump();
                self.binary(6);
                self.b.close(m, "relational_pattern")
            }
            "(" => {
                let m = self.b.open();
                self.bump();
                self.pattern();
                self.expect(")");
                self.b.close(m, "parenthesized_pattern")
            }
            "_" => {
                let m = self.b.open();
                self.bump();
                self.b.close(m, "discard")
            }
            "var" => {
                let m = self.b.open();
                self.bump();
                self.identifier();
                self.b.close(m, "var_pattern")
            }
            "[" => {
                let m = self.b.open();
                self.bump();
                loop {
                    if self.at("]") || self.peek().k == TK::Eof {
                        break;
                    }
                    self.pattern();
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.expect("]");
                self.b.close(m, "list_pattern")
            }
            "{" => {
                let m = self.b.open();
                self.property_pattern_clause();
                self.b.close(m, "recursive_pattern")
            }
            _ => {
                // type pattern / declaration pattern / constant pattern
                let t = self.peek();
                if t.k == TK::Ident && !matches!(w, "null" | "true" | "false") && self.looks_like_type_pattern() {
                    let m = self.b.open();
                    let ty = self.type_();
                    self.b.set_field(ty, "type");
                    if self.at("{") {
                        self.property_pattern_clause();
                        if self.peek().k == TK::Ident && !matches!(self.peek_text(), "when" | "and" | "or") {
                            self.identifier();
                        }
                        return self.b.close(m, "recursive_pattern");
                    }
                    if self.peek().k == TK::Ident && !matches!(self.peek_text(), "when" | "and" | "or") {
                        let n = self.identifier();
                        self.b.set_field(n, "name");
                        return self.b.close(m, "declaration_pattern");
                    }
                    self.b.abandon(m);
                    return ty;
                }
                let m = self.b.open();
                self.binary(6);
                self.b.close(m, "constant_pattern")
            }
        }
    }

    fn looks_like_type_pattern(&mut self) -> bool {
        let w = self.peek_text();
        if PREDEFINED.contains(&w) {
            return true;
        }
        let (k1, n1) = self.peek_nth(1);
        (k1 == TK::Ident && !matches!(n1, "when" | "and" | "or")) || n1 == "{"
    }

    fn property_pattern_clause(&mut self) {
        let m = self.b.open();
        self.bump(); // {
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let sm = self.b.open();
            if self.peek().k == TK::Ident && self.peek_nth(1).1 == ":" {
                self.identifier();
                self.bump();
            }
            self.pattern();
            self.b.close(sm, "subpattern");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        self.b.close(m, "property_pattern_clause");
    }

    // ----------------------------------------------------------- expressions
    fn expression(&mut self) -> NodeId {
        // lambda detection
        if self.is_lambda_ahead() {
            return self.lambda();
        }
        let left = self.conditional();
        let t = self.peek();
        if t.k == TK::Punct {
            let w = self.text(t);
            let is_shift_assign = w == ">" && self.by.get(t.e) == Some(&b'>') && self.by.get(t.e + 1) == Some(&b'=');
            if matches!(w, "=" | "+=" | "-=" | "*=" | "/=" | "%=" | "&=" | "|=" | "^=" | "<<=" | ">>>=" | "??=") || is_shift_assign {
                let m = self.b.open_before(left);
                self.b.set_field(left, "left");
                if is_shift_assign {
                    let id = self.b.leaf(">>=", false, t.s, t.s + 3);
                    self.pos = t.s + 3;
                    self.tok = None;
                    self.b.set_field(id, "operator");
                } else {
                    let o = self.bump();
                    self.b.set_field(o, "operator");
                }
                let r = self.expression();
                self.b.set_field(r, "right");
                return self.b.close(m, "assignment_expression");
            }
        }
        left
    }

    fn is_lambda_ahead(&mut self) -> bool {
        let t = self.peek();
        let w = self.text(t);
        if t.k == TK::Ident && (w == "async" || w == "static") && !matches!(self.peek_nth(1).1, "=" | ";" | ")" | ",") {
            let (k1, n1) = self.peek_nth(1);
            if (k1 == TK::Ident && self.peek_nth(2).1 == "=>") || n1 == "(" || n1 == "delegate" {
                return true;
            }
        }
        if t.k == TK::Ident && !KEYWORDS.contains(&w) && self.peek_nth(1).1 == "=>" {
            return true;
        }
        if w == "(" {
            // scan to matching ')' and check '=>'
            let st = self.save();
            let mut depth = 0i32;
            let mut cur = t;
            let mut n = 0;
            let mut res = false;
            loop {
                n += 1;
                if n > 5000 || cur.k == TK::Eof {
                    break;
                }
                let cw = self.text(cur);
                if cur.k == TK::Punct {
                    match cw {
                        "(" | "[" | "{" => depth += 1,
                        ")" | "]" | "}" => {
                            depth -= 1;
                            if depth == 0 {
                                self.pos = cur.e;
                                self.skip_trivia(false);
                                let nx = self.lex();
                                res = self.text(nx) == "=>";
                                break;
                            }
                        }
                        _ => {}
                    }
                }
                self.pos = self.skip_tok(cur);
                self.skip_trivia(false);
                cur = self.lex();
            }
            self.restore(st);
            return res;
        }
        false
    }

    fn lambda(&mut self) -> NodeId {
        let m = self.b.open();
        while self.at("async") || self.at("static") {
            let mm = self.b.open();
            self.bump();
            self.b.close(mm, "modifier");
        }
        if self.at("(") {
            let p = self.parameter_list();
            self.b.set_field(p, "parameters");
        } else {
            let p = self.bump_as("implicit_parameter", true);
            self.b.set_field(p, "parameters");
        }
        self.expect("=>");
        let b = if self.at("{") { self.block() } else { self.expression() };
        self.b.set_field(b, "body");
        self.b.close(m, "lambda_expression")
    }

    fn conditional(&mut self) -> NodeId {
        let c = self.binary(0);
        if self.at("?") {
            let m = self.b.open_before(c);
            self.b.set_field(c, "condition");
            self.bump();
            let a = self.expression();
            self.b.set_field(a, "consequence");
            self.expect(":");
            let b = self.expression();
            self.b.set_field(b, "alternative");
            return self.b.close(m, "conditional_expression");
        }
        c
    }

    fn binop(&mut self) -> Option<(&'static str, u8, usize)> {
        let t = self.peek();
        let w = self.text(t);
        if t.k == TK::Ident {
            return match w {
                "is" => Some(("is", 6, 2)),
                "as" => Some(("as", 6, 2)),
                "switch" => Some(("switch", 12, 6)),
                "with" => Some(("with", 12, 4)),
                _ => None,
            };
        }
        if t.k != TK::Punct {
            return None;
        }
        if w == ">" {
            let by = self.by;
            if by.get(t.e) == Some(&b'>') {
                if by.get(t.e + 1) == Some(&b'>') {
                    if by.get(t.e + 2) == Some(&b'=') {
                        return None;
                    }
                    return Some((">>>", 8, 3));
                }
                if by.get(t.e + 1) == Some(&b'=') {
                    return None;
                }
                return Some((">>", 8, 2));
            }
            if by.get(t.e) == Some(&b'=') {
                return Some((">=", 6, 2));
            }
            return Some((">", 6, 1));
        }
        Some(match w {
            "??" => ("??", 1, 2),
            "||" => ("||", 2, 2),
            "&&" => ("&&", 3, 2),
            "|" => ("|", 4, 1),
            "^" => ("^", 5, 1),
            "&" => ("&", 5, 1),
            "==" | "!=" => (intern(w), 5, 2),
            "<" | "<=" => (intern(w), 6, w.len()),
            "<<" => ("<<", 8, 2),
            "+" | "-" => (intern(w), 9, 1),
            "*" | "/" | "%" => (intern(w), 10, 1),
            ".." => ("..", 11, 2),
            _ => return None,
        })
    }

    fn binary(&mut self, min: u8) -> NodeId {
        let mut left = self.unary();
        loop {
            let (op, p, len) = match self.binop() {
                Some(x) => x,
                None => break,
            };
            // fix precedences: & is 7, ^ is 6, == is 5 in C#; use standard table
            let p = match op {
                "&" => 7,
                "^" => 6,
                "|" => 5,
                "==" | "!=" => 8,
                "<" | ">" | "<=" | ">=" | "is" | "as" => 9,
                "<<" | ">>" | ">>>" => 10,
                "+" | "-" => 11,
                "*" | "/" | "%" => 12,
                "switch" | "with" => 13,
                ".." => 14,
                _ => p,
            };
            if p < min {
                break;
            }
            match op {
                "is" => {
                    let m = self.b.open_before(left);
                    self.b.set_field(left, "expression");
                    self.bump();
                    let pat = self.pattern();
                    self.b.set_field(pat, "pattern");
                    left = self.b.close(m, "is_pattern_expression");
                    continue;
                }
                "as" => {
                    let m = self.b.open_before(left);
                    self.b.set_field(left, "left");
                    self.bump();
                    let t = self.type_();
                    self.b.set_field(t, "right");
                    left = self.b.close(m, "as_expression");
                    continue;
                }
                "switch" => {
                    let m = self.b.open_before(left);
                    self.bump();
                    self.expect("{");
                    loop {
                        if self.at("}") || self.peek().k == TK::Eof {
                            break;
                        }
                        let am = self.b.open();
                        self.pattern();
                        if self.at("when") {
                            let wm = self.b.open();
                            self.bump();
                            self.expression();
                            self.b.close(wm, "when_clause");
                        }
                        self.expect("=>");
                        self.expression();
                        self.b.close(am, "switch_expression_arm");
                        if self.at(",") {
                            self.bump();
                            continue;
                        }
                        break;
                    }
                    self.expect("}");
                    left = self.b.close(m, "switch_expression");
                    continue;
                }
                "with" => {
                    let m = self.b.open_before(left);
                    self.bump();
                    self.initializer_expression();
                    left = self.b.close(m, "with_expression");
                    continue;
                }
                ".." => {
                    let m = self.b.open_before(left);
                    self.bump();
                    if !matches!(self.peek_text(), "]" | ")" | ",") {
                        self.unary();
                    }
                    left = self.b.close(m, "range_expression");
                    continue;
                }
                _ => {}
            }
            let m = self.b.open_before(left);
            self.b.set_field(left, "left");
            let t = self.peek();
            let o = self.b.leaf(op, false, t.s, t.s + len);
            self.pos = t.s + len;
            self.tok = None;
            self.b.set_field(o, "operator");
            let right_assoc = op == "??";
            let r = self.binary(if right_assoc { p } else { p + 1 });
            self.b.set_field(r, "right");
            left = self.b.close(m, "binary_expression");
        }
        left
    }

    fn unary(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.text(t);
        if t.k == TK::Punct {
            match w {
                "!" | "~" | "-" | "+" | "++" | "--" | "&" | "*" | "^" => {
                    let m = self.b.open();
                    self.bump();
                    self.unary();
                    return self.b.close(m, "prefix_unary_expression");
                }
                ".." => {
                    let m = self.b.open();
                    self.bump();
                    if !matches!(self.peek_text(), "]" | ")" | ",") {
                        self.unary();
                    }
                    return self.b.close(m, "range_expression");
                }
                "(" => {
                    if self.is_cast() {
                        let m = self.b.open();
                        self.bump();
                        let ty = self.type_();
                        self.b.set_field(ty, "type");
                        self.expect(")");
                        let v = self.unary();
                        self.b.set_field(v, "value");
                        return self.b.close(m, "cast_expression");
                    }
                }
                _ => {}
            }
        }
        if t.k == TK::Ident && w == "await" && !matches!(self.peek_nth(1).1, ";" | ")" | "," | "=" | ".") {
            let m = self.b.open();
            self.bump();
            self.unary();
            return self.b.close(m, "await_expression");
        }
        if t.k == TK::Ident && w == "throw" {
            let m = self.b.open();
            self.bump();
            self.expression();
            return self.b.close(m, "throw_expression");
        }
        if t.k == TK::Ident && w == "ref" {
            let m = self.b.open();
            self.bump();
            self.unary();
            return self.b.close(m, "ref_expression");
        }
        let p = self.primary();
        self.postfix(p)
    }

    fn is_cast(&mut self) -> bool {
        let st = self.save();
        let m = self.b.open();
        self.bump(); // (
        let t = self.peek();
        let mut ok = false;
        if t.k == TK::Ident {
            let is_pre = PREDEFINED.contains(&self.text(t));
            self.type_();
            if self.at(")") {
                let (k1, n1) = self.peek_nth(1);
                ok = is_pre
                    || matches!(k1, TK::Ident | TK::Int | TK::Real | TK::Str | TK::Char)
                        && !matches!(n1, "is" | "as" | "switch" | "with" | "and" | "or" | "when")
                    || matches!(n1, "(" | "!" | "~");
            }
        }
        self.b.abandon(m);
        self.restore(st);
        ok
    }

    fn postfix(&mut self, mut e: NodeId) -> NodeId {
        loop {
            let t = self.peek();
            if t.k != TK::Punct {
                break;
            }
            let w = self.text(t);
            match w {
                "." | "->" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "expression");
                    self.bump();
                    let n = self.simple_name();
                    self.b.set_field(n, "name");
                    e = self.b.close(m, "member_access_expression");
                }
                "?." => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "condition");
                    self.bump();
                    let bm = self.b.open();
                    let n = self.simple_name();
                    self.b.set_field(n, "name");
                    self.b.close(bm, "member_binding_expression");
                    e = self.b.close(m, "conditional_access_expression");
                }
                "(" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "function");
                    let a = self.argument_list();
                    self.b.set_field(a, "arguments");
                    e = self.b.close(m, "invocation_expression");
                }
                "[" => {
                    let m = self.b.open_before(e);
                    self.b.set_field(e, "expression");
                    let a = self.bracketed_argument_list();
                    self.b.set_field(a, "subscript");
                    e = self.b.close(m, "element_access_expression");
                }
                "++" | "--" | "!" => {
                    if w == "!" && matches!(self.peek_nth(1).1, "=" | "(") {
                        // `!=` lexed separately or `!(`
                    }
                    let m = self.b.open_before(e);
                    self.bump();
                    e = self.b.close(m, "postfix_unary_expression");
                }
                "<" => {
                    // generic method call: f<T>(...)
                    if self.is_type_args_ahead() && matches!(self.b.kind(e), "identifier" | "member_access_expression") {
                        if self.b.kind(e) == "identifier" {
                            let m = self.b.open_before(e);
                            self.type_argument_list();
                            e = self.b.close(m, "generic_name");
                        } else {
                            // wrap the name part
                            let name = *self.b.nodes[e as usize].children.last().unwrap();
                            let ta = {
                                let st = self.b.nodes.len();
                                let _ = st;
                                let mm = self.b.open();
                                self.type_argument_list();
                                self.b.close(mm, "__tmp")
                            };
                            // splice: generic_name(name, type_argument_list)
                            let inner = self.b.nodes[ta as usize].children.clone();
                            let tal = inner[0];
                            let (s, en) = (self.b.nodes[name as usize].start, self.b.nodes[tal as usize].end);
                            let g = self.b.new_node("generic_name", true, s, en);
                            self.b.nodes[g as usize].children = vec![name, tal];
                            self.b.nodes[g as usize].field = Some("name");
                            self.b.nodes[name as usize].field = None;
                            let ch = &mut self.b.nodes[e as usize].children;
                            let last = ch.len() - 1;
                            ch[last] = g;
                            self.b.nodes[e as usize].end = en;
                            self.b.splice_child(ta, &[]);
                        }
                        continue;
                    }
                    break;
                }
                _ => break,
            }
        }
        e
    }

    fn argument_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // (
        self.arguments_until(")");
        self.expect(")");
        self.b.close(m, "argument_list")
    }

    fn bracketed_argument_list(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // [
        self.arguments_until("]");
        self.expect("]");
        self.b.close(m, "bracketed_argument_list")
    }

    fn arguments_until(&mut self, close: &str) {
        loop {
            if self.at(close) || self.peek().k == TK::Eof {
                break;
            }
            let am = self.b.open();
            if self.peek().k == TK::Ident && self.peek_nth(1).1 == ":" && self.peek_nth(2).1 != ":" {
                let n = self.identifier();
                self.b.set_field(n, "name");
                self.bump();
            }
            if matches!(self.peek_text(), "ref" | "out" | "in") {
                self.bump();
                if self.is_local_declaration_in_arg() {
                    let dm = self.b.open();
                    let ty = self.type_();
                    self.b.set_field(ty, "type");
                    let n = self.identifier();
                    self.b.set_field(n, "name");
                    self.b.close(dm, "declaration_expression");
                    self.b.close(am, "argument");
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
            }
            self.expression();
            self.b.close(am, "argument");
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
    }

    fn is_local_declaration_in_arg(&mut self) -> bool {
        let t = self.peek();
        if t.k != TK::Ident {
            return false;
        }
        let (k1, n1) = self.peek_nth(1);
        k1 == TK::Ident && (self.peek_nth(2).1 == ")" || self.peek_nth(2).1 == ",") || n1 == "<"
    }

    fn initializer_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // {
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            if self.at("{") {
                self.initializer_expression();
            } else {
                self.expression();
            }
            if self.at(",") {
                self.bump();
                continue;
            }
            break;
        }
        self.expect("}");
        self.b.close(m, "initializer_expression")
    }

    fn primary(&mut self) -> NodeId {
        let t = self.peek();
        match t.k {
            TK::Int => return self.bump_as("integer_literal", true),
            TK::Real => return self.bump_as("real_literal", true),
            TK::Str => return self.string_literal(),
            TK::Char => {
                let m = self.b.open();
                let by = self.by;
                self.b.leaf("'", false, t.s, t.s + 1);
                let inner_s = t.s + 1;
                let inner_e = if t.e > t.s + 1 && by[t.e - 1] == b'\'' { t.e - 1 } else { t.e };
                if inner_e > inner_s {
                    if by[inner_s] == b'\\' {
                        self.b.leaf("escape_sequence", true, inner_s, inner_e);
                    } else {
                        self.b.leaf("character_literal_content", true, inner_s, inner_e);
                    }
                }
                if inner_e < t.e {
                    self.b.leaf("'", false, inner_e, t.e);
                }
                self.pos = t.e;
                self.tok = None;
                return self.b.close(m, "character_literal");
            }
            TK::Eof => return self.b.missing("identifier", true),
            _ => {}
        }
        let w = self.text(t);
        match w {
            "(" => {
                let m = self.b.open();
                self.bump();
                let first = self.expression();
                let _ = first;
                if self.at(",") {
                    // tuple
                    let am = self.b.open_before(first);
                    self.b.close(am, "argument");
                    while self.at(",") {
                        self.bump();
                        let am2 = self.b.open();
                        if self.peek().k == TK::Ident && self.peek_nth(1).1 == ":" {
                            self.identifier();
                            self.bump();
                        }
                        self.expression();
                        self.b.close(am2, "argument");
                    }
                    self.expect(")");
                    return self.b.close(m, "tuple_expression");
                }
                self.expect(")");
                return self.b.close(m, "parenthesized_expression");
            }
            "new" => return self.new_expression(),
            "true" | "false" => return self.bump_as("boolean_literal", true),
            "null" => return self.bump_as("null_literal", true),
            "this" | "base" => {
                // anonymous keyword; member access will wrap it
                return self.bump();
            }
            "typeof" | "sizeof" => {
                let m = self.b.open();
                self.bump();
                self.expect("(");
                let ty = self.type_();
                self.b.set_field(ty, "type");
                self.expect(")");
                return self.b.close(m, if w == "typeof" { "typeof_expression" } else { "sizeof_expression" });
            }
            "default" => {
                let m = self.b.open();
                self.bump();
                if self.at("(") {
                    self.bump();
                    let ty = self.type_();
                    self.b.set_field(ty, "type");
                    self.expect(")");
                }
                return self.b.close(m, "default_expression");
            }
            "checked" | "unchecked" if self.peek_nth(1).1 == "(" => {
                let m = self.b.open();
                self.bump();
                self.bump();
                self.expression();
                self.expect(")");
                return self.b.close(m, "checked_expression");
            }
            "delegate" => {
                let m = self.b.open();
                self.bump();
                if self.at("(") {
                    let p = self.parameter_list();
                    self.b.set_field(p, "parameters");
                }
                self.block();
                return self.b.close(m, "anonymous_method_expression");
            }
            "stackalloc" => {
                let m = self.b.open();
                self.bump();
                if self.at("[") {
                    self.bump();
                    self.expect("]");
                    self.initializer_expression();
                    return self.b.close(m, "implicit_stackalloc_expression");
                }
                self.type_();
                if self.at("{") {
                    self.initializer_expression();
                }
                return self.b.close(m, "stackalloc_expression");
            }
            "[" => {
                // collection expression
                let m = self.b.open();
                self.bump();
                loop {
                    if self.at("]") || self.peek().k == TK::Eof {
                        break;
                    }
                    self.expression();
                    if self.at(",") {
                        self.bump();
                        continue;
                    }
                    break;
                }
                self.expect("]");
                return self.b.close(m, "collection_expression");
            }
            _ => {}
        }
        if t.k == TK::Ident {
            if PREDEFINED.contains(&w) {
                return self.bump_as("predefined_type", true);
            }
            return self.simple_name();
        }
        self.b.missing("identifier", true)
    }

    fn new_expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.bump(); // new
        if self.at("(") {
            self.argument_list();
            if self.at("{") {
                self.initializer_expression();
            }
            return self.b.close(m, "implicit_object_creation_expression");
        }
        if self.at("{") {
            // anonymous object
            self.bump();
            loop {
                if self.at("}") || self.peek().k == TK::Eof {
                    break;
                }
                if self.peek().k == TK::Ident && self.peek_nth(1).1 == "=" {
                    self.identifier();
                    self.bump();
                }
                self.expression();
                if self.at(",") {
                    self.bump();
                    continue;
                }
                break;
            }
            self.expect("}");
            return self.b.close(m, "anonymous_object_creation_expression");
        }
        if self.at("[") {
            self.bump();
            while self.at(",") {
                self.bump();
            }
            self.expect("]");
            self.initializer_expression();
            return self.b.close(m, "implicit_array_creation_expression");
        }
        // type
        let ty = self.type_no_array();
        if self.at("[") {
            // array creation: new int[5] { } / new int[] { }
            let am = self.b.open_before(ty);
            self.b.set_field(ty, "type");
            let rm = self.b.open();
            self.bump();
            while !self.at("]") && self.peek().k != TK::Eof {
                if self.at(",") {
                    self.bump();
                    continue;
                }
                self.expression();
            }
            self.expect("]");
            let r = self.b.close(rm, "array_rank_specifier");
            self.b.set_field(r, "rank");
            let at = self.b.close(am, "array_type");
            self.b.set_field(at, "type");
            if self.at("{") {
                self.initializer_expression();
            }
            return self.b.close(m, "array_creation_expression");
        }
        self.b.set_field(ty, "type");
        if self.at("(") {
            let a = self.argument_list();
            self.b.set_field(a, "arguments");
        }
        if self.at("{") {
            let i = self.initializer_expression();
            self.b.set_field(i, "initializer");
        }
        self.b.close(m, "object_creation_expression")
    }

    fn type_no_array(&mut self) -> NodeId {
        let t = self.peek();
        let w = self.text(t);
        let mut ty = if t.k == TK::Ident && PREDEFINED.contains(&w) {
            self.bump_as("predefined_type", true)
        } else {
            self.name_type()
        };
        if self.at("?") {
            let m = self.b.open_before(ty);
            self.b.set_field(ty, "type");
            self.bump();
            ty = self.b.close(m, "nullable_type");
        }
        ty
    }

    fn string_end(&self, s: usize) -> (usize, bool, bool, usize) {
        // returns (end, verbatim, interpolated, prefix_len)
        let by = self.by;
        let mut i = s;
        let mut verbatim = false;
        let mut interp = false;
        while i < by.len() && (by[i] == b'@' || by[i] == b'$') {
            if by[i] == b'@' {
                verbatim = true;
            } else {
                interp = true;
            }
            i += 1;
        }
        let prefix = i - s;
        // raw string
        let mut q = 0;
        while i + q < by.len() && by[i + q] == b'"' {
            q += 1;
        }
        if q >= 3 {
            let mut j = i + q;
            loop {
                if j >= by.len() {
                    return (by.len(), verbatim, interp, prefix);
                }
                if by[j] == b'"' {
                    let mut k = 0;
                    while j + k < by.len() && by[j + k] == b'"' {
                        k += 1;
                    }
                    if k >= q {
                        return (j + k, verbatim, interp, prefix);
                    }
                    j += k;
                    continue;
                }
                j += 1;
            }
        }
        i += 1;
        let mut depth = 0;
        while i < by.len() {
            let c = by[i];
            if interp && c == b'{' {
                if by.get(i + 1) == Some(&b'{') && depth == 0 {
                    i += 2;
                    continue;
                }
                depth += 1;
            } else if interp && c == b'}' && depth > 0 {
                depth -= 1;
            } else if depth == 0 {
                if verbatim {
                    if c == b'"' {
                        if by.get(i + 1) == Some(&b'"') {
                            i += 2;
                            continue;
                        }
                        return (i + 1, verbatim, interp, prefix);
                    }
                } else {
                    if c == b'\\' {
                        i += 2;
                        continue;
                    }
                    if c == b'"' || c == b'\n' {
                        return (i + 1, verbatim, interp, prefix);
                    }
                }
            }
            i += 1;
        }
        (by.len(), verbatim, interp, prefix)
    }

