        let s = t.s;
        let (end, verbatim, interp, prefix) = self.string_end(s);
        let by = self.by;
        let qs = s + prefix;
        let mut q = 0;
        while qs + q < by.len() && by[qs + q] == b'"' && q < 3 {
            q += 1;
        }
