            let m = self.b.open();
            let mut qq = 0;
            while qs + qq < by.len() && by[qs + qq] == b'"' {
                qq += 1;
            }
            self.b.leaf("raw_string_start", true, s, qs + qq);
            let ce = end.saturating_sub(qq).max(qs + qq);
            self.b.leaf("raw_string_content", true, qs + qq, ce);
            self.b.leaf("raw_string_end", true, ce, end);
            self.pos = end;
            self.tok = None;
            return self.b.close(m, "raw_string_literal");
