                self.b.close(im, "interpolation");
                i = j;
                continue;
            }
            if cs.is_none() {
                cs = Some(i);
            }
            i += 1;
        }
        if let Some(st) = cs.take() {
            self.b.leaf("string_content", true, st, close);
        }
        if close < end {
            self.b.leaf("\"", false, close, end);
        }
        self.pos = end;
        self.tok = None;
        self.b.close(m, "interpolated_string_expression")
    }
}
