//! HCL parser producing tree-sitter-hcl compatible trees.

use super::python::intern;
use crate::ts::builder::Builder;
use crate::ts::{NodeId, Tree};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK {
    Ident,
    Num,
    Str,
    Heredoc,
    Punct,
    Eof,
    Err,
}

#[derive(Clone, Copy, Debug)]
struct Tok {
    k: TK,
    s: usize,
    e: usize,
}

const PUNCTS: &[&str] = &[
    "...", "[*]", "=>", "==", "!=", ">=", "<=", "&&", "||", ".*", "=", ":", "{", "}", "[", "]",
    "(", ")", ",", ".", "?", "!", "-", "+", "*", "/", "%", ">", "<",
];

pub struct Hcl<'a> {
    src: &'a str,
    by: &'a [u8],
    b: Builder,
    pos: usize,
    tok: Option<Tok>,
}

pub fn parse(src: &str) -> Tree {
    let mut p = Hcl { src, by: src.as_bytes(), b: Builder::new(), pos: 0, tok: None };
    p.config_file();
    p.b.finish("config_file", src.len())
}

fn is_id_start(c: char) -> bool {
    c == '_' || c.is_alphabetic()
}
fn is_id_cont(c: char) -> bool {
    c == '_' || c == '-' || c.is_alphanumeric()
}

impl<'a> Hcl<'a> {
    fn ch(&self, i: usize) -> Option<char> {
        self.src.get(i..).and_then(|s| s.chars().next())
    }
    fn text(&self, t: Tok) -> &'a str {
        &self.src[t.s..t.e]
    }

    fn skip_trivia(&mut self) {
        let by = self.by;
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return,
            };
            if c.is_whitespace() {
                self.pos += c.len_utf8();
                continue;
            }
            if c == '#' || (c == '/' && by.get(self.pos + 1) == Some(&b'/')) {
                let s = self.pos;
                let mut e = s;
                while e < by.len() && by[e] != b'\n' {
                    e += 1;
                }
                let mut ce = e;
                if ce > s && by[ce - 1] == b'\r' {
                    ce -= 1;
                }
                self.b.extra("comment", s, ce);
                self.pos = e;
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'*') {
                let s = self.pos;
                let mut i = s + 2;
                while i + 1 < by.len() && !(by[i] == b'*' && by[i + 1] == b'/') {
                    i += 1;
                }
                let e = if i + 1 < by.len() { i + 2 } else { by.len() };
                self.b.extra("comment", s, e);
                self.pos = e;
                continue;
            }
            return;
        }
    }

    fn lex(&mut self) -> Tok {
        let s = self.pos;
        let by = self.by;
        let c = match self.ch(s) {
            None => return Tok { k: TK::Eof, s, e: s },
            Some(c) => c,
        };
        if c == '"' {
            return Tok { k: TK::Str, s, e: s };
        }
        if c == '<' && by.get(s + 1) == Some(&b'<') {
            return Tok { k: TK::Heredoc, s, e: s };
        }
        if is_id_start(c) {
            let mut e = s;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            return Tok { k: TK::Ident, s, e };
        }
        if c.is_ascii_digit() {
            let mut e = s;
            while e < by.len() && by[e].is_ascii_digit() {
                e += 1;
            }
            if e < by.len() && by[e] == b'.' && by.get(e + 1).map(|b| b.is_ascii_digit()).unwrap_or(false) {
                e += 1;
                while e < by.len() && by[e].is_ascii_digit() {
                    e += 1;
                }
            }
            if e < by.len() && (by[e] == b'e' || by[e] == b'E') {
                let mut f = e + 1;
                if f < by.len() && (by[f] == b'+' || by[f] == b'-') {
                    f += 1;
                }
                if f < by.len() && by[f].is_ascii_digit() {
                    e = f;
                    while e < by.len() && by[e].is_ascii_digit() {
                        e += 1;
                    }
                }
            }
            return Tok { k: TK::Num, s, e };
        }
        for p in PUNCTS {
            if self.src[s..].starts_with(p) {
                return Tok { k: TK::Punct, s, e: s + p.len() };
            }
        }
        Tok { k: TK::Err, s, e: s + c.len_utf8() }
    }

    fn peek(&mut self) -> Tok {
        if let Some(t) = self.tok {
            return t;
        }
        self.skip_trivia();
        let t = self.lex();
        self.tok = Some(t);
        t
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        matches!(t.k, TK::Punct | TK::Ident) && self.text(t) == s
    }

    fn bump_as(&mut self, kind: &'static str, named: bool) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        id
    }

    fn bump(&mut self) -> NodeId {
        let t = self.peek();
        let k = intern(self.text(t));
        self.bump_as(k, false)
    }

    fn expect(&mut self, s: &str) {
        if self.at(s) {
            self.bump();
        } else {
            self.b.missing(intern(s), false);
        }
    }

    fn wrap_leaf(&mut self, kind: &'static str, tok: &'static str) -> NodeId {
        // named node containing a single anonymous token
        let m = self.b.open();
        let t = self.peek();
        self.b.leaf(tok, false, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        self.b.close(m, kind)
    }

    fn peek_nth_text(&mut self, n: usize) -> &'a str {
        let save_pos = self.pos;
        let save_tok = self.tok;
        let save_nodes = self.b.nodes.len();
        let save_pending = self.b.pending_count();
        let mut cur = self.peek();
        for _ in 0..n {
            self.pos = cur.e;
            self.tok = None;
            cur = self.peek();
        }
        let r = self.text(cur);
        self.pos = save_pos;
        self.tok = save_tok;
        self.b.truncate_pending(save_pending);
        self.b.nodes.truncate(save_nodes);
        r
    }

    // ------------------------------------------------------------------ body
    fn config_file(&mut self) {
        let t = self.peek();
        if t.k == TK::Eof {
            return;
        }
        if self.at("{") {
            self.object();
            return;
        }
        self.body(true);
    }

    fn body(&mut self, top: bool) -> NodeId {
        let m = self.b.open();
        loop {
            let t = self.peek();
            if t.k == TK::Eof || (!top && self.at("}")) {
                break;
            }
            if t.k == TK::Ident {
                let n1 = self.peek_nth_text(1);
                if n1 == "=" {
                    self.attribute();
                } else {
                    self.block();
                }
            } else {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.b.close(m, "body")
    }

    fn attribute(&mut self) {
        let m = self.b.open();
        self.bump_as("identifier", true);
        self.expect("=");
        self.expression();
        self.b.close(m, "attribute");
    }

    fn block(&mut self) {
        let m = self.b.open();
        self.bump_as("identifier", true);
        loop {
            let t = self.peek();
            match t.k {
                TK::Str => {
                    self.string_like(true);
                }
                TK::Ident => {
                    self.bump_as("identifier", true);
                }
                _ => break,
            }
        }
        if self.at("{") {
            self.wrap_leaf("block_start", "{");
            if !self.at("}") {
                self.body(false);
            }
            if self.at("}") {
                self.wrap_leaf("block_end", "}");
            } else {
                self.b.missing("block_end", true);
            }
        } else {
            self.b.missing("block_start", true);
        }
        self.b.close(m, "block");
    }

    // ----------------------------------------------------------- expressions
    fn expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.expr_inner();
        self.b.close(m, "expression")
    }

    /// Parses conditional / operation / term into the currently open `expression` node.
    fn expr_inner(&mut self) {
        // operation or term
        let start_children = self.b.current_children().len();
        let is_op = self.operation(0);
        let _ = start_children;
        let _ = is_op;
        if self.at("?") {
            // conditional: wrap what we have into an expression
            let ch: Vec<NodeId> = self.b.current_children().to_vec();
            let first = ch[0];
            let cm = self.b.open_before(first);
            let em = self.b.open_before(first);
            let _ = em;
            // close inner expression containing all previous children
            self.b.close(em, "expression");
            self.bump();
            self.expression();
            self.expect(":");
            self.expression();
            self.b.close(cm, "conditional");
        }
    }

    fn binop_prec(&mut self) -> Option<u8> {
        let t = self.peek();
        if t.k != TK::Punct {
            return None;
        }
        Some(match self.text(t) {
            "*" | "/" | "%" => 6,
            "+" | "-" => 5,
            ">" | ">=" | "<" | "<=" => 4,
            "==" | "!=" => 3,
            "&&" => 2,
            "||" => 1,
            _ => return None,
        })
    }

    /// Parse an operation or a term; returns true if an operation node was created.
    fn operation(&mut self, min: u8) -> bool {
        let first_idx = self.b.current_children().len();
        // unary
        let mut is_op = false;
        if self.at("-") || self.at("!") {
            let om = self.b.open();
            let um = self.b.open();
            self.bump();
            self.term();
            self.b.close(um, "unary_operation");
            self.b.close(om, "operation");
            is_op = true;
        } else {
            self.term();
        }
        loop {
            let p = match self.binop_prec() {
                Some(p) => p,
                None => break,
            };
            if p < min {
                break;
            }
            let ch: Vec<NodeId> = self.b.current_children().to_vec();
            let first = ch[first_idx];
            let om = self.b.open_before(first);
            let bm = self.b.open_before(first);
            let _ = om;
            self.bump();
            // right operand: higher precedence operation or term
            let save_len = self.b.current_children().len();
            let right_is_op = self.operation(p + 1);
            let _ = (save_len, right_is_op);
            self.b.close(bm, "binary_operation");
            self.b.close(om, "operation");
            is_op = true;
        }
        is_op
    }

    /// Parse an expression term (with postfix chains) into the current node.
    fn term(&mut self) {
        let t = self.peek();
        match t.k {
            TK::Num => {
                let m = self.b.open();
                self.bump_as("numeric_lit", true);
                self.b.close(m, "literal_value");
            }
            TK::Str => {
                self.string_like(false);
            }
            TK::Heredoc => {
                self.heredoc();
            }
            TK::Ident => {
                let w = self.text(t);
                match w {
                    "true" | "false" => {
                        let m = self.b.open();
                        self.wrap_leaf("bool_lit", if w == "true" { "true" } else { "false" });
                        self.b.close(m, "literal_value");
                    }
                    "null" => {
                        let m = self.b.open();
                        self.wrap_leaf("null_lit", "null");
                        self.b.close(m, "literal_value");
                    }
                    _ => {
                        if self.peek_nth_text(1) == "(" {
                            let m = self.b.open();
                            self.bump_as("identifier", true);
                            self.bump(); // (
                            if !self.at(")") {
                                let am = self.b.open();
                                loop {
                                    self.expression();
                                    if self.at(",") {
                                        self.bump();
                                        if self.at(")") {
                                            break;
                                        }
                                        continue;
                                    }
                                    if self.at("...") {
                                        let em = self.b.open();
                                        self.bump();
                                        self.b.close(em, "ellipsis");
                                    }
                                    break;
                                }
                                self.b.close(am, "function_arguments");
                            }
                            self.expect(")");
                            self.b.close(m, "function_call");
                        } else {
                            let m = self.b.open();
                            self.bump_as("identifier", true);
                            self.b.close(m, "variable_expr");
                        }
                    }
                }
            }
            TK::Punct => match self.text(t) {
                "[" => {
                    if self.peek_nth_text(1) == "for" {
                        self.for_expr(true);
                    } else {
                        let cm = self.b.open();
                        let tm = self.b.open();
                        self.wrap_leaf("tuple_start", "[");
                        loop {
                            if self.at("]") || self.peek().k == TK::Eof {
                                break;
                            }
                            self.expression();
                            if self.at(",") {
                                self.bump();
                                continue;
                            }
                            break;
                        }
                        if self.at("]") {
                            self.wrap_leaf("tuple_end", "]");
                        } else {
                            self.b.missing("tuple_end", true);
                        }
                        self.b.close(tm, "tuple");
                        self.b.close(cm, "collection_value");
                    }
                }
                "{" => {
                    if self.peek_nth_text(1) == "for" {
                        self.for_expr(false);
                    } else {
                        let cm = self.b.open();
                        self.object();
                        self.b.close(cm, "collection_value");
                    }
                }
                "(" => {
                    self.bump();
                    self.expression();
                    self.expect(")");
                }
                _ => {
                    let m = self.b.open();
                    self.bump();
                    self.b.close(m, "ERROR");
                    return;
                }
            },
            _ => {
                self.b.missing("identifier", true);
                return;
            }
        }
        self.postfix();
    }

    fn postfix(&mut self) {
        loop {
            if self.at(".") {
                // get_attr or legacy index
                let save = self.pos;
                let _ = save;
                let t = self.peek();
                let by = self.by;
                let next = by.get(t.e).copied();
                if next.map(|b| b.is_ascii_digit()).unwrap_or(false) {
                    let im = self.b.open();
                    let lm = self.b.open();
                    self.bump();
                    self.bump_as("numeric_lit", false);
                    self.b.close(lm, "legacy_index");
                    self.b.close(im, "index");
                    continue;
                }
                let m = self.b.open();
                self.bump();
                let t2 = self.peek();
                if t2.k == TK::Ident {
                    self.bump_as("identifier", true);
                } else {
                    self.b.missing("identifier", true);
                }
                self.b.close(m, "get_attr");
                continue;
            }
            if self.at(".*") || self.at("[*]") {
                let full = self.at("[*]");
                let sm = self.b.open();
                let km = self.b.open();
                self.bump();
                loop {
                    if self.at(".") {
                        let by = self.by;
                        let t = self.peek();
                        if by.get(t.e).map(|b| b.is_ascii_digit()).unwrap_or(false) {
                            break;
                        }
                        let m = self.b.open();
                        self.bump();
                        self.bump_as("identifier", true);
                        self.b.close(m, "get_attr");
                        continue;
                    }
                    if full && self.at("[") {
                        let im = self.b.open();
                        let nm = self.b.open();
                        self.bump();
                        self.expression();
                        self.expect("]");
                        self.b.close(nm, "new_index");
                        self.b.close(im, "index");
                        continue;
                    }
                    break;
                }
                self.b.close(km, if full { "full_splat" } else { "attr_splat" });
                self.b.close(sm, "splat");
                continue;
            }
            if self.at("[") {
                let im = self.b.open();
                let nm = self.b.open();
                self.bump();
                self.expression();
                self.expect("]");
                self.b.close(nm, "new_index");
                self.b.close(im, "index");
                continue;
            }
            break;
        }
    }

    fn object(&mut self) {
        let om = self.b.open();
        self.wrap_leaf("object_start", "{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let em = self.b.open();
            let k = self.expression();
            self.b.set_field(k, "key");
            if self.at("=") || self.at(":") {
                self.bump();
            } else {
                self.b.missing("=", false);
            }
            let v = self.expression();
            self.b.set_field(v, "val");
            self.b.close(em, "object_elem");
            if self.at(",") {
                self.bump();
            }
        }
        if self.at("}") {
            self.wrap_leaf("object_end", "}");
        } else {
            self.b.missing("object_end", true);
        }
        self.b.close(om, "object");
    }

    fn for_expr(&mut self, tuple: bool) {
        let fm = self.b.open();
        let m = self.b.open();
        if tuple {
            self.wrap_leaf("tuple_start", "[");
        } else {
            self.wrap_leaf("object_start", "{");
        }
        // for intro
        let im = self.b.open();
        self.bump(); // for
        self.bump_as("identifier", true);
        if self.at(",") {
            self.bump();
            self.bump_as("identifier", true);
        }
        self.expect("in");
        self.expression();
        self.expect(":");
        self.b.close(im, "for_intro");
        self.expression();
        if !tuple {
            self.expect("=>");
            self.expression();
            if self.at("...") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ellipsis");
            }
        }
        if self.at("if") {
            let cm = self.b.open();
            self.bump();
            self.expression();
            self.b.close(cm, "for_cond");
        }
        if tuple {
            if self.at("]") {
                self.wrap_leaf("tuple_end", "]");
            }
            self.b.close(m, "for_tuple_expr");
        } else {
            if self.at("}") {
                self.wrap_leaf("object_end", "}");
            }
            self.b.close(m, "for_object_expr");
        }
        self.b.close(fm, "for_expr");
    }

    /// Parse a quoted string. If `label` (block label), always string_lit.
    fn string_like(&mut self, label: bool) {
        let t = self.peek();
        let s = t.s;
        let by = self.by;
        // determine if it contains template interpolation/directive
        let mut i = s + 1;
        let mut has_template = false;
        while i < by.len() && by[i] != b'"' && by[i] != b'\n' {
            if by[i] == b'\\' {
                i += 2;
                continue;
            }
            if (by[i] == b'$' || by[i] == b'%') && by.get(i + 1) == Some(&b'{') {
                if by.get(i + 2) == Some(&by[i]) {
                    // escaped $${ / %%{
                } else {
                    has_template = true;
                    break;
                }
            }
            i += 1;
        }
        if label || !has_template {
            let lm = if label { None } else { Some(self.b.open()) };
            let m = self.b.open();
            self.b.leaf("quoted_template_start", true, s, s + 1);
            let mut j = s + 1;
            while j < by.len() && by[j] != b'"' && by[j] != b'\n' {
                if by[j] == b'\\' {
                    j += 1;
                }
                j += 1;
            }
            let j = j.min(by.len());
            if j > s + 1 {
                self.b.leaf("template_literal", true, s + 1, j);
            }
            if j < by.len() && by[j] == b'"' {
                self.b.leaf("quoted_template_end", true, j, j + 1);
                self.pos = j + 1;
            } else {
                self.b.missing("quoted_template_end", true);
                self.pos = j;
            }
            self.tok = None;
            self.b.close(m, "string_lit");
            if let Some(lm) = lm {
                self.b.close(lm, "literal_value");
            }
            return;
        }
        let tm = self.b.open();
        let qm = self.b.open();
        self.b.leaf("quoted_template_start", true, s, s + 1);
        self.pos = s + 1;
        self.tok = None;
        let end = self.template_parts(b'"', None);
        if end < by.len() && by[end] == b'"' {
            self.b.leaf("quoted_template_end", true, end, end + 1);
            self.pos = end + 1;
        } else {
            self.b.missing("quoted_template_end", true);
            self.pos = end;
        }
        self.tok = None;
        self.b.close(qm, "quoted_template");
        self.b.close(tm, "template_expr");
    }

    /// Parse template parts from self.pos until the terminator; returns end position.
    fn template_parts(&mut self, quote: u8, heredoc_end: Option<(&str, bool)>) -> usize {
        let by = self.by;
        let mut i = self.pos;
        let mut lit_start: Option<usize> = None;
        loop {
            if i >= by.len() {
                break;
            }
            if let Some((ident, indent)) = heredoc_end {
                // at line start: check closing identifier
                if i == 0 || by[i - 1] == b'\n' {
                    let mut j = i;
                    if indent {
                        while j < by.len() && (by[j] == b' ' || by[j] == b'\t') {
                            j += 1;
                        }
                    }
                    if self.src[j..].starts_with(ident) {
                        let after = j + ident.len();
                        if after >= by.len() || by[after] == b'\n' || by[after] == b'\r' {
                            if let Some(ls) = lit_start.take() {
                                self.b.leaf("template_literal", true, ls, i);
                            }
                            return j;
                        }
                    }
                }
            } else if by[i] == quote || by[i] == b'\n' {
                break;
            }
            if by[i] == b'\\' && heredoc_end.is_none() {
                if lit_start.is_none() {
                    lit_start = Some(i);
                }
                i += 2;
                continue;
            }
            if (by[i] == b'$' || by[i] == b'%') && by.get(i + 1) == Some(&b'{') && by.get(i + 2) != Some(&by[i]) {
                if let Some(ls) = lit_start.take() {
                    self.b.leaf("template_literal", true, ls, i);
                }
                let is_directive = by[i] == b'%';
                self.pos = i;
                self.tok = None;
                if is_directive {
                    self.template_directive();
                } else {
                    let m = self.b.open();
                    self.b.leaf("template_interpolation_start", true, i, i + 2);
                    self.pos = i + 2;
                    self.tok = None;
                    if self.at("~") {
                        let sm = self.b.open();
                        self.bump();
                        self.b.close(sm, "strip_marker");
                    }
                    if !self.at("}") {
                        self.expression();
                    }
                    if self.at("~") {
                        let sm = self.b.open();
                        self.bump();
                        self.b.close(sm, "strip_marker");
                    }
                    let t = self.peek();
                    if self.text(t) == "}" {
                        self.b.leaf("template_interpolation_end", true, t.s, t.e);
                        self.pos = t.e;
                    } else {
                        self.b.missing("template_interpolation_end", true);
                    }
                    self.tok = None;
                    self.b.close(m, "template_interpolation");
                }
                i = self.pos;
                continue;
            }
            if lit_start.is_none() {
                lit_start = Some(i);
            }
            i += 1;
        }
        if let Some(ls) = lit_start.take() {
            if i > ls {
                self.b.leaf("template_literal", true, ls, i);
            }
        }
        i
    }

    fn template_directive(&mut self) {
        // %{ if cond } ... %{ else } ... %{ endif }  /  %{ for x in y } ... %{ endfor }
        let dm = self.b.open();
        let by = self.by;
        let s = self.pos;
        let mut j = s + 2;
        while j < by.len() && (by[j] == b' ' || by[j] == b'~') {
            j += 1;
        }
        let kw: String = self.src[j..].chars().take_while(|c| c.is_alphabetic()).collect();
        if kw == "if" {
            let ifm = self.b.open();
            let im = self.b.open();
            self.directive_start();
            self.bump(); // if
            self.expression();
            self.directive_end();
            self.b.close(im, "template_if_intro");
            let _ = self.template_parts_until_directive(&["else", "endif"]);
            if self.next_directive_kw().as_deref() == Some("else") {
                let em = self.b.open();
                self.directive_start();
                self.bump();
                self.directive_end();
                self.b.close(em, "template_if_else");
                let _ = self.template_parts_until_directive(&["endif"]);
            }
            let endm = self.b.open();
            self.directive_start();
            if self.at("endif") {
                self.bump();
            }
            self.directive_end();
            self.b.close(endm, "template_if_end");
            self.b.close(ifm, "template_if");
        } else {
            let fm = self.b.open();
            let sm = self.b.open();
            self.directive_start();
            self.bump(); // for
            self.bump_as("identifier", true);
            if self.at(",") {
                self.bump();
                self.bump_as("identifier", true);
            }
            self.expect("in");
            self.expression();
            self.directive_end();
            self.b.close(sm, "template_for_start");
            let _ = self.template_parts_until_directive(&["endfor"]);
            let em = self.b.open();
            self.directive_start();
            if self.at("endfor") {
                self.bump();
            }
            self.directive_end();
            self.b.close(em, "template_for_end");
            self.b.close(fm, "template_for");
        }
        self.b.close(dm, "template_directive");
    }

    fn directive_start(&mut self) {
        let s = self.pos;
        self.b.leaf("template_directive_start", true, s, s + 2);
        self.pos = s + 2;
        self.tok = None;
        if self.at("~") {
            let sm = self.b.open();
            self.bump();
            self.b.close(sm, "strip_marker");
        }
    }

    fn directive_end(&mut self) {
        if self.at("~") {
            let sm = self.b.open();
            self.bump();
            self.b.close(sm, "strip_marker");
        }
        let t = self.peek();
        if self.text(t) == "}" {
            self.b.leaf("template_directive_end", true, t.s, t.e);
            self.pos = t.e;
        }
        self.tok = None;
    }

    fn next_directive_kw(&mut self) -> Option<String> {
        let by = self.by;
        let i = self.pos;
        if by.get(i) == Some(&b'%') && by.get(i + 1) == Some(&b'{') {
            let mut j = i + 2;
            while j < by.len() && (by[j] == b' ' || by[j] == b'~') {
                j += 1;
            }
            let kw: String = self.src[j..].chars().take_while(|c| c.is_alphabetic()).collect();
            return Some(kw);
        }
        None
    }

    fn template_parts_until_directive(&mut self, kws: &[&str]) -> usize {
        let by = self.by;
        let mut i = self.pos;
        let mut lit_start: Option<usize> = None;
        while i < by.len() {
            if by[i] == b'%' && by.get(i + 1) == Some(&b'{') {
                self.pos = i;
                if let Some(kw) = self.next_directive_kw() {
                    if kws.contains(&kw.as_str()) {
                        if let Some(ls) = lit_start.take() {
                            self.b.leaf("template_literal", true, ls, i);
                        }
                        self.pos = i;
                        self.tok = None;
                        return i;
                    }
                }
                if let Some(ls) = lit_start.take() {
                    self.b.leaf("template_literal", true, ls, i);
                }
                self.tok = None;
                self.template_directive();
                i = self.pos;
                continue;
            }
            if by[i] == b'$' && by.get(i + 1) == Some(&b'{') {
                if let Some(ls) = lit_start.take() {
                    self.b.leaf("template_literal", true, ls, i);
                }
                let m = self.b.open();
                self.b.leaf("template_interpolation_start", true, i, i + 2);
                self.pos = i + 2;
                self.tok = None;
                self.expression();
                let t = self.peek();
                if self.text(t) == "}" {
                    self.b.leaf("template_interpolation_end", true, t.s, t.e);
                    self.pos = t.e;
                }
                self.tok = None;
                self.b.close(m, "template_interpolation");
                i = self.pos;
                continue;
            }
            if by[i] == b'"' {
                break;
            }
            if lit_start.is_none() {
                lit_start = Some(i);
            }
            i += 1;
        }
        if let Some(ls) = lit_start.take() {
            self.b.leaf("template_literal", true, ls, i);
        }
        self.pos = i;
        self.tok = None;
        i
    }

    fn heredoc(&mut self) {
        let t = self.peek();
        let s = t.s;
        let by = self.by;
        let tm = self.b.open();
        let hm = self.b.open();
        let indent = by.get(s + 2) == Some(&b'-');
        let ss = if indent { s + 3 } else { s + 2 };
        self.b.leaf("heredoc_start", true, s, ss);
        let mut e = ss;
        while e < by.len() && ((by[e] as char).is_alphanumeric() || by[e] == b'_') {
            e += 1;
        }
        let ident = &self.src[ss..e];
        self.b.leaf("heredoc_identifier", true, ss, e);
        // skip to next line
        let mut i = e;
        while i < by.len() && by[i] != b'\n' {
            i += 1;
        }
        self.pos = i;
        self.tok = None;
        let end = self.template_parts(0, Some((ident, indent)));
        if end < by.len() {
            self.b.leaf("heredoc_identifier", true, end, end + ident.len());
            self.pos = end + ident.len();
        } else {
            self.pos = end;
        }
        self.tok = None;
        self.b.close(hm, "heredoc_template");
        self.b.close(tm, "template_expr");
    }
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/langs/hcl.rs <<'EOF'
//! HCL parser producing tree-sitter-hcl compatible trees.

use super::python::intern;
use crate::ts::builder::Builder;
use crate::ts::{NodeId, Tree};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK {
    Ident,
    Num,
    Str,
    Heredoc,
    Punct,
    Eof,
    Err,
}

#[derive(Clone, Copy, Debug)]
struct Tok {
    k: TK,
    s: usize,
    e: usize,
}

const PUNCTS: &[&str] = &[
    "...", "[*]", "=>", "==", "!=", ">=", "<=", "&&", "||", ".*", "=", ":", "{", "}", "[", "]",
    "(", ")", ",", ".", "?", "!", "-", "+", "*", "/", "%", ">", "<",
];

pub struct Hcl<'a> {
    src: &'a str,
    by: &'a [u8],
    b: Builder,
    pos: usize,
    tok: Option<Tok>,
}

pub fn parse(src: &str) -> Tree {
    let mut p = Hcl { src, by: src.as_bytes(), b: Builder::new(), pos: 0, tok: None };
    p.config_file();
    p.b.finish("config_file", src.len())
}

fn is_id_start(c: char) -> bool {
    c == '_' || c.is_alphabetic()
}
fn is_id_cont(c: char) -> bool {
    c == '_' || c == '-' || c.is_alphanumeric()
}

impl<'a> Hcl<'a> {
    fn ch(&self, i: usize) -> Option<char> {
        self.src.get(i..).and_then(|s| s.chars().next())
    }
    fn text(&self, t: Tok) -> &'a str {
        &self.src[t.s..t.e]
    }

    fn skip_trivia(&mut self) {
        let by = self.by;
        loop {
            let c = match self.ch(self.pos) {
                Some(c) => c,
                None => return,
            };
            if c.is_whitespace() {
                self.pos += c.len_utf8();
                continue;
            }
            if c == '#' || (c == '/' && by.get(self.pos + 1) == Some(&b'/')) {
                let s = self.pos;
                let mut e = s;
                while e < by.len() && by[e] != b'\n' {
                    e += 1;
                }
                let mut ce = e;
                if ce > s && by[ce - 1] == b'\r' {
                    ce -= 1;
                }
                self.b.extra("comment", s, ce);
                self.pos = e;
                continue;
            }
            if c == '/' && by.get(self.pos + 1) == Some(&b'*') {
                let s = self.pos;
                let mut i = s + 2;
                while i + 1 < by.len() && !(by[i] == b'*' && by[i + 1] == b'/') {
                    i += 1;
                }
                let e = if i + 1 < by.len() { i + 2 } else { by.len() };
                self.b.extra("comment", s, e);
                self.pos = e;
                continue;
            }
            return;
        }
    }

    fn lex(&mut self) -> Tok {
        let s = self.pos;
        let by = self.by;
        let c = match self.ch(s) {
            None => return Tok { k: TK::Eof, s, e: s },
            Some(c) => c,
        };
        if c == '"' {
            return Tok { k: TK::Str, s, e: s };
        }
        if c == '<' && by.get(s + 1) == Some(&b'<') {
            return Tok { k: TK::Heredoc, s, e: s };
        }
        if is_id_start(c) {
            let mut e = s;
            while let Some(c) = self.ch(e) {
                if is_id_cont(c) {
                    e += c.len_utf8();
                } else {
                    break;
                }
            }
            return Tok { k: TK::Ident, s, e };
        }
        if c.is_ascii_digit() {
            let mut e = s;
            while e < by.len() && by[e].is_ascii_digit() {
                e += 1;
            }
            if e < by.len() && by[e] == b'.' && by.get(e + 1).map(|b| b.is_ascii_digit()).unwrap_or(false) {
                e += 1;
                while e < by.len() && by[e].is_ascii_digit() {
                    e += 1;
                }
            }
            if e < by.len() && (by[e] == b'e' || by[e] == b'E') {
                let mut f = e + 1;
                if f < by.len() && (by[f] == b'+' || by[f] == b'-') {
                    f += 1;
                }
                if f < by.len() && by[f].is_ascii_digit() {
                    e = f;
                    while e < by.len() && by[e].is_ascii_digit() {
                        e += 1;
                    }
                }
            }
            return Tok { k: TK::Num, s, e };
        }
        for p in PUNCTS {
            if self.src[s..].starts_with(p) {
                return Tok { k: TK::Punct, s, e: s + p.len() };
            }
        }
        Tok { k: TK::Err, s, e: s + c.len_utf8() }
    }

    fn peek(&mut self) -> Tok {
        if let Some(t) = self.tok {
            return t;
        }
        self.skip_trivia();
        let t = self.lex();
        self.tok = Some(t);
        t
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        matches!(t.k, TK::Punct | TK::Ident) && self.text(t) == s
    }

    fn bump_as(&mut self, kind: &'static str, named: bool) -> NodeId {
        let t = self.peek();
        let id = self.b.leaf(kind, named, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        id
    }

    fn bump(&mut self) -> NodeId {
        let t = self.peek();
        let k = intern(self.text(t));
        self.bump_as(k, false)
    }

    fn expect(&mut self, s: &str) {
        if self.at(s) {
            self.bump();
        } else {
            self.b.missing(intern(s), false);
        }
    }

    fn wrap_leaf(&mut self, kind: &'static str, tok: &'static str) -> NodeId {
        // named node containing a single anonymous token
        let m = self.b.open();
        let t = self.peek();
        self.b.leaf(tok, false, t.s, t.e);
        self.pos = t.e;
        self.tok = None;
        self.b.close(m, kind)
    }

    fn peek_nth_text(&mut self, n: usize) -> &'a str {
        let save_pos = self.pos;
        let save_tok = self.tok;
        let save_nodes = self.b.nodes.len();
        let save_pending = self.b.pending_count();
        let mut cur = self.peek();
        for _ in 0..n {
            self.pos = cur.e;
            self.tok = None;
            cur = self.peek();
        }
        let r = self.text(cur);
        self.pos = save_pos;
        self.tok = save_tok;
        self.b.truncate_pending(save_pending);
        self.b.nodes.truncate(save_nodes);
        r
    }

    // ------------------------------------------------------------------ body
    fn config_file(&mut self) {
        let t = self.peek();
        if t.k == TK::Eof {
            return;
        }
        if self.at("{") {
            self.object();
            return;
        }
        self.body(true);
    }

    fn body(&mut self, top: bool) -> NodeId {
        let m = self.b.open();
        loop {
            let t = self.peek();
            if t.k == TK::Eof || (!top && self.at("}")) {
                break;
            }
            if t.k == TK::Ident {
                let n1 = self.peek_nth_text(1);
                if n1 == "=" {
                    self.attribute();
                } else {
                    self.block();
                }
            } else {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ERROR");
            }
        }
        self.b.close(m, "body")
    }

    fn attribute(&mut self) {
        let m = self.b.open();
        self.bump_as("identifier", true);
        self.expect("=");
        self.expression();
        self.b.close(m, "attribute");
    }

    fn block(&mut self) {
        let m = self.b.open();
        self.bump_as("identifier", true);
        loop {
            let t = self.peek();
            match t.k {
                TK::Str => {
                    self.string_like(true);
                }
                TK::Ident => {
                    self.bump_as("identifier", true);
                }
                _ => break,
            }
        }
        if self.at("{") {
            self.wrap_leaf("block_start", "{");
            if !self.at("}") {
                self.body(false);
            }
            if self.at("}") {
                self.wrap_leaf("block_end", "}");
            } else {
                self.b.missing("block_end", true);
            }
        } else {
            self.b.missing("block_start", true);
        }
        self.b.close(m, "block");
    }

    // ----------------------------------------------------------- expressions
    fn expression(&mut self) -> NodeId {
        let m = self.b.open();
        self.expr_inner();
        self.b.close(m, "expression")
    }

    /// Parses conditional / operation / term into the currently open `expression` node.
    fn expr_inner(&mut self) {
        // operation or term
        let start_children = self.b.current_children().len();
        let is_op = self.operation(0);
        let _ = start_children;
        let _ = is_op;
        if self.at("?") {
            // conditional: wrap what we have into an expression
            let ch: Vec<NodeId> = self.b.current_children().to_vec();
            let first = ch[0];
            let cm = self.b.open_before(first);
            let em = self.b.open_before(first);
            let _ = em;
            // close inner expression containing all previous children
            self.b.close(em, "expression");
            self.bump();
            self.expression();
            self.expect(":");
            self.expression();
            self.b.close(cm, "conditional");
        }
    }

    fn binop_prec(&mut self) -> Option<u8> {
        let t = self.peek();
        if t.k != TK::Punct {
            return None;
        }
        Some(match self.text(t) {
            "*" | "/" | "%" => 6,
            "+" | "-" => 5,
            ">" | ">=" | "<" | "<=" => 4,
            "==" | "!=" => 3,
            "&&" => 2,
            "||" => 1,
            _ => return None,
        })
    }

    /// Parse an operation or a term; returns true if an operation node was created.
    fn operation(&mut self, min: u8) -> bool {
        let first_idx = self.b.current_children().len();
        // unary
        let mut is_op = false;
        if self.at("-") || self.at("!") {
            let om = self.b.open();
            let um = self.b.open();
            self.bump();
            self.term();
            self.b.close(um, "unary_operation");
            self.b.close(om, "operation");
            is_op = true;
        } else {
            self.term();
        }
        loop {
            let p = match self.binop_prec() {
                Some(p) => p,
                None => break,
            };
            if p < min {
                break;
            }
            let ch: Vec<NodeId> = self.b.current_children().to_vec();
            let first = ch[first_idx];
            let om = self.b.open_before(first);
            let bm = self.b.open_before(first);
            let _ = om;
            self.bump();
            // right operand: higher precedence operation or term
            let save_len = self.b.current_children().len();
            let right_is_op = self.operation(p + 1);
            let _ = (save_len, right_is_op);
            self.b.close(bm, "binary_operation");
            self.b.close(om, "operation");
            is_op = true;
        }
        is_op
    }

    /// Parse an expression term (with postfix chains) into the current node.
    fn term(&mut self) {
        let t = self.peek();
        match t.k {
            TK::Num => {
                let m = self.b.open();
                self.bump_as("numeric_lit", true);
                self.b.close(m, "literal_value");
            }
            TK::Str => {
                self.string_like(false);
            }
            TK::Heredoc => {
                self.heredoc();
            }
            TK::Ident => {
                let w = self.text(t);
                match w {
                    "true" | "false" => {
                        let m = self.b.open();
                        self.wrap_leaf("bool_lit", if w == "true" { "true" } else { "false" });
                        self.b.close(m, "literal_value");
                    }
                    "null" => {
                        let m = self.b.open();
                        self.wrap_leaf("null_lit", "null");
                        self.b.close(m, "literal_value");
                    }
                    _ => {
                        if self.peek_nth_text(1) == "(" {
                            let m = self.b.open();
                            self.bump_as("identifier", true);
                            self.bump(); // (
                            if !self.at(")") {
                                let am = self.b.open();
                                loop {
                                    self.expression();
                                    if self.at(",") {
                                        self.bump();
                                        if self.at(")") {
                                            break;
                                        }
                                        continue;
                                    }
                                    if self.at("...") {
                                        let em = self.b.open();
                                        self.bump();
                                        self.b.close(em, "ellipsis");
                                    }
                                    break;
                                }
                                self.b.close(am, "function_arguments");
                            }
                            self.expect(")");
                            self.b.close(m, "function_call");
                        } else {
                            let m = self.b.open();
                            self.bump_as("identifier", true);
                            self.b.close(m, "variable_expr");
                        }
                    }
                }
            }
            TK::Punct => match self.text(t) {
                "[" => {
                    if self.peek_nth_text(1) == "for" {
                        self.for_expr(true);
                    } else {
                        let cm = self.b.open();
                        let tm = self.b.open();
                        self.wrap_leaf("tuple_start", "[");
                        loop {
                            if self.at("]") || self.peek().k == TK::Eof {
                                break;
                            }
                            self.expression();
                            if self.at(",") {
                                self.bump();
                                continue;
                            }
                            break;
                        }
                        if self.at("]") {
                            self.wrap_leaf("tuple_end", "]");
                        } else {
                            self.b.missing("tuple_end", true);
                        }
                        self.b.close(tm, "tuple");
                        self.b.close(cm, "collection_value");
                    }
                }
                "{" => {
                    if self.peek_nth_text(1) == "for" {
                        self.for_expr(false);
                    } else {
                        let cm = self.b.open();
                        self.object();
                        self.b.close(cm, "collection_value");
                    }
                }
                "(" => {
                    self.bump();
                    self.expression();
                    self.expect(")");
                }
                _ => {
                    let m = self.b.open();
                    self.bump();
                    self.b.close(m, "ERROR");
                    return;
                }
            },
            _ => {
                self.b.missing("identifier", true);
                return;
            }
        }
        self.postfix();
    }

    fn postfix(&mut self) {
        loop {
            if self.at(".") {
                // get_attr or legacy index
                let save = self.pos;
                let _ = save;
                let t = self.peek();
                let by = self.by;
                let next = by.get(t.e).copied();
                if next.map(|b| b.is_ascii_digit()).unwrap_or(false) {
                    let im = self.b.open();
                    let lm = self.b.open();
                    self.bump();
                    self.bump_as("numeric_lit", false);
                    self.b.close(lm, "legacy_index");
                    self.b.close(im, "index");
                    continue;
                }
                let m = self.b.open();
                self.bump();
                let t2 = self.peek();
                if t2.k == TK::Ident {
                    self.bump_as("identifier", true);
                } else {
                    self.b.missing("identifier", true);
                }
                self.b.close(m, "get_attr");
                continue;
            }
            if self.at(".*") || self.at("[*]") {
                let full = self.at("[*]");
                let sm = self.b.open();
                let km = self.b.open();
                self.bump();
                loop {
                    if self.at(".") {
                        let by = self.by;
                        let t = self.peek();
                        if by.get(t.e).map(|b| b.is_ascii_digit()).unwrap_or(false) {
                            break;
                        }
                        let m = self.b.open();
                        self.bump();
                        self.bump_as("identifier", true);
                        self.b.close(m, "get_attr");
                        continue;
                    }
                    if full && self.at("[") {
                        let im = self.b.open();
                        let nm = self.b.open();
                        self.bump();
                        self.expression();
                        self.expect("]");
                        self.b.close(nm, "new_index");
                        self.b.close(im, "index");
                        continue;
                    }
                    break;
                }
                self.b.close(km, if full { "full_splat" } else { "attr_splat" });
                self.b.close(sm, "splat");
                continue;
            }
            if self.at("[") {
                let im = self.b.open();
                let nm = self.b.open();
                self.bump();
                self.expression();
                self.expect("]");
                self.b.close(nm, "new_index");
                self.b.close(im, "index");
                continue;
            }
            break;
        }
    }

    fn object(&mut self) {
        let om = self.b.open();
        self.wrap_leaf("object_start", "{");
        loop {
            if self.at("}") || self.peek().k == TK::Eof {
                break;
            }
            let em = self.b.open();
            let k = self.expression();
            self.b.set_field(k, "key");
            if self.at("=") || self.at(":") {
                self.bump();
            } else {
                self.b.missing("=", false);
            }
            let v = self.expression();
            self.b.set_field(v, "val");
            self.b.close(em, "object_elem");
            if self.at(",") {
                self.bump();
            }
        }
        if self.at("}") {
            self.wrap_leaf("object_end", "}");
        } else {
            self.b.missing("object_end", true);
        }
        self.b.close(om, "object");
    }

    fn for_expr(&mut self, tuple: bool) {
        let fm = self.b.open();
        let m = self.b.open();
        if tuple {
            self.wrap_leaf("tuple_start", "[");
        } else {
            self.wrap_leaf("object_start", "{");
        }
        // for intro
        let im = self.b.open();
        self.bump(); // for
        self.bump_as("identifier", true);
        if self.at(",") {
            self.bump();
            self.bump_as("identifier", true);
        }
        self.expect("in");
        self.expression();
        self.expect(":");
        self.b.close(im, "for_intro");
        self.expression();
        if !tuple {
            self.expect("=>");
            self.expression();
            if self.at("...") {
                let em = self.b.open();
                self.bump();
                self.b.close(em, "ellipsis");
            }
        }
        if self.at("if") {
            let cm = self.b.open();
            self.bump();
            self.expression();
            self.b.close(cm, "for_cond");
        }
        if tuple {
            if self.at("]") {
                self.wrap_leaf("tuple_end", "]");
            }
            self.b.close(m, "for_tuple_expr");
        } else {
            if self.at("}") {
                self.wrap_leaf("object_end", "}");
            }
            self.b.close(m, "for_object_expr");
        }
        self.b.close(fm, "for_expr");
    }

    /// Parse a quoted string. If `label` (block label), always string_lit.
    fn string_like(&mut self, label: bool) {
        let t = self.peek();
        let s = t.s;
        let by = self.by;
        // determine if it contains template interpolation/directive
        let mut i = s + 1;
        let mut has_template = false;
        while i < by.len() && by[i] != b'"' && by[i] != b'\n' {
            if by[i] == b'\\' {
                i += 2;
                continue;
            }
            if (by[i] == b'$' || by[i] == b'%') && by.get(i + 1) == Some(&b'{') {
                if by.get(i + 2) == Some(&by[i]) {
                    // escaped $${ / %%{
                } else {
                    has_template = true;
                    break;
                }
            }
            i += 1;
        }
        if label || !has_template {
            let lm = if label { None } else { Some(self.b.open()) };
            let m = self.b.open();
            self.b.leaf("quoted_template_start", true, s, s + 1);
            let mut j = s + 1;
            while j < by.len() && by[j] != b'"' && by[j] != b'\n' {
                if by[j] == b'\\' {
                    j += 1;
                }
                j += 1;
            }
            let j = j.min(by.len());
            if j > s + 1 {
                self.b.leaf("template_literal", true, s + 1, j);
            }
            if j < by.len() && by[j] == b'"' {
                self.b.leaf("quoted_template_end", true, j, j + 1);
                self.pos = j + 1;
            } else {
                self.b.missing("quoted_template_end", true);
                self.pos = j;
            }
            self.tok = None;
            self.b.close(m, "string_lit");
            if let Some(lm) = lm {
                self.b.close(lm, "literal_value");
            }
            return;
        }
        let tm = self.b.open();
        let qm = self.b.open();
        self.b.leaf("quoted_template_start", true, s, s + 1);
        self.pos = s + 1;
        self.tok = None;
        let end = self.template_parts(b'"', None);
        if end < by.len() && by[end] == b'"' {
            self.b.leaf("quoted_template_end", true, end, end + 1);
            self.pos = end + 1;
        } else {
            self.b.missing("quoted_template_end", true);
            self.pos = end;
        }
        self.tok = None;
        self.b.close(qm, "quoted_template");
        self.b.close(tm, "template_expr");
    }

    /// Parse template parts from self.pos until the terminator; returns end position.
    fn template_parts(&mut self, quote: u8, heredoc_end: Option<(&str, bool)>) -> usize {
        let by = self.by;
        let mut i = self.pos;
        let mut lit_start: Option<usize> = None;
        loop {
            if i >= by.len() {
                break;
            }
            if let Some((ident, indent)) = heredoc_end {
                // at line start: check closing identifier
                if i == 0 || by[i - 1] == b'\n' {
                    let mut j = i;
                    if indent {
                        while j < by.len() && (by[j] == b' ' || by[j] == b'\t') {
                            j += 1;
                        }
                    }
                    if self.src[j..].starts_with(ident) {
                        let after = j + ident.len();
                        if after >= by.len() || by[after] == b'\n' || by[after] == b'\r' {
                            if let Some(ls) = lit_start.take() {
                                self.b.leaf("template_literal", true, ls, i);
                            }
                            return j;
                        }
                    }
                }
            } else if by[i] == quote || by[i] == b'\n' {
                break;
            }
            if by[i] == b'\\' && heredoc_end.is_none() {
                if lit_start.is_none() {
                    lit_start = Some(i);
                }
                i += 2;
                continue;
            }
            if (by[i] == b'$' || by[i] == b'%') && by.get(i + 1) == Some(&b'{') && by.get(i + 2) != Some(&by[i]) {
                if let Some(ls) = lit_start.take() {
                    self.b.leaf("template_literal", true, ls, i);
                }
                let is_directive = by[i] == b'%';
                self.pos = i;
                self.tok = None;
                if is_directive {
                    self.template_directive();
                } else {
                    let m = self.b.open();
                    self.b.leaf("template_interpolation_start", true, i, i + 2);
                    self.pos = i + 2;
                    self.tok = None;
                    if self.at("~") {
                        let sm = self.b.open();
                        self.bump();
                        self.b.close(sm, "strip_marker");
                    }
                    if !self.at("}") {
                        self.expression();
                    }
                    if self.at("~") {
                        let sm = self.b.open();
                        self.bump();
                        self.b.close(sm, "strip_marker");
                    }
                    let t = self.peek();
                    if self.text(t) == "}" {
                        self.b.leaf("template_interpolation_end", true, t.s, t.e);
                        self.pos = t.e;
                    } else {
                        self.b.missing("template_interpolation_end", true);
                    }
                    self.tok = None;
                    self.b.close(m, "template_interpolation");
                }
                i = self.pos;
                continue;
            }
            if lit_start.is_none() {
                lit_start = Some(i);
            }
            i += 1;
        }
        if let Some(ls) = lit_start.take() {
            if i > ls {
                self.b.leaf("template_literal", true, ls, i);
            }
        }
        i
    }

    fn template_directive(&mut self) {
        // %{ if cond } ... %{ else } ... %{ endif }  /  %{ for x in y } ... %{ endfor }
        let dm = self.b.open();
        let by = self.by;
        let s = self.pos;
        let mut j = s + 2;
        while j < by.len() && (by[j] == b' ' || by[j] == b'~') {
            j += 1;
        }
        let kw: String = self.src[j..].chars().take_while(|c| c.is_alphabetic()).collect();
        if kw == "if" {
            let ifm = self.b.open();
            let im = self.b.open();
            self.directive_start();
            self.bump(); // if
            self.expression();
            self.directive_end();
            self.b.close(im, "template_if_intro");
            let _ = self.template_parts_until_directive(&["else", "endif"]);
            if self.next_directive_kw().as_deref() == Some("else") {
                let em = self.b.open();
                self.directive_start();
                self.bump();
                self.directive_end();
                self.b.close(em, "template_if_else");
                let _ = self.template_parts_until_directive(&["endif"]);
            }
            let endm = self.b.open();
            self.directive_start();
            if self.at("endif") {
                self.bump();
            }
            self.directive_end();
            self.b.close(endm, "template_if_end");
            self.b.close(ifm, "template_if");
        } else {
            let fm = self.b.open();
            let sm = self.b.open();
            self.directive_start();
            self.bump(); // for
            self.bump_as("identifier", true);
            if self.at(",") {
                self.bump();
                self.bump_as("identifier", true);
            }
            self.expect("in");
            self.expression();
            self.directive_end();
            self.b.close(sm, "template_for_start");
            let _ = self.template_parts_until_directive(&["endfor"]);
            let em = self.b.open();
            self.directive_start();
            if self.at("endfor") {
                self.bump();
            }
            self.directive_end();
            self.b.close(em, "template_for_end");
            self.b.close(fm, "template_for");
        }
        self.b.close(dm, "template_directive");
    }

    fn directive_start(&mut self) {
        let s = self.pos;
        self.b.leaf("template_directive_start", true, s, s + 2);
        self.pos = s + 2;
        self.tok = None;
        if self.at("~") {
            let sm = self.b.open();
            self.bump();
            self.b.close(sm, "strip_marker");
        }
    }

    fn directive_end(&mut self) {
        if self.at("~") {
            let sm = self.b.open();
            self.bump();
            self.b.close(sm, "strip_marker");
        }
        let t = self.peek();
        if self.text(t) == "}" {
            self.b.leaf("template_directive_end", true, t.s, t.e);
            self.pos = t.e;
        }
        self.tok = None;
    }

    fn next_directive_kw(&mut self) -> Option<String> {
        let by = self.by;
        let i = self.pos;
        if by.get(i) == Some(&b'%') && by.get(i + 1) == Some(&b'{') {
            let mut j = i + 2;
            while j < by.len() && (by[j] == b' ' || by[j] == b'~') {
                j += 1;
            }
            let kw: String = self.src[j..].chars().take_while(|c| c.is_alphabetic()).collect();
            return Some(kw);
        }
        None
    }

    fn template_parts_until_directive(&mut self, kws: &[&str]) -> usize {
        let by = self.by;
        let mut i = self.pos;
        let mut lit_start: Option<usize> = None;
        while i < by.len() {
            if by[i] == b'%' && by.get(i + 1) == Some(&b'{') {
                self.pos = i;
                if let Some(kw) = self.next_directive_kw() {
                    if kws.contains(&kw.as_str()) {
                        if let Some(ls) = lit_start.take() {
                            self.b.leaf("template_literal", true, ls, i);
                        }
                        self.pos = i;
                        self.tok = None;
                        return i;
                    }
                }
                if let Some(ls) = lit_start.take() {
                    self.b.leaf("template_literal", true, ls, i);
                }
                self.tok = None;
                self.template_directive();
                i = self.pos;
                continue;
            }
            if by[i] == b'$' && by.get(i + 1) == Some(&b'{') {
                if let Some(ls) = lit_start.take() {
                    self.b.leaf("template_literal", true, ls, i);
                }
                let m = self.b.open();
                self.b.leaf("template_interpolation_start", true, i, i + 2);
                self.pos = i + 2;
                self.tok = None;
                self.expression();
                let t = self.peek();
                if self.text(t) == "}" {
                    self.b.leaf("template_interpolation_end", true, t.s, t.e);
                    self.pos = t.e;
                }
                self.tok = None;
                self.b.close(m, "template_interpolation");
                i = self.pos;
                continue;
            }
            if by[i] == b'"' {
                break;
            }
            if lit_start.is_none() {
                lit_start = Some(i);
            }
            i += 1;
        }
        if let Some(ls) = lit_start.take() {
            self.b.leaf("template_literal", true, ls, i);
        }
        self.pos = i;
        self.tok = None;
        i
    }

    fn heredoc(&mut self) {
        let t = self.peek();
        let s = t.s;
        let by = self.by;
        let tm = self.b.open();
        let hm = self.b.open();
        let indent = by.get(s + 2) == Some(&b'-');
        let ss = if indent { s + 3 } else { s + 2 };
        self.b.leaf("heredoc_start", true, s, ss);
        let mut e = ss;
        while e < by.len() && ((by[e] as char).is_alphanumeric() || by[e] == b'_') {
            e += 1;
        }
        let ident = &self.src[ss..e];
        self.b.leaf("heredoc_identifier", true, ss, e);
        // skip to next line
        let mut i = e;
        while i < by.len() && by[i] != b'\n' {
            i += 1;
        }
        self.pos = i;
        self.tok = None;
        let end = self.template_parts(0, Some((ident, indent)));
        if end < by.len() {
            self.b.leaf("heredoc_identifier", true, end, end + ident.len());
            self.pos = end + ident.len();
        } else {
            self.pos = end;
        }
        self.tok = None;
        self.b.close(hm, "heredoc_template");
        self.b.close(tm, "template_expr");
    }
}
