use super::PreparedQuery;

fn block(kind: &str) -> String {
    format!(r#"((block (identifier) @name) @block (#eq? @name "{kind}"))"#)
}

pub fn prepared(name: &str, _pat: Option<&regex::Regex>) -> PreparedQuery {
    let q: String = match name {
        "variable" | "resource" | "data" | "output" | "provider" | "terraform" | "locals" | "module" => block(name),
        "required-providers" => r#"(block (identifier) @_SRGN_IGNORE.level1.identifier (body (block (identifier) @_SRGN_IGNORE.level2.identifier (body) @body)) (#eq? @_SRGN_IGNORE.level2.identifier "required_providers") (#eq? @_SRGN_IGNORE.level1.identifier "terraform"))"#.into(),
        "variables" => r#"[((block (identifier) @_SRGN_IGNORE.declaration (string_lit (template_literal) @name.declaration)) (#match? @_SRGN_IGNORE.declaration "variable")) ((expression (variable_expr (identifier) @_SRGN_IGNORE.usage) . (get_attr (identifier) @name.usage)) (#match? @_SRGN_IGNORE.usage "var"))]"#.into(),
        "resource-names" => r#"[((block (identifier) @_SRGN_IGNORE.declaration (string_lit) (string_lit (template_literal) @name.declaration)) (#match? @_SRGN_IGNORE.declaration "resource")) ((expression (variable_expr (identifier) @_SRGN_IGNORE.usage) . (get_attr (identifier) @name.usage)) (#not-any-of? @_SRGN_IGNORE.usage "var" "data" "count" "module" "local"))]"#.into(),
        "resource-types" => r#"[((block (identifier) @_SRGN_IGNORE.declaration . (string_lit (template_literal) @name.type)) (#match? @_SRGN_IGNORE.declaration "resource")) ((expression (variable_expr (identifier) @name.usage)) (#not-any-of? @name.usage "var" "data" "count" "module" "local"))]"#.into(),
        "data-names" => r#"[((block (identifier) @_SRGN_IGNORE.declaration (string_lit) (string_lit (template_literal) @name.declaration)) (#match? @_SRGN_IGNORE.declaration "data")) ((expression (variable_expr (identifier) @_SRGN_IGNORE.usage) . (get_attr) . (get_attr (identifier) @name.usage)) (#match? @_SRGN_IGNORE.usage "data"))]"#.into(),
        "data-sources" => r#"[((block (identifier) @_SRGN_IGNORE.declaration . (string_lit (template_literal) @name.provider)) (#match? @_SRGN_IGNORE.declaration "data")) ((expression (variable_expr (identifier) @_SRGN_IGNORE.usage) . (get_attr (identifier) @name.provider)) (#match? @_SRGN_IGNORE.usage "data"))]"#.into(),
        "comments" => "(comment) @comment".into(),
