//! German umlaut and eszett substitutions, validated against a word list.

use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

#[derive(Debug, Clone, Copy)]
pub struct GermanOptions {
    pub prefer_original: bool,
    pub naive: bool,
}

static WORDS_TXT: &str = include_str!("german_words.txt");

fn dict() -> &'static HashSet<&'static str> {
    static D: OnceLock<HashSet<&'static str>> = OnceLock::new();
    D.get_or_init(|| WORDS_TXT.lines().filter(|l| !l.is_empty()).collect())
}

fn contains(w: &str) -> bool {
    dict().contains(w)
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum Kind {
    Ae,
    Oe,
    Ue,
    Ss,
}

#[derive(Clone, Copy, Debug)]
struct Repl {
    start: usize,
    end: usize,
    kind: Kind,
    upper: bool,
}

fn find_replacements(word: &str) -> Vec<Repl> {
    let mut out = Vec::new();
    let mut pot: Option<(Kind, bool, usize)> = None;
    for (i, c) in word.char_indices() {
        if let Some((k, up, st)) = pot {
            let completes = match k {
                Kind::Ae | Kind::Oe | Kind::Ue => c == 'e' || c == 'E',
                Kind::Ss => c == 's' || c == 'S',
            };
            if completes {
                out.push(Repl { start: st, end: i + c.len_utf8(), kind: k, upper: up });
                pot = None;
                continue;
            }
        }
        pot = match c {
            'a' | 'A' => Some((Kind::Ae, c.is_uppercase(), i)),
            'o' | 'O' => Some((Kind::Oe, c.is_uppercase(), i)),
            'u' | 'U' => Some((Kind::Ue, c.is_uppercase(), i)),
            's' | 'S' => Some((Kind::Ss, c.is_uppercase(), i)),
            _ => None,
        };
    }
    out
}

fn repl_str(r: &Repl) -> &'static str {
    match (r.kind, r.upper) {
        (Kind::Ae, false) => "ä",
        (Kind::Ae, true) => "Ä",
        (Kind::Oe, false) => "ö",
        (Kind::Oe, true) => "Ö",
        (Kind::Ue, false) => "ü",
        (Kind::Ue, true) => "Ü",
        (Kind::Ss, false) => "ß",
        (Kind::Ss, true) => "ẞ",
    }
}

fn apply(word: &str, reps: &[Repl]) -> String {
    let mut out = String::with_capacity(word.len());
    let mut last = 0;
    for r in reps {
        out.push_str(&word[last..r.start]);
        out.push_str(repl_str(r));
        last = r.end;
    }
    out.push_str(&word[last..]);
    out
}

fn powerset(n: usize) -> Vec<Vec<usize>> {
    // ordered by size, then lexicographically (like itertools::powerset)
    let mut out = Vec::new();
    for size in 0..=n {
        let mut idx: Vec<usize> = (0..size).collect();
        loop {
            out.push(idx.clone());
            if size == 0 {
                break;
            }
            // next combination
            let mut i = size;
            let mut found = false;
            while i > 0 {
                i -= 1;
                if idx[i] != i + n - size {
                    idx[i] += 1;
                    for j in i + 1..size {
                        idx[j] = idx[j - 1] + 1;
                    }
                    found = true;
                    break;
                }
            }
            if !found {
                break;
            }
        }
    }
    out
}

#[derive(PartialEq)]
enum Casing {
    Lower,
    Title,
    Upper,
}

fn casing(w: &str) -> Option<Casing> {
    let mut chars = w.chars();
    let first = chars.next()?;
    let rest: Vec<char> = chars.collect();
    if first.is_lowercase() && rest.iter().all(|c| !c.is_uppercase()) {
        return Some(Casing::Lower);
    }
    if first.is_uppercase() {
        if rest.iter().all(|c| !c.is_uppercase()) {
            return Some(Casing::Title);
        }
        if rest.iter().all(|c| !c.is_lowercase()) {
            return Some(Casing::Upper);
        }
    }
    None
}

fn titlecase(w: &str) -> String {
    let mut chars = w.chars();
    match chars.next() {
        Some(f) => {
            let mut s: String = f.to_uppercase().collect();
            s.push_str(&chars.as_str().to_lowercase());
            s
        }
        None => String::new(),
    }
}

fn first_upper(w: &str) -> String {
    let mut chars = w.chars();
    match chars.next() {
        Some(f) => {
            let mut s: String = f.to_uppercase().collect();
            s.push_str(chars.as_str());
            s
        }
        None => String::new(),
    }
}

struct Checker {
    memo: HashMap<String, bool>,
}

impl Checker {
    fn suffix_ok(&mut self, s: &str) -> bool {
        if let Some(&v) = self.memo.get(s) {
            return v;
        }
        let cands = [first_upper(s), s.to_lowercase()];
        let mut res = false;
        'outer: for cand in cands.iter() {
            if contains(cand) {
                res = true;
                break;
            }
            let ends: Vec<usize> = cand.char_indices().map(|(i, c)| i + c.len_utf8()).collect();
            for &e in &ends[..ends.len().saturating_sub(1)] {
                if contains(&cand[..e]) && self.suffix_ok(&cand[e..]) {
                    res = true;
                    break 'outer;
                }
            }
        }
        self.memo.insert(s.to_string(), res);
        res
    }

    fn decompound_top(&mut self, w: &str) -> bool {
        let ends: Vec<usize> = w.char_indices().map(|(i, c)| i + c.len_utf8()).collect();
        for &e in &ends {
            if contains(&w[..e]) {
                if e == w.len() {
                    return true;
                }
                if self.suffix_ok(&w[e..]) {
                    return true;
                }
            }
        }
        false
    }

    fn is_valid(&mut self, w: &str) -> bool {
        match casing(w) {
            Some(Casing::Lower) => contains(w) || self.decompound_top(w),
            Some(Casing::Title) => {
                contains(w) || self.is_valid(&w.to_lowercase()) || self.decompound_top(w)
            }
            Some(Casing::Upper) => self.is_valid(&titlecase(w)),
            None => false,
        }
    }
}

fn process_word(word: &str, opts: &GermanOptions, checker: &mut Checker) -> String {
    let reps = find_replacements(word);
    if reps.is_empty() {
        return word.to_string();
    }
    if opts.naive {
        return apply(word, &reps);
    }
    for combo in powerset(reps.len()) {
        if combo.is_empty() && !opts.prefer_original {
            continue;
        }
        let chosen: Vec<Repl> = combo.iter().map(|&i| reps[i]).collect();
        let cand = apply(word, &chosen);
        if checker.is_valid(&cand) {
            return cand;
        }
    }
    word.to_string()
}

pub fn process(input: &str, opts: &GermanOptions) -> String {
    let mut checker = Checker { memo: HashMap::new() };
    let mut out = String::with_capacity(input.len());
    let mut word = String::new();
    for c in input.chars() {
        if c.is_alphabetic() {
            word.push(c);
        } else {
            if !word.is_empty() {
                out.push_str(&process_word(&word, opts, &mut checker));
                word.clear();
            }
            out.push(c);
        }
    }
    if !word.is_empty() {
        out.push_str(&process_word(&word, opts, &mut checker));
    }
    out
}
EOF
