    };
    let mut out = String::with_capacity(text.len());
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let mut i = 0;
    while i < chars.len() {
        let (pos, c) = chars[i];
        if is_token_char(c) {
            let mut j = i;
            while j < chars.len() && is_token_cont(chars[j].1) {
                j += 1;
            }
            let end = if j < chars.len() { chars[j].0 } else { text.len() };
            out.push_str(&process_token(&text[pos..end]));
            i = j;
        } else {
            out.push(c);
            i += 1;
        }
    }
    apply_exceptions(&out)
}
